export const NOVEL_AUDIO_CATALOG = Object.freeze({
  "v1-secret-forest-adventure-c1-en-title-e4c4bb0211ca3532": {
    "text": "The Whispering Tree",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-title-7ab66cb6ed4c58db": {
    "text": "會說話的樹",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-0-7d86dd2b5ac8bb85": {
    "text": "Lily was a curious girl.\nShe loved exploring new places.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-0-4dde8f824334df9a": {
    "text": "莉莉是一個充滿好奇心的女孩。\n她喜歡探索新的地方。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-1-b87555c9327b0164": {
    "text": "Every day after school, she liked to walk near her house.\nThere was a small forest not far away.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-1-6812f67e77307eed": {
    "text": "每天放學後，她都喜歡在家附近散步。\n那裡有一片小森林。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-2-ab7a7ab3fab29616": {
    "text": "Her mother always said,\n“Don’t go too deep into the forest.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-2-4de798cbf8135b6b": {
    "text": "她的媽媽總是說：\n「不要走進森林太深。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-3-a7d9621b1c22440e": {
    "text": "But Lily always wondered what was inside.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-3-9b58d64b72cb264a": {
    "text": "但莉莉總是很好奇裡面有什麼。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-4-0df42d1116ce5a89": {
    "text": "One sunny afternoon, Lily stood at the edge of the forest.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-4-e9669efa37a00318": {
    "text": "一個陽光明媚的下午，莉莉站在森林入口。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-5-59735293a9356040": {
    "text": "“The trees look different today,” she said softly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-5-dd8b372f53b0de47": {
    "text": "「今天的樹看起來有點不一樣，」她輕聲說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-6-9dc42615fb8be73d": {
    "text": "The wind blew gently.\nThe leaves made a soft sound.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-6-f6ab8fd97c66d51b": {
    "text": "微風吹過。\n樹葉發出沙沙聲。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-7-c1085d02e1ac6a86": {
    "text": "Lily took a small step forward.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-7-250aded176df0ce2": {
    "text": "莉莉往前走了一小步。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-8-8d6a2223e62f3981": {
    "text": "Then another.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-8-a4aee4b279f0eab4": {
    "text": "又走了一步。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-9-37ec757b21321518": {
    "text": "Soon, she was inside the forest.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-9-031615b9defbf205": {
    "text": "很快地，她已經走進森林裡。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-10-a9fbd637ee7d66d9": {
    "text": "It felt quiet.\nVery quiet.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-10-fdf1804948fc9d08": {
    "text": "這裡很安靜。\n非常安靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-11-0b0a6bb4489b7587": {
    "text": "“Hello?” Lily called.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-11-ae9d0c058cbdd786": {
    "text": "「有人嗎？」莉莉喊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-12-55150432712f8cde": {
    "text": "No one answered.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-12-1d7841f862b8a2a0": {
    "text": "沒有人回答。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-13-7ae35f30e86d0b80": {
    "text": "She walked deeper and deeper.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-13-aef334d42a06f231": {
    "text": "她越走越深。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-14-bc30f1a485d6b02a": {
    "text": "Suddenly—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-14-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-15-c18ba1033b9cb7bd": {
    "text": "“Hello…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-15-3a901d4dd265e1f1": {
    "text": "「哈囉……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-16-81c375aa7ad379ac": {
    "text": "Lily stopped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-16-e2fd6f400c488be5": {
    "text": "莉莉停住了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-17-a57e06f2d2b2aaca": {
    "text": "Her heart started beating fast.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-17-829b72f271efb9dc": {
    "text": "她的心跳變快。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-18-ccf85ce1543bc368": {
    "text": "“Who… who is there?” she asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-18-324c8c1fb398eb4b": {
    "text": "「誰…誰在那裡？」她問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-19-61be736565970e64": {
    "text": "The voice came again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-19-f4dd4a7809b8310d": {
    "text": "聲音再次出現。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-20-566c9f2eeb2d6955": {
    "text": "“Over here…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-20-f3f1d38fcdb8820b": {
    "text": "「在這裡……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-21-21fd3c210d4b5776": {
    "text": "Lily looked around.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-21-440eb415afcaaef3": {
    "text": "莉莉四處看。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-22-6828da277b08adec": {
    "text": "Then she saw it.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-22-7ec09bed5a2ebc7f": {
    "text": "然後她看見了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-23-25cb011ac9be1b80": {
    "text": "A big tree.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-23-aab35d9ebd14dbfd": {
    "text": "一棵大樹。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-24-e566eeab03d2a3f5": {
    "text": "But it was not a normal tree.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-24-35d5481c8f3f9984": {
    "text": "但那不是普通的樹。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-25-7f436543bf872e2d": {
    "text": "Its leaves were glowing.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-25-39a9181bce5f7b9f": {
    "text": "它的葉子在發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-26-26734eff85da567a": {
    "text": "Soft green light shined like stars.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-26-a45484cfb5dd691a": {
    "text": "柔和的綠光像星星一樣閃耀。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-27-4ea2cd0163aa6646": {
    "text": "Lily walked closer.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-27-8d0d5e8087a89100": {
    "text": "莉莉走近。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-28-d614db7f67fa7f37": {
    "text": "“You can hear me, right?” said the tree.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-28-1ea88b51ffc21021": {
    "text": "「你聽得到我，對嗎？」樹說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-29-8b53376a892fa6ab": {
    "text": "Lily opened her mouth.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-29-2070d87aa90dbe81": {
    "text": "莉莉張大嘴巴。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-30-146667302942d9ee": {
    "text": "“You… you are talking?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-30-db2f19132c198ebe": {
    "text": "「你…你在說話？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-31-4dd6d61184af3350": {
    "text": "“Yes,” the tree said kindly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-31-cd593fc6b1909c1c": {
    "text": "「是的，」樹溫柔地說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-32-81342080cf8d6edc": {
    "text": "“My name is Elder Tree.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-32-6eb6f7e2607cc96b": {
    "text": "「我叫長老樹。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-33-c35c3d8656a8d757": {
    "text": "Lily felt surprised, but also excited.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-33-1deec03e3917f1c6": {
    "text": "莉莉感到驚訝，也很興奮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-34-34fedebf77ebe8cc": {
    "text": "“I’m Lily,” she said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-34-691185339a46229b": {
    "text": "「我叫莉莉，」她說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-35-e9dae1a91cd08dce": {
    "text": "The tree’s leaves moved slowly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-35-935d462286b93bfa": {
    "text": "樹葉輕輕擺動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-36-a01aebb90d3f5435": {
    "text": "“Lily… I have been waiting for you.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-36-a6d145ff8923c13d": {
    "text": "「莉莉……我一直在等你。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-37-2866b6a2c070abf2": {
    "text": "“Waiting for me?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-37-fd513219b6122460": {
    "text": "「等我？」莉莉問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-38-036fb49851fe1f9d": {
    "text": "“Yes,” said the tree.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-38-d62fa7225e364848": {
    "text": "「是的，」樹說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-39-3496c89be2e4caf3": {
    "text": "“The forest needs your help.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-39-80a4a567417e41da": {
    "text": "「森林需要你的幫助。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-40-21fd3c210d4b5776": {
    "text": "Lily looked around.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-40-393fe1e5e9881baf": {
    "text": "莉莉環顧四周。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-41-187a8221f5994072": {
    "text": "She noticed something strange.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-41-382f1a9e15f8c0e9": {
    "text": "她發現一些奇怪的事。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-42-b594660899ac18fa": {
    "text": "Some trees looked darker.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-42-1e123d4f84727a2b": {
    "text": "有些樹變得比較暗。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-43-6fab4cced550598e": {
    "text": "Some flowers were closed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-43-e843d70e0d831232": {
    "text": "有些花都閉起來了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-44-957a22a727e63bb6": {
    "text": "“What happened?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-44-de0e6c33e76fee43": {
    "text": "「發生什麼事？」她問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-45-acbdc6993350f59d": {
    "text": "The tree spoke slowly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-45-39ce867ad7eccf85": {
    "text": "樹慢慢說：",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-46-b963b5e1e2141116": {
    "text": "“A dark shadow came to this forest.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-46-c9c3cdbcfb4f6591": {
    "text": "「有一個黑暗的影子來到森林。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-47-9fc9a9f59fa327ac": {
    "text": "“It is taking away our magic.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-47-34bc19d92ffcbf01": {
    "text": "「它正在奪走我們的魔法。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-48-dc8b7b98228ef4e4": {
    "text": "Lily felt a little scared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-48-611c5243ba205e8e": {
    "text": "莉莉有點害怕。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-49-d830e0fbe8c70860": {
    "text": "“A shadow?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-49-323663e448e5a104": {
    "text": "「影子？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-50-036fb49851fe1f9d": {
    "text": "“Yes,” said the tree.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-50-d62fa7225e364848": {
    "text": "「是的，」樹說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-51-43fd45a0ab9f322e": {
    "text": "“It hides in the deeper forest.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-51-395061d5ee203d15": {
    "text": "「它躲在更深的森林裡。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-52-7ad3dee7378827cc": {
    "text": "Lily thought for a moment.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-52-15510420a2bdee21": {
    "text": "莉莉想了一下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-53-dd8875fd4e1aac67": {
    "text": "“Can I help?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-53-ee843b40e18f0baf": {
    "text": "「我可以幫忙嗎？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-54-9714bf11ab203eb1": {
    "text": "The tree glowed brighter.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-54-bbcdc0054e5257e4": {
    "text": "樹發出更亮的光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-55-4e1e5eb65dc0bdcb": {
    "text": "“You are brave.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-55-86c5d69e2a0edb9f": {
    "text": "「你很勇敢。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-56-2912e03f971f82e9": {
    "text": "“It chose you.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-56-0129f30e6001b15c": {
    "text": "「它選擇了你。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-57-9c4a5e0137dc0707": {
    "text": "“It?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-57-0eebf9bca0986bf6": {
    "text": "「它？」莉莉問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-58-6544e0250c370424": {
    "text": "The tree dropped a small shining leaf.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-58-ca82bc83daf2e398": {
    "text": "樹掉下一片發光的葉子。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-59-7559aa295d0ad98e": {
    "text": "“This is the Light Leaf.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-59-6cc5b89f4c85c1cc": {
    "text": "「這是光之葉。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-60-425449305730bd64": {
    "text": "“It will guide you.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-60-2f874e7a98cc4118": {
    "text": "「它會指引你。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-61-b577abb0f2117621": {
    "text": "Lily picked it up.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-61-7155e3aac6716d90": {
    "text": "莉莉撿起來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-62-4943f090aa590229": {
    "text": "It felt warm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-62-51303376992c176b": {
    "text": "葉子暖暖的。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-63-b47537680eafaa55": {
    "text": "“What should I do?” she asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-63-f66183653b000c25": {
    "text": "「我該怎麼做？」她問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-64-453ef89074c6f731": {
    "text": "“Follow the light,” said the tree.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-64-98984ed7089c7b5a": {
    "text": "「跟著光走，」樹說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-65-35cedc48b2d2511a": {
    "text": "“And trust your heart.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-65-9fcd56baa809f072": {
    "text": "「相信你的心。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-66-3277daceb33d2b50": {
    "text": "Lily nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-66-81f695577409d703": {
    "text": "莉莉點點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-67-22cd7623837946c6": {
    "text": "“Okay… I will try.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-67-e87f5cadbbd84ca6": {
    "text": "「好……我會試試看。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-68-e33dc3ab9713c146": {
    "text": "She turned around.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-68-e61d61fc628412bd": {
    "text": "她轉身。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-69-e2af642b7a7d5ef7": {
    "text": "Step by step, she walked deeper into the forest.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-69-dd95ff39668b55d9": {
    "text": "一步一步走向森林更深處。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c1-en-block-70-225ef95c20162064": {
    "text": "Her adventure had begun.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c1-zh-block-70-9894612f720bded0": {
    "text": "她的冒險，開始了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-title-e5aedfbd66600129": {
    "text": "The Little Fairy",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-title-72fca1d10aa2931d": {
    "text": "小精靈",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-0-d73ed67896835457": {
    "text": "Lily followed the Light Leaf.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-0-568239184fd3fe7c": {
    "text": "莉莉跟著光之葉前進。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-1-bf67ae0307034841": {
    "text": "The leaf floated in front of her.\nIt moved slowly through the trees.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-1-e4ec14ae4dc575f4": {
    "text": "光之葉漂浮在她前方。\n它慢慢穿過樹林。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-2-535ab8c258589117": {
    "text": "Sometimes it went left.\nSometimes it went right.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-2-68c98cc34dd72ff7": {
    "text": "有時往左。\n有時往右。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-3-72734922388dc100": {
    "text": "Lily held her school bag tightly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-3-61d68a1d5cd58058": {
    "text": "莉莉緊緊抱著書包。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-4-aaf291b10ff8eca1": {
    "text": "“I hope I am going the right way,” she said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-4-b2a62840ff25706b": {
    "text": "「希望我走的方向是對的，」她說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-5-e3fc5a7c9c579835": {
    "text": "The forest became darker.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-5-97b9c2ae82b50c9f": {
    "text": "森林變得更暗了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-6-890449fcd5e7548d": {
    "text": "The trees were taller here.\nTheir branches looked like long arms.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-6-4a756ab6dffe95ae": {
    "text": "這裡的樹更高。\n它們的樹枝看起來像長長的手臂。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-7-0e700ddcda766798": {
    "text": "Lily heard a tiny sound.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-7-eb3dc066bf46b7fd": {
    "text": "莉莉聽見一個很小的聲音。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-8-74608c32a3b0291e": {
    "text": "“Help! Help!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-8-7c429e72d64c1e89": {
    "text": "「救命！救命！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-9-193895015d0dedd7": {
    "text": "She stopped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-9-60d10c5032f2d6a7": {
    "text": "她停下腳步。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-10-061c1d5fe19958f4": {
    "text": "“Who is calling?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-10-51a965dc9c434d20": {
    "text": "「是誰在呼救？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-11-d7433d536a5da450": {
    "text": "“Down here!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-11-0551e6b21c459aec": {
    "text": "「在下面！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-12-33085699acba98c4": {
    "text": "Lily looked down.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-12-c55e83f39a6f0277": {
    "text": "莉莉低頭看。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-13-66056fe1f5cfdea6": {
    "text": "Under a big mushroom, she saw something small.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-13-f435d209f89ea330": {
    "text": "在一朵大蘑菇下面，她看到一個小小的東西。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-14-ff9855aa55136cd9": {
    "text": "It was a little fairy.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-14-851aaab1d1f0632d": {
    "text": "那是一個小精靈。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-15-c43b59792b319b1b": {
    "text": "The fairy had blue wings.\nHer dress looked like a flower petal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-15-da1e1e6874d316a3": {
    "text": "小精靈有藍色的翅膀。\n她的裙子看起來像花瓣。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-16-9bde2ef898fc6221": {
    "text": "“Oh!” Lily said.\n“Are you okay?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-16-cd9429c1ef115e42": {
    "text": "「啊！」莉莉說。\n「你還好嗎？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-17-8337c0e69ee344a3": {
    "text": "The fairy was stuck under a fallen twig.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-17-b3ad339c529f0927": {
    "text": "小精靈被一根掉下來的小樹枝壓住了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-18-69b1546537bb8fc3": {
    "text": "Lily quickly lifted the twig.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-18-1a0b92fd9b76cc81": {
    "text": "莉莉立刻把樹枝抬起來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-19-90ab77d5232b542f": {
    "text": "The fairy flew up.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-19-029e0f0b69672ae6": {
    "text": "小精靈飛了起來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-20-5834da512e7d6b64": {
    "text": "“Thank you!” she said.\n“My name is Coco.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-20-2e50e4cb65c6cf32": {
    "text": "「謝謝你！」她說。\n「我叫可可。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-21-a7b6f9a97a569e19": {
    "text": "“I’m Lily,” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-21-cbec5ea37d54e7ab": {
    "text": "「我叫莉莉，」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-22-9d9497ee2e90b629": {
    "text": "Coco looked at the glowing leaf.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-22-cbbb5c3ada32e351": {
    "text": "可可看著發光的葉子。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-23-f48023bf16fdc452": {
    "text": "“You have the Light Leaf!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-23-128494920bdab040": {
    "text": "「你有光之葉！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-24-3277daceb33d2b50": {
    "text": "Lily nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-24-81f695577409d703": {
    "text": "莉莉點點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-25-ebe1de45ad0ce0da": {
    "text": "“The Elder Tree gave it to me.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-25-f5e2fd38d8433143": {
    "text": "「長老樹給我的。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-26-e304668f892a5d50": {
    "text": "Coco’s eyes became wide.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-26-4a423796599aa6ad": {
    "text": "可可睜大眼睛。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-27-23ef77a8d21a9f0c": {
    "text": "“Then you are the helper!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-27-dfcb44d5439d4e4d": {
    "text": "「那你就是幫助者！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-28-39482b8f626e01d4": {
    "text": "“I think so,” Lily said.\n“But I don’t really know what to do.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-28-9a88f7e95c3adbe9": {
    "text": "「我想是吧，」莉莉說。\n「但我其實不知道該做什麼。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-29-0c94b9770c6291f3": {
    "text": "Coco flew around Lily happily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-29-d6370a6dca2e5b9f": {
    "text": "可可開心地繞著莉莉飛。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-30-5e21f8a27d03c910": {
    "text": "“I can help you!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-30-3409b1163de63dcd": {
    "text": "「我可以幫你！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-31-9eb441354727725a": {
    "text": "“You know this forest?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-31-d29600d36cbd0a27": {
    "text": "「你認識這座森林嗎？」莉莉問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-32-436813776c664ce5": {
    "text": "“Yes!” said Coco.\n“I know the flower paths, the moon ponds, and the whispering stones.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-32-fa6be010f531e925": {
    "text": "「當然！」可可說。\n「我知道花之小路、月亮池，還有會低語的石頭。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-33-408431a6b8a3bcf2": {
    "text": "“Do you know about the dark shadow?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-33-53b06fcf018cbf80": {
    "text": "「你知道黑暗影子的事嗎？」莉莉問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-34-924ea026cc89f9da": {
    "text": "Coco’s smile disappeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-34-19f08ed1e8a51b3b": {
    "text": "可可的笑容消失了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-35-68301b472356f283": {
    "text": "“Yes,” she said quietly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-35-ee1dc4e7aa4c9820": {
    "text": "「知道，」她小聲說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-36-4f306fb41c232947": {
    "text": "“The shadow came three nights ago.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-36-bffeaed764cf04a3": {
    "text": "「黑影三個晚上前來到這裡。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-37-84f2f49d589729d9": {
    "text": "“It touched the flowers.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-37-8338626bb2520abb": {
    "text": "「它碰了花朵。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-38-e856155cc587b523": {
    "text": "“Then the flowers lost their colors.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-38-6276078e05e7291d": {
    "text": "「然後花朵失去了顏色。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-39-4439beab5a37622d": {
    "text": "“It touched the river.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-39-b08f8aa45727dc3d": {
    "text": "「它碰了河流。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-40-f15565457c2cecf8": {
    "text": "“Then the river stopped singing.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-40-9033a93ad67c4172": {
    "text": "「然後河流不再歌唱。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-41-a649d38663d0c4bc": {
    "text": "Lily looked sad.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-41-363aedaa99de34a5": {
    "text": "莉莉看起來很難過。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-42-3f5a2db0341eb55d": {
    "text": "“That is terrible.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-42-d0bac9e1f3f85f6b": {
    "text": "「那太可怕了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-43-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-43-df4dc167277b509c": {
    "text": "可可點點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-44-9e9ea3bf1e6bcd09": {
    "text": "“The shadow is looking for the Star Crystal.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-44-64d12ca468baec74": {
    "text": "「黑影正在尋找星之水晶。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-45-44c42151c61a5ccb": {
    "text": "“What is the Star Crystal?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-45-dfaf25141784a730": {
    "text": "「星之水晶是什麼？」莉莉問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-46-225f3598d5b93be8": {
    "text": "“It is the heart of the forest,” Coco said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-46-cddb6587eb4161bf": {
    "text": "「它是森林的心，」可可說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-47-c14494a559378542": {
    "text": "“It gives magic to every tree, flower, and animal.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-47-54af385c914f0407": {
    "text": "「它把魔法給每一棵樹、每一朵花、每一隻動物。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-48-ecf5a2c3f7e554d7": {
    "text": "“If the shadow takes it, the forest will become silent forever.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-48-233431cc39d31643": {
    "text": "「如果黑影拿走它，森林就會永遠變得安靜。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-49-2e768ac78482940a": {
    "text": "Lily held the Light Leaf closer.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-49-9b9b07fdb701b5e8": {
    "text": "莉莉把光之葉握得更緊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-50-9af2b1a2baa9cf53": {
    "text": "“Then we must stop it.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-50-070437ffecdfc522": {
    "text": "「那我們一定要阻止它。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-51-f62ef0473aef97ec": {
    "text": "Coco smiled again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-51-8072260753b7c07f": {
    "text": "可可又露出笑容。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-52-5f2f4e900bfb867c": {
    "text": "“Yes!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-52-20cbb294fe855c44": {
    "text": "「沒錯！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-53-ecbe901b77fe3362": {
    "text": "“But first, we need to find the Moon Key.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-53-04b98cb536e41cdf": {
    "text": "「但首先，我們要找到月之鑰匙。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-54-5a132656c2c413c6": {
    "text": "“The Moon Key?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-54-9271af2a20d184ff": {
    "text": "「月之鑰匙？」莉莉問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-55-609a1423102a39b3": {
    "text": "Coco pointed to a path covered with silver flowers.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-55-98419f1e82e7655c": {
    "text": "可可指向一條鋪滿銀色花朵的小路。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-56-f40d05690d7ba837": {
    "text": "“The Moon Key opens the gate to the old cave.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-56-d0b45175cfc7b3f5": {
    "text": "「月之鑰匙可以打開通往古老洞穴的門。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-57-27c2ced367db7f85": {
    "text": "“The shadow is hiding near that cave.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-57-52d82fafd9ad56cb": {
    "text": "「黑影就躲在那座洞穴附近。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-58-9171add57611a9cf": {
    "text": "Lily took a deep breath.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-58-2e8f4fdc6cbf9c7a": {
    "text": "莉莉深吸一口氣。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-59-e5476541b7967c82": {
    "text": "“Okay. Let’s find the Moon Key.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-59-7d715b7c02510609": {
    "text": "「好，我們去找月之鑰匙。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-60-15342735f22fda2b": {
    "text": "Coco flew beside her.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-60-dc53abc65eb49ae4": {
    "text": "可可飛在她旁邊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-61-24fe730fa76d0b6b": {
    "text": "“Follow me!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-61-66778acf997da958": {
    "text": "「跟我來！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-62-818f029ed01ea940": {
    "text": "They walked along the silver flower path.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-62-3fdf23079f0e7bdc": {
    "text": "她們沿著銀色花朵小路前進。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-63-8e64044fc4c58da2": {
    "text": "The flowers gave a soft light.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-63-74ff8b77feeadd02": {
    "text": "花朵散發柔和的光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-64-e0f16956f6310d96": {
    "text": "Lily felt less afraid now.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-64-cd39174abedafdfe": {
    "text": "莉莉現在比較不害怕了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c2-en-block-65-fa509fb6b98b9ca8": {
    "text": "She was not alone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c2-zh-block-65-773733bb058ddeb6": {
    "text": "因為她不再是一個人。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-title-413b734b3a83b55b": {
    "text": "The Singing River",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-title-93934cb05847be3f": {
    "text": "會唱歌的河流",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-0-aae6f6e3eddba329": {
    "text": "Lily and Coco walked for a long time.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-0-ca7c02b06bcd8305": {
    "text": "莉莉和可可走了很久。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-1-bdec85063e34611c": {
    "text": "The silver flowers slowly disappeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-1-56005be2ce7b3b13": {
    "text": "銀色花朵慢慢消失。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-2-66a30e20dc7740c0": {
    "text": "Soon, they came to a river.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-2-8924fd0e73fdc104": {
    "text": "不久，她們來到一條河邊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-3-ea35d722262e185e": {
    "text": "But this river was different.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-3-0e01c847a3b38e1e": {
    "text": "但這條河很不一樣。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-4-cd633d0e7040a89c": {
    "text": "The water did not move.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-4-768a37767f8b68b8": {
    "text": "河水沒有流動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-5-12fe7b29743405d2": {
    "text": "It was still and gray.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-5-03fed5d02fbf8202": {
    "text": "它靜靜的，灰灰的。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-6-c38b63e57d592859": {
    "text": "Coco landed on a small stone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-6-340cf6e47e4f0826": {
    "text": "可可停在一顆小石頭上。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-7-507466e7fdb66b2c": {
    "text": "“This is the Singing River,” she said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-7-599af379dbb2d8ce": {
    "text": "「這是會唱歌的河流，」她說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-8-c6fead173da39bb6": {
    "text": "Lily listened carefully.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-8-216fc0fc2bc1cb84": {
    "text": "莉莉仔細聽。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-9-bab4862953e4c26a": {
    "text": "“I don’t hear any singing.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-9-f329b271ee950b44": {
    "text": "「我沒有聽到歌聲。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-10-e9c93ad5d1864b99": {
    "text": "Coco looked sad.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-10-c38819fbf5cca60d": {
    "text": "可可看起來很難過。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-11-6927c7a5e2d915c8": {
    "text": "“It used to sing every morning.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-11-7281d42556fdef99": {
    "text": "「它以前每天早上都會唱歌。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-12-71eac42e9d8d1178": {
    "text": "“The song helped flowers grow.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-12-7f8c7e58762a4974": {
    "text": "「歌聲幫助花朵成長。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-13-0857194f462d89b1": {
    "text": "“The song helped birds find their way.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-13-792c99a78b4d8a28": {
    "text": "「歌聲幫助鳥兒找到方向。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-14-c6efe7e891edbc2d": {
    "text": "“But now it is silent.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-14-10928602d1939d70": {
    "text": "「但現在它沉默了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-15-6827598f0f218cd3": {
    "text": "Lily walked closer to the river.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-15-c268b12e386d22d7": {
    "text": "莉莉走近河邊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-16-76e035029ff4eedf": {
    "text": "The Light Leaf began to glow.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-16-3d764c6c7c223e90": {
    "text": "光之葉開始發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-17-74f9bb34c30e823e": {
    "text": "“It is showing us something,” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-17-9319f5b0e70920e9": {
    "text": "「它在給我們看什麼，」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-18-04a4f6a34905c1e0": {
    "text": "The leaf floated above the water.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-18-6ceac26fee614ebf": {
    "text": "葉子漂浮在水面上。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-19-1eec140b2bca46e3": {
    "text": "Then a picture appeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-19-e13b6a43952f873e": {
    "text": "接著，一幅畫面出現了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-20-2596cadb5b7b53e3": {
    "text": "Lily saw the dark shadow.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-20-34e43d9b2a055354": {
    "text": "莉莉看見黑暗影子。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-21-d1281d3355d34840": {
    "text": "It was tall and smoky.\nIts eyes glowed purple.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-21-d69ded511abc6acf": {
    "text": "它又高又像煙霧。\n它的眼睛發出紫色光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-22-198710979d1e90e9": {
    "text": "The shadow touched the river.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-22-e6abad2a56cdd592": {
    "text": "黑影碰了河流。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-23-b53cfed63199be01": {
    "text": "The river became gray.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-23-908a080f41f0c2a7": {
    "text": "河流變成灰色。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-24-df7492c918226b63": {
    "text": "Then something shiny fell into the water.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-24-bb9437e5361942db": {
    "text": "然後有個閃亮的東西掉進水裡。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-25-55993fb0fdd0ccbf": {
    "text": "“What was that?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-25-9d80e0dc3d300c46": {
    "text": "「那是什麼？」莉莉問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-26-dc56953f50338d95": {
    "text": "Coco looked closely.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-26-2eef57de289a3510": {
    "text": "可可仔細看。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-27-7de7ccee800a84f9": {
    "text": "“That is a River Bell!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-27-b6d4a949f05f949d": {
    "text": "「那是河之鈴！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-28-aba68b65ce6590a9": {
    "text": "“A River Bell?” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-28-8e90d160b2e74440": {
    "text": "「河之鈴？」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-29-3b24314064db7a33": {
    "text": "“Yes. The river cannot sing without its bell.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-29-4a67359f85daebdd": {
    "text": "「是的。沒有它，河流就不能唱歌。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-30-1a73b988c3287bf1": {
    "text": "“Where is it now?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-30-d42be91c41f568f8": {
    "text": "「它現在在哪裡？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-31-fafc5ccf66083f8f": {
    "text": "Coco pointed to the deep water.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-31-a7a5b803f87c1589": {
    "text": "可可指向深水處。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-32-1bf8afc4839e4623": {
    "text": "“At the bottom.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-32-5e929d784335817c": {
    "text": "「在河底。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-33-1fff08b8bbb894e3": {
    "text": "Lily looked worried.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-33-43a19cd1a0972813": {
    "text": "莉莉看起來很擔心。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-34-2a97ca91496bc584": {
    "text": "“I don’t know how to dive very well.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-34-af166b3d3da823fa": {
    "text": "「我不太會潛水。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-35-60045d1d1314e24c": {
    "text": "Just then, a small green frog jumped onto a rock.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-35-36d9c7d8bced0776": {
    "text": "就在這時，一隻小綠青蛙跳到石頭上。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-36-074955c4579d5fc1": {
    "text": "“Ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-36-8a51de2c2468d300": {
    "text": "「呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-37-e5b319b942d419b8": {
    "text": "Coco smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-37-ae4ca75292a57e96": {
    "text": "可可笑了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-38-e1167d2ea8e483f5": {
    "text": "“This is Prince Pebble.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-38-5aa679eddf0b8db7": {
    "text": "「這是卵石王子。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-39-b792b46a41cee3be": {
    "text": "Lily blinked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-39-2403a9ac01037b55": {
    "text": "莉莉眨了眨眼。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-40-42646b13642032a7": {
    "text": "“A frog prince?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-40-4a46a9b50584e44e": {
    "text": "「青蛙王子？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-41-15568a0ca6ae98f3": {
    "text": "The frog bowed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-41-ff96eda85cacebba": {
    "text": "青蛙鞠了一個躬。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-42-997f9adac3497758": {
    "text": "“Ribbit ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-42-3a2bd7c6fcd9fca1": {
    "text": "「呱呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-43-c3d80aa1f1dde128": {
    "text": "Coco laughed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-43-ae4ca75292a57e96": {
    "text": "可可笑了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-44-14f87202857f3583": {
    "text": "“He cannot speak human words, but he understands us.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-44-d3ad6ee8f66b27a3": {
    "text": "「牠不能說人類的話，但牠聽得懂我們。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-45-38930ed2ce1c7cb5": {
    "text": "Prince Pebble jumped into the river.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-45-b4e38b0cf3ab11e9": {
    "text": "卵石王子跳進河裡。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-46-cbb20538fdfd5983": {
    "text": "But he came back quickly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-46-d660a336bccf0ef8": {
    "text": "但牠很快又跳回來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-47-74b773edf32af623": {
    "text": "He shook his head.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-47-f63774f2e6537be4": {
    "text": "牠搖搖頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-48-b6c23d2845d99961": {
    "text": "Coco frowned.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-48-ff8b94dcc7c2ed29": {
    "text": "可可皺眉。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-49-e2ff6e28c769494a": {
    "text": "“The water is too cold and too dark.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-49-e1bc2f10273ed48c": {
    "text": "「水太冷，也太暗了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-50-704c358c9bc1e40b": {
    "text": "Lily thought hard.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-50-b446086c60e82fb7": {
    "text": "莉莉努力思考。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-51-245513bdc1b41a9d": {
    "text": "“There must be another way.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-51-ee13cfd91f3f0732": {
    "text": "「一定還有別的方法。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-52-ee7e76f4b0e8fa50": {
    "text": "She opened her school bag.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-52-f1ed45263d1a3a0a": {
    "text": "她打開書包。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-53-16cdd000dac5fddb": {
    "text": "Inside, she had a pencil, a ruler, a lunch box, and a red ribbon.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-53-9c4c6437ac35fad6": {
    "text": "裡面有鉛筆、尺、便當盒，還有一條紅色緞帶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-54-d72c9f548d198218": {
    "text": "Lily picked up the ribbon.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-54-7207a562183d6001": {
    "text": "莉莉拿起緞帶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-55-f6aadecc6132584d": {
    "text": "“Maybe we can use this.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-55-354d95576107de82": {
    "text": "「也許我們可以用這個。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-56-9e2c8d9943b18c05": {
    "text": "She tied the ribbon to a long branch.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-56-96fb46cdec3b486a": {
    "text": "她把緞帶綁在一根長樹枝上。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-57-f13e3096bcf18fe7": {
    "text": "Then she lowered it into the river.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-57-889dfe7b9a0932c2": {
    "text": "然後慢慢把它放進河裡。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-58-ba32e09393fd1e66": {
    "text": "The Light Leaf floated above the water and shined brightly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-58-f3ef1dc2676ac8e7": {
    "text": "光之葉漂浮在水面上，發出明亮的光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-59-ed07753ba57326c5": {
    "text": "A small bell began to sparkle below.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-59-02a51f7b0002ad5e": {
    "text": "水底有一個小鈴鐺開始閃光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-60-8e1b9da85bec2469": {
    "text": "“I see it!” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-60-a4031ca2af6c8253": {
    "text": "「我看到了！」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-61-df36c628308a2d69": {
    "text": "She moved the branch carefully.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-61-c3590a02e5deed47": {
    "text": "她小心地移動樹枝。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-62-4a0eca367c24789c": {
    "text": "The ribbon caught the bell.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-62-fbd87e67f79d8788": {
    "text": "緞帶勾住了鈴鐺。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-63-cc85f52a11a97d1f": {
    "text": "Slowly, Lily pulled it up.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-63-a646166591795081": {
    "text": "莉莉慢慢把它拉上來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-64-5dc468b7ddbdc142": {
    "text": "The bell was silver.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-64-8bdc34a1e12b4bd7": {
    "text": "鈴鐺是銀色的。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-65-e1539079916fc0e5": {
    "text": "It rang softly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-65-9cd877bbbb15bfbe": {
    "text": "它輕輕響著。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-66-e2943034d3c381f3": {
    "text": "Ding… ding…",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-66-ac45a6cd8c415e32": {
    "text": "叮……叮……",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-67-e93998bd8ddf1c20": {
    "text": "Suddenly, the river began to move.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-67-c6f3439997ac61e1": {
    "text": "突然，河水開始流動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-68-e964efcb93f549d7": {
    "text": "The gray color disappeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-68-081b0a3d729a2076": {
    "text": "灰色消失了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-69-b6e4a37a33a8f03e": {
    "text": "The water turned blue again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-69-3ae480f354c1aa6b": {
    "text": "河水又變回藍色。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-70-e0f38d71f1d1bead": {
    "text": "Then the river started to sing.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-70-933c568f150772c6": {
    "text": "接著，河流開始唱歌。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-71-04a2dd004d7f8e7e": {
    "text": "La la la…\nLa la la…",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-71-2f46e4cf369af9e2": {
    "text": "啦啦啦……\n啦啦啦……",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-72-1de49784503e18ca": {
    "text": "Flowers opened along the riverbank.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-72-ee961a12292f3653": {
    "text": "河岸邊的花朵都開了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-73-6855a12e22f3d4eb": {
    "text": "Birds flew back to the trees.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-73-3d781819650aeb4e": {
    "text": "鳥兒飛回樹上。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-74-35331124bcf92675": {
    "text": "Coco clapped her hands.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-74-169a6e95264f415a": {
    "text": "可可拍手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-75-d5bf37ee151f142e": {
    "text": "“You did it, Lily!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-75-e4f24e1ec16680f8": {
    "text": "「你成功了，莉莉！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-76-98b0f90a593f7dad": {
    "text": "Lily smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-76-65c8ac423228dec4": {
    "text": "莉莉微笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-77-4caac34639f49723": {
    "text": "“We did it together.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-77-36d66d7d4f1e330d": {
    "text": "「是我們一起成功的。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-78-ebdb827bfd085288": {
    "text": "Prince Pebble jumped happily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-78-8dd8a3b20930d87c": {
    "text": "卵石王子開心地跳來跳去。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-79-074955c4579d5fc1": {
    "text": "“Ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-79-8a51de2c2468d300": {
    "text": "「呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-80-04e8f451fbc5556c": {
    "text": "The river made a small wave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-80-bd8b09e0599c7a37": {
    "text": "河流捲起一朵小浪花。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-81-1d55659dd5956b99": {
    "text": "In the wave, something bright appeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-81-bf087448a9c4d436": {
    "text": "浪花中出現一個明亮的東西。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-82-584a13035d51bdd4": {
    "text": "It was a small moon-shaped stone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-82-42ec858233242bd5": {
    "text": "那是一顆月亮形狀的小石頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-83-c09bf67fff90fba3": {
    "text": "Coco gasped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-83-7d7844abab0eca64": {
    "text": "可可驚呼。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-84-c19b9415fbc86a39": {
    "text": "“The first piece of the Moon Key!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-84-d63cd46c431f4731": {
    "text": "「月之鑰匙的第一塊！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-85-b577abb0f2117621": {
    "text": "Lily picked it up.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-85-14182ee81ada1e1c": {
    "text": "莉莉把它撿起來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-86-71c5355ecb995d57": {
    "text": "“One piece?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-86-acdfc273cd6084ba": {
    "text": "「第一塊？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-87-40b96ae8dca4a21b": {
    "text": "“Yes,” Coco said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-87-f80cebbb0133d535": {
    "text": "「是的，」可可說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-88-238e931a5494f17a": {
    "text": "“The Moon Key has three pieces.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-88-81aa9b0b3ed97fe0": {
    "text": "「月之鑰匙有三塊。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-89-0594f749d5211ff8": {
    "text": "“To find the old cave, we need all three.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-89-3b0ce4ad3e24a57c": {
    "text": "「要找到古老洞穴，我們需要全部三塊。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-90-7d572bba2d447d64": {
    "text": "Lily looked at the path ahead.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-90-759986f95b3fd9bd": {
    "text": "莉莉看向前方的小路。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-91-9c0556045c94305c": {
    "text": "“Then let’s find the next piece.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-91-798017e36ad565bd": {
    "text": "「那我們去找下一塊吧。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-92-5f57b0eb6cd3fb9f": {
    "text": "The Light Leaf floated forward.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-92-446198b51ee43ce1": {
    "text": "光之葉向前飄去。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c3-en-block-93-20922f91b25c58b3": {
    "text": "And Lily followed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c3-zh-block-93-84c567f2f60fec0e": {
    "text": "莉莉也跟著前進。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-title-1a2c56d17ef8c087": {
    "text": "The Whispering Stones",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-title-6b2ac358c21ce758": {
    "text": "低語之石",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-0-335120c68044a31c": {
    "text": "Lily, Coco, and Prince Pebble continued their journey.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-0-3edd2e29d7e0c753": {
    "text": "莉莉、可可和卵石王子繼續前進。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-1-8d6fab4aedc47481": {
    "text": "The forest became quieter.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-1-eec6d7db7c8cd43f": {
    "text": "森林變得更安靜了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-2-f68ec14fe6a4c905": {
    "text": "The trees were older here.\nTheir trunks were thick and twisted.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-2-fead7cb521e325ee": {
    "text": "這裡的樹更老。\n樹幹又粗又彎曲。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-3-b8bd0024fe463b22": {
    "text": "The Light Leaf floated slowly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-3-ce09b3a0592e2782": {
    "text": "光之葉慢慢飄著。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-4-dadcd4b1edc32718": {
    "text": "“This place feels strange,” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-4-feb3b808391389c5": {
    "text": "「這個地方感覺怪怪的，」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-5-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-5-df4dc167277b509c": {
    "text": "可可點點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-6-394ce25ac1b0b3a9": {
    "text": "“This is the Whispering Stone Field.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-6-f02c8dc472946449": {
    "text": "「這裡是低語之石區。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-7-727d156580833d1d": {
    "text": "They walked into an open area.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-7-e7ef482cd076452f": {
    "text": "她們走進一個空地。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-8-37e7d0ad39c2663c": {
    "text": "Many stones stood on the ground.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-8-25f3d13cc270132c": {
    "text": "地上有很多石頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-9-78c197bce0b6ee66": {
    "text": "Some were tall.\nSome were small.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-9-650228b3aa9205b9": {
    "text": "有的很高。\n有的很小。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-10-519947f0470fbeb6": {
    "text": "All of them were covered with glowing lines.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-10-1dfecad5469f0cad": {
    "text": "全部都刻著發光的紋路。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-11-48cdceb5e0e1cf46": {
    "text": "“What are these?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-11-cbf5dafeea9e3405": {
    "text": "「這些是什麼？」莉莉問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-12-2996dcfbc90ec0b0": {
    "text": "“They are memory stones,” Coco said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-12-ae107324d9352330": {
    "text": "「它們是記憶之石，」可可說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-13-aa441e5afdc06283": {
    "text": "“They remember the past of the forest.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-13-4a72d49c654e05d5": {
    "text": "「它們記錄著森林的過去。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-14-cac8c294d1246fb8": {
    "text": "Lily walked closer to one stone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-14-0510bedecbd48ffd": {
    "text": "莉莉走近一顆石頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-15-f1037197ae4ecc6a": {
    "text": "She touched it gently.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-15-e9f137f41724c1df": {
    "text": "她輕輕摸了一下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-16-bc30f1a485d6b02a": {
    "text": "Suddenly—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-16-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-17-d8603cbf38651bf0": {
    "text": "She heard voices.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-17-732db48b64b6c427": {
    "text": "她聽到聲音。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-18-38f8f650564cfc1d": {
    "text": "Soft voices.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-18-44c5a2c917bba275": {
    "text": "很輕很輕的聲音。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-19-a80f02cf3a6c0e83": {
    "text": "“Help us…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-19-e0e5749f415a7fdd": {
    "text": "「幫助我們……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-20-bc9740b2ef069436": {
    "text": "“Find the light…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-20-d36e12540c73beab": {
    "text": "「找到光……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-21-d9a9527abbc1fb9d": {
    "text": "“Don’t trust the shadow…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-21-a7ce009bb46c8dcc": {
    "text": "「不要相信黑影……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-22-4723a3cbd7731682": {
    "text": "Lily stepped back.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-22-05a9ee59ac669df8": {
    "text": "莉莉退後一步。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-23-77cfc18d1d623f92": {
    "text": "“I can hear them!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-23-7bf3043eabd326cd": {
    "text": "「我聽得到它們！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-24-2998854483cd1c2b": {
    "text": "Coco smiled softly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-24-9b7a50ddc0d9f297": {
    "text": "可可微笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-25-1a3f9d574fdf6bc0": {
    "text": "“The stones are speaking to you.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-25-93cd79050ccacda0": {
    "text": "「石頭正在跟你說話。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-26-cbcdbf980cc1a9a8": {
    "text": "Prince Pebble jumped onto a stone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-26-5d5331f0036d9d50": {
    "text": "卵石王子跳到石頭上。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-27-074955c4579d5fc1": {
    "text": "“Ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-27-8a51de2c2468d300": {
    "text": "「呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-28-ae7a23a0403c667e": {
    "text": "The Light Leaf began to glow brighter.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-28-40de781ccaee4773": {
    "text": "光之葉開始變得更亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-29-7f093c59ab31cd8e": {
    "text": "Then, three stones lit up.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-29-2daf364f1a2db219": {
    "text": "接著，三顆石頭亮了起來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-30-2d69f286ddf28a23": {
    "text": "Each stone showed a different symbol.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-30-2501f62a47cd0ad0": {
    "text": "每顆石頭都有不同的符號。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-31-39f6822933cc482f": {
    "text": "One had a star.\nOne had a moon.\nOne had a spiral.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-31-3224b87d84f0ae12": {
    "text": "一個是星星。\n一個是月亮。\n一個是旋轉圖形。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-32-676d7fa914daf3de": {
    "text": "Coco looked serious.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-32-b5ec3022b8eff591": {
    "text": "可可表情變得認真。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-33-6f6118aec5d7ac76": {
    "text": "“This is a test.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-33-30ff1fdd56f153b0": {
    "text": "「這是一個測試。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-34-cf91e35f2683946c": {
    "text": "“A test?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-34-979b45c0aa35206b": {
    "text": "「測試？」莉莉問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-35-40b96ae8dca4a21b": {
    "text": "“Yes,” Coco said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-35-f80cebbb0133d535": {
    "text": "「是的，」可可說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-36-6b57a2f5929df052": {
    "text": "“To find the next Moon Key piece, you must choose the correct stone.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-36-bbd189b974e6fbb2": {
    "text": "「要找到下一塊月之鑰匙，你必須選對石頭。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-37-035fe8ce53910f07": {
    "text": "Lily looked at the three stones.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-37-993309d1eb51a172": {
    "text": "莉莉看著三顆石頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-38-68520633a888824d": {
    "text": "“They all look important…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-38-ed16de1193bfaaf2": {
    "text": "「看起來都很重要……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-39-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-39-51cdf3801661ec77": {
    "text": "可可點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-40-f17b69b12e4be1c6": {
    "text": "“Think carefully.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-40-bfa251dbd04ca3d0": {
    "text": "「要好好想。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-41-1fab5298dac092a0": {
    "text": "Lily walked slowly from one stone to another.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-41-5ea93c657ba67b40": {
    "text": "莉莉慢慢走過每顆石頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-42-80aef86ab96adf85": {
    "text": "She touched the star stone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-42-0629458fe2d7baa7": {
    "text": "她摸星星石。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-43-0d1645b3502fe2e0": {
    "text": "It felt cold.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-43-4e9f4db6d9bc00c4": {
    "text": "感覺很冰。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-44-4491f05635504344": {
    "text": "She touched the spiral stone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-44-f2fa81920cbfa128": {
    "text": "她摸旋轉石。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-45-f79a95827b64f925": {
    "text": "It felt heavy.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-45-fc9c98c61f8d174a": {
    "text": "感覺很重。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-46-cb9e33e02a063adf": {
    "text": "Then she touched the moon stone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-46-69dbe0e95b7eaa6f": {
    "text": "然後她摸月亮石。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-47-4943f090aa590229": {
    "text": "It felt warm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-47-7a8ca6395a595af8": {
    "text": "感覺很溫暖。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-48-b4fd34a112b2fc47": {
    "text": "“The moon…” Lily whispered.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-48-69abc51907509a88": {
    "text": "「月亮……」莉莉輕聲說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-49-00e2ddc94d8c171c": {
    "text": "“The first piece was also moon-shaped.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-49-b5aadb01a69b28a3": {
    "text": "「第一塊也是月亮形狀。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-50-e5b319b942d419b8": {
    "text": "Coco smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-50-ae4ca75292a57e96": {
    "text": "可可笑了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-51-c4879972774b530f": {
    "text": "“Good thinking.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-51-5517f081b807a287": {
    "text": "「想得很好。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-52-ebc1c08a8c59ee66": {
    "text": "Lily placed her hand on the moon stone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-52-e8669a88cccaad21": {
    "text": "莉莉把手放在月亮石上。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-53-3f2103741e0b3f3d": {
    "text": "The stone began to glow.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-53-242bbef758f49c79": {
    "text": "石頭開始發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-54-841f0d3e834ef2dd": {
    "text": "The ground shook a little.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-54-4507d5b1aa3176a1": {
    "text": "地面微微震動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-55-ca91aad2af3671c9": {
    "text": "Then the stone slowly moved.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-55-d8eba9a290ff4a45": {
    "text": "石頭慢慢打開。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-56-5f1f2799c2496357": {
    "text": "Inside, something shined.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-56-666e8648e673b9b2": {
    "text": "裡面有東西在發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-57-0639b6ecd34ddcb1": {
    "text": "Lily reached in.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-57-60ae48c0680e6e29": {
    "text": "莉莉伸手拿出來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-58-e56fddce599d8896": {
    "text": "She pulled out another piece.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-58-2405d167a27090f9": {
    "text": "那是第二塊月之鑰匙。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-59-e3c3cd51677659bd": {
    "text": "It was the second Moon Key piece.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-59-169a6e95264f415a": {
    "text": "可可拍手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-60-f26d2f946d505e18": {
    "text": "Coco clapped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-60-f60da01fb138fe8d": {
    "text": "「你又成功了！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-61-97756f5e59834769": {
    "text": "“You did it again!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-61-c363137f6dcd35c5": {
    "text": "卵石王子開心地跳。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-62-ebdb827bfd085288": {
    "text": "Prince Pebble jumped happily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-62-8a51de2c2468d300": {
    "text": "「呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-63-074955c4579d5fc1": {
    "text": "“Ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-63-076ed7f1a3b35e41": {
    "text": "但突然——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-64-229f9c926da73a76": {
    "text": "But suddenly—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-64-4bc1cb5deeed93b2": {
    "text": "空氣變冷了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-65-cb00c90d1b49bfda": {
    "text": "The air became cold.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-65-069c06e2054aed17": {
    "text": "石頭的光變暗。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-66-771228f84617785b": {
    "text": "The glowing lines on the stones turned dark.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-66-d6aac146c455dc98": {
    "text": "低語聲停止了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-67-46d7871df39cc179": {
    "text": "The whispering voices stopped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-67-458bb199dfe77e63": {
    "text": "莉莉看四周。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-68-21fd3c210d4b5776": {
    "text": "Lily looked around.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-68-0c84639380a882fb": {
    "text": "「不對勁……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-69-1431ff54f84e1c7a": {
    "text": "“Something is wrong…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-69-85d2f42b7bcee030": {
    "text": "一個影子在樹間移動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-70-b619c2e74aa6ffc3": {
    "text": "A shadow moved between the trees.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-70-7d7844abab0eca64": {
    "text": "可可驚呼。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-71-c09bf67fff90fba3": {
    "text": "Coco gasped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-71-7233d8bbda534701": {
    "text": "「它來了……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-72-5e37145126f34e12": {
    "text": "“It’s here…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-72-ba7cc64ca4383e37": {
    "text": "影子變大。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-73-834dceeef9572bd0": {
    "text": "The shadow grew larger.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-73-cbb1d24fe28460fe": {
    "text": "黑暗中出現紫色眼睛。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-74-4cbfb691814b36a4": {
    "text": "Purple eyes opened in the darkness.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-74-51cd8eba991b6234": {
    "text": "莉莉緊握光之葉。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-75-c2b0b27cd28b2dee": {
    "text": "Lily held the Light Leaf tightly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-75-afa66d8a495bd257": {
    "text": "「靠近我，」她說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-76-a0a01cf9bdaa56e3": {
    "text": "“Stay close,” she said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-76-7b4de309ead06b4b": {
    "text": "黑影發出低沉聲音。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-77-89f4b6e97305cdcc": {
    "text": "The shadow made a low sound.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-77-99f4069811eade8e": {
    "text": "「你找到了……鑰匙……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-78-77347e6250fabd99": {
    "text": "“You found… the key…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-78-440ce7f247141a69": {
    "text": "莉莉雙腿發抖。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-79-c32f750a8071be0c": {
    "text": "Lily felt her legs shaking.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-79-9400b99a93bae4dc": {
    "text": "但她沒有逃跑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-80-d74577508a43fb7c": {
    "text": "But she stood still.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-80-5d3be250fdcabd63": {
    "text": "「我們不會讓你拿走！」她說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-81-f9e60de125935add": {
    "text": "“We won’t let you take it!” she said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-81-d68302923a3bc69c": {
    "text": "黑影笑了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-82-cc9157c0e281ce17": {
    "text": "The shadow laughed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-82-e44564a622c3630f": {
    "text": "冰冷的回音笑聲。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-83-fec108df618b2cb7": {
    "text": "A cold, echoing laugh.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-83-70d61a85aef42764": {
    "text": "「你只是……小孩……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-84-2ff842afed45c1eb": {
    "text": "“You are just… a child…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-84-cbd98981a9159e05": {
    "text": "黑影伸出手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-85-5d956aba0cc7c316": {
    "text": "The shadow stretched its arm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-85-f5ae3aee86c15fa8": {
    "text": "黑煙向莉莉靠近。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-86-06ab470d0b8e07c8": {
    "text": "Dark smoke moved toward Lily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-86-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-87-bc30f1a485d6b02a": {
    "text": "Suddenly—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-87-9854ea1fb42e062c": {
    "text": "光之葉發出強光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-88-e421d8dfa0f1deee": {
    "text": "The Light Leaf flashed bright light.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-88-536bf18ff91449ee": {
    "text": "黑影退後。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-89-8b7d44dbcdec7c9d": {
    "text": "The shadow pulled back.\n“Ahhh!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-89-b27ba749ba692de5": {
    "text": "「啊！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-90-edd09863509b2534": {
    "text": "Coco shouted, “The light hurts it!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-90-4f2517c868db7c3b": {
    "text": "可可大喊：「光對它有效！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-91-1883529356719a03": {
    "text": "Lily raised the leaf.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-91-9cece9dfc7f41bb0": {
    "text": "莉莉舉起葉子。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-92-894391ba1fadaaee": {
    "text": "“Go away!” she shouted.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-92-3e720bd4e30100e1": {
    "text": "「離開！」她喊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-93-689759a85d44bf39": {
    "text": "The light became stronger.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-93-24a0f2a520407e8b": {
    "text": "光變得更強。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-94-65b4122ea64ab6fb": {
    "text": "The shadow slowly disappeared into the trees.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-94-8cf353c33829e06a": {
    "text": "黑影慢慢消失在樹林中。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-95-490bbdc6575d8d5c": {
    "text": "The forest became quiet again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-95-e81bcaf47e5ac88a": {
    "text": "森林再次安靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-96-9171add57611a9cf": {
    "text": "Lily took a deep breath.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-96-2e8f4fdc6cbf9c7a": {
    "text": "莉莉深吸一口氣。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-97-1a4729509470539f": {
    "text": "“That was scary…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-97-b90fe36eecc3b0f4": {
    "text": "「好可怕……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-98-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-98-51cdf3801661ec77": {
    "text": "可可點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-99-87e8eb1fbbeb9c82": {
    "text": "“But you were very brave.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-99-15df2ebe3f9533d0": {
    "text": "「但你很勇敢。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-100-8baae86c8c4d5b28": {
    "text": "Lily looked at the Moon Key pieces.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-100-f74aaba4832e2374": {
    "text": "莉莉看著鑰匙碎片。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-101-3a63b77a43cf73b6": {
    "text": "“We still need one more.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-101-f28dbf8bd10f750b": {
    "text": "「還差一塊。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-102-6a34ec5eb55ab399": {
    "text": "The Light Leaf floated forward again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-102-81715ee0eaaec1bc": {
    "text": "光之葉再次向前飄去。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c4-en-block-103-d5948d3ea46d3422": {
    "text": "Their journey was not over.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c4-zh-block-103-bdb3b762cfa41321": {
    "text": "她們的旅程還沒結束。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-title-deac07ef825540fc": {
    "text": "The Moon Lake",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-title-45ec4ec36b4d7edc": {
    "text": "月亮湖",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-0-157a8985e4ca46ab": {
    "text": "Lily, Coco, and Prince Pebble followed the Light Leaf again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-0-b7efb29aeeaf6e3c": {
    "text": "莉莉、可可和卵石王子再次跟著光之葉前進。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-1-7aead2633ca46fe5": {
    "text": "The forest slowly changed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-1-85929ad4a250444b": {
    "text": "森林慢慢改變。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-2-0fe67ef9dacceb93": {
    "text": "The trees became shorter.\nThe air felt cooler.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-2-6242e4b646e646ee": {
    "text": "樹變矮了。\n空氣變涼了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-3-a69dffd245600944": {
    "text": "A soft silver light appeared ahead.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-3-18aa9ac6e9fe27f9": {
    "text": "前方出現柔和的銀色光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-4-8f50e089e5e67221": {
    "text": "“Look!” Coco said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-4-ab90c3a5b04ef28a": {
    "text": "「看！」可可說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-5-ef6ed07b044b2e22": {
    "text": "“That is the Moon Lake!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-5-f6df769f61f147c6": {
    "text": "「那是月亮湖！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-6-0e7d031f9b602ef7": {
    "text": "They walked faster.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-6-9106a15cac89ebe2": {
    "text": "她們加快腳步。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-7-d10eb28d364fd5ed": {
    "text": "Soon, they arrived at a beautiful lake.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-7-e64c920ca3ff680c": {
    "text": "很快，她們來到一個美麗的湖邊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-8-4ea81e4ce89e1f45": {
    "text": "The water shined like a mirror.\nThe moon was reflected clearly on its surface.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-8-a7067d75dee8ff19": {
    "text": "湖水像鏡子一樣閃亮。\n月亮清楚地映在水面上。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-9-d2f2d87f320b4516": {
    "text": "“It’s so beautiful…” Lily whispered.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-9-59c8776ac7277520": {
    "text": "「好漂亮……」莉莉輕聲說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-10-581770cbeac551d2": {
    "text": "But something was wrong.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-10-4ccb7ba38b95d475": {
    "text": "但有點不對勁。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-11-d589516f11afc8ed": {
    "text": "The lake was too quiet.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-11-0600df26fa201b2c": {
    "text": "湖太安靜了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-12-69cc32239298f137": {
    "text": "No fish.\nNo birds.\nNo sound.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-12-515385d04236f06d": {
    "text": "沒有魚。\n沒有鳥。\n沒有聲音。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-13-eb5997e0d8308b56": {
    "text": "Coco looked worried.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-13-c49ab9719b77a846": {
    "text": "可可看起來很擔心。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-14-bb7d08f4535b065c": {
    "text": "“The lake is sleeping.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-14-a0d8871fadc16a2f": {
    "text": "「湖睡著了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-15-9970a90a83d0be8b": {
    "text": "“Sleeping?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-15-5a0139f3fab79d08": {
    "text": "「睡著了？」莉莉問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-16-40b96ae8dca4a21b": {
    "text": "“Yes,” Coco said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-16-f80cebbb0133d535": {
    "text": "「是的，」可可說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-17-c18bc7f23b707854": {
    "text": "“The Moon Lake should glow and move.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-17-a5b683cf1613c663": {
    "text": "「月亮湖本來會發光、會流動。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-18-7c2eeab06099bd2c": {
    "text": "“But now, it is frozen in silence.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-18-c5c2a5af8abbb031": {
    "text": "「但現在它安靜地停止了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-19-3d9f719972b1d021": {
    "text": "The Light Leaf floated above the water.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-19-c34dd31b1c732804": {
    "text": "光之葉飄到湖面上。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-20-4a6766795b378a2c": {
    "text": "It glowed strongly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-20-711ac0de17c4f8ba": {
    "text": "它發出強烈的光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-21-b7a7148cf5be9586": {
    "text": "Then the water moved slightly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-21-babe35b16079979a": {
    "text": "湖水微微動了一下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-22-17e6fd812e2c4db9": {
    "text": "A soft voice came from the lake.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-22-dc01172f4750caa6": {
    "text": "一個柔弱的聲音傳來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-23-b28e8bd8722aebe6": {
    "text": "“…help me…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-23-824cdbabcda7f342": {
    "text": "「……幫幫我……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-24-a0621ff28e7efe7a": {
    "text": "Lily stepped closer.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-24-8d0d5e8087a89100": {
    "text": "莉莉走近。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-25-f5e097681c115a8d": {
    "text": "“Who are you?” she asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-25-f3e98105027dd885": {
    "text": "「你是誰？」她問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-26-998111f4336a7d45": {
    "text": "“I am the Spirit of the Moon Lake…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-26-11cc691dd604f856": {
    "text": "「我是月亮湖的精靈……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-27-fe47db842dc95ce8": {
    "text": "The voice was gentle but weak.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-27-c2058ffc2c8f4205": {
    "text": "聲音溫柔但虛弱。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-28-eb3be3b36090ed68": {
    "text": "“The shadow… took my light…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-28-bfd5290bb40ce1d2": {
    "text": "「黑影……奪走了我的光……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-29-ac06415591dfc5db": {
    "text": "Lily held the Moon Key pieces.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-29-cd01ebb47ec64455": {
    "text": "莉莉握著鑰匙碎片。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-30-549020df625f18d5": {
    "text": "“Is the last piece here?” she asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-30-0362c93c0e9f57d6": {
    "text": "「最後一塊在這裡嗎？」她問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-31-464b93ac01f7ec8e": {
    "text": "“Yes…” the spirit replied.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-31-74b0cd96d06e011a": {
    "text": "「是的……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-32-05bc62237006520d": {
    "text": "“But it is hidden… beneath the mirror…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-32-7fda6a672b6359f6": {
    "text": "「但它藏在鏡子之下……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-33-7a2cee9804ea0fdd": {
    "text": "Lily looked at the water.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-33-910d645aa6221a61": {
    "text": "莉莉看著湖面。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-34-cd5927f01ca21c54": {
    "text": "“It looks like a mirror… I cannot see inside.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-34-ef63b768d4f22a11": {
    "text": "「看起來像鏡子……我看不到裡面。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-35-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-35-51cdf3801661ec77": {
    "text": "可可點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-36-8407fb40b799174b": {
    "text": "“That is the lake’s magic.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-36-1e2a07a54eb96726": {
    "text": "「這是湖的魔法。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-37-2ce8418a950a9b67": {
    "text": "“To find the key, you must see the truth, not just the reflection.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-37-7f0c210461716926": {
    "text": "「要找到鑰匙，你要看見真相，而不是倒影。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-38-bd09e3ea2f01c17d": {
    "text": "Lily frowned.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-38-b7bfe51956b9ccf7": {
    "text": "莉莉皺眉。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-39-fc98d98d8dc1183f": {
    "text": "“The truth?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-39-a651ce01cf897778": {
    "text": "「真相？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-40-666a4f84c7a3c10c": {
    "text": "She looked at the water again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-40-0b7fa1409dbcf765": {
    "text": "她再次看湖面。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-41-b0109fee9c3671d0": {
    "text": "She saw her own face.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-41-2bd33a8fe09e9f6b": {
    "text": "她看到自己的臉。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-42-7cd1747210cb215d": {
    "text": "She saw Coco flying.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-42-3ab5d4a04cc101a3": {
    "text": "看到可可在飛。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-43-e75e34f73c8fb558": {
    "text": "She saw the moon.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-43-2b5a489ea4cf7bab": {
    "text": "看到月亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-44-c9bbc32efb771626": {
    "text": "But nothing else.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-44-e6ab6c5eddac39aa": {
    "text": "但沒有其他東西。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-45-4c430d15b46b8119": {
    "text": "“There must be a clue…” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-45-364841250d876dc5": {
    "text": "「一定有線索……」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-46-04a3e4bfc09356eb": {
    "text": "Prince Pebble suddenly jumped into Lily’s bag.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-46-f9d0d6cbbe399da6": {
    "text": "卵石王子突然跳進莉莉的書包。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-47-074955c4579d5fc1": {
    "text": "“Ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-47-8a51de2c2468d300": {
    "text": "「呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-48-7bc41e91f8e653ff": {
    "text": "Then he came out holding something.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-48-7d146e1e218edf80": {
    "text": "然後牠拿出一樣東西。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-49-43ddbd7910aa416e": {
    "text": "It was Lily’s lunch box.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-49-ca324d972af5c477": {
    "text": "是莉莉的便當盒。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-50-b792b46a41cee3be": {
    "text": "Lily blinked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-50-3565681a0d3e2916": {
    "text": "莉莉愣住。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-51-5430ecbabaa88d43": {
    "text": "“My lunch?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-51-c5847d83775a3bbf": {
    "text": "「我的便當？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-52-5297dcddcadea0ed": {
    "text": "She opened it.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-52-3fb7fe49a00b1e74": {
    "text": "她打開。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-53-446e4ab5a83c4b79": {
    "text": "Inside, there was a shiny spoon.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-53-3a7f0f6dadaa31be": {
    "text": "裡面有一支亮亮的湯匙。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-54-d13ffe3ee7586213": {
    "text": "Coco’s eyes lit up.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-54-619efe4a7c20d70e": {
    "text": "可可眼睛一亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-55-32de53e2b5d614fd": {
    "text": "“The spoon!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-55-ece4f5a03b5d452d": {
    "text": "「湯匙！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-56-f17e7126628ee5a4": {
    "text": "Lily understood.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-56-d4981c0938596a3c": {
    "text": "莉莉明白了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-57-53afe9aa5274b324": {
    "text": "“The spoon shows things differently!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-57-38780dff61c3c8af": {
    "text": "「湯匙可以看到不同的東西！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-58-922161f45524596f": {
    "text": "She held the spoon over the lake.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-58-c01c8c782ba6fae2": {
    "text": "她把湯匙對著湖面。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-59-a2d1d15ff2b9e623": {
    "text": "The reflection changed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-59-6649c73a9d78c07a": {
    "text": "倒影改變了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-60-019054cc689c5bbe": {
    "text": "Now she could see beneath the water.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-60-346fa48a2483f9de": {
    "text": "現在她看見水底。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-61-dc61e4b830184482": {
    "text": "There was a glowing object.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-61-e27468cd33411d6e": {
    "text": "有一個發光的東西。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-62-441f02da2543ed8c": {
    "text": "“The key!” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-62-6d3f52b01ce83281": {
    "text": "「鑰匙！」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-63-27b9fe0e3d8da73d": {
    "text": "“But it is deep…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-63-65e6aad5adadb795": {
    "text": "「但它很深……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-64-2906f94c0b6ee0a9": {
    "text": "Coco flew around.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-64-30fd9574a16d1cd0": {
    "text": "可可飛來飛去。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-65-bacdf71b47b44bec": {
    "text": "“We need to bring it up.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-65-0d4a1478197cf122": {
    "text": "「我們要把它拿上來。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-66-24f9f23c259c54a8": {
    "text": "Lily looked at the lake carefully.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-66-c5bd0c2839a642f2": {
    "text": "莉莉仔細看湖面。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-67-9ea251412b4393ab": {
    "text": "Then she had an idea.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-67-ed46da2b63459a69": {
    "text": "然後她想到一個方法。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-68-8604554a1f2e663e": {
    "text": "“Pebble, can you help?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-68-fdcb7bca21e860cd": {
    "text": "「卵石，你可以幫忙嗎？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-69-074955c4579d5fc1": {
    "text": "“Ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-69-8a51de2c2468d300": {
    "text": "「呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-70-5207e1c81b750083": {
    "text": "Prince Pebble jumped into the water.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-70-bf34eef9b665a31a": {
    "text": "卵石王子跳進水裡。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-71-7eea759636e22a90": {
    "text": "But this time—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-71-c8cf185086313483": {
    "text": "但這次——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-72-441556cc773beb2f": {
    "text": "The water glowed around him.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-72-783e19e659f4df54": {
    "text": "水在牠周圍發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-73-82a90be6252f63ba": {
    "text": "It was not dark anymore.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-73-f9aa67477cd0bbb2": {
    "text": "不再黑暗。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-74-9c8c2db30b0d415f": {
    "text": "The spoon’s reflection showed the path.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-74-60fb9cd16fb0d3ee": {
    "text": "湯匙的影像顯示出路徑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-75-320d856de92e8533": {
    "text": "Prince Pebble swam down.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-75-56e1161beadcc5ff": {
    "text": "卵石王子游下去。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-76-19350a5f3439f87c": {
    "text": "He reached the glowing object.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-76-9ba9ce1393221723": {
    "text": "牠碰到發光的東西。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-77-f1a830d2220f2afa": {
    "text": "He pushed it upward.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-77-7a3d7a73e16c7e33": {
    "text": "把它推上來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-78-0516391bdad9036d": {
    "text": "Lily leaned forward.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-78-2770c233ea713e3c": {
    "text": "莉莉往前靠。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-79-bb40f2c618bbf532": {
    "text": "“Careful!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-79-e382ca8dc5c50888": {
    "text": "「小心！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-80-632ea13cc0aad05c": {
    "text": "The object rose slowly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-80-5adb015fa5a90c85": {
    "text": "東西慢慢浮上來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-81-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-81-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-82-da49cea4ca1cf55e": {
    "text": "Splash!",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-82-7a28da0d8e354c70": {
    "text": "啪！",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-83-b137336dd02b3bdd": {
    "text": "Prince Pebble jumped out of the water.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-83-671d689727fa6cea": {
    "text": "卵石王子跳出水面。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-84-57479a7d436309af": {
    "text": "In his mouth was the final piece.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-84-3e77e4ed827cbbe7": {
    "text": "嘴裡叼著最後一塊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-85-f26d2f946d505e18": {
    "text": "Coco clapped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-85-169a6e95264f415a": {
    "text": "可可拍手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-86-c2e43a2e337495e7": {
    "text": "“You got it!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-86-b8aa8c2b39f6f7b2": {
    "text": "「成功了！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-87-c587175fc581fd6d": {
    "text": "Lily took the piece.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-87-64b83c69f2e5d82e": {
    "text": "莉莉接過來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-88-ed0190cd5d76d5d2": {
    "text": "Now she had three pieces.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-88-08409c21d6442d43": {
    "text": "現在她有三塊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-89-b2a2dbc24547de75": {
    "text": "The pieces began to shine.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-89-ea238aa16d3a8b4a": {
    "text": "三塊開始發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-90-b130f77e6e610f38": {
    "text": "They floated in the air.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-90-f6762d7c3e8fad29": {
    "text": "它們飄到空中。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-91-5c868675020bc468": {
    "text": "Slowly, they joined together.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-91-5ac6d636b4318f51": {
    "text": "慢慢組合在一起。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-92-120cb24938da72e5": {
    "text": "Click.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-92-019792da7b48e033": {
    "text": "喀嚓。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-93-0b934cfe45dbc926": {
    "text": "A complete key appeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-93-ed9dc363270c3e44": {
    "text": "一把完整的鑰匙出現了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-94-9dbf1175610c596b": {
    "text": "The Moon Key.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-94-15191c269aa08219": {
    "text": "月之鑰匙。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-95-442ec92855d2a0d9": {
    "text": "It glowed with silver light.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-95-64112f3f19d71226": {
    "text": "發出銀色光芒。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-96-eb474d7ef911e753": {
    "text": "At that moment, the lake began to move.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-96-e820112706ab8166": {
    "text": "就在這時，湖水開始流動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-97-a35fc69819164dbb": {
    "text": "The water flowed gently.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-97-7a591328d9db951e": {
    "text": "水輕輕流動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-98-f0fc1bb902f53d28": {
    "text": "The moon reflection became brighter.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-98-ad804842a493b09d": {
    "text": "月亮的倒影變得更亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-99-9aa06d57de9ede9a": {
    "text": "The Spirit of the Lake spoke again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-99-d8450f7766c6b5c0": {
    "text": "湖的精靈再次說話。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-100-7d8b24fc10edfcae": {
    "text": "“Thank you… brave child…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-100-775eec11f4498cdc": {
    "text": "「謝謝你……勇敢的孩子……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-101-ed366ab62ec28ab2": {
    "text": "“My light… has returned…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-101-f5b8c66dc065e4d8": {
    "text": "「我的光……回來了……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-102-a6f3f80fb3b23b40": {
    "text": "Flowers bloomed near the water.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-102-bec8e1c5e7b087b2": {
    "text": "湖邊的花開了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-103-8cd48c93e60b6ed1": {
    "text": "Fireflies danced in the air.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-103-62ae0c2dfa2a72da": {
    "text": "螢火蟲在空中飛舞。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-104-e5b319b942d419b8": {
    "text": "Coco smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-104-9b7a50ddc0d9f297": {
    "text": "可可微笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-105-eb5162859787572b": {
    "text": "“The forest is healing.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-105-31dec46a3d01aec1": {
    "text": "「森林正在恢復。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-106-6dcfc3217c0044a0": {
    "text": "Lily held the Moon Key.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-106-1f68554049992700": {
    "text": "莉莉握著月之鑰匙。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-107-31d92267004f0b44": {
    "text": "“Now we can go to the cave.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-107-97bdc9b1dee462ee": {
    "text": "「現在我們可以去洞穴了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-108-34e0bb22b2327251": {
    "text": "The Light Leaf floated ahead.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-108-3db5402fa2d0b048": {
    "text": "光之葉再次往前飄。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-109-229f9c926da73a76": {
    "text": "But suddenly—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-109-076ed7f1a3b35e41": {
    "text": "但突然——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-110-fd8505ce169c1e75": {
    "text": "The sky turned dark.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-110-cfd579f5cdc7afdf": {
    "text": "天空變暗。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-111-4f6c8eea4f423dd0": {
    "text": "Clouds covered the moon.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-111-9b30d0e23612b348": {
    "text": "雲遮住月亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-112-0b18ab3631f7ba53": {
    "text": "A cold wind blew.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-112-ee87c75600506121": {
    "text": "冷風吹來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-113-e4e83c1a6095498f": {
    "text": "Coco looked up.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-113-8d5535485d261745": {
    "text": "可可抬頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-114-7bcb4abee0172842": {
    "text": "“No… it’s coming again…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-114-e2f76be01a8cb9f0": {
    "text": "「不……它又來了……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-115-64361d8628125737": {
    "text": "A deep voice echoed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-115-9dbbd3df770e908c": {
    "text": "一個低沉的聲音響起。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-116-d3dcdd3e2bb1c031": {
    "text": "“You have the key…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-116-4657f36d37c0ad02": {
    "text": "「你拿到鑰匙了……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-117-0c0723a03219a46b": {
    "text": "The shadow appeared above the lake.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-117-76ff077e14ad802a": {
    "text": "黑影出現在湖上空。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-118-37707a3c02ff5329": {
    "text": "Bigger than before.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-118-e0db659dfdacfbeb": {
    "text": "比之前更大。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-119-8f8740aa639cecf1": {
    "text": "Stronger.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-119-ac2cb21f51750eb9": {
    "text": "更強。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-120-bde035d97667abc2": {
    "text": "Its purple eyes glowed brighter.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-120-4da3de0390a17acc": {
    "text": "紫色眼睛更亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-121-aeb2e64588c3c4b6": {
    "text": "Lily stood firm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-121-5a9ffb14092542e7": {
    "text": "莉莉站穩。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-122-36178e71cc80a1a2": {
    "text": "“We are not afraid of you!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-122-0a07dc41334112bd": {
    "text": "「我們不怕你！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-123-cc9157c0e281ce17": {
    "text": "The shadow laughed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-123-e3e988092994306f": {
    "text": "黑影大笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-124-cf99ab159b9e2ba8": {
    "text": "“You should be…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-124-88b3ff285e49e8fd": {
    "text": "「你應該怕……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-125-1d754a17e266d97e": {
    "text": "It raised its arms.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-125-30e5eb094495d1f1": {
    "text": "它舉起雙手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-126-f06780b584f2fc5a": {
    "text": "Dark waves moved across the lake.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-126-d6bd4da1e565e756": {
    "text": "黑暗波動在湖面擴散。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-127-70222530f0b62863": {
    "text": "The water shook violently.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-127-31cdc69c6c93b398": {
    "text": "湖水劇烈搖晃。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-128-98460196ad4e7416": {
    "text": "Lily held the Moon Key tightly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-128-453c0b4822215f6e": {
    "text": "莉莉緊握鑰匙。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-129-c8bbc48a40b7882e": {
    "text": "The Light Leaf began to shine brighter than ever.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-129-3adeda454360f7ed": {
    "text": "光之葉發出最強的光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-130-b9b62e2a9d42b1b7": {
    "text": "Coco shouted,",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-130-1e9fe62b5e17f458": {
    "text": "可可大喊：",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-131-a9bd4a958f5d52c0": {
    "text": "“Lily! The key and the leaf together!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-131-ecbe632cd87383fe": {
    "text": "「莉莉！鑰匙和葉子一起！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-132-2fa81f79365f8bda": {
    "text": "Lily raised both.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-132-202522024d579500": {
    "text": "莉莉舉起兩者。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-133-871c4d3951194783": {
    "text": "Light exploded into the sky.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-133-0829fc09db03504f": {
    "text": "光衝上天空。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-134-b125317eb8348359": {
    "text": "The darkness stopped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-134-778458b312b61d9b": {
    "text": "黑暗停止。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-135-c55535a26b0ae8b3": {
    "text": "The shadow screamed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-135-1fa38e9a858954ec": {
    "text": "黑影慘叫。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-136-407ceee032a731b1": {
    "text": "“NO—!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-136-640e0fb6c16ae269": {
    "text": "「不——！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-137-47398ddb95fda654": {
    "text": "It disappeared again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-137-26b4005de991688d": {
    "text": "它再次消失。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-138-f1077c39b99765b9": {
    "text": "The clouds moved away.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-138-795aadcbc40ba5a9": {
    "text": "雲散開。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-139-10d592f07e05724b": {
    "text": "The moon shined once more.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-139-4d364be9c7bd2f04": {
    "text": "月亮重新出現。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-140-5e2128554c4aa9c9": {
    "text": "The lake became calm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-140-8e86c667139df8d1": {
    "text": "湖恢復平靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-141-00dcdb0699d7f771": {
    "text": "Lily breathed heavily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-141-3df9d0e77c1632cc": {
    "text": "莉莉大口呼吸。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-142-ed1b7a0ea85c5fd0": {
    "text": "“That was close…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-142-de5f2d2746b780e7": {
    "text": "「差點就完了……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-143-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-143-51cdf3801661ec77": {
    "text": "可可點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-144-77c76dc5d6a05b96": {
    "text": "“It is getting stronger.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-144-9db618da79f1ae0d": {
    "text": "「它變得更強了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-145-7d572bba2d447d64": {
    "text": "Lily looked at the path ahead.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-145-45faa170c723b937": {
    "text": "莉莉看著前方。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-146-981e65253ec50891": {
    "text": "“The cave must be near.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-146-d67bdeec796fb517": {
    "text": "「洞穴一定就在附近。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-147-13c1feaeb25a22a6": {
    "text": "The Light Leaf floated forward slowly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-147-54a28c8a702c3015": {
    "text": "光之葉慢慢前進。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-148-c7c09f287132e3ac": {
    "text": "This time, its light was steady.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-148-ae4457dd1e5418a8": {
    "text": "這次光很穩定。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-149-6dcfc3217c0044a0": {
    "text": "Lily held the Moon Key.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-149-1f68554049992700": {
    "text": "莉莉握著月之鑰匙。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c5-en-block-150-b4c80ea40d51ea30": {
    "text": "She was ready.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c5-zh-block-150-62f5b039ad7ada81": {
    "text": "她已經準備好了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-title-d1343ce56c6723b7": {
    "text": "The Hidden Cave",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-title-e99e9c50814737bd": {
    "text": "隱藏的洞穴",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-0-e296d5a39ba23a3e": {
    "text": "Lily, Coco, and Prince Pebble followed the Light Leaf deeper into the forest.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-0-baf41814f2e26c95": {
    "text": "莉莉、可可和卵石王子跟著光之葉繼續深入森林。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-1-7dd638c7960a69a1": {
    "text": "The path became narrow.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-1-660d88037b89c7e2": {
    "text": "小路變得狹窄。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-2-23d01782e8e762fc": {
    "text": "Tall rocks rose on both sides.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-2-bcb8ae65128ec1c0": {
    "text": "兩旁出現高大的岩石。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-3-b73be45892aa5213": {
    "text": "The air felt cold and still.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-3-5f8f2ae31003c4b0": {
    "text": "空氣變得冰冷又安靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-4-2a6c3680883073df": {
    "text": "“I think we are close,” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-4-b45257fc7a4982f2": {
    "text": "「我覺得我們快到了，」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-5-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-5-51cdf3801661ec77": {
    "text": "可可點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-6-8994a496de1dc529": {
    "text": "“This is the oldest part of the forest.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-6-931187598b524a7c": {
    "text": "「這裡是森林最古老的地方。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-7-3716106c9143d890": {
    "text": "The Light Leaf slowed down.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-7-55f91db83eacb48e": {
    "text": "光之葉慢了下來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-8-dfe01850570695a3": {
    "text": "Then it stopped in front of a large rock wall.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-8-7a42495caa7d5b3a": {
    "text": "然後停在一面巨大的岩壁前。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-9-21fd3c210d4b5776": {
    "text": "Lily looked around.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-9-e642e233b85ff3ad": {
    "text": "莉莉看了看四周。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-10-1c172a96e2891344": {
    "text": "“There is no cave here…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-10-a94f630bd19bf1f2": {
    "text": "「這裡沒有洞穴啊……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-11-b6c23d2845d99961": {
    "text": "Coco frowned.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-11-ff8b94dcc7c2ed29": {
    "text": "可可皺眉。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-12-1460372419c237ed": {
    "text": "“The cave should be here.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-12-db1c6fc0659d944c": {
    "text": "「洞穴應該就在這裡。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-13-8558390a37678f99": {
    "text": "The Light Leaf floated closer to the wall.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-13-7021ce2eaf72700b": {
    "text": "光之葉飄向岩壁。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-14-f366f208334a5a4c": {
    "text": "It touched the stone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-14-187de1bc63a1e869": {
    "text": "它碰到石頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-15-bc30f1a485d6b02a": {
    "text": "Suddenly—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-15-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-16-b8e909c35a001ba7": {
    "text": "The rock began to glow.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-16-2df0da7f55afbdbe": {
    "text": "岩壁開始發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-17-4d69bf9480e4e8d7": {
    "text": "Lines of light appeared on its surface.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-17-4a7e8d7316787a46": {
    "text": "表面出現發光的線條。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-18-15ae5046f76eaa82": {
    "text": "They formed shapes.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-18-34e0889c27609b97": {
    "text": "形成圖案。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-19-977a395228cdf6a5": {
    "text": "Circles… lines… symbols.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-19-ba2e2d944a410739": {
    "text": "圓形……線條……符號。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-20-c73c3f64ab1fe102": {
    "text": "“It’s a puzzle,” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-20-3268970e4cdc8317": {
    "text": "「這是一個謎題，」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-21-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-21-51cdf3801661ec77": {
    "text": "可可點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-22-b341966ce90159a3": {
    "text": "“The cave is hidden.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-22-16e58761ca8c530b": {
    "text": "「洞穴是隱藏的。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-23-5b346bb03f6c4c97": {
    "text": "“You must open it with the Moon Key.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-23-1f78836526ca03aa": {
    "text": "「你要用月之鑰匙打開它。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-24-c7509b6e7054db0e": {
    "text": "Lily took out the Moon Key.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-24-81d2a11245e04db8": {
    "text": "莉莉拿出鑰匙。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-25-877bcab10c378d65": {
    "text": "It shined softly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-25-76b341bfc2260f44": {
    "text": "它發出柔和的光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-26-46a11bf689f767ac": {
    "text": "But there was no keyhole.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-26-9ce2a13fe9ca4436": {
    "text": "但沒有鑰匙孔。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-27-8b6bc4358f07748c": {
    "text": "“Where do I use it?” Lily asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-27-f361ceac64997d10": {
    "text": "「我要怎麼用？」她問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-28-b35336833c75aebf": {
    "text": "The symbols on the wall began to move.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-28-bf83264f94be9ba3": {
    "text": "岩壁上的符號開始移動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-29-11217fe473afe151": {
    "text": "Three circles appeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-29-6e5da1bc6d1cbad7": {
    "text": "出現三個圓形。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-30-c90d2f9856da55b8": {
    "text": "Each circle had a space inside.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-30-40ce9a2054c89eec": {
    "text": "每個圓裡都有一個空位。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-31-e5b64ea356c420f1": {
    "text": "Coco pointed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-31-3c0617740f7484e8": {
    "text": "可可指著說：",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-32-5dd6ad31d9a873d5": {
    "text": "“Put the key there.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-32-14d3b51ecfce712b": {
    "text": "「把鑰匙放進去。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-33-d9503641ba2b1577": {
    "text": "Lily stepped forward.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-33-0af58852794a5bc3": {
    "text": "莉莉走上前。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-34-e23ba4a0e37f0ad3": {
    "text": "She placed the Moon Key into the center circle.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-34-da51443cd6e27c9a": {
    "text": "她把鑰匙放進中間。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-35-6b635a0931c751b1": {
    "text": "Nothing happened.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-35-21d41c26d14f1235": {
    "text": "沒有反應。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-36-787c08d49cb26fb1": {
    "text": "“Oh…” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-36-01b48103a1be576b": {
    "text": "「嗯……」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-37-88b01c121dc6aef9": {
    "text": "“Maybe it’s not that simple.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-37-bbc7905eadee5ed1": {
    "text": "「應該沒那麼簡單。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-38-ae7a23a0403c667e": {
    "text": "The Light Leaf began to glow brighter.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-38-e41277a8e1f504cf": {
    "text": "光之葉開始變亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-39-aee3a70ef9b19429": {
    "text": "It moved to one of the smaller circles.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-39-9d667ef39ce6adf1": {
    "text": "它移到其中一個圓形。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-40-beb25685f8aa88e6": {
    "text": "Coco watched carefully.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-40-2eef57de289a3510": {
    "text": "可可仔細看。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-41-50212648a2f39a06": {
    "text": "“The leaf is showing us something.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-41-9587e56ce001d185": {
    "text": "「葉子在提示我們。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-42-64b898c9df720d13": {
    "text": "Lily looked at the circles again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-42-11773e1d5eb016e0": {
    "text": "莉莉再次看那些圓形。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-43-1dac42225f78948a": {
    "text": "She noticed something.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-43-5f6dbbc255406868": {
    "text": "她發現一件事。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-44-faf2d934617cbd8b": {
    "text": "“The shapes are different…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-44-c2a4a627f0b0a1aa": {
    "text": "「圖案不一樣……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-45-5b1ed6be6f34342c": {
    "text": "One circle had a star pattern.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-45-e4451ae819644da6": {
    "text": "一個是星星。\n一個是月亮。\n一個是旋轉。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-46-8e7fecbd2f4a1384": {
    "text": "One had a moon pattern.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-46-2103fb02d935de8a": {
    "text": "莉莉想起低語之石。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-47-05acd35a364dfe49": {
    "text": "One had a spiral pattern.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-47-4fb70f271477d22b": {
    "text": "「星星、月亮、旋轉……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-48-8dcaa3eb12266dd7": {
    "text": "Lily remembered the Whispering Stones.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-48-ae4ca75292a57e96": {
    "text": "可可笑了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-49-cb8a91766b93160b": {
    "text": "“Star… moon… spiral…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-49-0aa52d854727ded0": {
    "text": "「你記得！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-50-e5b319b942d419b8": {
    "text": "Coco smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-50-15510420a2bdee21": {
    "text": "莉莉想了一下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-51-54ba2a9066089cbc": {
    "text": "“You remember!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-51-8326300542a06d09": {
    "text": "「月亮是鑰匙……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-52-704c358c9bc1e40b": {
    "text": "Lily thought hard.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-52-e61d7719fa9a7257": {
    "text": "她把鑰匙放進月亮圓。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-53-76bc3656de7e6759": {
    "text": "“The moon is the key…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-53-019792da7b48e033": {
    "text": "喀嚓。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-54-fa2ebb23bcbc63d4": {
    "text": "She moved the Moon Key into the moon circle.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-54-05e6f0b766c69b76": {
    "text": "圓形亮了起來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-55-120cb24938da72e5": {
    "text": "Click.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-55-68a348f6f9541165": {
    "text": "岩壁微微震動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-56-15b6b5b7b01a43a5": {
    "text": "The circle lit up.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-56-36ccb7e6431b626a": {
    "text": "「很好！」可可說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-57-d4dec30f343f8bcf": {
    "text": "The wall shook slightly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-57-cd7b37b362350382": {
    "text": "「另外兩個呢？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-58-cfab8b2eb2b9644e": {
    "text": "“Good!” Coco said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-58-458bb199dfe77e63": {
    "text": "莉莉看四周。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-59-75c215ab8ae3991f": {
    "text": "“What about the others?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-59-168f47d08b7a793d": {
    "text": "「可能不只用鑰匙。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-60-21fd3c210d4b5776": {
    "text": "Lily looked around.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-60-ef742a72095cc9bb": {
    "text": "卵石王子跳到地上。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-61-7eb2a63351824c53": {
    "text": "“Maybe… we need more than just the key.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-61-8a51de2c2468d300": {
    "text": "「呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-62-e4cf00d77ecb9446": {
    "text": "Prince Pebble jumped onto the ground.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-62-280650663e74dd52": {
    "text": "牠推了一顆小石頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-63-074955c4579d5fc1": {
    "text": "“Ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-63-876d107f5d0b992d": {
    "text": "石頭滾到岩壁。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-64-acb7ce5baba57bd7": {
    "text": "He tapped a small stone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-64-3a5e49264d1c0dbe": {
    "text": "碰到旋轉圖案——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-65-af7985ff9416f178": {
    "text": "The stone rolled toward the wall.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-65-e7db495ad4077fbb": {
    "text": "發光！",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-66-a62002159d381883": {
    "text": "When it touched the spiral circle—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-66-548853ee387763d9": {
    "text": "旋轉圓亮了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-67-0bbe928f6bb2fcb9": {
    "text": "Glow!\nThe spiral circle lit up.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-67-bdb56b62d657cce7": {
    "text": "「卵石幫忙了！」可可笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-68-5606b29f2e6c6ac7": {
    "text": "“Pebble helped!” Coco laughed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-68-4b7a853fd3325be7": {
    "text": "莉莉也笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-69-98b0f90a593f7dad": {
    "text": "Lily smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-69-bb7af61441f492bd": {
    "text": "「剩一個……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-70-69d1df63e06bfffd": {
    "text": "“One more…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-70-04cd763f5a7a561a": {
    "text": "光之葉飛到星星圖案。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-71-a89a4523829c1530": {
    "text": "The Light Leaf floated to the star circle.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-71-a2a16b317618f492": {
    "text": "發出強光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-72-a2e617abed087016": {
    "text": "It shined brightly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-72-d4981c0938596a3c": {
    "text": "莉莉明白了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-73-f17e7126628ee5a4": {
    "text": "Lily understood.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-73-990fe707224e175a": {
    "text": "「葉子就是星星。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-74-f1dd1da542304ce0": {
    "text": "“The leaf is the star.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-74-220522abc7f3ff63": {
    "text": "她把光之葉靠近圓形。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-75-06596809d5ab00b8": {
    "text": "She held the Light Leaf close to the circle.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-75-c552f5d7ed5f79bb": {
    "text": "閃光！",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-76-5d3f81ac378505bf": {
    "text": "Flash!",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-76-5da94c034a4b3be3": {
    "text": "星星圓亮起來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-77-eb47cfad64a6c76c": {
    "text": "The star circle lit up.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-77-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-78-bc30f1a485d6b02a": {
    "text": "Suddenly—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-78-28ae052674ade8da": {
    "text": "三個圓同時發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-79-1ed1cd640d06e2c1": {
    "text": "All three circles glowed together.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-79-6164f28bcdb2c5c8": {
    "text": "岩壁開始移動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-80-d06d8688745a426a": {
    "text": "The rock wall began to move.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-80-aa8d91f2f8e4db1e": {
    "text": "慢慢打開。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-81-65314f58ee1c4894": {
    "text": "Slowly, it opened.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-81-76d898adcf2af387": {
    "text": "一個黑暗的洞穴出現。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-82-e69fb53edd80d010": {
    "text": "A dark cave appeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-82-f0955399ca1f6a27": {
    "text": "冷空氣從裡面吹出。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-83-076471e477692746": {
    "text": "Cold air came from inside.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-83-b683c93988e2cfad": {
    "text": "莉莉看著裡面。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-84-be06597c85d9192a": {
    "text": "Lily looked into the darkness.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-84-c5e80e27c2902284": {
    "text": "「就是這裡……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-85-9b0d8a647b4a1f57": {
    "text": "“This is it…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-85-51cdf3801661ec77": {
    "text": "可可點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-86-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-86-a8004fe5d8b7b583": {
    "text": "「黑影就在裡面。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-87-17ea925a41c7a9c3": {
    "text": "“The shadow is inside.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-87-dd9a8e92bae9bc4b": {
    "text": "卵石王子躲到莉莉腳後。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-88-554dd2b467f68a9e": {
    "text": "Prince Pebble hid behind Lily’s foot.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-88-ea268340db34c09f": {
    "text": "「呱……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-89-3bee303e7ffe7eac": {
    "text": "“Ribbit…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-89-2e8f4fdc6cbf9c7a": {
    "text": "莉莉深吸一口氣。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-90-9171add57611a9cf": {
    "text": "Lily took a deep breath.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-90-e70890caaf5dc575": {
    "text": "「我們走到這裡了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-91-d19b16e628ec0583": {
    "text": "“We came this far.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-91-b93d9c8f5fc6a150": {
    "text": "「不能停。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-92-6ce31d9157c2fbfc": {
    "text": "“We cannot stop now.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-92-e243e03348d0f213": {
    "text": "光之葉飛進洞穴。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-93-f29fb0beee737cb0": {
    "text": "The Light Leaf floated into the cave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-93-5bf856aeb32411c2": {
    "text": "成為唯一的光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-94-11f15a7b8f039e3d": {
    "text": "Its light became the only light.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-94-27d56529eacfe98f": {
    "text": "莉莉走進去。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-95-d9503641ba2b1577": {
    "text": "Lily stepped forward.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-95-0e6afe940e6ede50": {
    "text": "可可跟著。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-96-65281a956eeb6987": {
    "text": "Coco followed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-96-b7ce6eb23a8bcde0": {
    "text": "卵石王子跳在後面。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-97-7131c9a0dfe97b40": {
    "text": "Pebble hopped behind them.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-97-d81b186b73f3dd4d": {
    "text": "洞穴裡很安靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-98-f26582c8e73bbc0e": {
    "text": "Inside the cave, it was very quiet.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-98-33238788957f2085": {
    "text": "水滴從天花板落下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-99-febbea2b5a722413": {
    "text": "Drops of water fell from the ceiling.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-99-e7e76d998f32d80f": {
    "text": "滴……滴……",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-100-66993bd52402cc05": {
    "text": "Drip… drip…",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-100-66aa1b4779c3f2fd": {
    "text": "牆壁上有古老的圖案。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-101-763fe5a0175176ea": {
    "text": "The walls were covered with old marks.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-101-6a815e0e7021c02c": {
    "text": "古老的符號。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-102-593dea96c3e525cf": {
    "text": "Ancient symbols.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-102-976ad00ae24082f1": {
    "text": "「這些是什麼？」莉莉輕聲問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-103-3ad26bc197b5b752": {
    "text": "“What are these?” Lily whispered.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-103-2eef57de289a3510": {
    "text": "可可仔細看。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-104-dc56953f50338d95": {
    "text": "Coco looked closely.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-104-3147bb90ff8bc80b": {
    "text": "「這是很古老的文字。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-105-3d73449f3029cd07": {
    "text": "“These are very old writings.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-105-af7329761cf1e566": {
    "text": "「記錄森林的故事。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-106-bb2ede8adcd4fc82": {
    "text": "“They tell the story of the forest.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-106-d4edca667b74e4a6": {
    "text": "莉莉摸著牆壁。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-107-4ba8ed4230d6f452": {
    "text": "Lily moved her hand along the wall.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-107-bfefe3b29c91c96f": {
    "text": "然後停下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-108-d963260f39bf4762": {
    "text": "Then she stopped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-108-f73d6bb33c6e64e2": {
    "text": "她看到一幅圖。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-109-5dc2540337ec389d": {
    "text": "There was a picture.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-109-323d8355859e2699": {
    "text": "中央是一顆發光的水晶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-110-d7e5c142a27c2248": {
    "text": "A bright crystal in the center.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-110-b34284eab9c380a3": {
    "text": "周圍是動物和樹木。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-111-5f72bbaf4706af06": {
    "text": "Animals and trees around it.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-111-7e52f00bda5b7224": {
    "text": "「那一定是星之水晶，」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-112-f481fd0b43d40abf": {
    "text": "“That must be the Star Crystal,” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-112-51cdf3801661ec77": {
    "text": "可可點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-113-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-113-e9c9c346d4f02a87": {
    "text": "「森林的心。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-114-4a825d930f31b636": {
    "text": "“Yes… the heart of the forest.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-114-d179670efa17f466": {
    "text": "但莉莉又看到另一個東西。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-115-0f362f07febd6a15": {
    "text": "But then Lily saw something else.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-115-a320c90a4f97c097": {
    "text": "一個黑影在水晶旁。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-116-2db1ef9dd472c91d": {
    "text": "A dark shape near the crystal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-116-544e64a794763d3e": {
    "text": "「它已經存在很久了……」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-117-62b575b216110933": {
    "text": "“It has been here for a long time…” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-117-c49ab9719b77a846": {
    "text": "可可看起來很擔心。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-118-eb5997e0d8308b56": {
    "text": "Coco looked worried.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-118-8245ae04f8f60195": {
    "text": "「黑影不是最近才出現……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-119-0ae49850492cac4e": {
    "text": "“The shadow is not new…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-119-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-120-bc30f1a485d6b02a": {
    "text": "Suddenly—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-120-5591a1de50a6b09c": {
    "text": "一個低沉聲音響起。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-121-64361d8628125737": {
    "text": "A deep voice echoed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-121-9b4ae763a32c4652": {
    "text": "「你們終於來了……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-122-d48ec468a76eed06": {
    "text": "“You finally came…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-122-2705a661b69df542": {
    "text": "莉莉轉身。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-123-67451594c8fcbeeb": {
    "text": "Lily turned quickly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-123-cbb1d24fe28460fe": {
    "text": "黑暗中出現紫色眼睛。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-124-70a9955865d5da2a": {
    "text": "Purple eyes appeared in the darkness.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-124-89a290388c167e9a": {
    "text": "黑影慢慢成形。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-125-a6b99055a3f7e1f6": {
    "text": "The shadow slowly formed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-125-b17aa4e2ac6028ba": {
    "text": "這次——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-126-a2f1103c37928e18": {
    "text": "But now—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-126-f9523de0fc2ae3d4": {
    "text": "更真實。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-127-5fea8855b7538a2f": {
    "text": "It looked more solid.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-127-ac2cb21f51750eb9": {
    "text": "更強。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-128-320b71c1ab9c1123": {
    "text": "More real.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-128-9c511b8abe78cdb8": {
    "text": "可可小聲說：",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-129-01ea3d76062e927c": {
    "text": "Stronger than before.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-129-163ad5bdb4425e4f": {
    "text": "「它在變化……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-130-a2baf535cbac7f11": {
    "text": "Coco whispered,\n“It’s changing…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-130-515431d1d9a5345e": {
    "text": "黑影走向前。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-131-b4491e660d2f69b0": {
    "text": "The shadow stepped forward.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-131-28e39abbbee77c40": {
    "text": "「你打開了洞穴……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-132-30dc0b7c198867e5": {
    "text": "“You opened the cave…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-132-40cc0f7880dfcdab": {
    "text": "「現在，把鑰匙交給我……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-133-b0f65e90b8851877": {
    "text": "“Now you will give me the key…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-133-453c0b4822215f6e": {
    "text": "莉莉緊握鑰匙。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-134-98460196ad4e7416": {
    "text": "Lily held the Moon Key tightly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-134-f1dca4b0e2227775": {
    "text": "「不。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-135-2d89decf03a12c3f": {
    "text": "“No.”\nThe shadow laughed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-135-e3e988092994306f": {
    "text": "黑影大笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-136-5ee8ead1fbb884a4": {
    "text": "“You cannot stop me.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-136-f8185a0f5515e9d4": {
    "text": "「你阻止不了我。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-137-1a786c603df16042": {
    "text": "Dark smoke filled the cave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-137-fe4ad2de84990557": {
    "text": "黑煙充滿洞穴。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-138-921f423d7434ea8c": {
    "text": "The walls trembled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-138-c680cfed466abb78": {
    "text": "牆壁震動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-139-810b2279f1372d12": {
    "text": "Lily raised the Light Leaf.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-139-3aa3236a0c298fd6": {
    "text": "莉莉舉起光之葉。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-140-020a987dcc1e33d8": {
    "text": "It shined, but not as strong as before.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-140-0b020519b7a2bae7": {
    "text": "但光沒有之前強。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-141-08320ec5e6af315b": {
    "text": "“It’s too dark…” Coco said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-141-c2d15efd8c21a226": {
    "text": "「太黑了……」可可說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-142-145f6c2a9a5c4a24": {
    "text": "The shadow grew bigger.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-142-2c31e8d24e8dbd27": {
    "text": "黑影變得更大。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-143-8b2ddc2aa206728b": {
    "text": "“You are too late…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-143-ac4c39683fa9934d": {
    "text": "「你太晚了……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-144-bc30f1a485d6b02a": {
    "text": "Suddenly—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-144-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-145-4c7b2f30fb90ccca": {
    "text": "The Moon Key began to glow.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-145-8a32122377f1967a": {
    "text": "月之鑰匙開始發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-146-01ea3d76062e927c": {
    "text": "Stronger than before.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-146-4499a904e060ceff": {
    "text": "比之前更強。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-147-49a00d29a53554af": {
    "text": "Silver light spread across the cave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-147-4636e7e25fe99de2": {
    "text": "銀光擴散整個洞穴。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-148-6edd351a49aad039": {
    "text": "The shadow stopped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-148-c3e3ee320a9c1856": {
    "text": "黑影停住。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-149-4ef869c63eb1feef": {
    "text": "“What is this…?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-149-3338fc683e9d75f5": {
    "text": "「這是什麼……？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-150-c09bf67fff90fba3": {
    "text": "Coco gasped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-150-7d7844abab0eca64": {
    "text": "可可驚呼。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-151-39e09f0a4e9e76ed": {
    "text": "“The key is reacting!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-151-6a8589f76ed472b3": {
    "text": "「鑰匙在反應！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-152-b4a0ffbd44621b7a": {
    "text": "Lily felt the key becoming warm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-152-fcb9af5776973d25": {
    "text": "莉莉感覺鑰匙變熱。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-153-dce4e0ca2068e72f": {
    "text": "“It’s leading us…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-153-ff159519a4fb5977": {
    "text": "「它在指路……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-154-74509012a157da8b": {
    "text": "A path of light appeared deeper in the cave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-154-a93e28370a123d9c": {
    "text": "一道光路出現在洞穴深處。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-155-8386a2e5ed413b07": {
    "text": "The shadow roared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-155-a1b90500166283b6": {
    "text": "黑影怒吼。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-156-399e4939c9cbc356": {
    "text": "“NO! STOP!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-156-bc32f653eb53fb3b": {
    "text": "「不！停下！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-157-5089a968691459a5": {
    "text": "Lily turned.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-157-2705a661b69df542": {
    "text": "莉莉轉身。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-158-97384b18bc5e5f77": {
    "text": "“Run!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-158-8263be01d7de9353": {
    "text": "「跑！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-159-f5f6a69bc528a379": {
    "text": "She ran toward the light path.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-159-21308d9b4158de50": {
    "text": "她往光的方向跑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-160-15342735f22fda2b": {
    "text": "Coco flew beside her.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-160-b481371e32ca23d4": {
    "text": "可可跟著飛。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-161-43b7dcae5e23e286": {
    "text": "Pebble jumped quickly behind.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-161-ac845af5b3867ec1": {
    "text": "卵石王子快速跳。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-162-8e63470dde5624b1": {
    "text": "The shadow chased them.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-162-bd48f47269f17237": {
    "text": "黑影追上來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-163-cca260f4a345fa0e": {
    "text": "The cave shook violently.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-163-99700ee68ee6c147": {
    "text": "洞穴劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-164-411a69bbdc25fd6d": {
    "text": "Rocks fell from above.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-164-48e3be43241b7d08": {
    "text": "石頭掉下來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-165-ac86247fa90f55e3": {
    "text": "Lily kept running.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-165-0301c16a3cd657ea": {
    "text": "莉莉不停跑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-166-70018c7408861f95": {
    "text": "“I can see something ahead!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-166-cd06a9670c15f328": {
    "text": "「前面有東西！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-167-f2b90935e059b461": {
    "text": "At the end of the path—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-167-6e48ae860431b5fb": {
    "text": "光的盡頭——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-168-e6f3a44fddd86334": {
    "text": "A bright light shined.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-168-058af188502b9f4c": {
    "text": "一個耀眼的光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c6-en-block-169-fe18d9f3d40f2d1b": {
    "text": "The Star Crystal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c6-zh-block-169-528ea65c373fd31a": {
    "text": "星之水晶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-title-f0172cb405038783": {
    "text": "The Star Crystal",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-title-00426348e64c7526": {
    "text": "星之水晶",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-0-467c64ef86140120": {
    "text": "Lily ran toward the bright light.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-0-68f5f48a95336c09": {
    "text": "莉莉朝著光跑去。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-1-f76b7bba39d2764f": {
    "text": "Her heart was beating fast.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-1-bef3a4d766b6616b": {
    "text": "她的心跳很快。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-2-fa29914b8586bc35": {
    "text": "The cave behind her shook again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-2-672a5dc9b88c9f27": {
    "text": "後方的洞穴再次震動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-3-3679bcdf302b1f45": {
    "text": "Rocks fell.\nDust filled the air.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-3-d7a3b81ca3ab4d39": {
    "text": "石頭掉落。\n空氣充滿灰塵。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-4-769e1e99bbacc70c": {
    "text": "“Faster!” Coco shouted.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-4-447ca3893abd2d89": {
    "text": "「快一點！」可可喊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-5-92eadcc019f3fbe9": {
    "text": "Lily did not stop.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-5-3ab8262e5f06ca51": {
    "text": "莉莉沒有停下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-6-f2b90935e059b461": {
    "text": "At the end of the path—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-6-f5c0215575dfed9e": {
    "text": "在路的盡頭——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-7-202de5e80df5280b": {
    "text": "She saw it.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-7-327b876ec562d2ba": {
    "text": "她看見了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-8-fe18d9f3d40f2d1b": {
    "text": "The Star Crystal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-8-528ea65c373fd31a": {
    "text": "星之水晶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-9-a4504153ef4d5dd6": {
    "text": "It floated in the center of a wide space.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-9-5a4f1adb84fba24f": {
    "text": "它漂浮在空間中央。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-10-9ad2c3a5a4d542a1": {
    "text": "Soft light spread across the cave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-10-75d359fc9c2f36e5": {
    "text": "柔和的光照亮整個洞穴。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-11-d8ed2291e873a024": {
    "text": "The light was warm and calm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-11-1771d60f1ba9177f": {
    "text": "光溫暖又平靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-12-627b1b98df3b34e1": {
    "text": "Lily slowed down.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-12-4ae6d2ab91a33805": {
    "text": "莉莉慢慢走近。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-13-d81fc621d2adf3c2": {
    "text": "“It’s… beautiful…” she whispered.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-13-4bcc83e55660455c": {
    "text": "「好……美……」她輕聲說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-14-43d0e651ab80975d": {
    "text": "The crystal shined like a small star.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-14-9eccd0f33e7cfbc6": {
    "text": "水晶像一顆小星星。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-15-190c8fadd28793d8": {
    "text": "Colors moved inside it.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-15-dcd14fbb415cd243": {
    "text": "裡面流動著顏色。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-16-351b9634a507bc37": {
    "text": "Blue… green… gold…",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-16-4bde7d769549c003": {
    "text": "藍色……綠色……金色……",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-17-51e9437bac2c926e": {
    "text": "Coco flew closer.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-17-89182e124455bdad": {
    "text": "可可飛近。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-18-84eb204747abea7d": {
    "text": "“This is the heart of the forest,” she said softly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-18-9ca6acd82996dedd": {
    "text": "「這是森林的心，」她說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-19-7d64e919c4e236af": {
    "text": "Prince Pebble sat quietly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-19-8757afd2e3a09c04": {
    "text": "卵石王子也安靜地坐著。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-20-5a3f52a99319c78b": {
    "text": "Even he stopped moving.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-20-1e81388e58d4a5e4": {
    "text": "連牠都不動了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-21-3935be21cfd00843": {
    "text": "The crystal felt peaceful.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-21-4a0a012f29c04423": {
    "text": "這個水晶讓人感到平靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-22-a0621ff28e7efe7a": {
    "text": "Lily stepped closer.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-22-9fc8526f78978694": {
    "text": "莉莉伸出手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-23-63fcf42228d287e7": {
    "text": "She raised her hand slowly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-23-1e030204bedae368": {
    "text": "當她碰到水晶——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-24-14f247005d0694a3": {
    "text": "The moment she touched it—\nFlash!",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-24-c552f5d7ed5f79bb": {
    "text": "閃光！",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-25-2e9b80986082ee73": {
    "text": "A bright light filled her eyes.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-25-64ee0d8bbd457f49": {
    "text": "她看見畫面。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-26-24a962ae1cc24166": {
    "text": "Lily gasped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-26-de109cf0717db623": {
    "text": "不是洞穴。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-27-9be23481b6091bf9": {
    "text": "She saw something.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-27-b3c9f317df478343": {
    "text": "不是森林。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-28-ce10e172f14374d0": {
    "text": "Not the cave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-28-1c4441b14ebd58ea": {
    "text": "是一段記憶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-29-3f03059e5aec81bd": {
    "text": "Not the forest.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-29-418d8d74220f5cb0": {
    "text": "很久以前——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-30-c6224024f90be8e6": {
    "text": "A memory.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-30-008b0eb77f945b52": {
    "text": "森林更明亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-31-5814d6d9b5964712": {
    "text": "Long ago—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-31-aa71a96b600b3c6c": {
    "text": "樹更高。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-32-dc019200b386c2f5": {
    "text": "The forest was brighter.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-32-c33f456f8e951f6a": {
    "text": "河流唱得更大聲。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-33-48eccc995f61f3c6": {
    "text": "The trees were taller.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-33-e93ec65adbb55f96": {
    "text": "動物快樂地玩耍。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-34-ec556f59e1c18afb": {
    "text": "The river sang louder.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-34-a78147e4c707f4fe": {
    "text": "中央的水晶更亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-35-2fd0c93bfe743227": {
    "text": "Animals played together.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-35-8291d0481fda9065": {
    "text": "但——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-36-6e293ba1d87fe212": {
    "text": "And in the center—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-36-324cb998e4b38b78": {
    "text": "一個小影子出現。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-37-168e604e72b717a5": {
    "text": "The Star Crystal shined even stronger.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-37-bc64be5b14f3952d": {
    "text": "很弱。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-38-08b61db03acf2b0b": {
    "text": "But then—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-38-559f3bea5c2b1607": {
    "text": "很小。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-39-d6bc4000d9e0af54": {
    "text": "A small shadow appeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-39-35bbb6b925b9fc73": {
    "text": "很孤單。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-40-68cafcf700938da1": {
    "text": "It was weak.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-40-4d2ddc8883b83cba": {
    "text": "它遠離光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-41-b37cc6ada87b953c": {
    "text": "Small.\nLonely.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-41-b5c14443ce2359f6": {
    "text": "「不……」莉莉輕聲說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-42-90ade76c324cc160": {
    "text": "It stayed far from the light.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-42-337ca4c8915b6f5c": {
    "text": "畫面改變。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-43-a1512ac6d7883763": {
    "text": "“No…” Lily whispered.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-43-ba7cc64ca4383e37": {
    "text": "影子變大。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-44-5adf06792e93f2b3": {
    "text": "The memory changed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-44-ee5a0ce868516c32": {
    "text": "它想靠近水晶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-45-145f6c2a9a5c4a24": {
    "text": "The shadow grew bigger.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-45-185b325be9e0135d": {
    "text": "但光把它推開。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-46-11a4eb1d87f132dc": {
    "text": "It tried to reach the crystal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-46-28413bf9f312f5ba": {
    "text": "一次又一次。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-47-42aa1773f1367da8": {
    "text": "But the light pushed it away.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-47-54f000438c81132d": {
    "text": "影子變得生氣。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-48-f4ccbd458f89c81d": {
    "text": "Again and again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-48-65aec7a920aacab9": {
    "text": "變得更黑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-49-8052d4a5f21f4542": {
    "text": "The shadow became angry.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-49-ac2cb21f51750eb9": {
    "text": "更強。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-50-7778f594965d404e": {
    "text": "It turned darker.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-50-29a210318f7f075b": {
    "text": "開始討厭光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-51-8f8740aa639cecf1": {
    "text": "Stronger.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-51-3e5235d5b26b44c6": {
    "text": "「我懂了……」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-52-74101a82efd72305": {
    "text": "It began to hate the light.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-52-232b5ac792befc88": {
    "text": "光消失。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-53-d809de787df90154": {
    "text": "“I understand…” Lily said softly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-53-67596bb73b819036": {
    "text": "她回到洞穴。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-54-dddab97b9f310bb3": {
    "text": "The light faded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-54-d4d720a453cfd282": {
    "text": "可可看著她。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-55-e7ac64d60fa5fd7a": {
    "text": "She returned to the cave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-55-59d154c07e21a568": {
    "text": "「你看到了什麼？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-56-a3dd9074eeef3d76": {
    "text": "Coco looked at her.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-56-97d7f802ad3a8fcf": {
    "text": "莉莉難過地說：",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-57-5a9688e54284c6b0": {
    "text": "“What did you see?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-57-a155d23727d3935e": {
    "text": "「黑影……原本不是壞的。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-58-a649d38663d0c4bc": {
    "text": "Lily looked sad.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-58-a514defd17c3396e": {
    "text": "可可很驚訝。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-59-bde4d0dfd5188d38": {
    "text": "“The shadow… was not always evil.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-59-9f4e54458fbc357b": {
    "text": "「什麼意思？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-60-b5f0baec9587e42a": {
    "text": "Coco was surprised.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-60-d73f648791bbeeec": {
    "text": "「它很孤單，」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-61-075f7ff21d444127": {
    "text": "“What do you mean?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-61-0fbfa2129bf6d8bd": {
    "text": "「它想要光……但光拒絕它。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-62-0106c3c7aba93cee": {
    "text": "“It was lonely,” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-62-9bb6e59e839e25ac": {
    "text": "這時——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-63-3ef695948e021c65": {
    "text": "“It wanted the light… but the light pushed it away.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-63-740c9567a6c2d9ba": {
    "text": "一個聲音大喊：",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-64-484ee6d58f3ba171": {
    "text": "At that moment—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-64-c532005418d80ff1": {
    "text": "「住手！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-65-7ba404efe0032a28": {
    "text": "A loud voice echoed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-65-a76b206eb75cedda": {
    "text": "黑影出現。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-66-36ba33e352481f7d": {
    "text": "“STOP!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-66-b17aa4e2ac6028ba": {
    "text": "這次——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-67-a503c96d9f1e2c47": {
    "text": "The shadow appeared again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-67-944ac307e28eef57": {
    "text": "完整成形。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-68-a2f1103c37928e18": {
    "text": "But now—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-68-9877a442faf3be7e": {
    "text": "高大、黑暗、真實。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-69-08b9735ff46716ea": {
    "text": "It was fully formed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-69-b1a9fa8e4ab58d86": {
    "text": "紫色眼睛像火。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-70-dc43ea70278033e0": {
    "text": "Tall. Dark. Solid.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-70-49d59de4edc3180c": {
    "text": "「你看到了真相……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-71-b1d6f1b3befa5105": {
    "text": "Its purple eyes burned like fire.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-71-c4ff3f1aee354fb5": {
    "text": "莉莉站在水晶前。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-72-b969cd216837fc21": {
    "text": "“You saw the truth…” it said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-72-4bd6f4312595e8e5": {
    "text": "「對。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-73-dd42546267d28ceb": {
    "text": "Lily stood in front of the crystal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-73-ffff90288d6de852": {
    "text": "黑影走近。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-74-372f174b7dea9bcb": {
    "text": "“Yes.”\nThe shadow stepped closer.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-74-ef4d92ac4804968d": {
    "text": "「我只是想成為光的一部分……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-75-c20cfb141865f55e": {
    "text": "“I only wanted to be part of the light…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-75-8fdb2e6ed44d56c5": {
    "text": "「但它拒絕我！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-76-146aac03a333c9d8": {
    "text": "“But it rejected me!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-76-42e0d1ea6df09eca": {
    "text": "洞穴震動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-77-5b6c288d83130d62": {
    "text": "The cave trembled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-77-66851d8f41e775dc": {
    "text": "黑暗能量擴散。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-78-a597622c8ef0756f": {
    "text": "Dark energy spread around.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-78-9c511b8abe78cdb8": {
    "text": "可可小聲說：",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-79-ec3090ccca477e79": {
    "text": "Coco whispered,\n“It’s angry…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-79-5d6ea5d795d295b1": {
    "text": "「它很生氣……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-80-7b99a545e81e03d6": {
    "text": "Lily shook her head.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-80-e74707d3086e54d6": {
    "text": "莉莉搖頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-81-90ffde7ebad4dc33": {
    "text": "“You don’t need to destroy the forest.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-81-a705da4227f58872": {
    "text": "「你不需要毀掉森林。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-82-7c181e9d137492a0": {
    "text": "The shadow laughed bitterly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-82-eed110785cd7e887": {
    "text": "黑影苦笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-83-e89b175b69bf19f8": {
    "text": "“If I cannot have the light…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-83-0b1a9e866865b70d": {
    "text": "「如果我得不到光……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-84-dfd619d3623040a0": {
    "text": "“Then no one will!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-84-9658eb799bc11a15": {
    "text": "「那誰都別想得到！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-85-1d754a17e266d97e": {
    "text": "It raised its arms.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-85-1243905bb4835303": {
    "text": "它舉手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-86-e80bae0a87f6fd74": {
    "text": "Darkness rushed toward the crystal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-86-93ced5166bf8041b": {
    "text": "黑暗衝向水晶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-87-6ad8fb09b1d973aa": {
    "text": "Lily quickly held up the Moon Key.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-87-d2fb98a25bb81172": {
    "text": "莉莉舉起鑰匙。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-88-b7f7609a09596263": {
    "text": "The key shined.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-88-3717c01f2f530647": {
    "text": "鑰匙發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-89-26a5818c4eed64f8": {
    "text": "The Light Leaf glowed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-89-d09b115ada1c65b2": {
    "text": "葉子發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-90-122f0705a4016ebe": {
    "text": "The crystal responded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-90-8dcac0adf6c678a5": {
    "text": "水晶回應。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-91-f31567d2a2a27490": {
    "text": "All three lights joined together.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-91-76e7580bda5c1ade": {
    "text": "三種光融合。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-92-f4c7ffa3d14a2a1f": {
    "text": "Silver. Green. Gold.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-92-5eef62baf35b1b31": {
    "text": "銀色、綠色、金色。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-93-372909bc8b6d2f0b": {
    "text": "They pushed back the darkness.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-93-ba5a8a40af682d4e": {
    "text": "黑暗被擋住。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-94-db5d34fec7e694e2": {
    "text": "The shadow screamed.\n“NO!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-94-a148fd03502fe05d": {
    "text": "黑影大叫：",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-95-78c11e54d00f01f0": {
    "text": "But it did not disappear.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-95-72b02aa47e79dac8": {
    "text": "「不！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-96-0190b8d61be6c9bb": {
    "text": "Instead—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-96-43aaa25529c869ca": {
    "text": "但它沒有消失。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-97-5259a4c0a10b3f62": {
    "text": "It grew even stronger.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-97-af30684663d7f854": {
    "text": "反而更強。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-98-a9ebd82d4d7c8727": {
    "text": "“I will take it by force!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-98-ef52e3477d1b5afb": {
    "text": "「我會用力量搶走它！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-99-7cd0e0c886a0fb41": {
    "text": "The shadow rushed forward.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-99-a5713c560ceb820c": {
    "text": "黑影衝過來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-100-86866043c6f3e85c": {
    "text": "Dark claws reached toward the crystal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-100-6865d26d155909c4": {
    "text": "黑色爪子伸向水晶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-101-aef48d777f41a3bc": {
    "text": "“Lily!” Coco shouted.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-101-faac1a27a235c137": {
    "text": "「莉莉！」可可喊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-102-c640b393c1413f2e": {
    "text": "Lily stepped forward.\n“No!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-102-1fa41540173ed7cf": {
    "text": "莉莉往前站。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-103-c199e774498e6bc4": {
    "text": "She stood between the shadow and the crystal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-103-72b02aa47e79dac8": {
    "text": "「不！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-104-ffaac5c9fa87ffc7": {
    "text": "Her hands were shaking.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-104-931c6866fa8a1b17": {
    "text": "她站在中間。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-105-5b56534370474c13": {
    "text": "But she did not move.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-105-0804ab7ee768e6ce": {
    "text": "手在發抖。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-106-4ff0fabd2ee7bb7e": {
    "text": "“You are not alone!” Lily shouted.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-106-a4bdf6a4a2d8f156": {
    "text": "但沒有退。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-107-6edd351a49aad039": {
    "text": "The shadow stopped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-107-46acf1596b5c3ce2": {
    "text": "「你不是一個人！」她喊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-108-d8541b121b21f995": {
    "text": "“What…?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-108-c3e3ee320a9c1856": {
    "text": "黑影停住。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-109-f265f23ad89b891e": {
    "text": "“You don’t need to fight,” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-109-a7cee81acc130322": {
    "text": "「什麼……？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-110-b1fa2dc2a4485266": {
    "text": "“You just need someone to understand you.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-110-93f4f8aaf8ac50dd": {
    "text": "「你不需要戰鬥，」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-111-fc0a88f0d6efaf38": {
    "text": "The cave became quiet.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-111-1df65eb0152f76b8": {
    "text": "「你只是需要有人理解你。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-112-d2ef1992c49f0ba4": {
    "text": "The shadow trembled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-112-ad708feced6b4d93": {
    "text": "洞穴安靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-113-b6097cc4422c1caf": {
    "text": "Its form flickered.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-113-92a66a540dd2a4cf": {
    "text": "黑影顫抖。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-114-08a6ab760fb1e5f5": {
    "text": "“Understand… me…?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-114-4087369c57418f9f": {
    "text": "形體不穩。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-115-76b458ea080cf1d7": {
    "text": "Lily nodded.\n“Yes.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-115-4cab2a19a7ed768f": {
    "text": "「理解……我……？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-116-90dbd603321ef3ad": {
    "text": "The Light Leaf floated closer.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-116-62fcedc953945497": {
    "text": "莉莉點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-117-8b0008845e4ff3dc": {
    "text": "It gave a soft light.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-117-4bd6f4312595e8e5": {
    "text": "「對。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-118-8520064184d3f27d": {
    "text": "Not strong.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-118-f8592fded2d73781": {
    "text": "光之葉飄近。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-119-29fa25f3cc5b673d": {
    "text": "Not painful.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-119-9657b8e1f590a3b4": {
    "text": "光變柔和。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-120-0de8429ea9d205f7": {
    "text": "Gentle.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-120-6201ea9021bebf8c": {
    "text": "不刺眼。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-121-415ee3b90d76ab1d": {
    "text": "The shadow stepped back.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-121-fb05a6c81610a9e7": {
    "text": "不痛。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-122-aad7332ce3528486": {
    "text": "The light touched it.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-122-0dbdcfb9ad24fa0e": {
    "text": "很溫暖。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-123-441e7510747f1f45": {
    "text": "It did not scream.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-123-93fcde7e23f6a27f": {
    "text": "黑影後退。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-124-0190b8d61be6c9bb": {
    "text": "Instead—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-124-7405093a43743bd1": {
    "text": "光碰到它。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-125-66a835ffdc18ef59": {
    "text": "It grew smaller.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-125-c33bbe4d20843dcb": {
    "text": "它沒有痛苦。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-126-00dde7ff3d788855": {
    "text": "Its shape changed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-126-b8503db0c72040ee": {
    "text": "反而——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-127-4a5474cedb248ea4": {
    "text": "The dark smoke faded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-127-36675c96fcfe4c4b": {
    "text": "變小了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-128-e0b44cdbd0517cbe": {
    "text": "Slowly—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-128-39955d3ac4c6c06c": {
    "text": "形狀改變。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-129-1700eefde41e4ee0": {
    "text": "A small figure appeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-129-4a121880d7597c80": {
    "text": "黑煙消失。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-130-20b68b19895515de": {
    "text": "Not a monster.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-130-73c1738eba68fa1a": {
    "text": "慢慢地——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-131-b01e562cd28d237c": {
    "text": "Just a tiny, shadow-like creature.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-131-02ecea61c5d25b1f": {
    "text": "變成一個小小的影子。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-132-36184e301d4ab85a": {
    "text": "It looked weak.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-132-7991664f94b68e73": {
    "text": "不是怪物。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-133-2c91c2dfeec32011": {
    "text": "Sad.\nLonely.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-133-3d1fbcc6489f7139": {
    "text": "只是小小的影子生物。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-134-c09bf67fff90fba3": {
    "text": "Coco gasped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-134-71e0afb664ce00a2": {
    "text": "看起來虛弱。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-135-5f7fb8c6b1de37ae": {
    "text": "“It’s… different…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-135-f6df67c3ae536157": {
    "text": "孤單。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-136-d02233d08c8d558d": {
    "text": "Lily knelt down.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-136-7d7844abab0eca64": {
    "text": "可可驚呼。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-137-445ddb9a46a2f759": {
    "text": "“It’s okay,” she said softly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-137-b21ff0f34fdef9ad": {
    "text": "「變了……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-138-641e2a8761e58c85": {
    "text": "The small shadow looked at her.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-138-d274449d5b51abfa": {
    "text": "莉莉蹲下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-139-8adb51650f9b4a6d": {
    "text": "“Really…?”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-139-84fe95b16d3c3032": {
    "text": "「沒事的，」她說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-140-721f6d7ff35aae07": {
    "text": "“Yes,” Lily smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-140-e079823f35e78f9b": {
    "text": "小影子看著她。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-141-32fa4007d17076e3": {
    "text": "“You can stay with the light.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-141-31c6579db48a3076": {
    "text": "「真的嗎……？」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-142-41de42ed0eea6e01": {
    "text": "The Star Crystal shined brighter.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-142-12749659f0830b4f": {
    "text": "「真的，」莉莉微笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-143-2ec29953d6e86a11": {
    "text": "Warm light filled the cave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-143-2bf2411aa451d616": {
    "text": "「你可以和光在一起。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-144-e3dc67a75a174c8a": {
    "text": "The small shadow did not disappear.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-144-629926bcaf9cffa1": {
    "text": "星之水晶發出更亮的光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-145-635f085a61b66c96": {
    "text": "It stayed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-145-37ea0a45ca3f707c": {
    "text": "溫暖充滿洞穴。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-146-a2f1103c37928e18": {
    "text": "But now—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-146-84533dc6ec26c239": {
    "text": "小影子沒有消失。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-147-c3444335a0bf390c": {
    "text": "It was calm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-147-f52b7e0b7f2743bd": {
    "text": "但變得平靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-148-bed0af397f15d14e": {
    "text": "The darkness was gone.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-148-407a895ee6786622": {
    "text": "黑暗消失了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-149-6818089efc1bd4cf": {
    "text": "The cave became peaceful again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-149-3af3a004bd75a59e": {
    "text": "洞穴恢復平靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-150-e5b319b942d419b8": {
    "text": "Coco smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-150-ae4ca75292a57e96": {
    "text": "可可笑了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-151-9d013f464254f184": {
    "text": "“You saved it… and the forest.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-151-b1d4db494b635ea4": {
    "text": "「你救了它，也救了森林。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-152-ebdb827bfd085288": {
    "text": "Prince Pebble jumped happily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-152-e014f9e3bc23da26": {
    "text": "卵石王子開心跳。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-153-074955c4579d5fc1": {
    "text": "“Ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-153-8a51de2c2468d300": {
    "text": "「呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-154-d8ff0bb40d0d28f7": {
    "text": "Lily looked at the crystal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-154-6042c0ad3ff0f428": {
    "text": "莉莉看著水晶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-155-59874313f37e32b2": {
    "text": "The colors were brighter than before.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-155-c5bee7f4e2ca83ef": {
    "text": "光比以前更亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c7-en-block-156-ef3c136b9856010a": {
    "text": "The forest was safe.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c7-zh-block-156-7a7f93fe755b1d30": {
    "text": "森林安全了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-title-3c385ca8ef35cbcf": {
    "text": "The Light Returns",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-title-30a191e463fc0f5e": {
    "text": "光的回歸",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-0-0e98ca64c874a290": {
    "text": "The cave was quiet again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-0-a9b58cacfa57f934": {
    "text": "洞穴再次恢復安靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-1-76f2ad8a3bb80de7": {
    "text": "The Star Crystal shined brighter than ever.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-1-4a9b115760512c55": {
    "text": "星之水晶比之前更加閃亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-2-a087430676211611": {
    "text": "Warm light filled every corner.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-2-7a0d66ad720e3ad9": {
    "text": "溫暖的光充滿每個角落。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-3-c5455147bf4e3199": {
    "text": "Lily stood up slowly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-3-2d580bd5dbaf5593": {
    "text": "莉莉慢慢站起來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-4-da819d290c07e26f": {
    "text": "She looked at the small shadow.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-4-a9ccde4994f83904": {
    "text": "她看著那個小影子。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-5-eadf2332f1b89b68": {
    "text": "It was no longer scary.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-5-0ac55100e53ad5ff": {
    "text": "它不再可怕。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-6-4d33d2d58d53d882": {
    "text": "It looked soft and calm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-6-d01327fd69b800ce": {
    "text": "看起來柔和又平靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-7-5cdd254029c11285": {
    "text": "Coco flew beside Lily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-7-f2bd042a4b59078c": {
    "text": "可可飛到莉莉旁邊。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-8-fa75995202982866": {
    "text": "“You did something amazing,” she said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-8-7fe13a9ef287a80f": {
    "text": "「你做了一件很了不起的事，」她說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-9-05e868478c08c4bb": {
    "text": "Lily smiled gently.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-9-85b26b0d2c54f947": {
    "text": "莉莉輕輕微笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-10-a82ad4432047d687": {
    "text": "“I just listened.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-10-964634803ac275ae": {
    "text": "「我只是願意傾聽。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-11-1fd59a09cdb0aa6f": {
    "text": "The small shadow moved closer.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-11-52607172d8d054c9": {
    "text": "小影子慢慢靠近。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-12-918c1ed8749f9790": {
    "text": "It looked at the crystal.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-12-e2eadb3846a4e651": {
    "text": "它看著水晶。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-13-c6dced70092f7724": {
    "text": "Then it looked at Lily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-13-55a836424a942d9c": {
    "text": "然後看著莉莉。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-14-bbb5667caa024ec4": {
    "text": "“Thank you…” it said softly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-14-a385188be177a5e3": {
    "text": "「謝謝你……」它輕聲說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-15-3277daceb33d2b50": {
    "text": "Lily nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-15-62fcedc953945497": {
    "text": "莉莉點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-16-25c3a95e00188449": {
    "text": "“You are not alone anymore.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-16-c47e6289bc971a8f": {
    "text": "「你不再孤單了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-17-aff94b8990ee083d": {
    "text": "The crystal glowed even brighter.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-17-39075a6d030a8144": {
    "text": "水晶發出更強的光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-18-b09db866102d532e": {
    "text": "Light spread out of the cave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-18-175cb4868246bab4": {
    "text": "光從洞穴散出去。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-19-82dfda19fc6a27a0": {
    "text": "It moved through the forest.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-19-b39340058d6a7e12": {
    "text": "傳遍整個森林。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-20-9d4975583230f58f": {
    "text": "Far and wide.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-20-91dae55a3cc2c3ad": {
    "text": "樹再次發光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-21-400942d9c6e4f33a": {
    "text": "Trees began to shine again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-21-eee43230101cc80e": {
    "text": "花朵綻放。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-22-7f57fceedf98d86e": {
    "text": "Flowers opened their petals.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-22-46994d9339c8760a": {
    "text": "河流再次歌唱。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-23-ba3a7ba021c809fe": {
    "text": "The river sang loudly once more.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-23-1b88527823d63022": {
    "text": "啦啦啦……",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-24-dc99536f1e1b26dd": {
    "text": "La la la…",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-24-e3949dccc194c30c": {
    "text": "鳥兒飛回天空。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-25-4398afb0c39b8973": {
    "text": "Birds returned to the sky.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-25-419e6badccc547bd": {
    "text": "動物從躲藏處出來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-26-3fda05845fad5d98": {
    "text": "Animals came out from hiding.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-26-e761dd8ec80a2426": {
    "text": "森林恢復了生命。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-27-448e837ea01eac58": {
    "text": "The forest was alive again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-27-7fac6f81cffe1bbf": {
    "text": "可可開心地拍手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-28-117b47ce9e4189e0": {
    "text": "Coco clapped happily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-28-8d3f2ebd38e27d08": {
    "text": "「魔法回來了！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-29-19bfb455ce0d5f30": {
    "text": "“The magic is back!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-29-968ef9efb1993f07": {
    "text": "卵石王子跳來跳去。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-30-5bd9b408121191ce": {
    "text": "Prince Pebble jumped and splashed in a small puddle.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-30-8a51de2c2468d300": {
    "text": "「呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-31-074955c4579d5fc1": {
    "text": "“Ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-31-e529f0db7a3f14b8": {
    "text": "莉莉笑了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-32-63030f7a61d1a4ff": {
    "text": "Lily laughed.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-32-070cf506f42106c6": {
    "text": "「我們成功了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-33-d546a45d8532031e": {
    "text": "“We did it.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-33-7d965af739f5c33a": {
    "text": "小影子靜靜站著。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-34-04cd6c4cb73eff7c": {
    "text": "The small shadow stood quietly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-34-a759f436f5864a03": {
    "text": "接著發生了奇妙的事。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-35-e577ec21211b64fe": {
    "text": "Then something wonderful happened.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-35-cacc944cf415ebf7": {
    "text": "它的黑暗身體開始改變。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-36-3bbb0ff06afe53d7": {
    "text": "Its dark body began to change.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-36-1434d99c48d0bb34": {
    "text": "一點一點——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-37-874f5471c57a0877": {
    "text": "Little by little—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-37-e0e8fc9710655fbc": {
    "text": "變成柔和的灰色光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-38-eb85b974b7e27420": {
    "text": "It turned into soft gray light.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-38-54e3039e38b39fb0": {
    "text": "它仍然是影子，",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-39-7e98d3bb489f37f6": {
    "text": "It was still a shadow,\nbut now it had light inside.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-39-df8789e2fcc65332": {
    "text": "但裡面有光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-40-c09bf67fff90fba3": {
    "text": "Coco gasped.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-40-7d7844abab0eca64": {
    "text": "可可驚呼。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-41-29e656584c17945f": {
    "text": "“It found its balance!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-41-84299465cf79ac29": {
    "text": "「它找到平衡了！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-42-5beb2ca24286f48c": {
    "text": "The small shadow smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-42-b7779c1c7f3fac33": {
    "text": "小影子微笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-43-d297682ba6d699aa": {
    "text": "“I feel… warm…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-43-dd99354017bfcb77": {
    "text": "「我覺得……好溫暖……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-44-1ba5e8bde507f28c": {
    "text": "Lily felt happy.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-44-df99ee2006abe0e7": {
    "text": "莉莉很開心。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-45-df59debf856449bd": {
    "text": "“That’s your light.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-45-8ab843256f295eb6": {
    "text": "「那就是你的光。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-46-48a40e4c2e40a15d": {
    "text": "The Star Crystal floated down slowly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-46-53c6f4821b68ce00": {
    "text": "星之水晶慢慢飄下來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-47-ea1081f69881d703": {
    "text": "It came closer to Lily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-47-9159c9a3b94ad51e": {
    "text": "靠近莉莉。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-48-b80166c3afbf6a3e": {
    "text": "Coco whispered,",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-48-9c511b8abe78cdb8": {
    "text": "可可小聲說：",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-49-147d67248d590184": {
    "text": "“It is thanking you.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-49-c9aeb5268c3d99fc": {
    "text": "「它在感謝你。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-50-8ce78368588d610e": {
    "text": "The crystal touched Lily’s hand.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-50-a10da82a550fe68b": {
    "text": "水晶碰到莉莉的手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-51-0ce996f9df7b2cc2": {
    "text": "A soft glow surrounded her.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-51-7c3c521039ad05be": {
    "text": "柔和光包圍她。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-52-465a2b146e52381e": {
    "text": "She felt warm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-52-40893cef2499dbdd": {
    "text": "她感到溫暖。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-53-33e91dca9be0d48a": {
    "text": "Peaceful.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-53-7e68ed18ff7ca5a9": {
    "text": "平靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-54-c3b7f28de9a1317d": {
    "text": "Brave.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-54-1a8d573110312ffe": {
    "text": "勇敢。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-55-3fe5369a1aecf13c": {
    "text": "Then the crystal slowly floated back.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-55-a8587f4c467a9d73": {
    "text": "然後水晶慢慢回到原位。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-56-c17a81014c977857": {
    "text": "Everything was calm.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-56-e5a9b62d66129c18": {
    "text": "一切恢復平靜。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-57-1fecbe1055c0d679": {
    "text": "After a moment, the Light Leaf moved again.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-57-c3c99b26b423eafa": {
    "text": "過了一會兒，光之葉再次移動。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-58-dc512010d13fc2ed": {
    "text": "It floated toward the cave entrance.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-58-e2a719404ab20f0a": {
    "text": "它飄向洞口。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-59-6a87f823ce6d7a18": {
    "text": "“I think it’s time to go,” Lily said.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-59-d1d9977de8d86cdf": {
    "text": "「我想我們該走了，」莉莉說。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-60-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-60-51cdf3801661ec77": {
    "text": "可可點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-61-860ce442aa05e2b2": {
    "text": "“Yes… but I will miss you.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-61-04898fc6d88c687c": {
    "text": "「是的……但我會想你的。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-62-06a26888ecde019f": {
    "text": "Lily looked at Coco.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-62-525387a6dc0fba3c": {
    "text": "莉莉看著可可。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-63-4788be0f85305c61": {
    "text": "“I will miss you too.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-63-d9cf3977cab1c82b": {
    "text": "「我也會想你。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-64-7f4216a31361ba9f": {
    "text": "Prince Pebble hopped over.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-64-e76814258464ed67": {
    "text": "卵石王子跳過來。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-65-3bee303e7ffe7eac": {
    "text": "“Ribbit…”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-65-ea268340db34c09f": {
    "text": "「呱……」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-66-d02233d08c8d558d": {
    "text": "Lily knelt down.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-66-d274449d5b51abfa": {
    "text": "莉莉蹲下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-67-00f900f558d4316c": {
    "text": "She gently touched his head.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-67-05d364af32a84f46": {
    "text": "輕輕摸牠的頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-68-70d62e76161fc563": {
    "text": "“Take care, Pebble.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-68-26b0dd41028b6fcc": {
    "text": "「保重，卵石。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-69-4b3dd680ad0580cc": {
    "text": "They walked out of the cave together.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-69-7132a5e70b73a760": {
    "text": "她們一起走出洞穴。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-70-d53247f8c8a55b5a": {
    "text": "The forest outside was bright and beautiful.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-70-9b34ff430db30f6b": {
    "text": "外面的森林明亮又美麗。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-71-9cecc3b4d757e733": {
    "text": "Everything looked alive.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-71-afe7d6d3865a052b": {
    "text": "一切充滿生命。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-72-295249c81cb2e5c2": {
    "text": "The sky was clear.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-72-65624fcd17738aca": {
    "text": "天空晴朗。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-73-d5a3222a4ddebe9d": {
    "text": "The air felt fresh.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-73-1fd525c5d9762b5e": {
    "text": "空氣清新。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-74-2509881da561c0af": {
    "text": "They walked back to the Whispering Stones.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-74-645f4ad79d69cbcf": {
    "text": "她們走回低語之石。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-75-87f777566e974b97": {
    "text": "The stones glowed softly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-75-6f4c96d72959419b": {
    "text": "石頭發出柔和光。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-76-e28446a49f7f4f74": {
    "text": "“Thank you…” the voices whispered.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-76-d80d39c5cdb6e241": {
    "text": "「謝謝你……」聲音低語。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-77-98b0f90a593f7dad": {
    "text": "Lily smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-77-65c8ac423228dec4": {
    "text": "莉莉微笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-78-e6ce187ab62abae5": {
    "text": "“You’re welcome.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-78-8f5110d0cd670307": {
    "text": "「不客氣。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-79-a084273f12d9a3cb": {
    "text": "They walked past the Singing River.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-79-c95130e7ad0ff406": {
    "text": "她們經過會唱歌的河流。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-80-e5ecc0c43632cd03": {
    "text": "The water sang happily.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-80-ab769d87fccaf31b": {
    "text": "河水開心地歌唱。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-81-4b1bb9c54b3ad3c0": {
    "text": "Flowers danced in the wind.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-81-0d6355e6530b3789": {
    "text": "花在風中搖擺。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-82-e14228d2a64bfc96": {
    "text": "They reached the place where Lily first met Coco.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-82-fe9688438e53fb70": {
    "text": "她們回到與可可相遇的地方。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-83-e4797afff09eea50": {
    "text": "Coco flew slowly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-83-5d3ede2b511c7778": {
    "text": "可可慢慢飛著。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-84-dea0bb96da843d4f": {
    "text": "“This is where we say goodbye.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-84-3b6d8eae418d202f": {
    "text": "「這裡就是說再見的地方了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-85-1052b74f52850953": {
    "text": "Lily felt a little sad.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-85-5047712a97ed9276": {
    "text": "莉莉有點難過。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-86-262ef4aa59db9b1a": {
    "text": "“Will I see you again?” she asked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-86-97fb001f92fd8ce5": {
    "text": "「我們還會再見嗎？」她問。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-87-e5b319b942d419b8": {
    "text": "Coco smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-87-9b7a50ddc0d9f297": {
    "text": "可可微笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-88-f1c620f929a8d74b": {
    "text": "“The forest remembers brave hearts.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-88-ee18bf9bc3856c4c": {
    "text": "「森林會記得勇敢的心。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-89-28c4c1ee2b438c1d": {
    "text": "“If you ever need us… we will be here.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-89-4f0be0851942496c": {
    "text": "「如果你需要我們……我們就在這裡。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-90-4beda07e7561348d": {
    "text": "The Light Leaf floated down.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-90-c825a1dc41dce25b": {
    "text": "光之葉慢慢落下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-91-7b301130198ce3d5": {
    "text": "It landed gently in Lily’s hand.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-91-67e18ed27115c5d6": {
    "text": "落在莉莉手中。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-92-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-92-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-93-160cab87c09605d5": {
    "text": "It turned into a normal leaf.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-93-d70dd1729820cf40": {
    "text": "變成普通葉子。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-94-1206ad0f081b8ce7": {
    "text": "The glow disappeared.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-94-f8f7e90a2992c882": {
    "text": "光消失了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-95-b792b46a41cee3be": {
    "text": "Lily blinked.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-95-b7cdb96f141f1003": {
    "text": "莉莉眨眼。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-96-3f8610477b9fdd96": {
    "text": "“It’s… just a leaf now.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-96-3e0175f506937352": {
    "text": "「現在只是普通葉子了。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-97-0a97e00c0113d73a": {
    "text": "Coco nodded.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-97-51cdf3801661ec77": {
    "text": "可可點頭。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-98-2fc6a4cbdcd070af": {
    "text": "“You don’t need it anymore.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-98-c91271cf7bc9c424": {
    "text": "「因為你不再需要它。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-99-f17e7126628ee5a4": {
    "text": "Lily understood.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-99-d4981c0938596a3c": {
    "text": "莉莉明白了。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-100-30ae7e55798451ca": {
    "text": "She had something stronger now.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-100-e88491b9f566d10c": {
    "text": "她已經擁有更重要的東西。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-101-1a7c2f3bd870db38": {
    "text": "Courage.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-101-0f52430a53fc0ad6": {
    "text": "勇氣。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-102-b3c6a2b02cab2e89": {
    "text": "Kindness.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-102-a5dec151e212c4b9": {
    "text": "善良。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-103-c511ccb02cd569fe": {
    "text": "And a brave heart.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-103-ed95c416f45ed99e": {
    "text": "還有一顆勇敢的心。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-104-e4b5c80854a5c522": {
    "text": "Prince Pebble gave one last jump.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-104-0e9c7b8657c1492e": {
    "text": "卵石王子最後跳了一下。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-105-074955c4579d5fc1": {
    "text": "“Ribbit!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-105-8a51de2c2468d300": {
    "text": "「呱！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-106-c2e28daabfc303ed": {
    "text": "Coco waved.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-106-2223b2f47c32bada": {
    "text": "可可揮手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-107-9c659ac8798289d7": {
    "text": "“Goodbye, Lily!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-107-b0fd6dc046d36b90": {
    "text": "「再見，莉莉！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-108-14427966ab8c0c26": {
    "text": "Lily waved back.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-108-826e7a74f60be7b1": {
    "text": "莉莉也揮手。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-109-7850f818e8d8e381": {
    "text": "“Goodbye!”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-109-02e0248817c86428": {
    "text": "「再見！」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-110-1855b2233e26b4bb": {
    "text": "She turned and walked out of the forest.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-110-0c76324885f91c15": {
    "text": "她轉身走出森林。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-111-ed4bbe61dfcea51d": {
    "text": "Step by step.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-111-6d8c37cda22b90e4": {
    "text": "一步一步。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-112-47bf7884c18d6e5c": {
    "text": "The trees became fewer.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-112-0784e02ad434c690": {
    "text": "樹越來越少。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-113-9854bc85f629ea18": {
    "text": "The sunlight grew brighter.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-113-a68262992d8a235d": {
    "text": "陽光越來越亮。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-114-cdd6bc9bf40107ee": {
    "text": "Soon—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-114-5b780605aec03a4a": {
    "text": "很快——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-115-044a054be99e83be": {
    "text": "She was back near her house.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-115-1adaccb5681f1449": {
    "text": "她回到家附近。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-116-6e85c45c73928b55": {
    "text": "It felt like a dream.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-116-5d0bdc40376cd768": {
    "text": "一切像一場夢。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-117-83d013658d936f70": {
    "text": "But in her hand,",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-117-19701683a0830954": {
    "text": "但她的手裡，",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-118-634d7a37db10f33c": {
    "text": "she still held the leaf.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-118-d21d12ce847edc21": {
    "text": "還握著那片葉子。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-119-98b0f90a593f7dad": {
    "text": "Lily smiled.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-119-65c8ac423228dec4": {
    "text": "莉莉微笑。",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-120-1ee31849f899e47c": {
    "text": "“I will come back someday.”",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-120-8c1525db9279c6f1": {
    "text": "「我一定會再回來。」",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-121-23736a09a54047c4": {
    "text": "Behind her—",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-121-9cf98486a04c2eef": {
    "text": "她的身後——",
    "lang": "zh-TW"
  },
  "v1-secret-forest-adventure-c8-en-block-122-04aa6f5b6eb18fe3": {
    "text": "the forest whispered softly.",
    "lang": "en-US"
  },
  "v1-secret-forest-adventure-c8-zh-block-122-d564acae545652ea": {
    "text": "森林輕聲低語。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-title-a09c6a162cf5d7a2": {
    "text": "The Letter in the Rain",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-title-c207721b784850ea": {
    "text": "雨中的信",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-0-755467d3dfbecf14": {
    "text": "Ethan Parker hated rainy days.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-0-88ee1aecd9802f8d": {
    "text": "伊森・帕克討厭下雨天。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-1-b5ccddac4ef9b48d": {
    "text": "Rain made the streets gray.\nIt made the windows cold.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-1-4d3942949f0ce5a9": {
    "text": "雨會讓街道變灰。\n讓窗戶變冷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-2-59a9f424d23d9bda": {
    "text": "And worst of all—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-2-d816cb3617d1cf5d": {
    "text": "最糟的是——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-3-05c873850a13c65d": {
    "text": "Rain always made the power go out in his apartment building.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-3-c99a6b126d5daae8": {
    "text": "每次下大雨，他住的公寓總會停電。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-4-b9f35501acd07bdd": {
    "text": "“Again?” Ethan sighed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-4-c0dbacbb57f18735": {
    "text": "「又來了？」伊森嘆氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-5-291191d025a7a64a": {
    "text": "The lights flickered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-5-816bac17e2db5b76": {
    "text": "燈閃了幾下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-6-0fa186a83dfde296": {
    "text": "Then everything became dark.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-6-7e76861aada33bad": {
    "text": "接著全部熄滅。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-7-e86962386991d7cc": {
    "text": "His grandmother lit a candle.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-7-b4302cdfd098703b": {
    "text": "奶奶點起一根蠟燭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-8-ee98651590fc57cd": {
    "text": "“There,” she said warmly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-8-e3c2ad2ccfb6ee8d": {
    "text": "「好了，」她溫柔地說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-9-7f7907f58a18373b": {
    "text": "“That’s better.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-9-83b3bf0aed732a97": {
    "text": "「這樣好多了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-10-87e7018d7360e8c4": {
    "text": "Ethan sat near the window.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-10-4e628419d18f2279": {
    "text": "伊森坐在窗邊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-11-406ea052002d57bc": {
    "text": "Outside, rain hit the glass softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-11-3365f3d7af6e074d": {
    "text": "外面的雨輕輕打在玻璃上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-12-a0eaaa42540df083": {
    "text": "Drip. Drip. Drip.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-12-f14c750b6514ccc9": {
    "text": "滴答。滴答。滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-13-117a84f068379845": {
    "text": "His grandmother smiled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-13-f1cb678b7d10c01c": {
    "text": "奶奶笑著說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-14-2e2550232c4f62c2": {
    "text": "“You always look so serious when it rains.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-14-3dcc9b5f6aa03e2b": {
    "text": "「你每次下雨都看起來很嚴肅。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-15-8d5037cb5170781a": {
    "text": "“I’m bored,” Ethan replied.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-15-14d20a6b8c7f85f1": {
    "text": "「因為很無聊，」伊森回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-16-82e9f84a150efaca": {
    "text": "“You say that every storm,” she laughed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-16-d99f4953f4392abe": {
    "text": "「你每次暴風雨都這樣說，」奶奶笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-17-71a4d3a287319966": {
    "text": "Ethan crossed his arms.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-17-0bca8e24e6a9e652": {
    "text": "伊森抱起手。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-18-4e91681eee54f940": {
    "text": "“There’s nothing exciting here.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-18-6d0196dc92479d45": {
    "text": "「這裡根本沒什麼有趣的事。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-19-228f05f32a538c4f": {
    "text": "His grandmother looked at him carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-19-15515d95b4efbaa7": {
    "text": "奶奶看著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-20-693da16375d180f9": {
    "text": "“Are you sure about that?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-20-e130b594e21355d9": {
    "text": "「你確定嗎？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-21-7090dfbf55f7eac5": {
    "text": "Before Ethan could answer—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-21-c417920b8c3d7259": {
    "text": "就在這時——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-22-89ed2147c57f3835": {
    "text": "Knock. Knock. Knock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-22-599ef1348d212f7c": {
    "text": "叩。叩。叩。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-23-f1f13809ce8876f6": {
    "text": "Someone was at the door.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-23-cbc6ce50e5539bf8": {
    "text": "有人敲門。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-24-f8f5e90c33f2c305": {
    "text": "“At this hour?” Ethan asked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-24-544267b906a1c599": {
    "text": "「這麼晚？」伊森問。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-25-2abf8869c401bfe7": {
    "text": "It was almost midnight.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-25-1f7432933195067c": {
    "text": "已經快午夜了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-26-e55cb3227d7d2608": {
    "text": "His grandmother stood slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-26-335a827b8b7b8950": {
    "text": "奶奶慢慢站起來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-27-d320bed2b6e976d7": {
    "text": "“I’ll get it.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-27-1ab1cbd466c40be2": {
    "text": "「我去看看。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-28-b481e9b661c2cf93": {
    "text": "When she opened the door—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-28-7cdbd13dab6fbd94": {
    "text": "當她打開門——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-29-2e68c4c3faea74d6": {
    "text": "Nobody was there.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-29-d965fc94f0f44548": {
    "text": "外面沒有人。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-30-24dbd82e0ac4cff9": {
    "text": "Only rain.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-30-259092513f0b0e72": {
    "text": "只有雨。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-31-97df5f4b2c84fcf4": {
    "text": "And a black envelope.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-31-bd6be05ad75f673f": {
    "text": "還有一個黑色信封。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-32-1d2e9047fe7a1f7e": {
    "text": "It rested quietly on the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-32-87276306d5fa820f": {
    "text": "靜靜躺在地上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-33-d67f68b9bf254d13": {
    "text": "Ethan blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-33-134fbeb356ccc19c": {
    "text": "伊森愣住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-34-2fd423a5e0a24891": {
    "text": "“That’s weird.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-34-50c5cfe57775146a": {
    "text": "「好奇怪。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-35-64826173dfd99538": {
    "text": "His grandmother picked it up carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-35-bcb030718eb76ada": {
    "text": "奶奶小心撿起信封。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-36-474b9897f0b02666": {
    "text": "The envelope looked old.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-36-f9485eb62fc10f4f": {
    "text": "那封信看起來很古老。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-37-78d1bc14be11155e": {
    "text": "Very old.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-37-73fc22df6649d89d": {
    "text": "非常古老。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-38-d9ccdc027c4a450e": {
    "text": "It had a silver symbol on the front.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-38-5ca1cd65bbc615e1": {
    "text": "正面有銀色圖案。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-39-3b2746a8538c8dcc": {
    "text": "A tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-39-8417cb3bdfcdbdcc": {
    "text": "一座高塔。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-40-4b39db3d88b846d5": {
    "text": "And around the tower—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-40-f7f1aa034b5b19c4": {
    "text": "高塔周圍——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-41-87ce6d86f5995dd5": {
    "text": "Tiny glowing stars.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-41-8787f0435f7654df": {
    "text": "發光的小星星。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-42-1c92748f313b2b2d": {
    "text": "Ethan stood up.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-42-5b1fbfc5db0893f1": {
    "text": "伊森站起來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-43-8a8f5c876fb4ddd9": {
    "text": "“Who sent that?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-43-80fc34e2abd743e9": {
    "text": "「誰寄的？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-44-47f8f2e99456f6c7": {
    "text": "His grandmother did not answer immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-44-30299bcb96b96a63": {
    "text": "奶奶沒有立刻回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-45-5599aa205be1d9cd": {
    "text": "Instead, she looked at the envelope silently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-45-f10f888e11de086c": {
    "text": "她只是安靜地看著信封。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-46-c7898345dfcb4823": {
    "text": "Almost nervously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-46-3947968733f59a9e": {
    "text": "看起來甚至有點緊張。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-47-ae7b7779d688e731": {
    "text": "“Grandma?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-47-82529cfd0552e34d": {
    "text": "「奶奶？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-48-23a88e7f2e3ba708": {
    "text": "She handed it to him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-48-717329500110404a": {
    "text": "她把信遞給他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-49-377b22cd17540e62": {
    "text": "“It has your name.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-49-7c4952ac6ae01dd7": {
    "text": "「上面寫著你的名字。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-50-e61b7ea861352676": {
    "text": "Ethan looked down.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-50-56c850ba903687c1": {
    "text": "伊森低頭看。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-51-03653b020e7612cf": {
    "text": "Written in silver ink were the words:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-51-f9cc11123a37a9c1": {
    "text": "銀色墨水寫著：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-52-b59f08c2afb99991": {
    "text": "✉️",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-52-2f2a4c905b455ac0": {
    "text": "✉️",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-53-16b0cb1a7ca08231": {
    "text": "To Ethan Parker\nRoom 7, Willow Street Apartments\nFor Immediate Delivery",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-53-811c10dcaf1d32fb": {
    "text": "寄給\n伊森・帕克\n柳樹街公寓7號房\n立即送達",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-54-c8270c3e70686e1e": {
    "text": "Ethan frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-54-f17d2890b308506c": {
    "text": "伊森皺起眉頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-55-e90857d0df9329b4": {
    "text": "“No stamp?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-55-e8ab277957a260f5": {
    "text": "「沒有郵票？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-56-f11d3eee184c455f": {
    "text": "“No address from the sender?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-56-04c0ec76a699f870": {
    "text": "「也沒有寄件地址？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-57-ade00a89880e12f1": {
    "text": "Then something strange happened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-57-7b5466b7eb213f85": {
    "text": "接著，奇怪的事發生了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-58-55ad2d606f99174c": {
    "text": "The silver letters began to glow.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-58-ec4493bf333d2f4e": {
    "text": "銀色字體開始發光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-59-fa69bdabcdf190b6": {
    "text": "Ethan almost dropped the envelope.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-59-e315d473e060600d": {
    "text": "伊森差點把信封丟掉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-60-8ddcd4f97aef61f3": {
    "text": "“What is this?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-60-68abb9fe61901902": {
    "text": "「這是什麼？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-61-869c46ae69a7c511": {
    "text": "“Open it,” his grandmother said softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-61-bf9f6aa587de5f18": {
    "text": "「打開它，」奶奶輕聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-62-74e8b056258d1329": {
    "text": "Ethan carefully broke the seal.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-62-103dfde38cfe3349": {
    "text": "伊森小心地拆開封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-63-1ffe2079174b77c1": {
    "text": "Inside was a thick paper letter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-63-1845b1b512fb2485": {
    "text": "裡面是一封厚厚的紙信。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-64-e6827b6c47779ba3": {
    "text": "The paper smelled like old books and rain.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-64-a1994c07d9cd7047": {
    "text": "那張紙聞起來像舊書和雨水。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-65-474f22136489570f": {
    "text": "He unfolded it slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-65-d5b8c520c2199e34": {
    "text": "他慢慢打開信。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-66-b59f08c2afb99991": {
    "text": "✉️",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-66-2f2a4c905b455ac0": {
    "text": "✉️",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-67-3a533c899eb591b1": {
    "text": "Dear Ethan Parker,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-67-81936afcf642d6d9": {
    "text": "親愛的伊森・帕克：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-68-2790cc9061017f9d": {
    "text": "You have been accepted into\nClock Tower Magic School.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-68-9594caedf7116e6c": {
    "text": "你已被錄取進入\n時鐘塔魔法學院。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-69-3046ccfda1eca5f1": {
    "text": "Classes begin in seven days.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-69-c8ff030c5ead8cef": {
    "text": "課程將於七天後開始。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-70-75357837a6b5d6bb": {
    "text": "A train ticket is enclosed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-70-cbfb6f0c9bbb57f2": {
    "text": "內附火車票。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-71-f48f354c8783db8e": {
    "text": "Do not be late.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-71-9821c91c464ebb0a": {
    "text": "請勿遲到。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-72-7a53679558770ae6": {
    "text": "The tower bell rings only once.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-72-561d7da5f56f5080": {
    "text": "鐘塔的鐘，只會響一次。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-73-1a854a3955ac4739": {
    "text": "Ethan stared at the letter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-73-a992d879e773fa76": {
    "text": "伊森盯著那封信。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-74-dd60a0dfd09131f3": {
    "text": "Then he laughed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-74-001d70b8c0075109": {
    "text": "然後他笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-75-1f0a718f5bba376a": {
    "text": "“Okay… very funny.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-75-ea63b2fdcd0205b0": {
    "text": "「好喔……真好笑。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-76-a93085de04f6eb76": {
    "text": "But his grandmother was not laughing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-76-2cf200b71296373d": {
    "text": "但奶奶沒有笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-77-9c601fc1ebdcf608": {
    "text": "She looked pale.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-77-714cd99a679807de": {
    "text": "她的臉色很蒼白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-78-da9ce3a8be1369f9": {
    "text": "“You need to go,” she whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-78-42392acc3bb93c9b": {
    "text": "「你必須去，」她低聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-79-8f9ab27d92d2acee": {
    "text": "Ethan stopped smiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-79-e38e0fce91daa81e": {
    "text": "伊森停止笑容。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-80-5442659457095c55": {
    "text": "“What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-80-5ab60aad745f2829": {
    "text": "「什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-81-672c483cf3454382": {
    "text": "“The school is real.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-81-5a3c363c37bfca4b": {
    "text": "「那間學校是真的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-82-71b73e7f639d4136": {
    "text": "Lightning flashed outside.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-82-11f33e95aa117fc9": {
    "text": "外面閃電劃過。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-83-02aec70c71035070": {
    "text": "BOOM.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-83-3900b75e01c0a237": {
    "text": "轟隆！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-84-5e1cad63dc2089d6": {
    "text": "Thunder shook the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-84-93ecd2e5d8fc5f8b": {
    "text": "雷聲震動房間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-85-bde91d8efc17e130": {
    "text": "Ethan looked at his grandmother.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-85-ccf278b5d8a889ce": {
    "text": "伊森看著奶奶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-86-d562d433ae13c817": {
    "text": "“You’re joking…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-86-71cb2d510aa2e8c5": {
    "text": "「妳在開玩笑吧……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-87-1757a084fd270b96": {
    "text": "She slowly sat down.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-87-779000aa9324fdec": {
    "text": "奶奶慢慢坐下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-88-0752c90b61e92054": {
    "text": "“I hoped the letter would never come.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-88-7e4f3944213b17a8": {
    "text": "「我一直希望這封信不要來。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-89-ac1900629fd25e4e": {
    "text": "“What are you talking about?” Ethan asked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-89-39cab6021ee2b527": {
    "text": "「妳到底在說什麼？」伊森問。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-90-33e417bcea6b5cf4": {
    "text": "His grandmother looked at the candle flame.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-90-049b04171b79b5a2": {
    "text": "奶奶看著蠟燭火光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-91-9ec976d718fd2727": {
    "text": "Then she spoke quietly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-91-43a726821ba61022": {
    "text": "然後輕聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-92-073c560db7c727ab": {
    "text": "“Your parents studied at Clock Tower Magic School.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-92-70d985145fc10024": {
    "text": "「你的父母以前就在時鐘塔魔法學院讀書。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-93-641a78e1b01c7f32": {
    "text": "Ethan froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-93-134fbeb356ccc19c": {
    "text": "伊森愣住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-94-5442659457095c55": {
    "text": "“What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-94-5ab60aad745f2829": {
    "text": "「什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-95-64cdd3abf0f9c0a7": {
    "text": "“They were magic users.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-95-3e1f3d4c2a2ccfb8": {
    "text": "「他們是魔法使用者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-96-967aced327f709d8": {
    "text": "The room became silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-96-4191760794c19a96": {
    "text": "房間安靜下來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-97-b11510459b0d5c31": {
    "text": "Only the rain remained.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-97-d52da0c0511f2674": {
    "text": "只剩雨聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-98-2f7ae249d85af141": {
    "text": "“That’s impossible,” Ethan whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-98-c5a91edba6fd28ce": {
    "text": "「這不可能……」伊森低聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-99-1369645af8adadae": {
    "text": "His grandmother stood again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-99-7c2d1839ca0a8876": {
    "text": "奶奶再次站起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-100-bd89e8dff2007d9d": {
    "text": "Without saying a word—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-100-6557bdf9f818f03d": {
    "text": "她一句話也沒說——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-101-c95bcf64802ecf7e": {
    "text": "She raised her hand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-101-9907463b0693d532": {
    "text": "只是抬起手。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-102-2b67b2d5681b164e": {
    "text": "The candle floated into the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-102-cd2358c94c5d3183": {
    "text": "蠟燭漂浮到空中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-103-6daad01fa18b0553": {
    "text": "Ethan’s eyes widened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-103-07d97fbc81d072b6": {
    "text": "伊森睜大眼睛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-104-2a8577007b9a0801": {
    "text": "The candle slowly circled the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-104-cad5674de2b2ef4e": {
    "text": "蠟燭慢慢繞著房間飛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-105-3a5bb1c53b3933ae": {
    "text": "Then gently returned to the table.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-105-037339a5123d84aa": {
    "text": "然後輕輕回到桌上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-106-732ed03b825ddd1e": {
    "text": "Ethan could not speak.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-106-cd37c57db50fe71b": {
    "text": "伊森說不出話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-107-b095d1c166338b40": {
    "text": "His heart raced wildly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-107-14038b557a4586fe": {
    "text": "他的心跳瘋狂加速。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-108-12466249f88bf081": {
    "text": "“You’re… a magician?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-108-f0ff45647d30545e": {
    "text": "「妳……是魔法師？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-109-33b142b2b645e87d": {
    "text": "His grandmother smiled sadly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-109-1f654f1945909356": {
    "text": "奶奶露出淡淡的悲傷微笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-110-52c6c2c489de3552": {
    "text": "“In our world, we are called Keepers.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-110-afd4f2489388493e": {
    "text": "「在我們的世界，我們被稱為『守護者』。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-111-2bdac7e11552fcc6": {
    "text": "Ethan looked at the letter again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-111-91d4310d136efc7c": {
    "text": "伊森再次看著那封信。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-112-18142ccf01bf7f1d": {
    "text": "The silver tower symbol glowed softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-112-e0f910d1c6d40a05": {
    "text": "銀色高塔圖案微微發光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-113-cba8a01413a2d6af": {
    "text": "“This can’t be real…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-113-22b25d36af6c8c58": {
    "text": "「這不可能是真的……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-114-b36030b9872fd660": {
    "text": "But deep inside—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-114-29e1ca2a3aea13d6": {
    "text": "但在他的心裡深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-115-81461ced0a59aa27": {
    "text": "For the first time in his life—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-115-f7237c67bc368c03": {
    "text": "人生第一次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-116-91ad3867d9e51cd8": {
    "text": "Ethan felt something strange.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-116-1b35151b60620fe9": {
    "text": "伊森感覺到某種奇妙的東西。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-117-1080f846c8e734fb": {
    "text": "Something exciting.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-117-794c452aef542d46": {
    "text": "某種令人興奮的東西。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-118-8c9709c69a2b2eaa": {
    "text": "Something impossible.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-118-18f6b30d4cbbd6dd": {
    "text": "某種不可能存在的東西。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c1-en-block-119-9b44b36a0cf5e4e1": {
    "text": "Magic.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c1-zh-block-119-5f657a7c3762e09f": {
    "text": "魔法。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-title-4e6c9fc11ff23684": {
    "text": "Platform Nine and the Hidden Train",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-title-50f3aff581bcb411": {
    "text": "九號月台與隱藏列車",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-0-090467ab8ae93563": {
    "text": "For the next seven days, Ethan could think about only one thing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-0-6522376c19186937": {
    "text": "接下來七天，伊森腦中只有一件事。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-1-9b44b36a0cf5e4e1": {
    "text": "Magic.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-1-5f657a7c3762e09f": {
    "text": "魔法。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-2-999a160e551d7e03": {
    "text": "Every morning, he looked at the silver letter again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-2-383322ecc5449645": {
    "text": "每天早上，他都會再次看那封銀色信件。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-3-0d3302b7ff9ad2e7": {
    "text": "Every night, he wondered the same question.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-3-4afa059e58f8c431": {
    "text": "每天晚上，他都在想同一個問題。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-4-9ddd571db2d3a076": {
    "text": "“Is this really happening?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-4-56a7922304a984be": {
    "text": "「這真的正在發生嗎？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-5-6f7228178c0d1442": {
    "text": "His grandmother answered very few questions.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-5-e5484f83327c8a53": {
    "text": "奶奶很少回答問題。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-6-4c6549788860bf0b": {
    "text": "She only said:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-6-8c417838d9d786fd": {
    "text": "她只說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-7-218116992bcc9e24": {
    "text": "“You will understand when you arrive.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-7-e9d10860c4507b2b": {
    "text": "「等你到了學校，你就會明白。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-8-0b812ce518e44682": {
    "text": "That made Ethan even more curious.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-8-501766d0f723832c": {
    "text": "這讓伊森更好奇了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-9-97631f0335118366": {
    "text": "On the seventh morning, heavy fog covered the city.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-9-43959c5a6dc8d342": {
    "text": "第七天早晨，濃霧籠罩城市。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-10-0e05724fa2445560": {
    "text": "Ethan stood beside his bed, staring at his suitcase.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-10-7455fce865cc4204": {
    "text": "伊森站在床邊，看著自己的行李箱。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-11-f1c7cd67dd210b5d": {
    "text": "Inside were strange things his grandmother bought for him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-11-fddf71b30c05be5a": {
    "text": "裡面裝著奶奶幫他買的奇怪東西。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-12-e8542c5ed7ded277": {
    "text": "A dark blue robe.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-12-c96be182de6a3f96": {
    "text": "深藍色長袍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-13-d3fdade7f62cf8d4": {
    "text": "Silver buttons.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-13-4fbcbbbbb514fa58": {
    "text": "銀色鈕扣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-14-844858ecfa56d7f5": {
    "text": "Three thick books:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-14-eccb5bb7f1fc8a44": {
    "text": "三本厚書：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-15-e287dc25c0964b7b": {
    "text": "History of the Keepers\nBeginner Spell Casting\nMagical Creatures of the North",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-15-9acf936f46d51e66": {
    "text": "《守護者歷史》\n《初級咒語施法》\n《北方魔法生物》",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-16-51e7d5bc91f7aa89": {
    "text": "And one more thing—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-16-ea60e17dee3c6500": {
    "text": "還有一樣東西——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-17-8df87355c715163c": {
    "text": "A silver pocket watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-17-540fc0acee74dfa1": {
    "text": "一只銀色懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-18-a0c2568925a6c5f0": {
    "text": "The watch had no numbers.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-18-e838261a9f7b67b8": {
    "text": "上面沒有數字。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-19-3e352e884342d7d4": {
    "text": "Only glowing lines.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-19-90cc93dd3296b5ef": {
    "text": "只有發光線條。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-20-15f847c40e1b4449": {
    "text": "“What does this do?” Ethan asked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-20-896014d864c4fc90": {
    "text": "「這是做什麼的？」伊森問。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-21-a189aaf26e7d3256": {
    "text": "His grandmother carefully placed it in his hand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-21-21feb36cd386fbba": {
    "text": "奶奶小心把它放到他手裡。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-22-c469b8207ddc5e28": {
    "text": "“It belonged to your father.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-22-1c26b431e6d013b8": {
    "text": "「這是你父親的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-23-a59b75efd0b1469e": {
    "text": "Ethan became quiet.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-23-cc7c9528d40fa538": {
    "text": "伊森安靜下來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-24-51452338125cd527": {
    "text": "He had very few memories of his parents.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-24-05654939c45b3a3e": {
    "text": "他對父母的記憶很少。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-25-41612e60384eec15": {
    "text": "They disappeared when he was very young.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-25-c15ff35fe710c2eb": {
    "text": "他們在他很小的時候就失蹤了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-26-5e7ae5cd784d5545": {
    "text": "His grandmother always avoided talking about them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-26-282175e8d7fdad13": {
    "text": "奶奶總是避免談論他們。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-27-a3d8f4a9dc09db9c": {
    "text": "But today felt different.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-27-84ffb9569aa14150": {
    "text": "但今天感覺不一樣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-28-a58ebe09fb5f9fc6": {
    "text": "“You’ll need it at the school,” she said.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-28-d0c4fb38dee2e761": {
    "text": "「你在學校會需要它，」她說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-29-9174df134dc4518a": {
    "text": "The watch suddenly ticked once.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-29-ee9d95e0f27bf6dd": {
    "text": "懷錶突然滴答一聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-30-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-30-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-31-9c23c0a041ad2898": {
    "text": "Its silver light flashed softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-31-5d271dab66e6c27c": {
    "text": "銀光微微閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-32-fd22141795730c58": {
    "text": "Ethan looked surprised.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-32-0f30db4b5525eb6a": {
    "text": "伊森驚訝地看著它。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-33-a2e4bfa2c26ff7ef": {
    "text": "“It works?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-33-b885513236d46e1b": {
    "text": "「它會動？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-34-700d2cbc5a42502a": {
    "text": "“It works when magic is near.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-34-d32e3689e52946b0": {
    "text": "「當魔法靠近時，它就會運作。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-35-0e5303deb04029ec": {
    "text": "Outside, thunder rumbled softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-35-7caee44affdf9846": {
    "text": "外面傳來低沉雷聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-36-117a84f068379845": {
    "text": "His grandmother smiled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-36-df190677f7ff33f3": {
    "text": "奶奶微笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-37-e22ec413e41712ba": {
    "text": "“That means the train is coming.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-37-82aa5ca41adc8cd9": {
    "text": "「那表示列車快到了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-38-074fe1bebc0f2e09": {
    "text": "An hour later, they arrived at Blackthorn Station.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-38-2d4a27625310b817": {
    "text": "一小時後，他們抵達黑荊棘車站。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-39-5885982f700d19c7": {
    "text": "The station was crowded.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-39-50124f77f32d878e": {
    "text": "車站非常擁擠。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-40-fe6a7345eab74607": {
    "text": "People rushed everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-40-37fe6ff296e220b2": {
    "text": "人們匆忙來去。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-41-2d206990ceffb73e": {
    "text": "Suitcases rolled loudly across the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-41-5682bf963da529dd": {
    "text": "行李箱在地板上滾動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-42-597f86294bef8e34": {
    "text": "Steam rose from the old trains.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-42-721a00a97afb9bf1": {
    "text": "老火車冒著蒸氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-43-d0a92ad65c924590": {
    "text": "Ethan looked around nervously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-43-af0f90d572d9f3b4": {
    "text": "伊森緊張地四處看。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-44-25e13c56ba5d0860": {
    "text": "“There’s no sign for Clock Tower School.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-44-bc46e996fd22b566": {
    "text": "「這裡沒有時鐘塔學院的標誌。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-45-4fbd0ee90378e62e": {
    "text": "His grandmother nodded calmly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-45-4fa778f6af3bd149": {
    "text": "奶奶平靜點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-46-9c4f8d6dc78af44d": {
    "text": "“Because ordinary people cannot see it.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-46-3eff8faa809c1107": {
    "text": "「因為普通人看不見。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-47-35bc79833ab13bf7": {
    "text": "She walked toward Platform Eight.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-47-c881a941e7a92d8b": {
    "text": "她走向八號月台。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-48-9488bf650ca11a20": {
    "text": "Then Platform Nine.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-48-f4c836dd839f3bfa": {
    "text": "再走向九號月台。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-49-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-49-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-50-2871b60b5a60cfe6": {
    "text": "She stopped between them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-50-8f4c2cf9d5729640": {
    "text": "停在中間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-51-d67f68b9bf254d13": {
    "text": "Ethan blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-51-3b39acb18939e7cb": {
    "text": "伊森眨眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-52-9a47e8b5a674200d": {
    "text": "“There’s… a wall.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-52-f226d243b63fb89b": {
    "text": "「那裡……是牆壁。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-53-d153219b384ff61c": {
    "text": "Between the platforms stood a large brick wall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-53-be7ddf365876de5d": {
    "text": "兩個月台中間有一面大磚牆。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-54-be48a0eda13277d0": {
    "text": "People walked past it normally.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-54-5a97254bc18fac19": {
    "text": "人們正常經過。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-55-eaf5f687f67fb7d5": {
    "text": "His grandmother leaned closer.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-55-9dd86ed8dd46f201": {
    "text": "奶奶靠近他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-56-314f4c5be33fade2": {
    "text": "“Listen carefully.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-56-796c5db4505669f7": {
    "text": "「仔細聽。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-57-875b0ee6e74d5e24": {
    "text": "“You must walk through the wall.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-57-6fb115eb3075cbf1": {
    "text": "「你必須穿過那面牆。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-58-53a3125b272c6be1": {
    "text": "Ethan stared at her.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-58-4955491aaab68f14": {
    "text": "伊森瞪大眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-59-389fc6b7ff4276ec": {
    "text": "“…What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-59-0e6d1d8c21b20b5e": {
    "text": "「……什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-60-3acebd074b0a4d22": {
    "text": "“You heard me.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-60-12bb40f63fa5dc3b": {
    "text": "「你聽到了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-61-9dde0b021bf80245": {
    "text": "“That’s impossible!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-61-6b5e2a03d77fcfbd": {
    "text": "「那不可能！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-62-98b803c2ed7548c1": {
    "text": "His grandmother smiled slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-62-40bc85dd90bea048": {
    "text": "奶奶微微一笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-63-23a0269fd0f509c8": {
    "text": "“Magic often feels impossible.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-63-6a3d0302dfeb5861": {
    "text": "「魔法本來就像不可能。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-64-adcacce689eb9610": {
    "text": "Ethan looked at the wall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-64-49f358bd27ba31b1": {
    "text": "伊森看著牆。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-65-a06769e13310c5f2": {
    "text": "Then at the busy station.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-65-baff273b1a48a10c": {
    "text": "又看著忙碌車站。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-66-3735669ef390fe39": {
    "text": "Nobody else seemed to notice anything strange.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-66-0d27aa2ed967154b": {
    "text": "沒有人注意奇怪的事。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-67-3d854f0e99eeb0f7": {
    "text": "“You’re serious?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-67-f727beee60496265": {
    "text": "「妳是認真的？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-68-605c32e719b72803": {
    "text": "“Yes.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-68-7ba644d596279e8c": {
    "text": "「是。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-69-be72e130add792ee": {
    "text": "Ethan swallowed hard.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-69-d7b281d380dbeed2": {
    "text": "伊森吞口水。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-70-2874634ddc2f73eb": {
    "text": "“What if I crash into it?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-70-e3fe55124f42ccf3": {
    "text": "「如果我撞上去怎麼辦？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-71-07cc7648fa31a6b2": {
    "text": "“You won’t.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-71-7be51f8a22999893": {
    "text": "「你不會。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-72-e42ebfb6403b4b7d": {
    "text": "“That is not a comforting answer!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-72-4f54bbcf08155729": {
    "text": "「這完全沒有讓人安心！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-73-6eb239c55d8e5899": {
    "text": "His grandmother laughed softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-73-154a36d2b345e8a5": {
    "text": "奶奶輕笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-74-b49bbd0c7dd0c84f": {
    "text": "“Trust yourself.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-74-8fd70f7fb7bf15d4": {
    "text": "「相信自己。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-75-49d0b2d24a844267": {
    "text": "Ethan gripped his suitcase tightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-75-2af203e907417120": {
    "text": "伊森緊抓行李箱。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-76-cde66e8a8a2c0af4": {
    "text": "He took one slow step forward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-76-5c91b0a0a4dbec4f": {
    "text": "伊森慢慢往前踏出一步。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-77-8d6a2223e62f3981": {
    "text": "Then another.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-77-a9f9b4819e0723d5": {
    "text": "接著又一步。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-78-e503d87f96c2a7b1": {
    "text": "The wall grew closer.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-78-b7a2643004077355": {
    "text": "牆越來越近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-79-6bde392af93a7912": {
    "text": "Closer.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-79-036011a301dbf83c": {
    "text": "更近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-80-a71c9755d2ff96f3": {
    "text": "Closer—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-80-401d9c79142017c9": {
    "text": "更近——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-81-ca37c99a79fc3c1e": {
    "text": "WHOOSH!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-81-cda2e8f082302827": {
    "text": "呼——！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-82-b3c0ad1690ace639": {
    "text": "A cold wind rushed past him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-82-33d2f9d03af1f58c": {
    "text": "冷風吹過他身邊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-83-da523ed476d4a092": {
    "text": "Ethan stumbled forward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-83-3748487118243868": {
    "text": "伊森踉蹌往前。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-84-d6cf0c8aaeab9a6d": {
    "text": "Then stopped.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-84-bfefe3b29c91c96f": {
    "text": "然後停下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-85-d6220024ee1c9f1e": {
    "text": "His eyes widened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-85-2fbfd40fa3c545b3": {
    "text": "他睜大眼睛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-86-0323e0b95249b38c": {
    "text": "A hidden train platform stretched before him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-86-22cf9698a8300106": {
    "text": "眼前是一座隱藏月台。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-87-ce10652ec2075c57": {
    "text": "Golden lamps glowed through the fog.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-87-8c3c4fa77b4a5f60": {
    "text": "金色燈光穿透濃霧。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-88-293f583adb6c03a3": {
    "text": "A huge black train waited beside the tracks.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-88-d8a5ebbe08c07cd8": {
    "text": "一輛巨大的黑色列車停在軌道旁。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-89-d966d99e17a3fd9c": {
    "text": "Steam hissed loudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-89-42aeb2ce848ba866": {
    "text": "蒸氣大聲嘶嘶作響。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-90-94a44dc94951e4e1": {
    "text": "Students wearing dark robes walked everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-90-1aaf9ed8b4d6109b": {
    "text": "穿著黑袍的學生到處走動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-91-89674d9e97b031e5": {
    "text": "Owls flew overhead.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-91-827d61906d97add1": {
    "text": "貓頭鷹從頭頂飛過。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-92-1a2aa720d973b270": {
    "text": "Cats slept on suitcases.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-92-9360c35baae8cbf4": {
    "text": "貓咪睡在行李箱上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-93-4e04aa70e8b74231": {
    "text": "Some students waved glowing wands.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-93-c4899cd852555bae": {
    "text": "有些學生揮著發光魔杖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-94-3f4b0bf8d9e25440": {
    "text": "Others carried floating books.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-94-a4ab5b609eaa36fa": {
    "text": "有些人帶著漂浮的書本。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-95-68274b31d73f35b3": {
    "text": "Ethan stared in amazement.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-95-c3da66e78d601f70": {
    "text": "伊森驚訝地看著一切。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-96-a90b1bab5afd3365": {
    "text": "“This is…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-96-516aa630821a52c5": {
    "text": "「這是……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-97-a09356d37cc0fef1": {
    "text": "A voice behind him finished the sentence.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-97-86bf657ff8d8cc85": {
    "text": "身後有個聲音接完他的話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-98-848409089548ac52": {
    "text": "“Clock Tower Platform.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-98-101b576bb5ebaad2": {
    "text": "「時鐘塔月台。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-99-c3b0acae77b42953": {
    "text": "Ethan turned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-99-8cfb923eaa2e88d0": {
    "text": "伊森轉身。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-100-ee33339dbef51300": {
    "text": "An old conductor smiled at him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-100-66ee68c52686bf84": {
    "text": "一名老列車長對他微笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-101-24ad178b17a25de4": {
    "text": "His uniform was dark green with silver clocks on the sleeves.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-101-3a108c8ca6cfbdc2": {
    "text": "他的制服是深綠色，袖子上有銀色時鐘。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-102-fdf1489c5525e548": {
    "text": "“First year?” the conductor asked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-102-cc0348e8077bc01a": {
    "text": "「一年級？」列車長問。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-103-3fb0e2301238e3fa": {
    "text": "Ethan nodded slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-103-ac7f50ca4e3b4d92": {
    "text": "伊森慢慢點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-104-7c8e299eca6bab5a": {
    "text": "The conductor smiled kindly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-104-fc398791e9f9d988": {
    "text": "列車長親切一笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-105-59eeccd69f25f27b": {
    "text": "“You’d better hurry.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-105-4cb8623ead22b466": {
    "text": "「你最好快一點。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-106-d34fb908aac200cd": {
    "text": "“The Midnight Train does not wait.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-106-4a00a8ff87e2ba85": {
    "text": "「午夜列車不等人。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-107-05e50ce6ddead0df": {
    "text": "A loud bell rang across the station.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-107-02705662311bdd14": {
    "text": "巨大鐘聲響徹車站。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-108-f56db54e9137cbed": {
    "text": "DONGGGGG—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-108-e3a6a0b2696365cb": {
    "text": "噹————",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-109-2bab4f2e92cd8779": {
    "text": "The sound echoed everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-109-61c64bf0b44f5b95": {
    "text": "聲音在四周回盪。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-110-274cf526c9d66c62": {
    "text": "Students rushed onto the train.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-110-aa22dbfa472045f1": {
    "text": "學生急忙上車。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-111-d0a92ad65c924590": {
    "text": "Ethan looked around nervously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-111-6bbaee184ace2285": {
    "text": "伊森緊張地看向四周。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-112-bfd0af8ad41a3929": {
    "text": "“This is insane…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-112-554ed7c5a17e5222": {
    "text": "「這太瘋狂了……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-113-6e8fae1ac64e3e0f": {
    "text": "But inside—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-113-502943a6ce772127": {
    "text": "但在心裡——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-114-6f2d95133c3adc82": {
    "text": "He was excited.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-114-1f4b99f223e3a9b7": {
    "text": "他很興奮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-115-5562776cffe3f3a9": {
    "text": "Very excited.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-115-7f99397ac4ee4cb5": {
    "text": "非常興奮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-116-58ba39918baa0f01": {
    "text": "His grandmother stepped through the wall behind him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-116-5eaacf75a3fdad2b": {
    "text": "奶奶從他身後穿過牆。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-117-7d0932efec381644": {
    "text": "“You made it,” she smiled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-117-07f03b98acd46915": {
    "text": "「你成功了，」她笑著說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-118-faa3a55f3c56f600": {
    "text": "Ethan laughed nervously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-118-a05e85d88f3c91c2": {
    "text": "伊森緊張地笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-119-3acf0022864e4e1f": {
    "text": "“I actually made it.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-119-0ee4cdfdde5af961": {
    "text": "「我真的進來了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-120-49b181348cd2debf": {
    "text": "She adjusted his scarf gently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-120-bc42127dfc8a44a3": {
    "text": "奶奶輕輕替他整理圍巾。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-121-9b7db9b8b0207d2d": {
    "text": "Then her smile faded slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-121-fc2619d8a92f740a": {
    "text": "接著，她的笑容慢慢淡去。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-122-e116bf3cf1a2bfbd": {
    "text": "“When you arrive at the school…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-122-7480b6b428d13528": {
    "text": "「你到學校之後……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-123-ef11df340a3689ff": {
    "text": "“Be careful who you trust.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-123-bedc42ad950b4803": {
    "text": "「要小心你相信的人。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-124-c8270c3e70686e1e": {
    "text": "Ethan frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-124-ea8c4b4b54b7c512": {
    "text": "伊森皺起眉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-125-e8a8d9056500ec37": {
    "text": "“What does that mean?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-125-f77d3deea84b9179": {
    "text": "「那是什麼意思？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-126-36644fc80db4ff6e": {
    "text": "But before she could answer—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-126-9f7ba0c33f453280": {
    "text": "但她還沒回答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-127-e37a70ae6de0136e": {
    "text": "The silver pocket watch ticked loudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-127-a709dbc5682c9d34": {
    "text": "銀色懷錶突然大聲滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-128-cfb1fbcea3ad2afd": {
    "text": "Tick. Tick. Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-128-f14c750b6514ccc9": {
    "text": "滴答。滴答。滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-129-3daee04ca8bb1771": {
    "text": "Its light flashed rapidly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-129-7997f87864ab7487": {
    "text": "光快速閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-130-b18082afe1f4062c": {
    "text": "His grandmother’s face suddenly changed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-130-40e5ad919dbb8a39": {
    "text": "奶奶的臉色突然變了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-131-55713c64d6734122": {
    "text": "Worried.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-131-ce2b2250140dbb19": {
    "text": "擔心。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-132-bb7094a17e1b86fd": {
    "text": "Very worried.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-132-37fbb51e3e603efe": {
    "text": "非常擔心。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-133-60875b69b3e98c5e": {
    "text": "Ethan noticed immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-133-f3a6807273755fce": {
    "text": "伊森立刻注意到了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-134-2cad78c456330092": {
    "text": "“What’s wrong?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-134-f414f5476008b2f4": {
    "text": "「怎麼了？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-135-afc58710cb62c39d": {
    "text": "She looked toward the foggy tracks.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-135-7c8e4793d58c44ff": {
    "text": "她看向霧濛濛的鐵軌。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-136-547ae745242d3d16": {
    "text": "Far away—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-136-d6d8650b8c3b3e0b": {
    "text": "遠方——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-137-e84eeb71edcd8255": {
    "text": "Something moved in the mist.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-137-41aa6b0260252c88": {
    "text": "有東西在霧裡動了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-138-b1ee467214d52c5d": {
    "text": "Tall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-138-ad5ff075a6a00f48": {
    "text": "高大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-139-f0dde14fa2d55aba": {
    "text": "Dark.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-139-b57ef4fdb68f3866": {
    "text": "黑暗。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-140-2678d6620d437a6e": {
    "text": "Watching them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-140-75e2d814178cc9c4": {
    "text": "正看著他們。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-141-0c96e7cfd79c304e": {
    "text": "The watch glowed brighter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-141-858eed9f581ea78d": {
    "text": "懷錶變得更亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-142-cfb1fbcea3ad2afd": {
    "text": "Tick. Tick. Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-142-f14c750b6514ccc9": {
    "text": "滴答。滴答。滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-143-4be51d11481d7fe4": {
    "text": "The dark figure disappeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-143-0576b3758d7fc38f": {
    "text": "黑影消失了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-144-929449416bcbf615": {
    "text": "But Ethan felt cold suddenly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-144-a102abfc6cd97518": {
    "text": "但伊森突然覺得很冷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-145-dac03be4c452688b": {
    "text": "Very cold.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-145-3c0cea4da07fad4c": {
    "text": "非常冷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-146-5380e2a1eb1bff0b": {
    "text": "His grandmother whispered quietly:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-146-322ce884e2114c7a": {
    "text": "奶奶低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-147-48c6fb15cd8e012e": {
    "text": "“It found you.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-147-0a3c5df82e19028f": {
    "text": "「它找到你了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-148-bc260166f180dbba": {
    "text": "Before Ethan could ask anything—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-148-918e3c469083dcde": {
    "text": "伊森還來不及問——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-149-ada06035242ab97a": {
    "text": "The train whistle screamed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-149-f21114999892599c": {
    "text": "列車汽笛尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-150-6997ed92e0c97c16": {
    "text": "SCREEEEEE—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-150-0699a7485b3786e9": {
    "text": "嗶————",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-151-0f5116d6b7784b5c": {
    "text": "“All aboard!” shouted the conductor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-151-c3357fd5634279c0": {
    "text": "「全部上車！」列車長大喊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-152-d87a99eb14a07b5b": {
    "text": "Students climbed inside quickly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-152-703c89a800856256": {
    "text": "學生快速上車。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-153-9d3efd5c58e6df1c": {
    "text": "His grandmother placed one hand on Ethan’s shoulder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-153-61cd6431a467454d": {
    "text": "奶奶把手放在伊森肩膀。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-154-ab56842239892a1d": {
    "text": "“No matter what happens…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-154-b765b14fe91bf886": {
    "text": "「不管發生什麼事……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-155-79bdfb2fe8182378": {
    "text": "“Do not lose that watch.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-155-cc113c38ea5b0d6a": {
    "text": "「不要弄丟那只懷錶。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-156-3fb0e2301238e3fa": {
    "text": "Ethan nodded slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-156-ac7f50ca4e3b4d92": {
    "text": "伊森慢慢點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-157-354a37fffe23e5b8": {
    "text": "“…Okay.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-157-c215d44596ac1134": {
    "text": "「……好。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-158-fee2f757c095035e": {
    "text": "She hugged him tightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-158-65dfade8998a2542": {
    "text": "奶奶緊緊抱住他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-159-0652bd4709026d6a": {
    "text": "Then stepped back.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-159-24d272e48680972e": {
    "text": "然後退開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-160-e1ec25c6312655ae": {
    "text": "“Go.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-160-62c2c4854a47ea6b": {
    "text": "「去吧。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-161-92763a458825cc6c": {
    "text": "Ethan picked up his suitcase.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-161-cb36141e79535df7": {
    "text": "伊森拿起行李。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-162-cb2a15ce51cd6358": {
    "text": "He climbed onto the Midnight Train.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-162-67ab1f38e0fd9b3b": {
    "text": "登上午夜列車。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-163-23df7d64a1217b1b": {
    "text": "As the doors closed—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-163-3a0975f6d663d698": {
    "text": "車門關閉時——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-164-33ac3ac22ec289a4": {
    "text": "He looked back one last time.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-164-2d33e8bb20d5de3b": {
    "text": "他最後回頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-165-af58ee310afe109e": {
    "text": "His grandmother stood alone in the fog.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-165-9bccf14cb5bc5137": {
    "text": "奶奶獨自站在濃霧中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-166-6a26bccb788410b2": {
    "text": "Watching him carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-166-acc2f7be4bf18553": {
    "text": "靜靜看著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-167-c50037931bb9b7a0": {
    "text": "The train began to move.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-167-bbad60c23fd1d207": {
    "text": "列車開始移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-168-967e21216cf38d18": {
    "text": "Slowly at first.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-168-8b28b2c8b0e4600f": {
    "text": "先慢慢地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-169-3042b13fe78a09e3": {
    "text": "Then faster.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-169-0acdf3a04f85fcb0": {
    "text": "然後越來越快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-170-1df973e3fd33e32e": {
    "text": "The city disappeared behind the mist.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-170-76857a5bca2a1dc9": {
    "text": "城市消失在霧後。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-171-87e7018d7360e8c4": {
    "text": "Ethan sat near the window.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-171-4e628419d18f2279": {
    "text": "伊森坐在窗邊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-172-c2af2b7adf6facf5": {
    "text": "His heart raced.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-172-db87aa3f8166e2d7": {
    "text": "心跳很快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-173-4ebd0b3c9833dac6": {
    "text": "Outside, thunder flashed across the sky.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-173-190b12f91da59afc": {
    "text": "外面雷光閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-174-4f8c5f1d1aae8b33": {
    "text": "Inside his pocket—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-174-20cd612b98ec3149": {
    "text": "而他的口袋裡——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-175-d65958a7e0376477": {
    "text": "The silver watch ticked softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-175-d54fd81f1537d42b": {
    "text": "銀色懷錶輕輕滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-176-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-176-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-177-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-177-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-178-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-178-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-179-77e5e15e98aee82a": {
    "text": "And somewhere far away—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-179-fef5eaff13f64e4b": {
    "text": "而在遠方——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c2-en-block-180-46a691bf399d197f": {
    "text": "Something was waiting for him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c2-zh-block-180-2b5344379731176a": {
    "text": "有什麼東西正在等著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-title-ada2071a28456d4e": {
    "text": "The Boy in Cabin Seven",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-title-6e5eef886422d643": {
    "text": "七號車廂的男孩",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-0-845e0a4425339a01": {
    "text": "The Midnight Train raced through the storm.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-0-b936be2c414b0a0e": {
    "text": "午夜列車在暴風雨中高速前進。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-1-697e468451b7ce9f": {
    "text": "Rain hit the windows loudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-1-e49f3710d07b46e3": {
    "text": "雨重重打在窗戶上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-2-a33d801758fb167e": {
    "text": "Lightning flashed across the dark sky.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-2-c2fb213597fc6c13": {
    "text": "閃電劃過黑暗天空。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-3-20fcd6ac087e62cd": {
    "text": "Inside the train, golden lamps glowed softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-3-84e4263346e084e1": {
    "text": "車廂裡，金色燈光柔和閃耀。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-4-8c8366c8c6294415": {
    "text": "The hallways smelled like old wood and smoke.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-4-0fededb2e2cbafa5": {
    "text": "走廊充滿舊木頭和煙霧味道。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-5-47ab4cd6bd97d98a": {
    "text": "Ethan carefully walked through the moving train.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-5-99e5bbcdd75f299b": {
    "text": "伊森小心地走在搖晃列車中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-6-9b9e81587ab105d7": {
    "text": "Students filled almost every cabin.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-6-f512d9d34c2fbc2f": {
    "text": "幾乎每個包廂都坐滿學生。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-7-9d77f105da18551b": {
    "text": "Some were laughing loudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-7-c9a6ea8ff84f57d7": {
    "text": "有人大聲聊天。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-8-de5dc7957afc5ca0": {
    "text": "Some practiced tiny spells with glowing sparks.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-8-832fed77ab6c1381": {
    "text": "有人練習小魔法。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-9-9902217e07e236f4": {
    "text": "One boy accidentally turned his sandwich purple.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-9-c66ed9119be27847": {
    "text": "一個男孩不小心把三明治變成紫色。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-10-1e1bef33f0828aad": {
    "text": "A girl nearby rolled her eyes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-10-8a0d3184fc0ef21e": {
    "text": "旁邊女孩翻白眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-11-7f38060f6cd988e9": {
    "text": "“First years,” she sighed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-11-f2ab9b63f91af0ff": {
    "text": "「一年級生，」她嘆氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-12-e4c569ec14736f0a": {
    "text": "Ethan smiled nervously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-12-40779583992fc166": {
    "text": "伊森緊張地笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-13-d7315a9000973a60": {
    "text": "Everything still felt unreal.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-13-f53d1c3281d2455c": {
    "text": "一切還是很不真實。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-14-03ea82dbad743ce2": {
    "text": "He checked the silver pocket watch again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-14-4113b66861a104fa": {
    "text": "他再次看向銀色懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-15-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-15-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-16-71a81d27b044519a": {
    "text": "The glowing lines moved slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-16-8ef3a50be075c3a2": {
    "text": "發光線條慢慢移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-17-87edcc4a7088e8d4": {
    "text": "“What are you trying to tell me?” Ethan whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-17-9259ae5db750f63d": {
    "text": "「你到底想告訴我什麼？」伊森低聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-18-bc30f1a485d6b02a": {
    "text": "Suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-18-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-19-1c138121a56d11a7": {
    "text": "BANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-19-f71121b471973ddc": {
    "text": "砰！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-20-dcba6024ff0a3f2a": {
    "text": "A cabin door slammed open nearby.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-20-8cb7649c25c99b9a": {
    "text": "附近包廂門突然打開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-21-01f5b5e88245f4ee": {
    "text": "A tall boy stepped out.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-21-707ebc7b8ed40ed0": {
    "text": "一個高個子男孩走出來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-22-41081f1641307d69": {
    "text": "He had messy black hair and sharp gray eyes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-22-5e176d0501106f77": {
    "text": "他有凌亂黑髮和灰色眼睛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-23-28c5f284bc323877": {
    "text": "His dark school robe looked perfectly neat.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-23-4c719805060009a8": {
    "text": "深色校袍整整齊齊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-24-1366fb0901fb78e3": {
    "text": "Unlike everyone else, he did not seem excited.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-24-fee25b118ac52057": {
    "text": "和其他人不同，他看起來完全不興奮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-25-9bf0ac32febff4c5": {
    "text": "He looked… annoyed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-25-49145329d9d9034f": {
    "text": "反而有點不耐煩。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-26-548bbd4c45ebeac5": {
    "text": "The boy noticed Ethan immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-26-53e538142584c2b2": {
    "text": "男孩立刻注意到伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-27-244a69721bd5de09": {
    "text": "“You’re blocking the hallway.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-27-9604ac63d19186d1": {
    "text": "「你擋住走道了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-28-f38e02c5dc1ff87e": {
    "text": "“Oh—sorry,” Ethan said quickly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-28-c078b82d821844da": {
    "text": "「喔——抱歉，」伊森連忙說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-29-a07f041b2280394f": {
    "text": "The boy stared at him for a second.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-29-ce665e47b2033192": {
    "text": "男孩盯著他幾秒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-30-f3e4981bf4a32b21": {
    "text": "Then his eyes moved to the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-30-f359e97f0e96f32e": {
    "text": "然後視線移到懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-31-38611e264bb89bed": {
    "text": "His expression changed slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-31-bff385ed62aaf182": {
    "text": "表情微微改變。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-32-1b54b40396c253a7": {
    "text": "“…Where did you get that?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-32-45d690d1ac104b89": {
    "text": "「……你從哪得到那個？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-33-5e69246fa9570736": {
    "text": "Ethan touched the watch carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-33-39479b87edf2cd83": {
    "text": "伊森碰了碰懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-34-08120edcd47a9cd4": {
    "text": "“It belonged to my father.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-34-1cbe4e13413dc99e": {
    "text": "「這是我爸爸的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-35-66288eb7cc6e0a67": {
    "text": "The boy became quiet.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-35-d6d500265f3c911a": {
    "text": "男孩安靜下來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-36-9fbfcfb860dc7419": {
    "text": "For a moment, he looked almost surprised.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-36-71a432b63d50fc7a": {
    "text": "那瞬間，他看起來有些驚訝。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-37-0cd2dc481f5e7be0": {
    "text": "But then his cold expression returned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-37-aa0ff19ab6cb8e33": {
    "text": "但很快又恢復冷淡。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-38-16e617eea85ba9da": {
    "text": "“What’s your name?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-38-daec22425e592caf": {
    "text": "「你叫什麼名字？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-39-2971c8eba7b547b9": {
    "text": "“Ethan Parker.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-39-c9f9991b960bbc31": {
    "text": "「伊森・帕克。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-40-e85e3ed2f04ecf18": {
    "text": "The boy’s eyes narrowed slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-40-a12cd50b2ddceb49": {
    "text": "男孩眼神微微變化。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-41-8f7e4d165c1ada12": {
    "text": "“…Parker?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-41-df14bb048991619b": {
    "text": "「……帕克？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-42-7cdedc8af539dedd": {
    "text": "Before Ethan could ask why—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-42-b045f1529a129ba2": {
    "text": "伊森正想問——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-43-31bcfd97e19c2863": {
    "text": "A loud voice interrupted them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-43-ac3898a48ea4c639": {
    "text": "突然有聲音打斷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-44-6341b34fa45461cc": {
    "text": "“There you are!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-44-aee57ce3a3aadbfb": {
    "text": "「原來你在這！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-45-4493a2f93aaef3f8": {
    "text": "A girl with curly brown hair rushed toward them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-45-de3308c0016cf000": {
    "text": "一個棕色捲髮女孩衝過來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-46-befbf3fcee98416c": {
    "text": "She carried at least six books in her arms.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-46-c95003154e6cb173": {
    "text": "懷裡抱著至少六本書。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-47-7324121aa71ff39d": {
    "text": "“How are there no empty cabins left?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-47-076546ee28a8790b": {
    "text": "「為什麼都沒有空包廂了？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-48-83d9c6139757c534": {
    "text": "She stopped when she saw Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-48-7b851557ded12aee": {
    "text": "她停下來看著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-49-f958822813db4c35": {
    "text": "“Oh. New student?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-49-7fbdb56b34997ce1": {
    "text": "「喔，新生？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-50-6d2b47333902f2b0": {
    "text": "Ethan nodded.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-50-bcc6b4a6a77adaf2": {
    "text": "伊森點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-51-cd5ca86b482c557e": {
    "text": "“I’m Ethan.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-51-2cb1740248cb0869": {
    "text": "「我叫伊森。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-52-64e41e58c42e1696": {
    "text": "“I’m Lucy,” she said brightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-52-da434af6dbe4922f": {
    "text": "「我是露西，」她開朗地說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-53-7ce7d998ebf4cda2": {
    "text": "Then she pointed at the tall boy.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-53-e0a892db959d83d1": {
    "text": "然後指向高個男孩。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-54-57f93c4132642f96": {
    "text": "“And this grumpy ghost is Adrian.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-54-f8b08114066efc3d": {
    "text": "「這個臭臉幽靈叫亞德里安。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-55-b0adeafbfe7f651b": {
    "text": "“I am not grumpy,” Adrian replied immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-55-754889d7378c4342": {
    "text": "「我沒有臭臉，」亞德里安立刻反駁。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-56-7f647b7a5b23f36b": {
    "text": "Lucy ignored him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-56-51819bdb1a863b44": {
    "text": "露西直接無視。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-57-58fb86879b97413b": {
    "text": "She looked at Ethan carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-57-f2047167b82149a3": {
    "text": "她看著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-58-087d0d6227a5c2a2": {
    "text": "“You look lost.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-58-cf7740f9f157b979": {
    "text": "「你看起來迷路了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-59-259c4aedfeadda78": {
    "text": "“I probably am,” Ethan admitted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-59-a6e2116931c42026": {
    "text": "「我可能真的迷路了，」伊森承認。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-60-c7ba392f3b916ad2": {
    "text": "Lucy grinned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-60-21202fcc096c8c1c": {
    "text": "露西露出笑容。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-61-bc10899e4c3f1040": {
    "text": "“Perfect. You can sit with us.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-61-d8bcc213773380ed": {
    "text": "「太好了，你可以跟我們坐。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-62-b6ab68795b4762d3": {
    "text": "Adrian sighed deeply.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-62-37cbc5704877d112": {
    "text": "亞德里安深深嘆氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-63-597f63e1aad78f1c": {
    "text": "“Wonderful.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-63-73568670bd02b0d8": {
    "text": "「真棒。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-64-2aae8338ecf652ad": {
    "text": "Lucy pushed open the cabin door.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-64-5af37768c1bc8065": {
    "text": "露西推開包廂門。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-65-aa3504d2bb28dd90": {
    "text": "“Cabin Seven,” she announced proudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-65-dc7359d270f8252e": {
    "text": "「七號包廂，」她驕傲宣布。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-66-f5107251bd684238": {
    "text": "The cabin inside was warm and cozy.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-66-ce6013d85144289c": {
    "text": "裡面溫暖舒服。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-67-4e403d8669090c19": {
    "text": "Rain tapped softly against the windows.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-67-db6184709e573007": {
    "text": "雨輕輕打在窗上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-68-150a29b241ec6a23": {
    "text": "Books floated slowly near the ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-68-cb15f019dd76e6f0": {
    "text": "書本漂浮在天花板附近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-69-8d3077c36631ff15": {
    "text": "A teapot poured tea by itself.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-69-81757a0e84f58035": {
    "text": "茶壺自己倒茶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-70-f1fd569bafe21974": {
    "text": "Ethan stared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-70-4955491aaab68f14": {
    "text": "伊森瞪大眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-71-37ed472f2dc4536a": {
    "text": "“The tea is alive?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-71-4a340349bc5fc7ea": {
    "text": "「茶壺是活的？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-72-367142891e766b9d": {
    "text": "Lucy laughed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-72-8036e250b43a77e8": {
    "text": "露西笑出來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-73-dbfe89f6274e9a51": {
    "text": "“No, that’s beginner house magic.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-73-a6f8d1dd0e56c8d7": {
    "text": "「不，那只是初級居家魔法。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-74-7b22933477af54f3": {
    "text": "Adrian sat near the window silently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-74-d6e194d0761b77c1": {
    "text": "亞德里安安靜坐在窗邊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-75-18730acc0b415537": {
    "text": "Lucy dropped her books onto the seat.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-75-80f7e02985f170cf": {
    "text": "露西把書丟到座位。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-76-52419db5cc971f7e": {
    "text": "“So,” she said excitedly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-76-3e4bfd2be729ce77": {
    "text": "「所以，」她興奮問。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-77-deb4b577e39c6cc8": {
    "text": "“What kind of magic can you use?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-77-b800aa4b6f745012": {
    "text": "「你會什麼魔法？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-78-d67f68b9bf254d13": {
    "text": "Ethan blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-78-134fbeb356ccc19c": {
    "text": "伊森愣住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-79-2a95feb5574c038c": {
    "text": "“…None?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-79-14df5519aa2c9ea1": {
    "text": "「……完全不會？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-80-62a45a8f89f26975": {
    "text": "Lucy looked confused.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-80-729c9d4edb11a405": {
    "text": "露西一臉疑惑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-81-1614470895d80f5d": {
    "text": "“None at all?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-81-9a2d7aeaba939f60": {
    "text": "「完全不會？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-82-6cf19b101f286331": {
    "text": "“He didn’t grow up in a Keeper family,” Adrian said calmly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-82-ab3c1f19df58093d": {
    "text": "「他不是在守護者家庭長大的，」亞德里安平靜說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-83-a6c74e62fb913a01": {
    "text": "Ethan looked at him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-83-13a2f989c873556f": {
    "text": "伊森看著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-84-dd23e2f7d119174d": {
    "text": "“How did you know that?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-84-a250c344c7be8dfa": {
    "text": "「你怎麼知道？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-85-18985497e0e72cf6": {
    "text": "Adrian crossed his arms.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-85-2bb355e5b4b07f3c": {
    "text": "亞德里安抱起手。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-86-81e602fa8bdacf55": {
    "text": "“Because if you did, you wouldn’t look surprised every five seconds.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-86-304b088aecd6210d": {
    "text": "「因為如果你是，你就不會每五秒驚訝一次。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-87-ab66c29fecb964c0": {
    "text": "Lucy laughed loudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-87-b54442166d3d5fe7": {
    "text": "露西大笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-88-aebf07e76777bdd3": {
    "text": "“He’s right.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-88-70465fbff2f26b33": {
    "text": "「他說得沒錯。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-89-2198b8b659c7a057": {
    "text": "Ethan rolled his eyes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-89-2b2ca8fb02e1bc5f": {
    "text": "伊森翻白眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-90-36ce4d1542ee039d": {
    "text": "“Thanks.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-90-46400a0eac4cd8f6": {
    "text": "「謝了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-91-70f5ecc553db7370": {
    "text": "Lucy leaned closer.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-91-13e65b474ce9bb5a": {
    "text": "露西靠近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-92-e5c8b02cf8a82eea": {
    "text": "“Wait… if you’re new to magic…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-92-97800114c427a3d6": {
    "text": "「等等……如果你不懂魔法……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-93-b0cdd62959f8fc44": {
    "text": "“Then how did you get accepted into Clock Tower?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-93-d4bfcf11e1540325": {
    "text": "「那你怎麼進時鐘塔的？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-94-da7228daa29adc5a": {
    "text": "Ethan hesitated.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-94-59a2639741b20a55": {
    "text": "伊森猶豫了一下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-95-a090c7861e68d45f": {
    "text": "Then he quietly showed them the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-95-767d927837d18d4b": {
    "text": "然後慢慢拿出銀色懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-96-aad75ce1aadcd4a9": {
    "text": "Lucy’s eyes widened immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-96-81a2ec996fe1a507": {
    "text": "露西立刻睜大眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-97-81790765d52c046c": {
    "text": "“No way…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-97-9ace78ededbce602": {
    "text": "「不可能……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-98-41c5f2c7425a8a01": {
    "text": "Even Adrian sat up straighter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-98-2af312ebe45dff84": {
    "text": "連亞德里安都坐直了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-99-bddafd54d9d621ad": {
    "text": "“Where did you get that?” Lucy whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-99-f583f1454ac64e6b": {
    "text": "「你從哪得到那個？」露西低聲問。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-100-6d9949d37d38dafd": {
    "text": "“My grandmother said it belonged to my father.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-100-b1596dc69f4d5e5f": {
    "text": "「奶奶說這是我爸爸的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-101-2d67c925681941c9": {
    "text": "Adrian stared at the watch silently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-101-2f2e2365b2178a6b": {
    "text": "亞德里安沉默看著懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-102-1ea9d6d2d74f231a": {
    "text": "Then he asked quietly:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-102-70f4891c54028e11": {
    "text": "然後低聲問：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-103-537e509f8408d55c": {
    "text": "“Your father’s name… was it Daniel Parker?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-103-162632956ae63618": {
    "text": "「你爸爸……是不是叫丹尼爾・帕克？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-104-641a78e1b01c7f32": {
    "text": "Ethan froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-104-134fbeb356ccc19c": {
    "text": "伊森愣住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-105-afd90b1eedcb98b8": {
    "text": "“…How do you know that name?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-105-eb74c16adcff9d56": {
    "text": "「……你怎麼知道？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-106-33cef999446010e9": {
    "text": "Before Adrian could answer—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-106-36908a9728644b25": {
    "text": "亞德里安還來不及回答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-107-291191d025a7a64a": {
    "text": "The lights flickered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-107-ce89c3dd56bf580e": {
    "text": "燈突然閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-108-0574d756ca0db154": {
    "text": "Once.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-108-5c9d1ecbc8afeb2b": {
    "text": "一下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-109-754a7f4abfcf2fb2": {
    "text": "Twice.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-109-e4514c6a97957c01": {
    "text": "兩下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-110-f65c9cec6ef0fd1e": {
    "text": "Then the entire train became silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-110-f0f7732f0041da75": {
    "text": "接著整列火車突然安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-111-095a220820f01776": {
    "text": "The floating books dropped suddenly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-111-5f4fd7d3262c4a44": {
    "text": "漂浮書本全部掉下來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-112-4ea86a9389e4982c": {
    "text": "THUD.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-112-273fabb0b16884e7": {
    "text": "砰。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-113-77f30c0a78fb3eda": {
    "text": "The teapot stopped moving.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-113-5d4e037c50eba8d7": {
    "text": "茶壺停止動作。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-114-aaba71f9a60c4b89": {
    "text": "Lucy frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-114-48073e7e244fc819": {
    "text": "露西皺眉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-115-32dc3789a8300261": {
    "text": "“That’s not normal.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-115-f3381f06fc49ac53": {
    "text": "「這不正常。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-116-1bb2a0cdd9d70825": {
    "text": "The silver watch began ticking rapidly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-116-302830fca2b058aa": {
    "text": "銀色懷錶開始快速滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-117-be899b8f020f73b4": {
    "text": "Tick. Tick. Tick. Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-117-b3a473a8b166cf37": {
    "text": "滴答。滴答。滴答。滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-118-13073d7acb062ba3": {
    "text": "Ethan’s stomach tightened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-118-51f4db741d8ecaea": {
    "text": "伊森胃部一緊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-119-74ba926a7ee6c366": {
    "text": "Cold air filled the cabin.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-119-7e78b63c6c97b8ad": {
    "text": "冰冷空氣充滿車廂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-120-264ba0d15a9e5609": {
    "text": "Adrian stood up immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-120-d454aa8be7dca810": {
    "text": "亞德里安立刻站起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-121-772e8147e64a2033": {
    "text": "“Stay behind me.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-121-6691fc46e55c756d": {
    "text": "「站到我後面。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-122-25c024483204434c": {
    "text": "Lucy looked nervous now.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-122-c30446bdb78831ad": {
    "text": "露西也開始緊張。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-123-25836b8c1b397950": {
    "text": "“What’s happening?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-123-cc1cb4b472d9bfe1": {
    "text": "「發生什麼事？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-124-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-124-932da14da57c5006": {
    "text": "接著——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-125-fe463ca8b275c79a": {
    "text": "SCRAAAAAPE.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-125-2a96382ecd7ccfe8": {
    "text": "刮————",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-126-0556c2021546eb92": {
    "text": "Something moved across the roof of the train.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-126-f591217ccdc45af6": {
    "text": "有東西在列車頂部移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-127-68cad7121adcce4c": {
    "text": "Slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-127-5a095fb990919bed": {
    "text": "慢慢地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-128-cc759b9f6bb233cd": {
    "text": "Like claws.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-128-8644bed521001c12": {
    "text": "像爪子。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-129-ce020688bcd961f6": {
    "text": "Students screamed in distant cabins.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-129-8870fca978ea663c": {
    "text": "遠處車廂傳來學生尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-130-12a6fcb4c4b550fa": {
    "text": "The train shook violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-130-8d06c2a73973c17c": {
    "text": "列車劇烈搖晃。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-131-890bf8f31ec68767": {
    "text": "Outside the window—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-131-eba9c6e25eaee0f3": {
    "text": "窗外——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-132-4aff1600e780e7dc": {
    "text": "A dark shape moved through the storm clouds.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-132-a3246ef515d7b589": {
    "text": "黑暗雲層中有巨大影子移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-133-34272c3e25de3f43": {
    "text": "Huge.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-133-293d1ed47502ad26": {
    "text": "巨大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-134-4f422d51cbfcc9dd": {
    "text": "Fast.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-134-97caf9486a113405": {
    "text": "快速。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-135-5be6bd004a352a93": {
    "text": "Watching the train.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-135-d41a662dd37a0843": {
    "text": "正在盯著列車。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-136-d8efb1becc2299ea": {
    "text": "Ethan’s heart pounded.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-136-37d9b3e199e86b78": {
    "text": "伊森心跳狂跳。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-137-cce7f8af28ca1caf": {
    "text": "“That thing…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-137-2e21f0728495deb4": {
    "text": "「那個東西……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-138-64e1a9ed9b7a6e0c": {
    "text": "The silver watch flashed bright silver light.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-138-5ae97072f4580cd6": {
    "text": "銀色懷錶發出強烈銀光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-139-9917ddaa75ce0eba": {
    "text": "TickTickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-139-59611e0f2c93d5d7": {
    "text": "滴答滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-140-e25ffc2946c3653c": {
    "text": "Adrian’s face turned pale.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-140-08f4ea32ae6d1e08": {
    "text": "亞德里安臉色發白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-141-7c387c5f8e40517f": {
    "text": "“No…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-141-92141de36152d128": {
    "text": "「不……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-142-39c6f7e58d06302e": {
    "text": "Lucy whispered,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-142-1dbabc472dbdd497": {
    "text": "露西低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-143-3c5b9ce47fdf79c3": {
    "text": "“It found the train…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-143-c4485529b2e37154": {
    "text": "「它找到列車了……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-144-f0a7df8816525de7": {
    "text": "Then the cabin door exploded open.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-144-66c06b69181c142f": {
    "text": "下一秒，包廂門爆開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-145-1c138121a56d11a7": {
    "text": "BANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-145-f71121b471973ddc": {
    "text": "砰！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-146-b392b2ea77859f17": {
    "text": "Cold wind rushed inside.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-146-b6f18f7ccca9e506": {
    "text": "冷風吹進來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-147-5fa49167262f82b5": {
    "text": "The lights went out instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-147-947847707498edb4": {
    "text": "燈瞬間熄滅。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-148-e135a6889362073e": {
    "text": "Darkness swallowed everything.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-148-7b7f10049234f6c3": {
    "text": "黑暗吞沒一切。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-149-d63e753d39751901": {
    "text": "And from the hallway—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-149-150b010c159416e6": {
    "text": "而在走廊裡——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c3-en-block-150-4bf0f31275618e46": {
    "text": "A pair of glowing purple eyes slowly appeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c3-zh-block-150-eb15a944e1403176": {
    "text": "一雙紫色發光眼睛慢慢出現。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-title-36005477643b7913": {
    "text": "The Creature on the Train",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-title-59b463139b933107": {
    "text": "列車上的怪物",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-0-e190e9185369a15c": {
    "text": "The purple eyes floated in the darkness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-0-330dd635837b6c50": {
    "text": "紫色眼睛漂浮在黑暗中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-1-09f0121e1f8693f8": {
    "text": "Silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-1-5bc94dfb664bfb43": {
    "text": "安靜地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-2-2678d6620d437a6e": {
    "text": "Watching them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-2-57125f306d2bf5fc": {
    "text": "盯著他們。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-3-6fae5c82fde206f8": {
    "text": "Ethan could hear his own heartbeat.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-3-ae1d28fd45f4f690": {
    "text": "伊森聽得到自己的心跳。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-4-f3ef75e14d511ff3": {
    "text": "Thump. Thump. Thump.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-4-52f99cbfa8bcf769": {
    "text": "砰。砰。砰。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-5-24c09a8f0f1b46fa": {
    "text": "The train shook violently again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-5-d9ed6066618b264f": {
    "text": "列車再次劇烈搖晃。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-6-7ea1cb14760aac52": {
    "text": "Outside, thunder exploded across the sky.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-6-6a1ed548ac686ba7": {
    "text": "外面雷聲爆炸般響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-7-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-7-3900b75e01c0a237": {
    "text": "轟隆！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-8-d4a580e18bc9679d": {
    "text": "Lucy grabbed her wand quickly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-8-b92734ae7fee23d6": {
    "text": "露西立刻抓緊魔杖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-9-ffaac5c9fa87ffc7": {
    "text": "Her hands were shaking.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-9-81bade165e7372e5": {
    "text": "她的手在發抖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-10-422c197156e11666": {
    "text": "“What… is that thing?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-10-fdf7c4795e1561a5": {
    "text": "「那……那是什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-11-5e7238271cb8878e": {
    "text": "Adrian stepped forward slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-11-8c2ee709854c2cde": {
    "text": "亞德里安慢慢往前站。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-12-8dcbe2938167c342": {
    "text": "His gray eyes never left the darkness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-12-7f0a0dd015b7cdfe": {
    "text": "灰色眼睛沒有離開黑暗。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-13-345e164625106e1b": {
    "text": "“…Shadow Stalker,” he whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-13-b6e747f3b278dcbc": {
    "text": "「……暗影追獵者，」他低聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-14-c8270c3e70686e1e": {
    "text": "Ethan frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-14-f09e32b4e8865c97": {
    "text": "伊森皺眉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-15-d2783bd7fcf38fb5": {
    "text": "“A what?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-15-856bb09056ec443d": {
    "text": "「什麼東西？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-16-265195a070c15041": {
    "text": "But before Adrian could explain—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-16-4cfc441a45551eca": {
    "text": "但亞德里安還沒回答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-17-df8989e13c18ccc5": {
    "text": "The creature moved.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-17-874a3830e79db85e": {
    "text": "那怪物動了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-18-af17e4ba64ce4fd2": {
    "text": "FAST.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-18-5f4f9bf455776c23": {
    "text": "超快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-19-a900cacd58dbf700": {
    "text": "A black shape rushed through the cabin doorway.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-19-eedd1319c226911e": {
    "text": "黑影衝進車廂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-20-7a64854042a46aa4": {
    "text": "Its body looked like smoke and claws twisted together.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-20-95c84882d74bed93": {
    "text": "它的身體像煙霧與利爪扭曲而成。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-21-f2c6e7560d525305": {
    "text": "Its purple eyes burned brightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-21-00f1a7347a13554e": {
    "text": "紫色眼睛燃燒般發亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-22-47b6f584aa88c0a5": {
    "text": "Lucy screamed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-22-56f99869072512a2": {
    "text": "露西尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-23-41ad0b0bc054ddfb": {
    "text": "The creature slammed into the ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-23-76642716c8afb614": {
    "text": "怪物撞上天花板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-24-e65fd82647eed620": {
    "text": "Wood cracked everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-24-ed8d78bf42fd24b2": {
    "text": "木頭四處裂開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-25-3037e7e6948481c2": {
    "text": "Students shouted in nearby cabins.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-25-2ac0208811c20ef3": {
    "text": "附近車廂傳來學生尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-26-79524b4a40dfec0a": {
    "text": "The train lights flickered wildly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-26-28fc178ab07a9363": {
    "text": "燈瘋狂閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-27-71c3490c2e694144": {
    "text": "Ethan stumbled backward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-27-6194fd38ff8dcd4c": {
    "text": "伊森跌退。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-28-bfc35a0d758823df": {
    "text": "“That thing is HUGE!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-28-b7000ad6b401324d": {
    "text": "「那東西超大！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-29-20f3d149747d5573": {
    "text": "Adrian pulled out a silver wand immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-29-d4549e8bde900a44": {
    "text": "亞德里安立刻抽出銀色魔杖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-30-d79b2b37b03cab37": {
    "text": "“Stay down!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-30-d70d1233118797e7": {
    "text": "「趴下！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-31-905359db4cf821ae": {
    "text": "He pointed the wand forward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-31-63f0898ef726f5f0": {
    "text": "他指向前方。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-32-91c215ce1c8f5209": {
    "text": "“LUX FERA!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-32-f6ae9f48ff1f9f73": {
    "text": "「光耀烈閃！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-33-5c608fa41240d14a": {
    "text": "A burst of white light exploded from the wand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-33-360f08d52ba9fd76": {
    "text": "一道白光從魔杖爆發。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-34-5b4c1a64a931431e": {
    "text": "The creature hissed loudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-34-367e4da6998aff43": {
    "text": "怪物發出尖銳嘶吼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-35-03440ab7204543cc": {
    "text": "Smoke rose from its body.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-35-acb33f2b052013c6": {
    "text": "身體冒煙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-36-78c11e54d00f01f0": {
    "text": "But it did not disappear.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-36-43aaa25529c869ca": {
    "text": "但它沒有消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-37-0190b8d61be6c9bb": {
    "text": "Instead—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-37-b8503db0c72040ee": {
    "text": "反而——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-38-a7160340fb07effd": {
    "text": "It smiled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-38-10172770071a4d95": {
    "text": "笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-39-f12b36a2f2ec9f0f": {
    "text": "A horrible, sharp-toothed smile.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-39-1f1d7c5d9f4592d9": {
    "text": "露出可怕尖牙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-40-b31373aff65b3c92": {
    "text": "Lucy whispered fearfully,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-40-35c4d2f118d2880b": {
    "text": "露西害怕低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-41-3f28fef8afee3811": {
    "text": "“That’s impossible…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-41-9ace78ededbce602": {
    "text": "「不可能……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-42-e7a8b3d8c5abf133": {
    "text": "The creature jumped again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-42-81d3a8b2178bc9af": {
    "text": "怪物再次跳起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-43-bf837b129e97b9fe": {
    "text": "This time toward Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-43-1d2d48035196439b": {
    "text": "這次衝向伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-44-1fb7814ecc471d70": {
    "text": "The silver watch suddenly flashed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-44-9f414932733272c9": {
    "text": "銀色懷錶突然爆發強光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-45-109214be97a1c577": {
    "text": "BRIGHT.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-45-3fe9bfa17864115f": {
    "text": "非常亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-46-b18b8432d4c98374": {
    "text": "Very bright.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-46-ea4aeb49c7fc120f": {
    "text": "非常非常亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-47-b75aee97b1adced7": {
    "text": "The creature stopped in midair.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-47-de43d49910ccd9ad": {
    "text": "怪物停在半空中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-48-19adf495888610a1": {
    "text": "Its purple eyes widened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-48-b26d2cfac5b83922": {
    "text": "紫色眼睛睜大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-49-2b7c0f5814a1a870": {
    "text": "It stared directly at the watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-49-61d088618201f61a": {
    "text": "它死死盯著懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-50-a8cf6c88d91bbccf": {
    "text": "Then at Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-50-de8102799f24db67": {
    "text": "又盯向伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-51-1fe075448a7fda7f": {
    "text": "Almost… recognizing him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-51-fd86ceb705b9e4de": {
    "text": "像是在認出他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-52-a741e0125346e453": {
    "text": "Ethan’s hands trembled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-52-4ec16f164a52270f": {
    "text": "伊森雙手發抖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-53-729f5316c28fe61b": {
    "text": "“Why is it looking at me?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-53-bff668d5d8ef0628": {
    "text": "「它為什麼看著我？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-54-74c8a3b6c0159f24": {
    "text": "The creature made a low growling sound.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-54-ae024ef7aa89d77f": {
    "text": "怪物發出低沉咆哮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-55-b1ff894c56f9c1d6": {
    "text": "“Paaaarrrkkkeeerrrr…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-55-aefd09600ed509fc": {
    "text": "「帕……克……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-56-641a78e1b01c7f32": {
    "text": "Ethan froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-56-134fbeb356ccc19c": {
    "text": "伊森愣住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-57-9790978554686ebb": {
    "text": "“It… said my name.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-57-7d559cb08334e3e8": {
    "text": "「它……剛剛叫我的名字。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-58-ca72a28bbd84c08d": {
    "text": "Adrian’s face turned pale again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-58-d5868055ed1666d3": {
    "text": "亞德里安臉色更白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-59-c659ad62e52196c4": {
    "text": "“That’s bad.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-59-62dec0feb12fb394": {
    "text": "「那很糟。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-60-b9e87458b8ba91fa": {
    "text": "“VERY bad.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-60-05b365ec6bfaff73": {
    "text": "「非常糟。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-61-1c2fbdecb1508ed1": {
    "text": "The creature rushed forward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-61-0d3fd122f137a576": {
    "text": "怪物再次衝過來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-62-4963ec398e8f0388": {
    "text": "Lucy fired a spell quickly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-62-0416a46dbfc0d198": {
    "text": "露西快速施法。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-63-18da6c27303ebc54": {
    "text": "“IGNIS!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-63-3fbcea544b1ef08b": {
    "text": "「火焰爆裂！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-64-50c294fd5173764f": {
    "text": "A ball of fire shot across the cabin.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-64-10dccb26cdaf2aa7": {
    "text": "火球射過車廂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-65-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-65-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-66-12b18e056797edc9": {
    "text": "The creature slammed into the wall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-66-2ca8de8ed804fd63": {
    "text": "怪物撞進牆壁。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-67-f7a339e5c1614e81": {
    "text": "Smoke filled the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-67-5dc14a82d86f9937": {
    "text": "濃煙充滿車廂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-68-533c3937cbbefecb": {
    "text": "Lucy breathed heavily.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-68-997689e3f3fb20b7": {
    "text": "露西喘著氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-69-6fb4a30114da2a32": {
    "text": "“Did I get it?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-69-7498128189c2d369": {
    "text": "「我打中了嗎？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-70-95a0f876c5abaefa": {
    "text": "The smoke slowly cleared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-70-9ad43e7aa0de316f": {
    "text": "煙霧慢慢散開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-71-eb65391aab96f58d": {
    "text": "The creature was still standing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-71-d0da5f15ac7b499e": {
    "text": "怪物還站著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-72-3de3df5e21dac5c2": {
    "text": "Not hurt.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-72-b9838318c00a18c4": {
    "text": "毫髮無傷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-73-6f912e96bddfe534": {
    "text": "Not even burned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-73-d3dc223e4038197d": {
    "text": "甚至沒有被燒焦。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-74-9fad5d07ed837573": {
    "text": "Lucy stared in horror.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-74-83289a4247a27a7a": {
    "text": "露西驚恐地看著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-75-511bf58ddcb5bb00": {
    "text": "“…Oh no.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-75-998f53a729aea837": {
    "text": "「……完了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-76-2fd9978a4dd48981": {
    "text": "The Shadow Stalker tilted its head slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-76-4591c7cb6680032d": {
    "text": "暗影追獵者慢慢歪頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-77-9e47656e867ffa67": {
    "text": "Then it whispered:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-77-2765ec3304c2c39c": {
    "text": "然後低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-78-d3161924eb930bea": {
    "text": "“Give… me… the watch…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-78-0f63f9d53e7cae4e": {
    "text": "「把……懷錶……給我……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-79-bd3fb8d2aca6e3a4": {
    "text": "Cold spread across the cabin floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-79-ab59b4e709bf6f2f": {
    "text": "寒氣蔓延車廂地板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-80-319ff072aac827dd": {
    "text": "Ice formed on the windows.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-80-dfab4673791197b5": {
    "text": "窗戶結上冰。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-81-d389aecd91f84a22": {
    "text": "Ethan backed away.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-81-8713d4cb09ecd3cc": {
    "text": "伊森後退。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-82-6915bce1ac260d65": {
    "text": "“How does it know about the watch?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-82-33589243fd546a84": {
    "text": "「它怎麼知道懷錶？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-83-af3622629e7bc2bb": {
    "text": "Adrian suddenly grabbed Ethan’s arm.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-83-b38c6e68d7c21a08": {
    "text": "亞德里安突然抓住伊森手臂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-84-181123a883d45e15": {
    "text": "“We have to move. NOW.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-84-d8baa75a94207f6e": {
    "text": "「我們得走。現在就走。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-85-8f12c861806d212e": {
    "text": "Another loud crash echoed somewhere on the train.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-85-56ecdddf93b9d372": {
    "text": "列車另一處傳來巨大撞擊聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-86-479f6ca5ef9067ac": {
    "text": "More screams.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-86-81b5a18c883393fd": {
    "text": "更多尖叫聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-87-135267db46ce38c8": {
    "text": "The creature was not alone.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-87-04db0eb49a974462": {
    "text": "怪物不只一隻。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-88-ecddd2a8a2867552": {
    "text": "Lucy looked terrified.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-88-c9bff90e45fe8092": {
    "text": "露西嚇壞了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-89-d60e47cb3278ea27": {
    "text": "“There are more of them?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-89-10e06b0fc785e219": {
    "text": "「還有更多？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-90-67beb0b3f37f5e20": {
    "text": "Adrian nodded grimly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-90-a0a6ddf14ebc27c8": {
    "text": "亞德里安沉重點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-91-7e4d29b862e16024": {
    "text": "“They travel in groups.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-91-abe091921eff19fb": {
    "text": "「牠們通常成群行動。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-92-24c78240062127ce": {
    "text": "The Shadow Stalker lunged again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-92-e3fe50a75dc8cc09": {
    "text": "暗影追獵者再次撲來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-93-c2cdc52e8200d17a": {
    "text": "This time Adrian shouted:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-93-fa8b4e4d53adc926": {
    "text": "這次亞德里安大喊：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-94-4979d6c993182993": {
    "text": "“TEMPO SHIELD!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-94-10992d676daced3f": {
    "text": "「時間護盾！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-95-22e405ff99e93e93": {
    "text": "A glowing silver barrier appeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-95-c9a1eb0c99bd4d66": {
    "text": "發光銀色屏障出現。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-96-4f2407ec45061cff": {
    "text": "CRASH!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-96-f71121b471973ddc": {
    "text": "砰！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-97-fac51bed2e422bd8": {
    "text": "The creature smashed against it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-97-e88b6d3fb1784e4d": {
    "text": "怪物撞上屏障。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-98-05eba935b0e322cb": {
    "text": "The barrier cracked instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-98-0930504d6e2719d5": {
    "text": "屏障立刻裂開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-99-55658d8c7193dd36": {
    "text": "Adrian gritted his teeth.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-99-a297148caf9248cd": {
    "text": "亞德里安咬牙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-100-49425f38e376890d": {
    "text": "“It’s stronger than normal…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-100-3538093723c54c51": {
    "text": "「它比普通的更強……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-101-bc6540216dcaa4a0": {
    "text": "The watch ticked faster.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-101-5a9616225af82692": {
    "text": "懷錶滴答越來越快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-102-f7215333185486cd": {
    "text": "TickTickTickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-102-59611e0f2c93d5d7": {
    "text": "滴答滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-103-e5fc830c02ed403e": {
    "text": "Ethan suddenly noticed something strange.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-103-8b894a3fd009780d": {
    "text": "伊森突然發現一件奇怪的事。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-104-7ecc0cf8ce055b98": {
    "text": "The creature seemed weaker whenever the watch glowed brighter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-104-805dadbdd5e06b5e": {
    "text": "每當懷錶更亮，怪物似乎就變弱。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-105-a8cfa0a66d712a28": {
    "text": "“Wait…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-105-37df1fff400ccc6e": {
    "text": "「等等……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-106-d12d0d7121052ea2": {
    "text": "He held up the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-106-d305cb008360c98d": {
    "text": "他舉起銀色懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-107-d08178964216b9d5": {
    "text": "The creature hissed again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-107-662cba556902faef": {
    "text": "怪物再次嘶吼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-108-0b95b99fd6e5e705": {
    "text": "Its body flickered slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-108-e64acdf924fcc1d8": {
    "text": "身體微微閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-109-44644db30747a122": {
    "text": "Lucy’s eyes widened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-109-9d7dd247b7fce733": {
    "text": "露西睜大眼睛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-110-7199306e433e79fa": {
    "text": "“The watch is protecting you!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-110-9672700480214963": {
    "text": "「懷錶在保護你！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-111-60ade824861a1022": {
    "text": "Ethan looked at the glowing lines.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-111-04760989efc05c01": {
    "text": "伊森看著發光線條。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-112-add8082d99c15ce6": {
    "text": "Then he remembered his grandmother’s words.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-112-e35e95f793512ada": {
    "text": "接著想起奶奶的話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-113-d3d5e84ca7f95149": {
    "text": "It works when magic is near.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-113-cb63bbff941aff63": {
    "text": "當魔法靠近時，它就會運作。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-114-bebd5fe7eda53705": {
    "text": "“No…” Ethan whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-114-56f79585a4d5b0ef": {
    "text": "「不……」伊森低聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-115-729b82b1ad24e4cb": {
    "text": "“It reacts to dark magic.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-115-8e7e4344d6473e82": {
    "text": "「它是在感應黑暗魔法。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-116-c83db068e618c4b1": {
    "text": "The Shadow Stalker growled angrily.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-116-4265cf2b22401bef": {
    "text": "暗影追獵者憤怒咆哮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-117-24ce060715fbd283": {
    "text": "“Give it… to me…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-117-52ad1bb5779c5662": {
    "text": "「把它……給我……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-118-be72e130add792ee": {
    "text": "Ethan swallowed hard.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-118-b47233f753c5037e": {
    "text": "伊森吞了吞口水。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-119-89df0a67f40aa14b": {
    "text": "Then slowly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-119-398ea5147c285d7f": {
    "text": "然後慢慢——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-120-d4e5340fef7e3b90": {
    "text": "He pressed the button on the watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-120-8beeba50d8f255bd": {
    "text": "按下懷錶按鈕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-121-0dd175ab100e45c3": {
    "text": "CLICK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-121-019792da7b48e033": {
    "text": "喀嚓。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-122-1b970504fee5ad8b": {
    "text": "The watch opened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-122-3c311e1c3039dcea": {
    "text": "懷錶打開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-123-e1293b5f302fd52e": {
    "text": "Inside was not a clock face.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-123-5ec53e9785e61eab": {
    "text": "裡面不是時鐘。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-124-d772810d57b0363a": {
    "text": "It was a symbol.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-124-ff6c819163858ddc": {
    "text": "而是一個圖案。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-125-93c8bba32d2e5864": {
    "text": "A glowing silver tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-125-ad6b58316fba5c70": {
    "text": "發光銀色高塔。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-126-bc30f1a485d6b02a": {
    "text": "Suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-126-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-127-b47ffb64f5ddb662": {
    "text": "Light exploded from the watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-127-b6358f36a60e1f75": {
    "text": "光從懷錶爆炸般衝出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-128-0ac7333bfaa4f2dd": {
    "text": "The entire cabin turned white.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-128-a8eae21302367e29": {
    "text": "整個車廂變白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-129-49063582d4c6186a": {
    "text": "The creature screamed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-129-edd9422193d5e9a3": {
    "text": "怪物尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-130-6997ed92e0c97c16": {
    "text": "SCREEEEEE—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-130-4d75678b72e85fb5": {
    "text": "啊啊啊啊——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-131-6b77836eb4022f1f": {
    "text": "Its smoky body broke apart violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-131-f5c33eefbaaed2ea": {
    "text": "煙霧身體劇烈崩裂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-132-36e1043d38640f7c": {
    "text": "Darkness burst across the room like shattered glass.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-132-fd0c3ebbc14fabd2": {
    "text": "黑暗像玻璃碎裂般炸開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-133-caeff3544cba7713": {
    "text": "The train stopped shaking.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-133-911a5717d6a29a1e": {
    "text": "列車停止搖晃。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-134-c640df0ff26e1300": {
    "text": "The ice melted instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-134-46fab30829810c1b": {
    "text": "冰瞬間融化。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-135-091e8c4cdba39a0e": {
    "text": "Silence filled the cabin.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-135-950f9d79944d5a4e": {
    "text": "安靜充滿車廂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-136-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-136-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-137-b9f90bd891fc00e8": {
    "text": "The creature disappeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-137-9ae34ebf2752fde7": {
    "text": "怪物消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-138-d7dd818e0c51171b": {
    "text": "Gone.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-138-46e0f0b3e07bed41": {
    "text": "徹底不見。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-139-3d960de81d151129": {
    "text": "Ethan stared at the watch in shock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-139-5155d398b479e9c3": {
    "text": "伊森震驚看著懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-140-30ba709e09493f74": {
    "text": "“What… was THAT?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-140-97595f4abe37dbbe": {
    "text": "「剛剛那到底是什麼？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-141-cea77b327b3a9054": {
    "text": "Lucy looked speechless.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-141-0ac6f2c639549a4a": {
    "text": "露西完全說不出話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-142-4259adcec450a37d": {
    "text": "Adrian stared at Ethan silently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-142-68ae1b6ca30df01d": {
    "text": "亞德里安安靜看著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-143-25783a209105cb09": {
    "text": "Then he whispered:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-143-2765ec3304c2c39c": {
    "text": "然後低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-144-59f65d3b5b8783b8": {
    "text": "“…Your father used the same magic.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-144-a4235f38f3be3c35": {
    "text": "「……你父親也使用過同樣的魔法。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-145-4c8a0b8e3ebd465b": {
    "text": "Ethan looked at him immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-145-a38b25cb7a699fca": {
    "text": "伊森立刻看向他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-146-4c3f1b9816937e2b": {
    "text": "“You knew my father, didn’t you?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-146-29d0e5f1ae0a5a39": {
    "text": "「你認識我爸爸，對不對？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-147-33cef999446010e9": {
    "text": "Before Adrian could answer—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-147-2e9cd23796c31001": {
    "text": "亞德里安還沒回答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-148-039caa074930b115": {
    "text": "The train speakers crackled loudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-148-240db4ddf3f03f65": {
    "text": "列車廣播突然響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-149-b34fb65d4ce89699": {
    "text": "“All students remain calm.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-149-417d4df64bd669d9": {
    "text": "「所有學生請保持冷靜。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-150-d9aef14ca8e211ce": {
    "text": "“We will arrive at Clock Tower shortly.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-150-0696a4dd64852f7d": {
    "text": "「列車即將抵達時鐘塔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-151-8ac1f3639a2fa047": {
    "text": "Outside the windows—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-151-eba9c6e25eaee0f3": {
    "text": "窗外——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-152-f03103b5c1477a43": {
    "text": "The storm had disappeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-152-f8b2a5b54253c5dd": {
    "text": "暴風雨已經消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-153-67a9df6860fb8c57": {
    "text": "Moonlight now covered the mountains.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-153-778775bdab838ee5": {
    "text": "月光照耀群山。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-154-7a774acb9c2ebfe6": {
    "text": "And far away—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-154-a5b248109b32a9fa": {
    "text": "而遠方——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-155-b62c622db283308f": {
    "text": "On top of a cliff—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-155-1b6aff7588a3cdaf": {
    "text": "懸崖之上——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-156-0d04001698d8572d": {
    "text": "Ethan finally saw it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-156-b06d76dd6d2f0e3e": {
    "text": "伊森終於看見它。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-157-0d415116d12f65c2": {
    "text": "A giant tower touching the clouds.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-157-3939cfb9613a2bdd": {
    "text": "一座巨大高塔直入雲層。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-158-2b804badcc9b7352": {
    "text": "Golden clock faces glowed in the night.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-158-488f414a5154d2be": {
    "text": "金色時鐘在夜裡閃耀。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-159-213a1f7147b6097b": {
    "text": "Lightning circled its highest point.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-159-f30a8795cd7eb40a": {
    "text": "閃電環繞塔頂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-160-be941502653fb9ae": {
    "text": "The Clock Tower Magic School.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-160-50959034adfca5fc": {
    "text": "時鐘塔魔法學院。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c4-en-block-161-31cbdacab5e56859": {
    "text": "Waiting for him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c4-zh-block-161-6f0be768d3b4af9b": {
    "text": "正在等著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-title-df4983edd84f3eef": {
    "text": "The Clock Tower School",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-title-347ba172f1873c6c": {
    "text": "時鐘塔魔法學院",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-0-a1bbdf325c94200d": {
    "text": "The Midnight Train slowed as it climbed the mountain tracks.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-0-33747457503f075c": {
    "text": "午夜列車慢慢沿著山路前進。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-1-d42ce6a7d061fd2e": {
    "text": "Steam covered the windows.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-1-9cf87f747e281f68": {
    "text": "蒸氣覆蓋窗戶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-2-ff1e6fd2cfb85d03": {
    "text": "The giant tower grew larger and larger outside.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-2-b7eb2b1d07835b83": {
    "text": "外面的巨大高塔越來越近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-3-13ad7f31e4034938": {
    "text": "Ethan pressed his face against the glass.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-3-c2a8d4201d1452fd": {
    "text": "伊森整張臉貼在玻璃上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-4-3d3ff58f0948bf12": {
    "text": "The school was enormous.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-4-3fc3a4ac3b14310e": {
    "text": "學校巨大得不可思議。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-5-dac588c52fb340df": {
    "text": "Tall black towers stretched into the clouds.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-5-a59f728a2073ad50": {
    "text": "高聳黑塔直衝雲層。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-6-d05e7c892152fe7a": {
    "text": "Golden clock faces glowed from every direction.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-6-f875ce20bc074850": {
    "text": "到處都有發光金色時鐘。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-7-b0447d668a487295": {
    "text": "Bridges connected floating buildings in the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-7-4b67cd7d0079cf3e": {
    "text": "橋梁連接漂浮在空中的建築。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-8-cb8ee36e16b259e6": {
    "text": "Blue flames burned beside the pathways.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-8-5a4997dd249f9e84": {
    "text": "道路旁燃燒著藍色火焰。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-9-a93b136015817b70": {
    "text": "And above everything—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-9-30da5db40e41b613": {
    "text": "而在最上方——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-10-a4b25514f563197a": {
    "text": "A massive clock ticked slowly at the top of the highest tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-10-ce8b4fb8eede9dac": {
    "text": "最高塔頂有一個巨大時鐘，正在慢慢滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-11-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-11-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-12-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-12-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-13-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-13-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-14-78235e9a81fdb980": {
    "text": "Ethan whispered,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-14-53cd7e9af115d060": {
    "text": "伊森低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-15-9d23bb497b93ec4f": {
    "text": "“This place is unbelievable…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-15-5bc343bdf039cc88": {
    "text": "「這地方太誇張了……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-16-5a8ddae2fcded74a": {
    "text": "Lucy grinned proudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-16-124e5918f729143b": {
    "text": "露西得意地笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-17-1bb164b21ed8c430": {
    "text": "“Wait until you see the inside.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-17-453c72fa7f7735f2": {
    "text": "「等你看到裡面。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-18-ef6b5015a90ef782": {
    "text": "Adrian remained silent near the window.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-18-d1cb07e79f96a7bb": {
    "text": "亞德里安依然沉默坐在窗邊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-19-3105ffaecafcb97d": {
    "text": "His expression looked troubled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-19-62dea16dbd29d73a": {
    "text": "但表情很沉重。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-20-60875b69b3e98c5e": {
    "text": "Ethan noticed immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-20-34f3be51f232d9cc": {
    "text": "伊森立刻注意到。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-21-8d99e2125ab2472f": {
    "text": "“You okay?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-21-65ea8b3613f8c4b5": {
    "text": "「你還好嗎？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-22-513bf0e285704bca": {
    "text": "Adrian looked away.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-22-d690ae42aca6c22f": {
    "text": "亞德里安移開視線。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-23-41b90109fe8e7a51": {
    "text": "“…The Shadow Stalker should not have found the train.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-23-5cf9d0c78967babb": {
    "text": "「……暗影追獵者不應該找到列車。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-24-84dc0226e3d84106": {
    "text": "Lucy nodded nervously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-24-b4bcd8f60e1822dc": {
    "text": "露西也緊張點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-25-43c9eb9c791ac131": {
    "text": "“That never happens.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-25-7fc792353532171e": {
    "text": "「從來沒發生過。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-26-ab575157fc8cad3d": {
    "text": "Ethan touched the silver watch again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-26-e39787b1e78bb1fd": {
    "text": "伊森摸了摸懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-27-8836b8dddd6176d5": {
    "text": "“You think it came because of this?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-27-173216ddbd6c7e5f": {
    "text": "「你們覺得是因為這個？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-28-02a07eb92f45e750": {
    "text": "Neither of them answered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-28-5a91a46f5b88e8eb": {
    "text": "兩人都沒回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-29-958e7e548819c7e9": {
    "text": "That silence told Ethan enough.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-29-f2ff729c327a1bcf": {
    "text": "那份沉默已經說明一切。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-30-9a732bbb3550f067": {
    "text": "The train finally stopped.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-30-b29a88548a0f0658": {
    "text": "列車終於停下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-31-9deb39fc78afd56f": {
    "text": "SCREEEEEEE—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-31-df75582c9404ebd3": {
    "text": "刺耳煞車聲響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-32-4927adbd565a699c": {
    "text": "A loud whistle echoed across the mountain.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-32-feb4da0d2699e42e": {
    "text": "一聲響亮汽笛回盪山間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-33-e7ee9e85938c9201": {
    "text": "Outside, students hurried onto the station platform.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-33-65051b33529e8936": {
    "text": "外面學生快速走上月台。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-34-a3c3970470f5cc75": {
    "text": "Cold night air rushed into the cabins.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-34-f5f8503d46d1d4f6": {
    "text": "冰冷夜風吹進車廂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-35-eede8e228fb40acf": {
    "text": "“Come on!” Lucy said excitedly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-35-139c8cff4308f875": {
    "text": "「快點！」露西興奮地說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-36-349ac4857704f449": {
    "text": "“We’re going to miss the arrival ceremony!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-36-f54ac6e82e834907": {
    "text": "「我們會錯過入學儀式！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-37-1b6517a18e62ea15": {
    "text": "Ethan grabbed his suitcase quickly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-37-7ca0fe9448c65fcd": {
    "text": "伊森快速抓起行李。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-38-c3388ec10f6834ba": {
    "text": "The three of them stepped onto the platform.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-38-8594a3ef30a3c1bb": {
    "text": "三人走上月台。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-39-d1b105eb94caecbd": {
    "text": "The mountain air smelled like rain and smoke.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-39-6f6fd41de6a16e53": {
    "text": "山上的空氣帶著雨和煙味。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-40-603f5bfa428c8e6e": {
    "text": "Huge stone statues lined the pathway toward the school.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-40-00163d0864ade120": {
    "text": "巨大石像排列在通往學校的道路旁。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-41-4da959d7dc63d5e3": {
    "text": "Each statue held a glowing lantern.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-41-7c16f203496a8f7b": {
    "text": "每個石像都拿著發光燈籠。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-42-13c217648b71fa72": {
    "text": "Some statues even moved slightly when students passed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-42-69a6695c8f96f4a1": {
    "text": "有些石像甚至會在學生經過時稍微轉頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-43-3acdf95e27c6d871": {
    "text": "Ethan nearly jumped.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-43-5ba7c30401c7914f": {
    "text": "伊森差點跳起來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-44-e69bd24962f73558": {
    "text": "“Did that statue just LOOK at me?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-44-84b93a54287031f6": {
    "text": "「那個石像剛剛是不是看我？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-45-367142891e766b9d": {
    "text": "Lucy laughed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-45-977912d4ba8e498b": {
    "text": "露西笑了出來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-46-f4a82ae10c484693": {
    "text": "“You get used to it.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-46-f3589a078ff1cac7": {
    "text": "「你會習慣的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-47-70f179e01d136862": {
    "text": "“I don’t think I will.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-47-f655d2a7ecc04f4c": {
    "text": "「我覺得我不會。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-48-857195ec83598578": {
    "text": "Far above them, thunder rolled around the tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-48-291fbb9db8febc1c": {
    "text": "高空雷聲環繞高塔。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-49-7b3e08fefa85656b": {
    "text": "The giant clock rang once.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-49-9ceb0e3355088db7": {
    "text": "巨大時鐘敲了一聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-50-f56db54e9137cbed": {
    "text": "DONGGGGG—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-50-e3a6a0b2696365cb": {
    "text": "噹————",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-51-0bf22ee856523ca6": {
    "text": "The sound shook the mountain itself.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-51-61c4ca7dd15ad1e1": {
    "text": "聲音震動整座山。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-52-538ea7ddf18e0436": {
    "text": "All the students stopped walking immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-52-f38c0b44b2ebe069": {
    "text": "所有學生立刻停下腳步。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-53-180f0c7aa1c7bc06": {
    "text": "The air became silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-53-da0afe0e5ff7299b": {
    "text": "空氣變安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-54-2c7492748fe09d22": {
    "text": "Even the wind disappeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-54-49e8b70af4e33420": {
    "text": "連風都停止了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-55-8b096f13c5b4e7a9": {
    "text": "Lucy whispered quietly,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-55-4f92b713da6b9e42": {
    "text": "露西小聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-56-70eb3c2c3821c504": {
    "text": "“That means the Headmaster is watching.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-56-9f84d1a08749821e": {
    "text": "「那代表校長正在看著我們。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-57-b2ba4ca373417fc5": {
    "text": "Ethan looked up at the highest tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-57-df66fc4c4acb7627": {
    "text": "伊森抬頭望向最高塔。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-58-5de34d3bbfe55b9d": {
    "text": "For one second—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-58-5db6b1f8819d38d7": {
    "text": "那一瞬間——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-59-ac6cf6988e1f7398": {
    "text": "He thought he saw someone standing near the giant clock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-59-8b431635e961fd02": {
    "text": "他以為自己看見有人站在巨大時鐘旁。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-60-7062577b53581250": {
    "text": "A tall figure in silver robes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-60-2586ce18b9ab30f7": {
    "text": "銀色長袍的高大身影。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-61-d3c6265e271edc71": {
    "text": "Watching the new students below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-61-ab35059919ba2ed4": {
    "text": "正看著下方新生。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-62-55b40ae2dddd42f1": {
    "text": "Then lightning flashed—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-62-4e935830a0ab07ee": {
    "text": "接著閃電劃過——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-63-dc2ec929c2bbee46": {
    "text": "And the figure vanished.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-63-cce5dc6acd1e9629": {
    "text": "身影消失了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-64-faae5b9d10763674": {
    "text": "“Uh… was someone up there?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-64-8b5780ff58bc53a1": {
    "text": "「呃……剛剛上面有人嗎？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-65-62a45a8f89f26975": {
    "text": "Lucy looked confused.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-65-c368166dd0676ee9": {
    "text": "露西疑惑地看著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-66-02a8ccaec5748651": {
    "text": "“Where?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-66-d2ab32039de283ff": {
    "text": "「哪裡？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-67-be80e7eb0b0ec46e": {
    "text": "But Adrian’s face became serious again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-67-fbb3f86c052690fa": {
    "text": "但亞德里安的表情又嚴肅起來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-68-01a8c870acebfb88": {
    "text": "“…Don’t stare at the tower too long.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-68-179f8bdf037689c5": {
    "text": "「……不要盯著塔看太久。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-69-c8270c3e70686e1e": {
    "text": "Ethan frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-69-f09e32b4e8865c97": {
    "text": "伊森皺眉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-70-312bdd396206f4b1": {
    "text": "“Why?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-70-68827126cd3b529a": {
    "text": "「為什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-71-513bf0e285704bca": {
    "text": "Adrian looked away.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-71-d690ae42aca6c22f": {
    "text": "亞德里安移開視線。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-72-491ac68f6803956b": {
    "text": "“Because sometimes…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-72-111a35acff6bb6d2": {
    "text": "「因為有時候……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-73-079efddb49282d7b": {
    "text": "“The tower stares back.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-73-c9131c2e74783ba2": {
    "text": "「塔也會看著你。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-74-1b1fc55f50e4e558": {
    "text": "“That is the least comforting thing I’ve ever heard.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-74-0437b0a1bf4c8b0c": {
    "text": "「這是我今天聽過最不安心的話。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-75-eb2ac4b347b4a6f7": {
    "text": "Lucy burst into laughter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-75-9dd3f556c68f549a": {
    "text": "露西直接笑了出來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-76-fb09192e8569a1f2": {
    "text": "The students followed glowing lanterns toward the school gates.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-76-95c6341181e4f1d9": {
    "text": "學生跟著發光燈籠走向學校大門。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-77-d48100f387f9bc5a": {
    "text": "The gates were enormous.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-77-b8192cb812f00bf8": {
    "text": "學校大門非常巨大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-78-338b61ce2c7ade2d": {
    "text": "Black metal covered with silver symbols.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-78-2c829d24815ae921": {
    "text": "黑色金屬覆蓋著銀色符號。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-79-ae49f70c2e6bb818": {
    "text": "As Ethan walked closer—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-79-185c2b39039d1592": {
    "text": "當伊森靠近——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-80-07f2618a93554ade": {
    "text": "The gates slowly opened by themselves.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-80-45b9fe9182392d01": {
    "text": "大門自己慢慢打開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-81-ec13330b716355ca": {
    "text": "CREEEEEEAK—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-81-90e7da1414347ade": {
    "text": "嘎————",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-82-f646bbadb095b3a4": {
    "text": "Warm golden light spilled outward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-82-60169716f93ff553": {
    "text": "溫暖金光從裡面流出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-83-3177ebc211065847": {
    "text": "Inside was a gigantic hall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-83-34d7f70f4774b709": {
    "text": "裡面是一座巨大大廳。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-84-d39111772d9442bc": {
    "text": "Floating candles filled the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-84-7956749f45f9b0a2": {
    "text": "漂浮蠟燭充滿空中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-85-25c87d8de48fa4a6": {
    "text": "Long tables stretched across the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-85-ae3b3db68675cadd": {
    "text": "長桌橫跨整個大廳。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-86-0339ab48acb55dc9": {
    "text": "Hundreds of students sat together in dark robes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-86-20bd6312f63c5599": {
    "text": "數百名學生穿著黑袍坐在一起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-87-03bae19c58620099": {
    "text": "At the far end of the hall—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-87-e0d0569879f3a710": {
    "text": "而在大廳盡頭——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-88-1080c43690be6bb5": {
    "text": "A staircase floated in the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-88-e6298be52e3b5923": {
    "text": "樓梯漂浮在空中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-89-1b3b56a6a5522f5f": {
    "text": "Moving slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-89-353c2079b1aecf80": {
    "text": "慢慢移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-90-353c461df40c571e": {
    "text": "Changing direction by itself.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-90-b1f7cbfcd7f50f98": {
    "text": "自己改變方向。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-91-ea78f844c80a4f78": {
    "text": "Ethan stared upward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-91-b24370db935441bd": {
    "text": "伊森抬頭發呆。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-92-97c055aa91c6e247": {
    "text": "“The stairs are floating?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-92-33f43179f0a22b30": {
    "text": "「樓梯會飛？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-93-b6d78a96753b2cd2": {
    "text": "Lucy smiled proudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-93-124e5918f729143b": {
    "text": "露西得意地笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-94-eec55b22db6b0840": {
    "text": "“Yep.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-94-4bd6f4312595e8e5": {
    "text": "「對。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-95-106a94dca3194432": {
    "text": "“They change every day.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-95-54e62ff0687016eb": {
    "text": "「而且每天都不一樣。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-96-6fa123326b6885e8": {
    "text": "“That sounds extremely dangerous.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-96-be204343254ff22d": {
    "text": "「聽起來超危險。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-97-c9632f12759f3baf": {
    "text": "“It is.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-97-a8ee6b33ee280eed": {
    "text": "「確實是。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-98-d5e27e7f180ebbe3": {
    "text": "Teachers stood near the front of the hall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-98-74f18bb569e463bf": {
    "text": "老師們站在前方。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-99-17ec0b34500289a1": {
    "text": "Some looked kind.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-99-ca30aa221c06db44": {
    "text": "有些看起來很親切。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-100-fd797640279be6ab": {
    "text": "Some looked terrifying.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-100-79daf6e6019480e2": {
    "text": "有些超可怕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-101-fb57297aa9837629": {
    "text": "One teacher had an eyepatch made of silver glass.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-101-658984ae1ce48fac": {
    "text": "一位老師戴著銀色玻璃眼罩。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-102-f4ad0799d46ac8ac": {
    "text": "Another had glowing blue tattoos across both hands.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-102-840801e6543b2f37": {
    "text": "另一位老師雙手有藍色發光紋路。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-103-5103b79c98075c1a": {
    "text": "And standing at the center—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-103-0c32ffb2ffef48d5": {
    "text": "而站在中央的——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-104-5d44e85b07cbef2e": {
    "text": "Was the Headmaster.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-104-b6bfb4f07c22c551": {
    "text": "是校長。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-105-c7f967544d48d889": {
    "text": "He wore long silver robes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-105-3f48474ac378cdc2": {
    "text": "他穿著長長銀袍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-106-08d67943fce528d2": {
    "text": "White hair flowed down his shoulders.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-106-9215f13bae309489": {
    "text": "白色長髮垂落肩膀。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-107-244601163a9d753b": {
    "text": "His eyes glowed faintly gold.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-107-dd98ee5a576cbcb2": {
    "text": "雙眼微微發出金光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-108-7b701084ded30c43": {
    "text": "The entire hall became silent when he stepped forward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-108-42ecea65a9f6f8d1": {
    "text": "當他往前一步時，整個大廳瞬間安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-109-ea031e08cf37c795": {
    "text": "He looked ancient.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-109-79a0c144b8329a84": {
    "text": "他看起來古老。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-110-85b3b1c7ab93bb4a": {
    "text": "Powerful.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-110-402045cbafdb3c68": {
    "text": "強大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-111-16ed9275164d5874": {
    "text": "Like he could hear every heartbeat in the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-111-9e0ac6ca19cc9569": {
    "text": "像能聽見房間裡每個人的心跳。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-112-100160e363afe9b4": {
    "text": "“Welcome,” he said calmly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-112-265d39be8957163a": {
    "text": "「歡迎，」他平靜地說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-113-15aa55cada1b8bc1": {
    "text": "His voice echoed everywhere without being loud.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-113-891d4e1fbfa08dd2": {
    "text": "他的聲音不大，卻傳遍整個大廳。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-114-12601d19a4994f06": {
    "text": "“Welcome to Clock Tower Magic School.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-114-3cdf741bf94bb022": {
    "text": "「歡迎來到時鐘塔魔法學院。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-115-99b324b5be287593": {
    "text": "The floating candles brightened instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-115-81e1d7cf52712aa4": {
    "text": "漂浮蠟燭瞬間變亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-116-b1d6736ae9b1d02c": {
    "text": "“Tonight, you begin your journey as Keepers.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-116-34349e1866b29dd2": {
    "text": "「今晚，你們將開始成為守護者的旅程。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-117-0e0b4c1432d3deaf": {
    "text": "“Some of you will learn courage.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-117-fe365b2599ebeaf4": {
    "text": "「有人將學會勇氣。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-118-1a157aa06e7c79a6": {
    "text": "“Some wisdom.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-118-cfb254e6bdbc85b5": {
    "text": "「有人將學會智慧。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-119-d6a9cc1d90c328b7": {
    "text": "“Some sacrifice.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-119-943fc95330c65723": {
    "text": "「有人將學會犧牲。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-120-84e7f8bedba632f8": {
    "text": "His golden eyes slowly moved across the students.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-120-45783d2568dd6507": {
    "text": "他的金色眼睛慢慢掃過學生。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-121-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-121-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-122-c8af2ba912674855": {
    "text": "For the briefest moment—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-122-c8ba5d760a83ced0": {
    "text": "短短一瞬間——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-123-01b49c81f523d2dd": {
    "text": "They stopped on Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-123-ae37d8d0c75b1f80": {
    "text": "停在伊森身上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-124-049c56f1b759b00c": {
    "text": "The silver watch suddenly ticked loudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-124-4935b0b1e6ceacff": {
    "text": "伊森口袋裡的懷錶突然大聲滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-125-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-125-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-126-a9ea7a984b7f732a": {
    "text": "The Headmaster’s expression changed slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-126-ae66144b178e51a6": {
    "text": "校長表情微微變化。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-127-834f0c36cb6a7948": {
    "text": "Almost surprised.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-127-57ae09bd6f874561": {
    "text": "像是驚訝。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-128-fba4509cdeb699ef": {
    "text": "But only for a second.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-128-0a8ee6f27c5583fb": {
    "text": "但只有一秒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-129-0ff93ece6fad3370": {
    "text": "Then he continued speaking normally.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-129-a89d7ee15de72074": {
    "text": "接著恢復正常。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-130-ebcc66164d92d2d2": {
    "text": "“You will soon be assigned to your tower houses.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-130-02be8cbe6cb14d82": {
    "text": "「你們很快就會被分配到各塔宿舍。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-131-69f0c7fbb3d9b09d": {
    "text": "Lucy whispered excitedly,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-131-371bd6876f955538": {
    "text": "露西興奮低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-132-ba4cd84f4fc80a2d": {
    "text": "“This is the best part.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-132-f3b4358ab6faf777": {
    "text": "「最好玩的部分來了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-133-bf32c05ba3b9b363": {
    "text": "At the center of the hall stood four giant banners.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-133-2f1b7e1f982f107a": {
    "text": "大廳中央有四面巨大旗幟。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-134-d15fbcb4d3c3285c": {
    "text": "A silver wolf.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-134-faedb739cc0d0f12": {
    "text": "銀狼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-135-c678ed943898ea12": {
    "text": "A black raven.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-135-dde7dfbdf9c397c8": {
    "text": "黑鴉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-136-86015d22971d8941": {
    "text": "A golden lion.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-136-cc9768ec487b1083": {
    "text": "金獅。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-137-2179c72a7944784b": {
    "text": "And a white serpent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-137-1b6bbfdbe59950c1": {
    "text": "白蛇。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-138-89a6fde982fde1cb": {
    "text": "“Each house trains different kinds of magic,” Lucy explained.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-138-fa7f947c348cf314": {
    "text": "「每個學院都學不同魔法，」露西解釋。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-139-698464ba403296e4": {
    "text": "Ethan looked impressed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-139-0e9b96ef0685e956": {
    "text": "伊森看得入迷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-140-b7c2ac816fb47ec3": {
    "text": "“That actually looks amazing.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-140-4f6181e2d7dc40de": {
    "text": "「這真的超酷。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-141-bc30f1a485d6b02a": {
    "text": "Suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-141-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-142-02aec70c71035070": {
    "text": "BOOM.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-142-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-143-90610b3fef5bcb9c": {
    "text": "The hall doors slammed shut by themselves.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-143-94e6b5a272462be8": {
    "text": "大廳門自己關上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-144-b7f31d442db6a2b2": {
    "text": "Every candle flickered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-144-f5b7158e2ebfb134": {
    "text": "所有蠟燭閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-145-ae003fd85c7c9c98": {
    "text": "Cold wind rushed through the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-145-cd5b5baed2ba35be": {
    "text": "冷風吹過整個大廳。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-146-25f9e0c1d3086e6d": {
    "text": "The Headmaster stopped speaking immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-146-a36e9e1559f3afe4": {
    "text": "校長瞬間停止說話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-147-44733fefe98bd8b6": {
    "text": "Teachers stood up quickly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-147-bde3fa9fcd2df816": {
    "text": "老師們立刻站起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-148-6ecf16062f446220": {
    "text": "The silver watch in Ethan’s pocket began ticking wildly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-148-90db660567b6f823": {
    "text": "伊森口袋裡的懷錶開始瘋狂滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-149-f7215333185486cd": {
    "text": "TickTickTickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-149-59611e0f2c93d5d7": {
    "text": "滴答滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-150-94b17ab4cc8ffb93": {
    "text": "Adrian whispered,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-150-f2c9b8f250efe691": {
    "text": "亞德里安低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-151-816c3340c91e31c8": {
    "text": "“…No way.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-151-c50722a8734fd7db": {
    "text": "「……不可能。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-152-1a361848d2c95523": {
    "text": "A dark mark slowly appeared on the ceiling above the hall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-152-a062ad3548d6d84e": {
    "text": "黑色痕跡慢慢出現在大廳天花板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-153-803e5fa12e27ef40": {
    "text": "Smoke spread outward like black veins.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-153-f06b633329fe9321": {
    "text": "煙霧像黑色血管擴散。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-154-4e21f9b88d1bae43": {
    "text": "Students screamed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-154-455f83e561255f17": {
    "text": "學生開始尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-155-8041820c9c492f0a": {
    "text": "The floating candles turned blue.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-155-d7f3deb0fb898d74": {
    "text": "漂浮蠟燭全部變藍色。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-156-fd00dd090cfbad95": {
    "text": "And from inside the darkness—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-156-b2cbd771a8ffb6cc": {
    "text": "而在黑暗裡——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-157-3e5b9815950cbfb9": {
    "text": "Two glowing purple eyes opened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-157-fcc6e48ab73dd5c3": {
    "text": "兩隻紫色眼睛慢慢睜開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c5-en-block-158-c11e1682c341ce07": {
    "text": "Watching Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c5-zh-block-158-349cd6793be4d2aa": {
    "text": "正在看著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-title-8d475920173b67f3": {
    "text": "The Forbidden Mark",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-title-434859ec6d4725fb": {
    "text": "禁忌印記",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-0-b60ea50d3cfbb9ef": {
    "text": "The entire hall froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-0-613ea93d774b844e": {
    "text": "整個大廳瞬間凍結。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-1-626e02867a5d9e0c": {
    "text": "Nobody moved.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-1-438942b9029c88f1": {
    "text": "沒有人移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-2-b937072d6bb772be": {
    "text": "Nobody breathed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-2-b575119deca0636a": {
    "text": "沒有人呼吸。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-3-e4dd800adf73e3d0": {
    "text": "Above the students, the black mark spread across the ceiling like living smoke.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-3-7730e0777d150381": {
    "text": "學生頭頂上方，黑色印記像活著的煙霧般擴散。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-4-b357ace15afa781e": {
    "text": "The purple eyes stared directly at Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-4-f4879fc1de531c42": {
    "text": "紫色眼睛直直盯著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-5-70270cf48903a330": {
    "text": "Cold air swept through the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-5-f866464a113567a9": {
    "text": "冰冷空氣席捲整個大廳。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-6-4f59eb21617bca58": {
    "text": "The floating candles flickered violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-6-edaac4d4362fac20": {
    "text": "漂浮蠟燭劇烈閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-7-132176b8f493dcb9": {
    "text": "Students began whispering nervously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-7-90916512e090a16d": {
    "text": "學生開始不安低語。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-8-c8628376d56fff4b": {
    "text": "“What is that?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-8-8cfbd487be1490e5": {
    "text": "「那是什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-9-03425c8d262cb20c": {
    "text": "“Is this part of the ceremony?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-9-94eb9f91b1b6d193": {
    "text": "「這是入學儀式的一部分嗎？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-10-0fac7aad6b284b65": {
    "text": "“No… something’s wrong…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-10-6a990f6bdb0f730b": {
    "text": "「不對……有事情不對勁……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-11-817d395beac6e924": {
    "text": "Ethan’s heart pounded painfully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-11-6ba120ccd2eadbbe": {
    "text": "伊森心臟劇烈跳動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-12-164bdb1630f43566": {
    "text": "The silver watch in his pocket burned with heat.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-12-460898f68bd790ac": {
    "text": "口袋裡的銀色懷錶燙得發熱。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-13-9917ddaa75ce0eba": {
    "text": "TickTickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-13-59611e0f2c93d5d7": {
    "text": "滴答滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-14-64bfa1a7d0adc104": {
    "text": "The Headmaster stepped forward slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-14-c515ff995ca155d2": {
    "text": "校長慢慢往前走。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-15-c35019161640825e": {
    "text": "His golden eyes glowed brighter now.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-15-0742b6a3e7cbcf5a": {
    "text": "金色眼睛變得更亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-16-4170fc514ecd59b9": {
    "text": "Every teacher in the hall raised their wands immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-16-5bc93369eea97308": {
    "text": "所有老師立刻舉起魔杖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-17-cfc2d70eaa57d96e": {
    "text": "“Remain calm,” the Headmaster said firmly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-17-e5fa31d3564c9d47": {
    "text": "「保持冷靜，」校長沉聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-18-71779a1e99b2c848": {
    "text": "His voice echoed like thunder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-18-a2ca82d4701a7064": {
    "text": "聲音像雷聲般回盪。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-19-7838978e96c6f819": {
    "text": "The frightened whispers stopped instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-19-9b5d8d92b9cb69c5": {
    "text": "學生的騷動瞬間停止。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-20-d8c8246287214e6e": {
    "text": "The dark shape above twisted slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-20-9d7f6003a28d0d74": {
    "text": "上方黑影緩緩扭曲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-21-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-21-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-22-f1ed4eeb6620b55c": {
    "text": "A symbol appeared inside the smoke.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-22-f2dabfbe2ce8aff2": {
    "text": "煙霧裡出現一個符號。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-23-1f46e59136053d8f": {
    "text": "A black circle surrounded by broken clock hands.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-23-bd2a8032267b70e9": {
    "text": "黑色圓圈周圍是破碎的時鐘指針。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-24-c68b093ef1eb1aea": {
    "text": "The moment Adrian saw it—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-24-a6d7015fcec70a79": {
    "text": "亞德里安一看到——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-25-f336d98b659a6455": {
    "text": "His face lost all color.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-25-3ba4246375cfdeee": {
    "text": "臉色瞬間慘白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-26-70deee506a541fe0": {
    "text": "“No way…” he whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-26-61f6fc2547bf4e30": {
    "text": "「不可能……」他低聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-27-ecddd2a8a2867552": {
    "text": "Lucy looked terrified.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-27-6e6a4915156db763": {
    "text": "露西也嚇壞了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-28-d1ec82ff86ce7ed4": {
    "text": "“That symbol was destroyed years ago…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-28-014494073b9ae5de": {
    "text": "「那個符號幾年前就被消滅了……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-29-c8270c3e70686e1e": {
    "text": "Ethan frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-29-f09e32b4e8865c97": {
    "text": "伊森皺眉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-30-5aa677add415a71e": {
    "text": "“What symbol?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-30-587ac3bbcf48f30e": {
    "text": "「什麼符號？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-31-e1b542d2e585f623": {
    "text": "Neither answered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-31-5a91a46f5b88e8eb": {
    "text": "兩人都沒回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-32-89a1d58144915695": {
    "text": "The smoke suddenly moved.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-32-22e83c33d715bf03": {
    "text": "煙霧突然動了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-33-af17e4ba64ce4fd2": {
    "text": "FAST.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-33-5f4f9bf455776c23": {
    "text": "超快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-34-ee3cf550be1b5476": {
    "text": "Darkness shot downward from the ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-34-be9dbfbbfd64b00e": {
    "text": "黑暗從天花板猛衝下來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-35-4e21f9b88d1bae43": {
    "text": "Students screamed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-35-da8b4403b15d07c7": {
    "text": "學生尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-36-f4cb2c3e2b36e205": {
    "text": "Teachers fired spells instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-36-8c5f9e04c02b3161": {
    "text": "老師立刻施法。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-37-de9c332dfb071879": {
    "text": "“LUMINA!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-37-d476d1d6366f38fc": {
    "text": "「光耀！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-38-39743f7259eb31c3": {
    "text": "“VAREX!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-38-6b27ab31fba6244e": {
    "text": "「結界展開！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-39-f1c4e4f6084e31af": {
    "text": "“IGNIS WALL!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-39-b7f3473da0182d5d": {
    "text": "「烈焰之牆！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-40-41aaad541c353511": {
    "text": "Golden light exploded across the hall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-40-33d43dd9961d06f6": {
    "text": "金色光芒在大廳爆發。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-41-fdf2c212b7ed7991": {
    "text": "Fire and silver shields filled the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-41-04980bef87ee7142": {
    "text": "火焰與銀色護盾充滿空氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-42-ede04e12eb591495": {
    "text": "The dark smoke smashed against the magical barriers.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-42-aa6ecdffe85881cf": {
    "text": "黑暗狠狠撞上魔法屏障。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-43-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-43-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-44-7d9c0841f70258c5": {
    "text": "The floor shook violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-44-24950d94903cc4d7": {
    "text": "地板劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-45-71c3490c2e694144": {
    "text": "Ethan stumbled backward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-45-a094e3ee7171649d": {
    "text": "伊森差點跌倒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-46-0f4fef7ee15e8600": {
    "text": "The silver watch glowed brighter and brighter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-46-28febc74945c6586": {
    "text": "懷錶光越來越亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-47-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-47-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-48-2cb461a265cca98d": {
    "text": "The dark smoke suddenly changed direction.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-48-d939edc9b4326b97": {
    "text": "黑煙突然轉向。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-49-df286663f0f97de9": {
    "text": "Toward Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-49-fb4400d33e11f4de": {
    "text": "朝伊森衝去。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-50-c11056eb8e553b0c": {
    "text": "The Headmaster shouted immediately:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-50-99fb681f4bd487ba": {
    "text": "校長立刻大喊：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-51-9a7bbab3cc978df4": {
    "text": "“Protect the boy!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-51-552bd0fff2e06141": {
    "text": "「保護那孩子！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-52-af08772fddb3ef1d": {
    "text": "Three teachers jumped between Ethan and the smoke.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-52-ab495c458224485d": {
    "text": "三名老師跳到伊森與黑煙之間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-53-1e24e7e9e198f589": {
    "text": "The silver-eyed teacher slammed his wand downward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-53-2e3344fefebb027d": {
    "text": "銀眼老師猛然揮杖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-54-5fa58ad038640062": {
    "text": "A giant glowing wall appeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-54-62032a49e23ed0a9": {
    "text": "巨大發光牆壁出現。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-55-4f2407ec45061cff": {
    "text": "CRASH!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-55-f71121b471973ddc": {
    "text": "砰！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-56-713509c69fa48e48": {
    "text": "Darkness exploded against it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-56-0fe277921d5ad88b": {
    "text": "黑暗撞上屏障。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-57-05eba935b0e322cb": {
    "text": "The barrier cracked instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-57-97b941beabd39a73": {
    "text": "屏障瞬間裂開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-58-3eddd439b6db51bf": {
    "text": "Students panicked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-58-cfc7727ce406db08": {
    "text": "學生陷入恐慌。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-59-4027bf6a060607df": {
    "text": "Tables overturned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-59-6276b57939d236af": {
    "text": "桌子翻倒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-60-354da32f7fbfad0e": {
    "text": "Books and plates flew everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-60-b9b945c87f9532ac": {
    "text": "書本與盤子四處飛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-61-ee56f533b7f7ab55": {
    "text": "Lucy grabbed Ethan’s sleeve.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-61-0548a1d82983a2a1": {
    "text": "露西抓住伊森袖子。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-62-4b2c895f3641d75b": {
    "text": "“We have to MOVE!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-62-b5e210c2ad56a139": {
    "text": "「我們得快走！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-63-48561225eb435d7d": {
    "text": "“What IS this thing?!” Ethan shouted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-63-39f7ec0d30978878": {
    "text": "「這到底是什麼？！」伊森大喊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-64-6dc788d9780fd319": {
    "text": "Adrian’s gray eyes stayed fixed on the black symbol.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-64-3257526543dc3ce0": {
    "text": "亞德里安死死盯著黑色符號。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-65-25783a209105cb09": {
    "text": "Then he whispered:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-65-2765ec3304c2c39c": {
    "text": "然後低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-66-b8f59401094bf1c8": {
    "text": "“…The Mark of Noctis.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-66-76cac6334c44f2f6": {
    "text": "「……諾克提斯印記。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-67-d67f68b9bf254d13": {
    "text": "Ethan blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-67-134fbeb356ccc19c": {
    "text": "伊森愣住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-68-c2e1bb7b3fa1fbe7": {
    "text": "“The what?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-68-5ab60aad745f2829": {
    "text": "「什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-69-d69b9dcf2e64dea9": {
    "text": "Adrian swallowed hard.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-69-5744e11bf723fa46": {
    "text": "亞德里安吞口水。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-70-ea3fc82026d2e111": {
    "text": "“It belonged to the Dark Keeper.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-70-300aede94af3967b": {
    "text": "「那是黑暗守護者的標誌。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-71-a8ed003d0c39815b": {
    "text": "The hall became colder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-71-ded960c97513a1f9": {
    "text": "整個大廳變得更冷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-72-64d1ff7df3b3a04a": {
    "text": "Even saying the name felt dangerous.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-72-71fd1ccd02110acb": {
    "text": "連說出名字都令人不安。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-73-8940425e0b517332": {
    "text": "Lucy looked around nervously before whispering:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-73-6093e6e19a271097": {
    "text": "露西緊張看四周後低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-74-4f7b34346c0591e8": {
    "text": "“You’re not supposed to say it out loud.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-74-045431f448af5f50": {
    "text": "「那名字不能隨便說出口。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-75-dcfce2b82ef919c6": {
    "text": "Ethan stared at them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-75-099b8681db4e47af": {
    "text": "伊森看著他們。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-76-92cb9073e986810f": {
    "text": "“Who is the Dark Keeper?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-76-7deea1ddcf2f7d0a": {
    "text": "「黑暗守護者到底是誰？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-77-557a960365e79237": {
    "text": "Before they could answer—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-77-fd7671099706177d": {
    "text": "還來不及回答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-78-ea635328bd674f97": {
    "text": "The smoke above the hall began forming a face.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-78-3549b753d9dcfb80": {
    "text": "天花板煙霧開始形成一張臉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-79-34272c3e25de3f43": {
    "text": "Huge.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-79-293d1ed47502ad26": {
    "text": "巨大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-80-ddc73d7ffb47abe1": {
    "text": "Shadowy.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-80-b57ef4fdb68f3866": {
    "text": "黑暗。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-81-0bdd86e0ca63800e": {
    "text": "Human.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-81-07e029bbbfba9f16": {
    "text": "像人類。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-82-45725f96d94ba5eb": {
    "text": "Purple eyes burned within it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-82-e9b4281acadf6851": {
    "text": "紫色眼睛在其中燃燒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-83-b3d3a0689d8b58a1": {
    "text": "And then it spoke.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-83-caf84f2339de7fb1": {
    "text": "然後它開口。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-84-fc3af9390da04e89": {
    "text": "“Return… the heir…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-84-243d8c4f0719fe76": {
    "text": "「把……繼承者……交出來……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-85-ed40f51e9bdf0360": {
    "text": "The entire hall fell silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-85-cc32556da544b740": {
    "text": "整個大廳安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-86-5b095811acc4d038": {
    "text": "The voice echoed inside Ethan’s head like ice.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-86-b6ae37b1ab2f7ac8": {
    "text": "那聲音像冰一樣刺進伊森腦中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-87-ef22148601f83662": {
    "text": "“Return… the watch…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-87-62d1978dd2e4a353": {
    "text": "「把……懷錶……交出來……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-88-de9fec26db06d212": {
    "text": "Ethan stepped backward slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-88-fb649207eb753bcf": {
    "text": "伊森慢慢後退。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-89-8632d8f0ce132a46": {
    "text": "“It wants the watch…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-89-c048d276bcdbed2f": {
    "text": "「它想要懷錶……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-90-10d81f6bd6c70581": {
    "text": "The giant shadow face smiled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-90-5dad6a762750ca2e": {
    "text": "巨大黑影露出可怕笑容。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-91-8f008327446dbd40": {
    "text": "A horrible smile.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-91-61b1f13c232c07fc": {
    "text": "可怕的笑容。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-92-e6a1791eb838fa82": {
    "text": "“Yes…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-92-cfea374a2eb73659": {
    "text": "「沒錯……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-93-d3004def4dd621af": {
    "text": "The silver watch suddenly opened by itself.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-93-45a83313a6550e17": {
    "text": "銀色懷錶突然自己打開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-94-0dd175ab100e45c3": {
    "text": "CLICK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-94-019792da7b48e033": {
    "text": "喀嚓。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-95-c8cc80e4bb423123": {
    "text": "Bright silver light burst from inside.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-95-1f10f0b96b794750": {
    "text": "銀色強光爆發。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-96-b7ac4b9d474b4b5a": {
    "text": "The entire hall glowed white.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-96-526096abc95aa9f5": {
    "text": "整個大廳被白光覆蓋。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-97-c64a4e104f2ed8f0": {
    "text": "Students covered their eyes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-97-43ae2665db9c75fd": {
    "text": "學生遮住眼睛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-98-0a2a754aac0deb8d": {
    "text": "The dark smoke hissed violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-98-0c33e2970df6f53d": {
    "text": "黑煙發出淒厲尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-99-e2c17dd51b420e63": {
    "text": "The shadow face twisted angrily.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-99-44d25a40ac2b01c1": {
    "text": "黑影臉孔憤怒扭曲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-100-c0baf6c30a3927e7": {
    "text": "“No…!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-100-640e0fb6c16ae269": {
    "text": "「不——！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-101-15e59c0fb97546b0": {
    "text": "The Headmaster turned sharply toward Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-101-267c52f4928c660b": {
    "text": "校長猛然看向伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-102-8de8a656e2c29220": {
    "text": "For the first time—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-102-f34020f63d9ecb89": {
    "text": "第一次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-103-82807dc43fc2d57d": {
    "text": "He looked shocked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-103-b478d2eaddc6ad73": {
    "text": "他露出震驚表情。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-104-b0fa9622d3cccef1": {
    "text": "Not scared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-104-a6b23f6e459f9452": {
    "text": "不是害怕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-105-2573684e306c07c2": {
    "text": "Not angry.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-105-b11d61750e966029": {
    "text": "不是憤怒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-106-e48491eed04bb834": {
    "text": "Shocked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-106-fbe544ed71d84fdc": {
    "text": "而是震驚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-107-3a7718d18c406c5c": {
    "text": "“You…” the Headmaster whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-107-a8321eceacf3350c": {
    "text": "「你……」校長低聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-108-7f1bbb63a6117213": {
    "text": "The watch floated upward from Ethan’s pocket.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-108-f46a00960aee8437": {
    "text": "懷錶從伊森口袋漂浮起來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-109-5a9be438c0beec10": {
    "text": "Hovering in the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-109-c8324ad4c1a855f5": {
    "text": "停在空中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-110-46681fb904062873": {
    "text": "The glowing tower symbol inside expanded across the hall floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-110-b585cfafa69857ad": {
    "text": "裡面的高塔圖案擴散到整個地板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-111-d6db43bcb0c00fc5": {
    "text": "Silver light spread everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-111-f161b5c160305d11": {
    "text": "銀光覆蓋全場。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-112-3c076cd2f86cf6d2": {
    "text": "The dark smoke screamed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-112-81b5cb0d81729c3e": {
    "text": "黑煙慘叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-113-ce882b6213748910": {
    "text": "The Mark of Noctis cracked apart.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-113-715c2fc39fa3ebf0": {
    "text": "諾克提斯印記開始碎裂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-114-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-114-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-115-6c0a1d0eea8153da": {
    "text": "Darkness exploded like shattered glass.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-115-615201cc521a29f0": {
    "text": "黑暗像玻璃般炸開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-116-7c41051a463dd47d": {
    "text": "The purple eyes vanished instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-116-15a03d6ef0ad3056": {
    "text": "紫色眼睛瞬間消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-117-42caaf875bd101d6": {
    "text": "Silence.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-117-833204688b72a129": {
    "text": "安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-118-3fda833a47318451": {
    "text": "Complete silence.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-118-cb16313461aa2b72": {
    "text": "完全安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-119-b5aec98d6cc0df42": {
    "text": "The floating candles slowly returned to normal.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-119-ed67ca90c18cc4dd": {
    "text": "漂浮蠟燭慢慢恢復正常。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-120-d36b9ba4a6a60548": {
    "text": "One by one.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-120-3a8440b443e9b284": {
    "text": "一盞接一盞。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-121-75ac66377f80d7b1": {
    "text": "Students stared at Ethan in shock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-121-9260202e73302823": {
    "text": "所有學生震驚看著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-122-cd4daa0d82968adb": {
    "text": "Nobody spoke.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-122-e9b5350bd9981b75": {
    "text": "沒有人說話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-123-b90e76c3b042ad06": {
    "text": "The silver watch gently floated back into Ethan’s hand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-123-0796e0bb00196142": {
    "text": "銀色懷錶慢慢飄回伊森手中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-124-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-124-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-125-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-125-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-126-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-126-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-127-03323b4a73224a75": {
    "text": "The Headmaster walked slowly toward him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-127-7afeeb15f0b5e967": {
    "text": "校長慢慢走向他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-128-04a3bee5faa7e71b": {
    "text": "The entire hall watched nervously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-128-042fbcc25d1e9f1c": {
    "text": "整個大廳都在看。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-129-be72e130add792ee": {
    "text": "Ethan swallowed hard.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-129-d7b281d380dbeed2": {
    "text": "伊森吞口水。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-130-e0c64a043d94df58": {
    "text": "“Uh…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-130-fbb6209db68ca194": {
    "text": "「呃……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-131-f9a34aeaae3da2e5": {
    "text": "The Headmaster stopped directly in front of him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-131-6afe15f3caefbcf2": {
    "text": "校長停在他面前。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-132-bcd28417030ab963": {
    "text": "His golden eyes studied Ethan carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-132-65a6f3bbeda3945f": {
    "text": "金色眼睛仔細觀察他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-133-6cbc7b7443828f28": {
    "text": "Then he quietly asked:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-133-70f4891c54028e11": {
    "text": "然後低聲問：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-134-f0687cee9e002cef": {
    "text": "“…Where did you get that watch?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-134-a124525ee55b4fa0": {
    "text": "「……你從哪裡得到那只懷錶？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-135-da7228daa29adc5a": {
    "text": "Ethan hesitated.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-135-0166dd5d51fa91d3": {
    "text": "伊森猶豫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-136-08120edcd47a9cd4": {
    "text": "“It belonged to my father.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-136-fbd191f08804f85f": {
    "text": "「那是我父親的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-137-29a373d62a575203": {
    "text": "The Headmaster became still.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-137-cea8f2aeb430daf3": {
    "text": "校長瞬間沉默。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-138-830509790796258d": {
    "text": "Very still.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-138-3c2170014f6dccab": {
    "text": "非常安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-139-8f1c42e24668545d": {
    "text": "Around the hall, teachers exchanged nervous looks.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-139-b519279dc8a87058": {
    "text": "老師們彼此交換緊張眼神。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-140-c1f373c9176f0261": {
    "text": "Adrian looked pale.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-140-dfe483825176a806": {
    "text": "亞德里安臉色蒼白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-141-8b096f13c5b4e7a9": {
    "text": "Lucy whispered quietly,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-141-1dbabc472dbdd497": {
    "text": "露西低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-142-4031d809ff34263f": {
    "text": "“I knew something was strange about you…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-142-d4a8bbe3925397eb": {
    "text": "「我就知道你不普通……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-143-72048e16df1422c0": {
    "text": "The Headmaster finally spoke again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-143-a719e29c70238d03": {
    "text": "校長終於再次開口。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-144-711876997fccf7cd": {
    "text": "“Daniel Parker…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-144-d808d0dde6677ba1": {
    "text": "「丹尼爾・帕克……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-145-d51f651ad2dba819": {
    "text": "The name echoed softly through the hall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-145-3cb5b3c8f42eb873": {
    "text": "名字在大廳裡輕輕回響。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-146-b46f3b11b3524591": {
    "text": "“You truly are his son.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-146-f1eb16ac15253a5a": {
    "text": "「你果然是他的兒子。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-147-65cd40160f4f98a3": {
    "text": "Ethan’s chest tightened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-147-9e332bdf8f52e275": {
    "text": "伊森胸口一緊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-148-dccf9dff39437895": {
    "text": "“You knew my father?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-148-64b0332668522c7e": {
    "text": "「你認識我爸爸？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-149-ffb48324f71d1ff1": {
    "text": "The Headmaster looked at the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-149-0bfe9d47813bfa44": {
    "text": "校長看向懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-150-943564c858a90617": {
    "text": "Then at the broken dark mark on the ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-150-379989070e0bd67a": {
    "text": "再看向天花板破碎黑印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-151-11d9cbde74c4e226": {
    "text": "His expression darkened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-151-32e1af31b3e7b7e3": {
    "text": "表情變得沉重。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-152-605c32e719b72803": {
    "text": "“Yes.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-152-24d8447e95122842": {
    "text": "「認識。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-153-03554dae202af308": {
    "text": "“And if the Mark of Noctis has returned…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-153-84c49857b83bd086": {
    "text": "「而如果諾克提斯印記再次出現……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-154-27a22ad84d452142": {
    "text": "“That means the war may not be over.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-154-092effedce7c5891": {
    "text": "「那代表戰爭可能還沒結束。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-155-81362fed37498c6d": {
    "text": "The hall became silent again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-155-8c83431b1b3bbcb1": {
    "text": "大廳再次安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-156-a8dc198ee0de4d58": {
    "text": "Nobody understood completely.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-156-589c11c63dcd8391": {
    "text": "沒有人完全理解。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-157-8074a17b3426700c": {
    "text": "But everyone felt the same thing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-157-05386b3ae8092f4b": {
    "text": "但所有人都有同樣感覺。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-158-3de40135feb83a9d": {
    "text": "Fear.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-158-c78104b0afc488de": {
    "text": "恐懼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-159-21731b597d673777": {
    "text": "Real fear.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-159-c34b512d5e612e31": {
    "text": "真正的恐懼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-160-8db69337363a07bf": {
    "text": "The Headmaster turned toward the students.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-160-07957f62dad86bfe": {
    "text": "校長轉向學生。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-161-b23e2086ffd25051": {
    "text": "“The Sorting Ceremony is postponed.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-161-359b50a9e1c70d48": {
    "text": "「分院儀式延期。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-162-406b8913235c1396": {
    "text": "Murmurs spread immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-162-5d6be1e5206dd885": {
    "text": "學生立刻開始騷動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-163-f8051782fd23bb22": {
    "text": "Teachers quickly guided frightened students away.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-163-aa97539187185f7c": {
    "text": "老師快速帶走害怕的學生。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-164-bb86459e291fce5e": {
    "text": "But before Ethan left—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-164-280223c86074259b": {
    "text": "但在伊森離開前——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-165-904c5aba1eebdc75": {
    "text": "The Headmaster spoke one final sentence.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-165-dd2a0a2fbbfc77a6": {
    "text": "校長說了最後一句話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-166-022077cfd8fbd7b7": {
    "text": "Quietly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-166-26ccbf39ce3401ca": {
    "text": "低聲地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-167-096340dc83f98641": {
    "text": "Only to him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-167-48180e86589d7b65": {
    "text": "只有伊森聽見。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-168-3dad7bd33bf663bb": {
    "text": "“The tower has awakened.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-168-02342de088fc50b1": {
    "text": "「高塔已經甦醒。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c6-en-block-169-9db23ef0f8aec233": {
    "text": "“And it awakened for you.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c6-zh-block-169-0b1b6a7c65c94f1b": {
    "text": "「而它，是為你甦醒的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-title-760822b8208743b4": {
    "text": "The Tower That Watches",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-title-ee25a8f3ab0a9745": {
    "text": "注視著的高塔",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-0-c25ccf95e45deb85": {
    "text": "After the attack in the Great Hall, nothing felt normal anymore.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-0-dd790557f5cf4fa8": {
    "text": "大廳遭到襲擊後，一切都不再正常。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-1-d25952900a923eb2": {
    "text": "Students whispered everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-1-64228d824d362e0c": {
    "text": "學生到處都在低聲討論。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-2-c04284d54a158496": {
    "text": "The Mark of Noctis became the only thing people talked about.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-2-f460711b6fe22586": {
    "text": "「諾克提斯印記」成了全校唯一話題。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-3-4f0d60b5e71cd017": {
    "text": "Some students looked frightened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-3-531c6ebb3b81ccd6": {
    "text": "有些學生很害怕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-4-3a32d6c2df567acd": {
    "text": "Others looked excited.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-4-05485df13722e771": {
    "text": "有些卻很興奮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-5-487dd03e33893fae": {
    "text": "And every time Ethan walked past—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-5-1a612a1c40b55453": {
    "text": "而每當伊森經過——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-6-5ae1eeec9c48af5b": {
    "text": "People stared at him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-6-7a225b320bfd62d2": {
    "text": "大家都會盯著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-7-5b3eb79cf8c5a927": {
    "text": "“That’s him…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-7-425a4826db46065c": {
    "text": "「就是他……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-8-b8ea76c15a87028a": {
    "text": "“The boy with the silver watch…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-8-be2a30f8486cf518": {
    "text": "「那個銀色懷錶男孩……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-9-d676391371b79bab": {
    "text": "“Did you see the light?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-9-00a526ce2b167b59": {
    "text": "「你有看到那道光嗎？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-10-d456c6b374a56ffc": {
    "text": "Ethan pulled his hood lower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-10-892f472876ce1f1b": {
    "text": "伊森把帽子拉低。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-11-0b5fb432d39bd605": {
    "text": "“I already hate this school,” he muttered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-11-98a945b52f8cd7f0": {
    "text": "「我已經開始討厭這學校了，」他低聲抱怨。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-12-99b59863fa6a53dc": {
    "text": "Lucy walked beside him carrying another pile of books.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-12-2e3d195956db5a4a": {
    "text": "露西抱著另一大堆書走在旁邊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-13-c30950dc50afaff0": {
    "text": "“You don’t hate the school.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-13-22f7d346a516ab98": {
    "text": "「你不是討厭學校。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-14-5903bd1d135efffe": {
    "text": "“You hate attention.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-14-c9d18e50e49af958": {
    "text": "「你是討厭被注意。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-15-17a9d1a99aa6973c": {
    "text": "“That too.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-15-589d20d908e2692e": {
    "text": "「這倒是真的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-16-e572b71d6d2f1cdd": {
    "text": "Adrian walked ahead silently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-16-933d2f16945521e7": {
    "text": "亞德里安沉默走在前面。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-17-07c919c6fb2b454e": {
    "text": "He had barely spoken since the attack.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-17-9f2237192181c1ca": {
    "text": "從襲擊事件後，他幾乎沒再說話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-18-f477d72f3b27f6fe": {
    "text": "The three of them climbed a long staircase inside the west tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-18-e3e52ee3b4c9077e": {
    "text": "三人沿著西塔長樓梯往上走。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-19-2ab02b476ec7e169": {
    "text": "The stairs moved unexpectedly every few minutes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-19-39deb04ffb65ad65": {
    "text": "樓梯每隔幾分鐘就會自己移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-20-61e639338730a0dd": {
    "text": "Ethan nearly fell twice.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-20-07069cab74d6fe07": {
    "text": "伊森差點摔倒兩次。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-21-11692d91a65ec993": {
    "text": "“WHY are the stairs alive?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-21-b2ca1a39fb868021": {
    "text": "「為什麼樓梯是活的？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-22-367142891e766b9d": {
    "text": "Lucy laughed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-22-b54442166d3d5fe7": {
    "text": "露西大笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-23-3f3b4752bc41053e": {
    "text": "“They’re enchanted.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-23-3f266c5aff182920": {
    "text": "「因為它們被施法了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-24-a6ad6f1af9b04a51": {
    "text": "“They’re evil.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-24-4a191a43b83212d6": {
    "text": "「它們根本邪惡。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-25-4463d22701cffffc": {
    "text": "Finally, they reached a large wooden door.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-25-9fe36faed058fef0": {
    "text": "終於，他們來到一扇巨大木門前。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-26-a28cfe74b43cd8e3": {
    "text": "Silver numbers floated above it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-26-168d459a56283c96": {
    "text": "銀色數字漂浮在空中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-27-c76f520c202a99dc": {
    "text": "Tower Dormitory — Room 18",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-27-f5d87c338d7b868a": {
    "text": "西塔宿舍——18號房",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-28-85fa78ccb2df4712": {
    "text": "Lucy pushed the door open.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-28-2597b87090ea52a5": {
    "text": "露西推開門。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-29-29e1dde1abe7beaa": {
    "text": "The room inside was enormous.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-29-da47e91a104b379a": {
    "text": "裡面非常巨大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-30-bdc5dffc1b539f73": {
    "text": "Four beds stood near the walls.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-30-aa81047c14028de5": {
    "text": "四張床靠牆擺放。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-31-a7309d350ad80f6e": {
    "text": "Tall windows overlooked the mountains.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-31-e502c52a5e38e00c": {
    "text": "高大窗戶能看到山脈。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-32-b274e1c89a17a2d8": {
    "text": "Bookshelves stretched to the ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-32-830ca9929f8322a2": {
    "text": "書櫃一路高到天花板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-33-a93b136015817b70": {
    "text": "And above everything—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-33-985c846d25d9c85f": {
    "text": "而最顯眼的是——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-34-4189397886ffada7": {
    "text": "A giant clock covered the center wall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-34-a1757cc753bba39f": {
    "text": "牆中央有一座巨大時鐘。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-35-5c80eaeb9de734f5": {
    "text": "Its silver hands moved slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-35-82a54d272a811298": {
    "text": "銀色指針慢慢移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-36-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-36-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-37-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-37-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-38-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-38-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-39-f3bcd6b4ef249b09": {
    "text": "Ethan stared at it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-39-8f5f1e6e18220e79": {
    "text": "伊森盯著它。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-40-dc7b0e9abe0bb9be": {
    "text": "“Every room has one?” he asked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-40-84223b7e98020010": {
    "text": "「每個房間都有？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-41-1481633d8775fbc5": {
    "text": "Lucy nodded.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-41-339fd531da0886fc": {
    "text": "露西點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-42-71f0bad849245bbc": {
    "text": "“The tower clocks are connected.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-42-aa240d3bf4bc60b9": {
    "text": "「塔內時鐘彼此相連。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-43-97a7fe4f00daeee9": {
    "text": "“Connected to what?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-43-322444b9e1c0d0eb": {
    "text": "「連到什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-44-c6eac1103330d22c": {
    "text": "Lucy hesitated slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-44-bf60cc2d13f76ce2": {
    "text": "露西猶豫了一下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-45-f2b9cb3a37da573c": {
    "text": "“…Nobody really knows.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-45-28a2838506c1b414": {
    "text": "「……其實沒人真的知道。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-46-a900fb4522c8d5ca": {
    "text": "Adrian finally spoke quietly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-46-3f27ef0fa82a0e15": {
    "text": "亞德里安終於低聲開口。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-47-356793af90b0f5f8": {
    "text": "“They say the clocks listen.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-47-a367371e48ce894a": {
    "text": "「有人說，時鐘會傾聽。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-48-a6c74e62fb913a01": {
    "text": "Ethan looked at him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-48-13a2f989c873556f": {
    "text": "伊森看著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-49-525a23beaf0c4704": {
    "text": "“Listen to WHAT?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-49-d80e07455d136584": {
    "text": "「傾聽什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-50-6a76762a7a92da71": {
    "text": "Adrian stared at the giant clock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-50-c8f7b987874054b7": {
    "text": "亞德里安盯著巨大時鐘。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-51-9c408fb7be002bdd": {
    "text": "“Everything.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-51-f76974e495d5b76c": {
    "text": "「一切。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-52-9910f8d3eaf13f07": {
    "text": "“That is somehow worse.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-52-0b46e0c784f3b28f": {
    "text": "「這聽起來更可怕了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-53-aa3ad7e91cb70eb9": {
    "text": "Lucy dropped her books onto a table.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-53-88818cf0c8f31761": {
    "text": "露西把書丟到桌上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-54-fcbf4ba1ed6f217c": {
    "text": "“Well, at least we survived our first night.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-54-a697ab1f883d061e": {
    "text": "「至少我們活過第一晚了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-55-d1662b50d1f70a33": {
    "text": "The moment she said that—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-55-23e920f660705cec": {
    "text": "就在她說完——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-56-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-56-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-57-4445dd7ace43924c": {
    "text": "The giant clock suddenly stopped moving.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-57-868eadc56bde967f": {
    "text": "巨大時鐘突然停止。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-58-eab99287f06f5584": {
    "text": "All three students froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-58-7e6c574e6fb4df26": {
    "text": "三人瞬間僵住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-59-967aced327f709d8": {
    "text": "The room became silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-59-f8ceca656483c978": {
    "text": "房間變得安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-60-b28ceae37edfdcd7": {
    "text": "Too silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-60-5eac561576466d01": {
    "text": "太安靜了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-61-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-61-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-62-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-62-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-63-01cb024830ecdeb6": {
    "text": "The clock moved backward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-63-a9b9110431041605": {
    "text": "時鐘開始倒轉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-64-0574d756ca0db154": {
    "text": "Once.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-64-5c9d1ecbc8afeb2b": {
    "text": "一下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-65-754a7f4abfcf2fb2": {
    "text": "Twice.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-65-e4514c6a97957c01": {
    "text": "兩下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-66-e09787e0de63815c": {
    "text": "Three times.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-66-d70a2119ea9d7045": {
    "text": "三下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-67-6ebfecd38c5769ec": {
    "text": "Ethan’s silver watch began glowing immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-67-dfaf27a19a821b0a": {
    "text": "伊森的銀色懷錶立刻發光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-68-9917ddaa75ce0eba": {
    "text": "TickTickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-68-59611e0f2c93d5d7": {
    "text": "滴答滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-69-7913e0539263bc1b": {
    "text": "The giant clock on the wall started ringing by itself.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-69-f039c93663abde96": {
    "text": "牆上巨大時鐘開始自己敲響。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-70-170ee7d507b174a3": {
    "text": "DONG.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-70-c3d49368221bbc81": {
    "text": "噹。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-71-170ee7d507b174a3": {
    "text": "DONG.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-71-c3d49368221bbc81": {
    "text": "噹。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-72-170ee7d507b174a3": {
    "text": "DONG.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-72-c3d49368221bbc81": {
    "text": "噹。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-73-fe297981ba585079": {
    "text": "Lucy stepped backward nervously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-73-cce708a9cea06118": {
    "text": "露西緊張後退。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-74-0b97a19453e2d59c": {
    "text": "“That’s not supposed to happen…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-74-db47f7f910fd55cf": {
    "text": "「這不應該發生……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-75-ee3c2e313c187725": {
    "text": "Cold air filled the dorm room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-75-40f72b641644e4f8": {
    "text": "冰冷空氣充滿宿舍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-76-5d78898fbe6f21c8": {
    "text": "The shadows near the walls began moving.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-76-27c4f753c421d1db": {
    "text": "牆邊陰影開始移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-77-c8d935215fee4681": {
    "text": "Not naturally.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-77-603aea5bada1da14": {
    "text": "不是自然移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-78-97e191ca84cf97c8": {
    "text": "Like something inside them was alive.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-78-a6c4debd94b599e4": {
    "text": "像裡面有東西活著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-79-4990f41b7c348704": {
    "text": "Adrian pulled out his wand instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-79-e9794442e1ba5fdb": {
    "text": "亞德里安立刻拔出魔杖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-80-363ff5be9bdf66c6": {
    "text": "“Get away from the walls.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-80-8210b276f899508c": {
    "text": "「離牆遠一點。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-81-ef48f4efa686c37d": {
    "text": "Ethan stared at the moving darkness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-81-1a91627b1cf03081": {
    "text": "伊森看著那些黑影。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-82-89c1b714d7441307": {
    "text": "“…Please tell me this is normal.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-82-4a4c1f1340f58439": {
    "text": "「……拜託跟我說這很正常。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-83-642d595d55d9932f": {
    "text": "“It absolutely is not.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-83-d1205f15370c6999": {
    "text": "「完全不正常。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-84-310021e1fb064806": {
    "text": "The shadows stretched slowly across the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-84-c7640931ff0c5355": {
    "text": "陰影慢慢延伸過地板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-85-df286663f0f97de9": {
    "text": "Toward Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-85-317168b50a5f6b7a": {
    "text": "朝伊森靠近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-86-e535c92361dae749": {
    "text": "The silver watch suddenly floated upward again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-86-679dd1444d86b5a5": {
    "text": "銀色懷錶再次漂浮起來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-87-06ef110f22a2b15d": {
    "text": "Bright silver light filled the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-87-0661610e0a1cef04": {
    "text": "銀光充滿整個房間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-88-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-88-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-89-bfebb9c3c115a5d4": {
    "text": "A hidden door appeared behind the giant clock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-89-943da7130286d013": {
    "text": "巨大時鐘後方出現一扇隱藏門。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-90-0d3c71e5c0c12ae8": {
    "text": "CREEEEAK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-90-90e7da1414347ade": {
    "text": "嘎————",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-91-c9df4d583090b773": {
    "text": "The clock slowly moved aside.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-91-b666f80d6ec2713a": {
    "text": "時鐘慢慢移開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-92-ea9c62ae8b6b9b10": {
    "text": "A dark staircase revealed itself behind it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-92-15c40ff4c581cf79": {
    "text": "後面露出黑暗樓梯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-93-cd4daa0d82968adb": {
    "text": "Nobody spoke.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-93-e9b5350bd9981b75": {
    "text": "沒有人說話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-94-ecddd2a8a2867552": {
    "text": "Lucy looked terrified.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-94-cd40bedf10568f51": {
    "text": "露西看起來非常害怕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-95-6c3765cc89be0afa": {
    "text": "“…That door wasn’t there before.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-95-393161f34a9e58cc": {
    "text": "「……那扇門之前根本不存在。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-96-e25ffc2946c3653c": {
    "text": "Adrian’s face turned pale.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-96-dfe483825176a806": {
    "text": "亞德里安臉色蒼白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-97-b814ef5311a4ecc4": {
    "text": "“I knew the rumors were real.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-97-769ec0396fe61988": {
    "text": "「原來傳聞是真的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-98-50bc3e313454794a": {
    "text": "Ethan looked between them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-98-099b8681db4e47af": {
    "text": "伊森看著他們。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-99-d24d2d7963e9f990": {
    "text": "“What rumors?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-99-874266e1b822eaac": {
    "text": "「什麼傳聞？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-100-c89b4c3c1f8bdf86": {
    "text": "Adrian pointed at the hidden staircase.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-100-8a67ea3b98d557af": {
    "text": "亞德里安指向樓梯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-101-2ddd955beda11bf6": {
    "text": "“The Forbidden Tower.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-101-4539f7b7b83523b4": {
    "text": "「禁忌高塔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-102-db19252e596e817a": {
    "text": "The air became colder immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-102-0f4767a7c31c8391": {
    "text": "空氣瞬間更冷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-103-fe3b2305bf71b74b": {
    "text": "Even Lucy looked uncomfortable hearing the name.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-103-336de5def31e73d4": {
    "text": "連露西聽到名字都不舒服。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-104-c8270c3e70686e1e": {
    "text": "Ethan frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-104-f09e32b4e8865c97": {
    "text": "伊森皺眉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-105-254633afc82d8fcc": {
    "text": "“You’re telling me there’s a secret tower INSIDE the tower?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-105-664283a427d30407": {
    "text": "「等等，你是說高塔裡面還有另一座秘密高塔？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-106-605c32e719b72803": {
    "text": "“Yes.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-106-4bd6f4312595e8e5": {
    "text": "「對。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-107-8ef54214385ddd21": {
    "text": "“And nobody thought to mention this earlier?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-107-1f10ca5ebb13ac38": {
    "text": "「居然沒人早點說？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-108-39c6f7e58d06302e": {
    "text": "Lucy whispered,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-108-1dbabc472dbdd497": {
    "text": "露西低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-109-9c99d1c6c00f821c": {
    "text": "“Students aren’t allowed inside.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-109-290330669de4c8dc": {
    "text": "「學生不能進去。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-110-aa5c56f81c8fae9d": {
    "text": "“No student has entered it for years.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-110-72a891c32227c7d7": {
    "text": "「很多年沒人進去過了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-111-c2f006c3cff820ff": {
    "text": "Ethan looked at the dark staircase.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-111-03cb38001df902b9": {
    "text": "伊森看著黑暗樓梯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-112-ac8865e795374e75": {
    "text": "Silver light from his watch pointed directly toward it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-112-82acaaf34941c02d": {
    "text": "懷錶銀光正指向那裡。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-113-325e8e6f54f8722f": {
    "text": "Like it wanted him to go inside.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-113-41a12c990c54529a": {
    "text": "像在叫他進去。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-114-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-114-c417920b8c3d7259": {
    "text": "就在這時——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-115-05701e92871bc764": {
    "text": "A whisper echoed from below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-115-2ebe40f16219572a": {
    "text": "樓梯下方傳來低語。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-116-75333b50fb6a22bc": {
    "text": "“Ethan…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-116-f385b004225909eb": {
    "text": "「伊森……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-117-dd6230a233ad1c6a": {
    "text": "He froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-117-471b4ccfa208351c": {
    "text": "他瞬間僵住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-118-01cf12b053510688": {
    "text": "Lucy grabbed his sleeve tightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-118-b58718dab69e1289": {
    "text": "露西緊抓他的袖子。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-119-398014a3e282f6fb": {
    "text": "“Tell me you heard that.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-119-a9b61bcc25f6d427": {
    "text": "「拜託告訴我你也聽到了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-120-d251e48f920630af": {
    "text": "“I heard it.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-120-4dff24834438c6a9": {
    "text": "「我聽到了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-121-017c9347cd48a43f": {
    "text": "The whisper came again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-121-07e0398800f4cdbc": {
    "text": "低語再次傳來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-122-1cb999795f4784bc": {
    "text": "Softer this time.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-122-c60a68ba9796ac51": {
    "text": "這次更輕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-123-a52eec2f37be7a0d": {
    "text": "“Help… me…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-123-7702ce50476748be": {
    "text": "「……救我……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-124-0ca48570eb79a3e0": {
    "text": "The silver watch glowed brighter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-124-dac31407ebacb9aa": {
    "text": "銀色懷錶變得更亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-125-9a82cb0ed66d5189": {
    "text": "Adrian looked alarmed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-125-603a27714f84f063": {
    "text": "亞德里安神情驚恐。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-126-74343c4d3d47bd5e": {
    "text": "“The tower is calling you.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-126-4d052ba37225972a": {
    "text": "「高塔正在呼喚你。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-127-f8446554d6c6c1ba": {
    "text": "“That sentence should not sound as terrifying as it does.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-127-922c2622333e7477": {
    "text": "「這句話不該這麼恐怖。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-128-cabd54d67c17d6df": {
    "text": "The staircase below seemed endless.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-128-992b6e3174e02fae": {
    "text": "下方樓梯彷彿沒有盡頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-129-f0dde14fa2d55aba": {
    "text": "Dark.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-129-b57ef4fdb68f3866": {
    "text": "黑暗。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-130-09f0121e1f8693f8": {
    "text": "Silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-130-833204688b72a129": {
    "text": "安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-131-2678d6620d437a6e": {
    "text": "Watching them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-131-82ba5f50c2499712": {
    "text": "像正在看著他們。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-132-b20e808d1c41773a": {
    "text": "Then suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-132-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-133-a1eb7ecef895a06c": {
    "text": "The giant clock rang again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-133-20f59dcb4746b8db": {
    "text": "巨大時鐘再次敲響。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-134-f56db54e9137cbed": {
    "text": "DONGGGGG—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-134-e3a6a0b2696365cb": {
    "text": "噹————",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-135-a375a27f09205c8a": {
    "text": "The sound shook the room violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-135-aa2d19870de47706": {
    "text": "聲音震動整個房間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-136-3b85cf12a7324770": {
    "text": "Books fell from the shelves.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-136-fd7d753de943c487": {
    "text": "書從書架掉下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-137-65badf2139013704": {
    "text": "Windows rattled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-137-e658d1ed3a334f0e": {
    "text": "窗戶劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-138-5c5fb97dddcdf83f": {
    "text": "And from deep below the hidden staircase—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-138-e788b7652fd4a7dc": {
    "text": "而在隱藏樓梯深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-139-f071d35097bef81d": {
    "text": "A second sound answered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-139-a339ba477b62dac3": {
    "text": "另一個聲音回應了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-140-9713383f5a35799d": {
    "text": "A low metallic ticking.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-140-45629eb5719de14c": {
    "text": "低沉金屬滴答聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-141-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-141-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-142-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-142-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-143-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-143-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-144-6a580bad320f9f02": {
    "text": "But this ticking was different.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-144-54fb5fa7bb452d53": {
    "text": "但這次的滴答聲不一樣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-145-13fad12f8a79bb8f": {
    "text": "Slower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-145-c09b2b92390ac423": {
    "text": "更慢。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-146-5450be1742eae357": {
    "text": "Heavier.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-146-0dfee2b3f5c8d0bc": {
    "text": "更重。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-147-521bfe65d8a85095": {
    "text": "Almost alive.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-147-1335058701d36d54": {
    "text": "像活著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-148-65cd40160f4f98a3": {
    "text": "Ethan’s chest tightened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-148-dea7686edafeee90": {
    "text": "伊森胸口發緊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-149-c6e1d66b7fa5f7c3": {
    "text": "The silver watch in his hand began shaking.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-149-e7e80b6baf46a42c": {
    "text": "手中的銀色懷錶開始震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-150-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-150-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-151-6b38d54b99676815": {
    "text": "A single sentence appeared across its glowing surface.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-151-2fcee7afa8d32c7e": {
    "text": "表面浮現一句話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-152-dc8ddf306600205b": {
    "text": "WELCOME BACK, HEIR.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-152-f8e21a656d8e0b88": {
    "text": "「歡迎回來，繼承者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-153-4a724ebd93fafb83": {
    "text": "Ethan stared in horror.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-153-fa06043241c3a83c": {
    "text": "伊森驚恐看著它。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-154-f3c1683ae70bf4b2": {
    "text": "“…What does that mean?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-154-6d80ca9e96b58763": {
    "text": "「……這到底是什麼意思？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-155-4a926d974d53ed49": {
    "text": "Neither Lucy nor Adrian answered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-155-c63fa36e819fcde5": {
    "text": "露西與亞德里安都沒有回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-156-6a39506d51ac73fa": {
    "text": "Because both of them looked just as frightened as he felt.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-156-1cc614c791a759ad": {
    "text": "因為他們的表情，和伊森一樣害怕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-157-0d76170955dfc9d4": {
    "text": "And below them—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-157-e63c9911bb340896": {
    "text": "而在他們下方——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-158-369147914498f0dd": {
    "text": "Deep inside the Forbidden Tower—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-158-fc46fd011a39f84d": {
    "text": "禁忌高塔深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c7-en-block-159-9ab88d366673da43": {
    "text": "Something had awakened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c7-zh-block-159-5fed044fd918954d": {
    "text": "有某種東西，已經甦醒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-title-546019f207f7ba67": {
    "text": "The Keeper of the Forbidden Tower",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-title-fcb63c1866ce333c": {
    "text": "禁忌高塔的守護者",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-0-626e02867a5d9e0c": {
    "text": "Nobody moved.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-0-438942b9029c88f1": {
    "text": "沒有人移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-1-2e22aec559e9b366": {
    "text": "The hidden staircase remained open behind the giant clock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-1-6d163f32ea2794c1": {
    "text": "巨大時鐘後方的隱藏樓梯依然開著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-2-03a6b7176e02a24f": {
    "text": "Darkness waited below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-2-6c0c8bef235726d6": {
    "text": "黑暗在下方等待。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-3-726eae5ddb32c048": {
    "text": "The cold metallic ticking continued echoing upward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-3-f5d0cfd48846ae77": {
    "text": "低沉金屬滴答聲持續傳來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-4-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-4-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-5-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-5-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-6-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-6-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-7-d70c7d4159b6423c": {
    "text": "Ethan stared at the glowing message on the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-7-7c1728db9b13aee1": {
    "text": "伊森盯著懷錶上的發光文字。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-8-dc8ddf306600205b": {
    "text": "WELCOME BACK, HEIR.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-8-f8e21a656d8e0b88": {
    "text": "「歡迎回來，繼承者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-9-f79e1527859a28dd": {
    "text": "His hands trembled slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-9-c77c615b3629e9de": {
    "text": "他的手微微發抖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-10-16a4067733f2d68e": {
    "text": "“I seriously do not like that sentence,” he whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-10-ed240a9aebcc3487": {
    "text": "「我真的超討厭這句話，」他低聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-11-07138a8a32936037": {
    "text": "Lucy nodded immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-11-99a1b5930fd492f6": {
    "text": "露西立刻點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-12-4a72168f7125ebb6": {
    "text": "“Agreed.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-12-b07b93026ba1bf77": {
    "text": "「完全同意。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-13-e9dd85ae7cd7c867": {
    "text": "Adrian kept staring at the staircase.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-13-b6bfd10213fbfa89": {
    "text": "亞德里安依然盯著樓梯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-14-0e45b2107bf7ec42": {
    "text": "His wand remained raised.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-14-cc46f2127d0d9843": {
    "text": "魔杖沒有放下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-15-ea9c6954dac0a498": {
    "text": "“We should tell the Headmaster.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-15-6e4780e35f1168bd": {
    "text": "「我們應該去找校長。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-16-a32905b3c461a8e3": {
    "text": "Before anyone could move—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-16-218694856f51cf0b": {
    "text": "但就在這時——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-17-bf7103b5b114ba44": {
    "text": "The hidden staircase suddenly lit up.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-17-619a3e011a799686": {
    "text": "隱藏樓梯突然亮了起來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-18-33470fe357bb37e6": {
    "text": "One step at a time.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-18-999b866e4100b685": {
    "text": "一階又一階。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-19-0f1c65a7a995501d": {
    "text": "Silver flames appeared along the walls below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-19-9f809c00ac5b0d45": {
    "text": "銀色火焰沿著牆壁燃起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-20-2cb087fd2952da77": {
    "text": "Not warm flames.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-20-3983ec82774ee5cb": {
    "text": "不是溫暖的火。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-21-40fe87ced59584f7": {
    "text": "Cold silver fire.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-21-e930e54db6bf4a72": {
    "text": "而是冰冷銀火。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-22-84cc3fabe2dbc897": {
    "text": "The watch in Ethan’s hand glowed brighter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-22-4851d0a55024e59d": {
    "text": "伊森手中的懷錶變得更亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-23-a06cb69cee50fcd4": {
    "text": "Then the whisper returned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-23-13dae475400b9412": {
    "text": "接著低語再次傳來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-24-541dfc4c34caf7b7": {
    "text": "“Come…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-24-6406e04a0c5e630c": {
    "text": "「過來……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-25-be72e130add792ee": {
    "text": "Ethan swallowed hard.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-25-b47233f753c5037e": {
    "text": "伊森吞了吞口水。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-26-22b4ded9a1280bb2": {
    "text": "Lucy grabbed his sleeve tighter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-26-9a6ec3ad1629c4bc": {
    "text": "露西死死抓住他袖子。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-27-8412c352dfd5e867": {
    "text": "“Nope.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-27-be32935b9f6298a1": {
    "text": "「不要。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-28-91fcebaec773d5dd": {
    "text": "“Absolutely not.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-28-afd4f82f017b6e50": {
    "text": "「絕對不要。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-29-fcd1fe3680cefad4": {
    "text": "“We are NOT following creepy magical voices into death stairs.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-29-94ebadb86066ca6f": {
    "text": "「我們絕對不要跟著恐怖魔法聲音走進死亡樓梯。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-30-b0c0e5666be31602": {
    "text": "Adrian looked conflicted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-30-193bf20176b8eec0": {
    "text": "亞德里安表情很複雜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-31-e29610c766406ec1": {
    "text": "“She’s right.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-31-a6100be8332126bf": {
    "text": "「她說得對。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-32-473498521beb5faf": {
    "text": "“But…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-32-79a1c87996fc3cb8": {
    "text": "「但是……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-33-f3889afd609533fc": {
    "text": "His gray eyes moved toward Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-33-3b843f545eca109d": {
    "text": "他的灰眼睛看向伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-34-62dc765f45bd5609": {
    "text": "“The tower only opened for him.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-34-f260a0cdcfc0304d": {
    "text": "「高塔只為他打開。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-35-3281311c56a2d3bf": {
    "text": "The room became quiet again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-35-2df363c5043b6c2c": {
    "text": "房間再次安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-36-e28b2cdb193be750": {
    "text": "Ethan looked toward the staircase.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-36-4c39e0654ecbb91c": {
    "text": "伊森望向樓梯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-37-17f6a281a6584653": {
    "text": "Deep below, he could see something faint.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-37-ff8bb262582fd343": {
    "text": "深處隱約有某種光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-38-7ec671d31ea28c76": {
    "text": "A light.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-38-6282f16e262847e1": {
    "text": "一道光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-39-e2f7cecdc701805a": {
    "text": "Very far away.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-39-3ab7d3aa99630ca6": {
    "text": "非常遙遠。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-40-6559a07c0746b0b5": {
    "text": "And somehow—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-40-0bc313efac9837af": {
    "text": "而且不知為何——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-41-35accc61f4bf3c43": {
    "text": "He felt connected to it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-41-41c1e7d7f76cb227": {
    "text": "他感覺自己與那道光有連結。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-42-ef0328b150c9a9d3": {
    "text": "Like the tower recognized him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-42-aff3861c77fc0cf0": {
    "text": "像高塔認識他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-43-195f4f60c110a8ac": {
    "text": "Like it had been waiting.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-43-d71ab19e3bcf9544": {
    "text": "像它一直在等待。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-44-3536a81d0ac58fee": {
    "text": "“That’s impossible…” Ethan whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-44-c5a91edba6fd28ce": {
    "text": "「這不可能……」伊森低聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-45-3a5c3fa3e8a50653": {
    "text": "The silver watch ticked louder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-45-169f61066c5cb510": {
    "text": "銀色懷錶滴答聲變大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-46-24ac229c0a69a711": {
    "text": "TickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-46-9c4f4560ec4ef226": {
    "text": "滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-47-b20e808d1c41773a": {
    "text": "Then suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-47-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-48-9fae1abfaeece48d": {
    "text": "The hidden door slammed shut behind them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-48-a285450e7892b94b": {
    "text": "隱藏門在他們身後猛然關上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-49-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-49-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-50-30a447df1332d155": {
    "text": "All three jumped.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-50-0fed144f437e3bf8": {
    "text": "三人全都跳起來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-51-ce83cf5509dc25eb": {
    "text": "The giant clock began spinning wildly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-51-a63b239589a8f80d": {
    "text": "巨大時鐘開始瘋狂轉動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-52-e0c59ec9d24c597f": {
    "text": "Backward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-52-1d5be36feb97aacb": {
    "text": "倒轉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-53-06bfa7996471cbe4": {
    "text": "Faster and faster.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-53-5443029869094d19": {
    "text": "越來越快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-54-31b0b31ebb6fdd40": {
    "text": "The room shook violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-54-299a8f67ed92300a": {
    "text": "房間劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-55-6058a7f76f9e7044": {
    "text": "Books flew off shelves.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-55-f41807e208d2a9ea": {
    "text": "書本從書架飛出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-56-e3e592eb8c6d3cda": {
    "text": "The windows froze solid with ice.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-56-b7006896828a793f": {
    "text": "窗戶瞬間結冰。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-57-544b385786e5c03f": {
    "text": "Lucy shouted,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-57-a1a7cbaf98b330b6": {
    "text": "露西大喊：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-58-8cc156855b5303cb": {
    "text": "“THIS SCHOOL IS INSANE!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-58-b4efc828b6d1c226": {
    "text": "「這學校瘋了！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-59-98cb1b5fb91804b2": {
    "text": "A deep voice echoed through the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-59-9f7c381f8f05a28b": {
    "text": "一個低沉聲音在房內回盪。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-60-ee29288f54310704": {
    "text": "“THE HEIR RETURNS.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-60-ccab5607a00d0796": {
    "text": "「繼承者已歸來。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-61-d2548f16a4700433": {
    "text": "The voice was not human.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-61-e0f7894642a0507c": {
    "text": "那聲音不像人類。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-62-bfdf317e0c1f9dc5": {
    "text": "It sounded ancient.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-62-73fc22df6649d89d": {
    "text": "非常古老。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-63-85b3b1c7ab93bb4a": {
    "text": "Powerful.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-63-402045cbafdb3c68": {
    "text": "強大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-64-62215b2900ca39db": {
    "text": "Like stone grinding together.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-64-86d9a57971c93b71": {
    "text": "像岩石摩擦。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-65-50f9507441e425e8": {
    "text": "The giant clock split open again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-65-8ab07cf4b6cdb310": {
    "text": "巨大時鐘再次裂開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-66-7eea759636e22a90": {
    "text": "But this time—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-66-c8cf185086313483": {
    "text": "但這次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-67-45c8f04854613f50": {
    "text": "Something stepped out.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-67-12e0c8352f6edffe": {
    "text": "有東西走了出來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-68-234209e897b51d2a": {
    "text": "A tall figure wearing black armor covered in silver symbols.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-68-ce4cd0299dde0f66": {
    "text": "一個穿著刻滿銀色符號黑色盔甲的高大身影。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-69-9d505091add9cd3c": {
    "text": "Its face was hidden behind a cracked metal mask.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-69-e4f1fa985aad7597": {
    "text": "臉被破裂金屬面具覆蓋。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-70-bc19454c23c1dea1": {
    "text": "Blue fire burned inside the cracks.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-70-2294a4ea5f0bd2c2": {
    "text": "裂縫裡燃燒藍色火焰。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-71-a8d3b50b043db96c": {
    "text": "The figure carried a giant silver spear.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-71-a8933ae674040396": {
    "text": "它手裡拿著巨大銀槍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-72-641a78e1b01c7f32": {
    "text": "Ethan froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-72-8d885feee9177340": {
    "text": "伊森瞬間僵住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-73-5731738b279f8e6f": {
    "text": "“…What is THAT?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-73-4e41e8e040ff652a": {
    "text": "「……那是什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-74-127e6e7a0f51da6f": {
    "text": "Adrian looked horrified.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-74-f942676117239cc9": {
    "text": "亞德里安露出驚恐表情。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-75-fe85696fb2172f93": {
    "text": "“The Tower Keeper…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-75-dab33841ed2d1ffa": {
    "text": "「高塔守護者……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-76-39c6f7e58d06302e": {
    "text": "Lucy whispered,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-76-1dbabc472dbdd497": {
    "text": "露西低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-77-f0f7e72311c08809": {
    "text": "“I thought it was just a story…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-77-a1d009917447415e": {
    "text": "「我一直以為那只是故事……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-78-edc4b99c664c53de": {
    "text": "The armored figure slowly raised its spear.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-78-26668619ce55e853": {
    "text": "盔甲身影慢慢舉起長槍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-79-c271e129494378d0": {
    "text": "Blue flames spread across the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-79-770ef9546b314d63": {
    "text": "藍色火焰蔓延整個地板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-80-209a3b58c979d4e7": {
    "text": "The giant voice echoed again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-80-5a5c8bd87b9ef6c5": {
    "text": "巨大聲音再次響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-81-bbabd5d9db06619f": {
    "text": "“STATE YOUR NAME, HEIR.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-81-840295e50bc7b474": {
    "text": "「報上名字，繼承者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-82-d67f68b9bf254d13": {
    "text": "Ethan blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-82-134fbeb356ccc19c": {
    "text": "伊森愣住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-83-ec3bd63b167d8584": {
    "text": "“…It’s talking to me?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-83-6fca5e58806a6d6c": {
    "text": "「……它在跟我說話？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-84-340ce78647ca6346": {
    "text": "“ANSWER IT!” Adrian shouted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-84-60f7fee0fbac0b23": {
    "text": "「回答它！」亞德里安大喊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-85-fb7f3edc8f1c220c": {
    "text": "The Tower Keeper stepped forward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-85-6bf83960adb26aab": {
    "text": "高塔守護者往前一步。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-86-4c1bba50dfc4de1a": {
    "text": "The floor cracked beneath its feet.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-86-e99f85b1df82908b": {
    "text": "地板在它腳下裂開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-87-2dce0669b62b1d52": {
    "text": "Ethan quickly swallowed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-87-6200c8211b5477ba": {
    "text": "伊森立刻吞口水。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-88-a90328b45cf966ab": {
    "text": "“E-Ethan Parker!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-88-a6ed540994998ac5": {
    "text": "「伊……伊森・帕克！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-89-42caaf875bd101d6": {
    "text": "Silence.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-89-833204688b72a129": {
    "text": "安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-90-c01f4f53d1fc876d": {
    "text": "The blue flames flickered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-90-00124561b4359a77": {
    "text": "藍火微微晃動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-91-dbb46ec500caf11a": {
    "text": "The Tower Keeper tilted its head slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-91-8325c030abb67058": {
    "text": "高塔守護者慢慢歪頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-92-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-92-932da14da57c5006": {
    "text": "接著——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-93-4d3808eb61fdf78d": {
    "text": "It slammed the spear into the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-93-12a85ea8e177401c": {
    "text": "它將長槍猛插地面。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-94-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-94-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-95-bcbadf3d824bd047": {
    "text": "Silver light exploded outward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-95-1d1e7a81fa962e9d": {
    "text": "銀色光芒瞬間爆發。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-96-eefab7f9ff714137": {
    "text": "Ancient symbols appeared across the walls.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-96-2d012a36f62ac3cc": {
    "text": "古老符號浮現在牆壁上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-97-b8fb8979f93b9d3f": {
    "text": "The giant clock stopped spinning instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-97-528fa9ee1cec0deb": {
    "text": "巨大時鐘立刻停止旋轉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-98-94aaa3a23bfc046a": {
    "text": "The armored figure lowered its head slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-98-a274611b190c5bdd": {
    "text": "盔甲守護者微微低頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-99-37fb72b10705576e": {
    "text": "“BLOODLINE CONFIRMED.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-99-4e08a39bdfc689b0": {
    "text": "「血脈確認。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-100-7c28417bde6d4082": {
    "text": "Lucy stared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-100-e2cbfaae038999f9": {
    "text": "露西瞪大眼睛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-101-c519fbefa2ad0ea2": {
    "text": "“…What.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-101-1cb2a4046cc54217": {
    "text": "「……什麼。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-102-2892321e15b7d19b": {
    "text": "Ethan stared harder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-102-45991d89c0fa3cb9": {
    "text": "伊森更震驚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-103-1d000375563fafe7": {
    "text": "“…WHAT?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-103-7785ebcd3d91aa1e": {
    "text": "「……什麼？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-104-38165109d4a779c9": {
    "text": "The Tower Keeper slowly stepped aside.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-104-7089d8356af0cb11": {
    "text": "高塔守護者慢慢退開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-105-96acfd6a495f7ecf": {
    "text": "Behind it—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-105-edf62b2b138b0640": {
    "text": "在它身後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-106-0379c1269e29a476": {
    "text": "The staircase reopened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-106-8adbc63da281fdcb": {
    "text": "樓梯再次打開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-107-8bc1b8a8fdc77ae0": {
    "text": "But now the darkness below had changed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-107-1639afe601f4fda1": {
    "text": "但這次下方黑暗改變了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-108-3304d8b3fc97d751": {
    "text": "Silver lights glowed along the walls.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-108-b47dde4684dc01d7": {
    "text": "銀光沿著牆壁亮起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-109-aff9e2c7a4f03ea2": {
    "text": "The terrifying cold feeling was weaker.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-109-afde504358ecdc33": {
    "text": "那種恐怖寒意減弱許多。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-110-68bcf1ed1a5e991c": {
    "text": "The giant voice echoed one final sentence:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-110-e9c9baaa90fe30da": {
    "text": "巨大聲音最後說了一句話：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-111-0a600cb2af97eae8": {
    "text": "“THE TOWER AWAITS.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-111-7de6c354bea69cfb": {
    "text": "「高塔正在等待。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-112-f7cf88e120a7e671": {
    "text": "Then silence returned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-112-15249c5b0657e18e": {
    "text": "然後安靜恢復。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-113-387438eada9ea86f": {
    "text": "The blue flames disappeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-113-4d6b0d81da3e86f6": {
    "text": "藍色火焰消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-114-a660066212d7a5a2": {
    "text": "The Tower Keeper stood motionless beside the staircase.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-114-da35a8d4260cb583": {
    "text": "高塔守護者站在樓梯旁一動也不動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-115-c16d5e590696241d": {
    "text": "Like a statue.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-115-217089c6d6e9c020": {
    "text": "像雕像一樣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-116-94d8f3f780588a3d": {
    "text": "Lucy looked ready to faint.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-116-68086219c3be7f5e": {
    "text": "露西看起來快昏倒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-117-ca560eaf6ab7a6ba": {
    "text": "Adrian slowly lowered his wand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-117-e70ed4ee846678ef": {
    "text": "亞德里安慢慢放下魔杖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-118-01164e8b17a315b3": {
    "text": "“I cannot believe this is happening.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-118-0c71727f5362c12d": {
    "text": "「我不敢相信這是真的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-119-b16002a5ada9a743": {
    "text": "Ethan pointed at the armored guardian.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-119-02a4bb9eebdb429f": {
    "text": "伊森指著那名盔甲守護者。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-120-30073cc45bef02a6": {
    "text": "“Could someone PLEASE explain why murder knight knows my name?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-120-fdf8c2f3bd7b1ede": {
    "text": "「有人可以解釋一下為什麼殺人騎士知道我的名字嗎？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-121-826df6ee9b2653b6": {
    "text": "Lucy shook her head rapidly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-121-12a10d8c873cf5e6": {
    "text": "露西拼命搖頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-122-4fe3d9211cdb152b": {
    "text": "“Nope. I’m done. I want to go home.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-122-63d85f391fff7ee6": {
    "text": "「不行，我不玩了，我想回家。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-123-290c5c264fb1f418": {
    "text": "Adrian looked at Ethan seriously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-123-32e385134bfe907c": {
    "text": "亞德里安嚴肅地看著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-124-919f8050c85b4c0e": {
    "text": "“The Tower Keeper only appears for descendants of the First Keepers.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-124-d1efe96de793c965": {
    "text": "「只有初代守護者的後代，才能喚醒高塔守護者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-125-c8270c3e70686e1e": {
    "text": "Ethan frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-125-f09e32b4e8865c97": {
    "text": "伊森皺眉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-126-31d29cc7308ac00d": {
    "text": "“The First Keepers?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-126-5d6cb827d8078587": {
    "text": "「初代守護者？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-127-020a6313c97ee388": {
    "text": "Adrian nodded slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-127-4ba5945d6c687ee7": {
    "text": "亞德里安慢慢點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-128-d8c23fed40b9f1e7": {
    "text": "“They founded Clock Tower School hundreds of years ago.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-128-cf8b9bb7b0e75553": {
    "text": "「幾百年前創立時鐘塔學院的人。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-129-62a45a8f89f26975": {
    "text": "Lucy looked confused.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-129-f25f269484b19307": {
    "text": "露西一臉混亂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-130-d9d8613bfa56f308": {
    "text": "“But all their bloodlines disappeared during the Shadow War…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-130-5e96d6dbab6ca6b2": {
    "text": "「但那些血脈在暗影戰爭後早就消失了……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-131-1fa58551e9ad194d": {
    "text": "The room became quiet.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-131-4191760794c19a96": {
    "text": "房間安靜下來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-132-8c86022375e9fd98": {
    "text": "All three slowly looked at Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-132-6b9196d36d7d1c21": {
    "text": "三人慢慢一起看向伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-133-d67f68b9bf254d13": {
    "text": "Ethan blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-133-3b39acb18939e7cb": {
    "text": "伊森眨眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-134-37b2072cdc390f4d": {
    "text": "“…Why are you both looking at me like that?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-134-fda87c001fd19993": {
    "text": "「……你們為什麼這樣看我？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-135-b800ee55f7749c2b": {
    "text": "Nobody answered immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-135-5363b359450a6e07": {
    "text": "沒有人立刻回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-136-8eda9c6dbd965beb": {
    "text": "Because they were all thinking the same thing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-136-9c0f69e3d5839eef": {
    "text": "因為他們都在想同一件事。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-137-296b597f75bceb41": {
    "text": "If Ethan truly belonged to the First Keeper bloodline—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-137-1d747e2c95711b4f": {
    "text": "如果伊森真的是初代守護者後代——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-138-2e1ee84b2f8eb638": {
    "text": "Then his arrival at the school was not an accident.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-138-5e057c687af1f112": {
    "text": "那他來到這學校，就不是巧合。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-139-e7ad5bb14ed7232a": {
    "text": "And somewhere deep inside the Forbidden Tower—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-139-0c79e734bb8406a6": {
    "text": "而在禁忌高塔深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-140-a4a0ed39d75dd833": {
    "text": "Something had been waiting specifically for him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-140-cc305dcc145a0676": {
    "text": "有某種東西，一直在等他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-141-b0ea4deed778d7ef": {
    "text": "The silver watch ticked softly once more.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-141-aac7bd7fbeb25280": {
    "text": "銀色懷錶再次輕輕滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-142-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-142-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-143-0e4f07660a2cdcff": {
    "text": "Then a new message appeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-143-df1f28c6b5fdaaaf": {
    "text": "接著新的文字浮現。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-144-9d157ce29ee73289": {
    "text": "COME BELOW.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-144-4ace13ab3ab56148": {
    "text": "「下來。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c8-en-block-145-b97b4fcb770de2b4": {
    "text": "ALONE.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c8-zh-block-145-ab67ca8839771566": {
    "text": "「獨自一人。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-title-e8407e75236db94c": {
    "text": "The Hidden Library Beneath the Tower",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-title-d2760aa76142520e": {
    "text": "高塔下的隱藏圖書館",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-0-5eb72bf331b6ca4f": {
    "text": "The room stayed silent after the message appeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-0-9f8bd97f91bce73d": {
    "text": "訊息出現後，房間陷入安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-1-10c00970d7dc395f": {
    "text": "COME BELOW.\nALONE.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-1-ff386f5730ebe807": {
    "text": "「下來。」\n「獨自一人。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-2-e118658e5455848a": {
    "text": "The glowing words slowly faded from the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-2-28c0558a182402b8": {
    "text": "懷錶上的發光文字慢慢消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-3-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-3-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-4-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-4-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-5-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-5-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-6-4d4c3f721beafe3a": {
    "text": "Lucy crossed her arms immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-6-4f2f57c5f38bc789": {
    "text": "露西立刻抱起手。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-7-637352124e69d434": {
    "text": "“No.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-7-fbb8ef22f1209e9f": {
    "text": "「不行。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-8-d67f68b9bf254d13": {
    "text": "Ethan blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-8-134fbeb356ccc19c": {
    "text": "伊森愣住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-9-0e7068d504a287ff": {
    "text": "“…No?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-9-218d55764614dbac": {
    "text": "「……不行？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-10-f1b33fdf45e1c7b7": {
    "text": "“No,” Lucy repeated firmly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-10-3ad868d234069e8e": {
    "text": "「不行，」露西堅定重複。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-11-2f3ac2883ab678e8": {
    "text": "“You are absolutely NOT walking alone into the forbidden nightmare tower.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-11-118be5ee743df15f": {
    "text": "「你絕對不能一個人走進那個恐怖禁忌死亡高塔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-12-8e085297533b0363": {
    "text": "Adrian nodded once.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-12-b628c434d467bb66": {
    "text": "亞德里安點了一下頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-13-aa48572fb5bcaddb": {
    "text": "“For once, I agree with her.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-13-ac72b1787e6f8ef2": {
    "text": "「難得我同意她。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-14-94945c86431653f2": {
    "text": "Ethan looked toward the hidden staircase again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-14-84b8b28d33daa033": {
    "text": "伊森再次望向樓梯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-15-1d3a368aa4f7cdef": {
    "text": "Silver light still glowed faintly below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-15-32c95bf358a53d43": {
    "text": "下方依然散發微弱銀光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-16-0ac5904aaf2ee82d": {
    "text": "The Tower Keeper remained perfectly still beside it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-16-447a22806e671704": {
    "text": "高塔守護者依然站在旁邊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-17-885c75a98ac77b41": {
    "text": "Watching.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-17-5706de263b5e0517": {
    "text": "注視著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-18-2a84a09c8d4b28a7": {
    "text": "Waiting.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-18-ef6a58a01293e1ab": {
    "text": "等待著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-19-fbd2c06fd6bd2877": {
    "text": "Ethan took a slow breath.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-19-f8b469877ed56672": {
    "text": "伊森深吸一口氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-20-98d9b2f6d2f83437": {
    "text": "“But what if the tower has answers?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-20-5c70c2f743aed168": {
    "text": "「但如果高塔裡有答案呢？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-21-fb52b93e56731779": {
    "text": "Lucy pointed dramatically at the terrifying staircase.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-21-ce2fdaeae55199ec": {
    "text": "露西誇張地指向樓梯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-22-805d7beca9733991": {
    "text": "“And what if the answers kill you?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-22-ad76e629f43bf730": {
    "text": "「那如果答案會殺了你呢？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-23-f37c79c0d70c9993": {
    "text": "“That is also possible,” Adrian admitted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-23-97ae5ee7919f8cdd": {
    "text": "「這也有可能，」亞德里安平靜補充。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-24-22a41078c0d19d14": {
    "text": "“Very comforting. Thank you.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-24-5ba56b7aa7084af8": {
    "text": "「真令人安心，謝謝。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-25-d55ef0f9075859af": {
    "text": "The silver watch suddenly became warm again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-25-71c71590978cdcd7": {
    "text": "銀色懷錶再次變暖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-26-63458a8591b869bd": {
    "text": "A soft light pointed downward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-26-b891faabed18cb1f": {
    "text": "柔和光芒指向下方。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-27-2cffdb5315152110": {
    "text": "Almost impatiently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-27-04fc39931322fceb": {
    "text": "像在催促他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-28-c8270c3e70686e1e": {
    "text": "Ethan frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-28-f09e32b4e8865c97": {
    "text": "伊森皺眉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-29-6572dabf9875e5c3": {
    "text": "“It really wants me to go.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-29-0808344ff6782fc5": {
    "text": "「它真的很想要我下去。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-30-9f3aa038d7b3e548": {
    "text": "Lucy looked nervous.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-30-15fd5f8bbaf240f4": {
    "text": "露西一臉不安。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-31-5798a45cf7dc7933": {
    "text": "“That sentence sounds worse every time you say it.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-31-8eab8be756fc6a31": {
    "text": "「這句話你每講一次就變得更恐怖。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-32-fdc026c1d5dcb4c9": {
    "text": "Adrian stepped closer to the staircase carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-32-4a46be671bd3a4c3": {
    "text": "亞德里安小心靠近樓梯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-33-68d2bea60fcb2d78": {
    "text": "The Tower Keeper immediately lowered its spear slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-33-a4b829f0a98784e5": {
    "text": "高塔守護者立刻放低長槍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-34-c81782e73d72a8e8": {
    "text": "Blocking the path.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-34-85c3da88c1e349fc": {
    "text": "擋住去路。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-35-fbe8920cbed44b8b": {
    "text": "Adrian stopped instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-35-e7ec4d0d4208c2c1": {
    "text": "亞德里安瞬間停下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-36-55aafc89499d8dfe": {
    "text": "“…Interesting.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-36-3ae71cffb4522e3e": {
    "text": "「……有意思。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-37-5442659457095c55": {
    "text": "“What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-37-9f4e54458fbc357b": {
    "text": "「什麼意思？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-38-2d0ec59dc919d0f7": {
    "text": "“It will only allow YOU to enter.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-38-af45bf35ee41df56": {
    "text": "「它只允許你進去。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-39-902f7a78ff034c0a": {
    "text": "Lucy groaned loudly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-39-ff4647a478ce73aa": {
    "text": "露西痛苦哀號。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-40-e2caf63846653209": {
    "text": "“Of course it will.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-40-7920c38d4685fd06": {
    "text": "「我就知道。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-41-8690e67ad5527c6f": {
    "text": "Ethan stared into the staircase darkness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-41-5df6e6c2d4199771": {
    "text": "伊森看著樓梯深處。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-42-72ded712d1cebd38": {
    "text": "Part of him wanted to run away.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-42-a8852d1c87526cc4": {
    "text": "有一部分的他想逃走。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-43-0050ba6fab38f195": {
    "text": "Far away.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-43-07d66ef418d0474b": {
    "text": "逃得遠遠的。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-44-e21402c5f3ec294e": {
    "text": "Back home.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-44-ec3b9b8bb1d6611a": {
    "text": "回家。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-45-4eff177e7d2e5096": {
    "text": "Back to normal life.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-45-33542c8777a0d856": {
    "text": "回到正常生活。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-46-f55d78e70fc659ac": {
    "text": "But another part—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-46-38833ccdd3110f79": {
    "text": "但另一部分——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-47-d5461b77d32404c7": {
    "text": "A stronger part—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-47-805362a2b36d87a2": {
    "text": "更強烈的部分——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-48-4deb661e7b5dac65": {
    "text": "Needed to know the truth.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-48-dc90fbaac7ee5d18": {
    "text": "想知道真相。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-49-61768c78d7fc9d4d": {
    "text": "About the tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-49-6d807802b4c35ec1": {
    "text": "關於高塔。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-50-64c77cff18457cde": {
    "text": "About the watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-50-b915d15f99de0b2e": {
    "text": "關於懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-51-f83762d36ce69f76": {
    "text": "About his father.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-51-0482372fc03cb95a": {
    "text": "還有他的父親。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-52-d8c0e1ac736ee151": {
    "text": "Ethan tightened his grip on the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-52-0f87d218ed1937cb": {
    "text": "伊森握緊懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-53-149d66277471d826": {
    "text": "Then he looked at his friends.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-53-7d2f02e68576625e": {
    "text": "然後看向朋友們。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-54-718fd393e2336e4e": {
    "text": "“I’ll go.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-54-41227916ae50e766": {
    "text": "「我要下去。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-55-0fe66dfc75d3970b": {
    "text": "Lucy pointed at him in disbelief.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-55-5b0c0090ee19e0ef": {
    "text": "露西震驚指著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-56-e3cd691b50b7c6b0": {
    "text": "“You have known magic for TWO DAYS.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-56-980f1cabf47bb685": {
    "text": "「你接觸魔法才兩天！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-57-f2dff4dd44f96bab": {
    "text": "“And now you want to explore haunted death stairs alone?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-57-522d6698b3cd5cf0": {
    "text": "「現在居然想一個人探索恐怖死亡樓梯？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-58-67c142bf09da8ad7": {
    "text": "“…When you say it like that, it sounds bad.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-58-6c8773d6b1f67ad3": {
    "text": "「……妳這樣講真的變很糟。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-59-b223f841d1c2e378": {
    "text": "“Because IT IS BAD!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-59-752791b51e8fc1a7": {
    "text": "「因為本來就很糟！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-60-fa5399f9d3799938": {
    "text": "Adrian looked serious.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-60-770dc9d921e83634": {
    "text": "亞德里安神情認真。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-61-648bd7a6c9d3bddc": {
    "text": "“If you go below…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-61-d870dfcd0c3a5d82": {
    "text": "「如果你下去……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-62-973c55b6e1df9ee3": {
    "text": "“Be careful what you trust.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-62-e1d058b437c928c1": {
    "text": "「小心你相信的東西。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-63-f006dd50c0378c06": {
    "text": "Ethan sighed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-63-49d5f001789677da": {
    "text": "伊森嘆氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-64-8e55b0dc72c2ec04": {
    "text": "“Why does everyone in this school talk like cursed fortune cookies?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-64-e524441796edb49f": {
    "text": "「為什麼這學校每個人講話都像被詛咒的幸運餅乾？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-65-1cdee9ed0535cbc0": {
    "text": "For the first time that night—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-65-50a091856f8b29d3": {
    "text": "那晚第一次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-66-c6e0db4c8ec59b9c": {
    "text": "Adrian almost smiled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-66-aae5235cf034d178": {
    "text": "亞德里安差點笑出來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-67-b1fd0cb60d69798b": {
    "text": "Almost.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-67-340feedae62f40d0": {
    "text": "差一點。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-68-0ab26137eba8cace": {
    "text": "Ethan walked toward the hidden staircase slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-68-1f3e30488cc83754": {
    "text": "伊森慢慢走向樓梯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-69-5e3a293b87c5d133": {
    "text": "The Tower Keeper stepped aside immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-69-2ff583dfc3e32c2d": {
    "text": "高塔守護者立刻退開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-70-42c42999c8674b0d": {
    "text": "Blue fire flickered across its armor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-70-ecafd9ae625f0c59": {
    "text": "藍色火焰在盔甲上閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-71-aa0ed361704acb7d": {
    "text": "The silver watch glowed brighter with every step Ethan took.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-71-aa4ff752d176886b": {
    "text": "伊森每往下一步，懷錶就更亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-72-932609f00df21720": {
    "text": "Behind him, Lucy whispered nervously:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-72-d4d0b176f853cd7b": {
    "text": "身後露西緊張低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-73-f645960d0dad7904": {
    "text": "“If he dies, I’m blaming you.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-73-ab0c6ebc706119f0": {
    "text": "「如果他死掉，我一定怪你。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-74-2be420b45661a503": {
    "text": "“I’m aware,” Adrian replied calmly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-74-5999b67993b6be46": {
    "text": "「我知道，」亞德里安平靜回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-75-f6ad3a1eff4100ef": {
    "text": "Ethan stepped onto the staircase.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-75-056390a1117ad417": {
    "text": "伊森踏上樓梯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-76-b9ff0d829489ec0a": {
    "text": "The moment he did—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-76-cf172d82c06f42a5": {
    "text": "下一秒——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-77-64ed790561d8109e": {
    "text": "The hidden doorway closed behind him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-77-8d1cf5eed8c3283c": {
    "text": "隱藏門在後方關閉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-78-02aec70c71035070": {
    "text": "BOOM.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-78-8d21a7fa73765405": {
    "text": "轟。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-79-2aa5dff79bb62d5a": {
    "text": "Darkness swallowed the sound of his friends instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-79-73c041e2d500e4db": {
    "text": "朋友們的聲音瞬間消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-80-a7e92e721c7ae33a": {
    "text": "Now he was alone.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-80-1c263afea482a37e": {
    "text": "現在只剩他一人。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-81-5f0ff5ca63604071": {
    "text": "Only silver flames lit the path downward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-81-ce18bec2e6b0806b": {
    "text": "只有銀色火焰照亮下方。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-82-fe3291ae61a7cc5b": {
    "text": "Step after step.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-82-f3b1312b7f42c475": {
    "text": "一步又一步。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-83-bfd7d41d8d43b26b": {
    "text": "The staircase spiraled deep beneath the school.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-83-636051003b409be9": {
    "text": "樓梯一路往學校地下深處延伸。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-84-f810dd0238e5cd82": {
    "text": "The air became colder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-84-80313a595880f1e4": {
    "text": "空氣越來越冷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-85-39e97175605037dd": {
    "text": "Older.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-85-aee528b2586c2e2f": {
    "text": "越來越古老。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-86-e551a369c488fc2b": {
    "text": "The walls were covered with ancient symbols.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-86-dc8c832474309310": {
    "text": "牆壁刻滿古老符號。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-87-4d14b2458bf8671b": {
    "text": "Some moved slowly when Ethan looked away.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-87-caaab03c5dc622d5": {
    "text": "有些符號在伊森轉頭時還會動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-88-3792769ea0963ef3": {
    "text": "“…Nope,” Ethan whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-88-772c14c575e778ac": {
    "text": "「……不行。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-89-11f4645038adcb11": {
    "text": "“I officially hate this place.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-89-3527b61ba82fa34b": {
    "text": "「我正式討厭這地方了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-90-3a5c3fa3e8a50653": {
    "text": "The silver watch ticked louder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-90-60ef49a56619490e": {
    "text": "銀色懷錶滴答更響。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-91-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-91-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-92-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-92-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-93-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-93-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-94-b20e808d1c41773a": {
    "text": "Then suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-94-4f96ee8acafc5094": {
    "text": "然後突然——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-95-394807c0eea95f40": {
    "text": "The staircase ended.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-95-222d9012593e48b4": {
    "text": "樓梯到底了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-96-6843124a399b3f76": {
    "text": "Ethan stopped.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-96-37467680d9630f77": {
    "text": "伊森停住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-97-d6220024ee1c9f1e": {
    "text": "His eyes widened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-97-2fbfd40fa3c545b3": {
    "text": "他睜大眼睛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-98-1feb63fc719a3d32": {
    "text": "A massive underground library stretched before him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-98-b0029ed6a92aa0d4": {
    "text": "一座巨大地下圖書館出現在眼前。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-99-553f5319a216949e": {
    "text": "Thousands upon thousands of books filled enormous shelves.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-99-0525f3deb79af2eb": {
    "text": "成千上萬本書填滿巨大書架。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-100-f48e55958227c0cb": {
    "text": "Floating lanterns drifted through the darkness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-100-d0eef765ae699cf1": {
    "text": "漂浮燈籠在黑暗中移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-101-4cf9e03f318263bc": {
    "text": "Silver chains hung from the ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-101-b568ba9ad31df476": {
    "text": "銀色鎖鏈垂掛天花板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-102-9fe5241150531ae0": {
    "text": "Ancient clocks covered the walls.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-102-50af3466769c61a2": {
    "text": "古老時鐘覆蓋牆壁。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-103-c076d7e1636a3100": {
    "text": "Every clock showed a different time.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-103-94ed195d6487202b": {
    "text": "每個時鐘時間都不同。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-104-3d888ef372aca4e8": {
    "text": "Ticking echoed everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-104-f8826a4054df8071": {
    "text": "滴答聲回盪整個空間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-105-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-105-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-106-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-106-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-107-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-107-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-108-e6abe43703423b78": {
    "text": "At the center of the library stood a giant tree made entirely of silver light.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-108-71b9b4e538ded5e5": {
    "text": "在圖書館中央，有一棵完全由銀光組成的巨大樹。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-109-25a7349b425e0416": {
    "text": "Its glowing branches reached toward the ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-109-9073e581f127605f": {
    "text": "發光樹枝伸向天花板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-110-fd102010f2760d44": {
    "text": "Books floated around it slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-110-305a9de4b9653e6c": {
    "text": "書本慢慢漂浮在周圍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-111-78235e9a81fdb980": {
    "text": "Ethan whispered,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-111-53cd7e9af115d060": {
    "text": "伊森低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-112-3d80e425d6771a41": {
    "text": "“…What IS this place?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-112-ed30ae6b97f3105b": {
    "text": "「……這到底是什麼地方？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-113-a33079f30e856111": {
    "text": "A voice answered from the darkness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-113-661035f38b0a95be": {
    "text": "黑暗中傳來聲音。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-114-1dd84492be4dd25d": {
    "text": "“The Memory Library.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-114-a3312e2c0c478cbe": {
    "text": "「記憶圖書館。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-115-a35513db1d7ba06f": {
    "text": "Ethan spun around instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-115-e6918030403b25d0": {
    "text": "伊森瞬間轉身。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-116-11c7e357ad3d887f": {
    "text": "A figure stepped forward between the shelves.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-116-9572e52acc56b53b": {
    "text": "一個身影從書架間走出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-117-d0a5dd4bc140fbff": {
    "text": "An old woman wearing long gray robes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-117-0d88562b36bad9f3": {
    "text": "一位穿灰袍的老女人。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-118-09948214552cd61d": {
    "text": "Silver symbols glowed across her sleeves.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-118-b131b9a42679854c": {
    "text": "袖子上發光銀色符號。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-119-55d664bf0d35de82": {
    "text": "One of her eyes was mechanical.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-119-379c01fca3dec006": {
    "text": "其中一隻眼睛是機械義眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-120-912ff72fc180ad64": {
    "text": "Clockwork gears moved inside it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-120-e9a5edf408d4cac3": {
    "text": "裡面齒輪正在轉動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-121-f2d872f6d62253cb": {
    "text": "The woman studied Ethan carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-121-d03d77d2ec9d92c3": {
    "text": "女人仔細觀察伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-122-912e83d9f171700e": {
    "text": "Then she looked at the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-122-c7eb0b9deefc5b0d": {
    "text": "然後看向銀色懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-123-2dcb7afe7f307e84": {
    "text": "“…So the tower chose you after all.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-123-c8a16c422198c0fd": {
    "text": "「……所以高塔最後還是選擇了你。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-124-ec94e380e633ea73": {
    "text": "Ethan stepped backward carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-124-fb649207eb753bcf": {
    "text": "伊森慢慢後退。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-125-bcf32ec20e16b4d0": {
    "text": "“Who are you?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-125-2063fa927b584d5e": {
    "text": "「妳是誰？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-126-2bfe01243a1b277d": {
    "text": "The old woman bowed slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-126-8f31e1198f06b2f7": {
    "text": "老女人微微行禮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-127-ea2b562f0c1a0bc3": {
    "text": "“My name is Seraphine.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-127-f5f099b18314bea8": {
    "text": "「我叫瑟拉芬。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-128-bda1d253a52bfc37": {
    "text": "“I am the Keeper of Memories.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-128-82087112e38bc880": {
    "text": "「我是記憶守護者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-129-d67f68b9bf254d13": {
    "text": "Ethan blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-129-3b39acb18939e7cb": {
    "text": "伊森眨眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-130-3426be83a79da3f2": {
    "text": "“…That sounds extremely important.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-130-1fc43f3d4f3f2a0c": {
    "text": "「……這聽起來超級重要。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-131-c9632f12759f3baf": {
    "text": "“It is.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-131-b0cb9a166a98b1d4": {
    "text": "「確實如此。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-132-dccf8f3ae4a54bc8": {
    "text": "The giant silver tree glowed brighter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-132-847121c03ed96519": {
    "text": "巨大銀樹變得更亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-133-8b73e3c9cb51816c": {
    "text": "Seraphine walked toward it slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-133-cafdb07770857467": {
    "text": "瑟拉芬慢慢走向它。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-134-cf4040092cc00291": {
    "text": "“For hundreds of years, this library has protected the truth of the First Keepers.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-134-74a02552b8cf3370": {
    "text": "「數百年來，這座圖書館一直守護初代守護者的真相。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-135-f7b2f6fcfb75b0e1": {
    "text": "Ethan followed carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-135-bf51677d9be4d850": {
    "text": "伊森小心跟上。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-136-c8bd3d2ba6ae2c83": {
    "text": "“And the tower brought me here because…?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-136-3c74f51bcfb8692a": {
    "text": "「那高塔帶我來這裡是因為……？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-137-1b0a023a00616cf6": {
    "text": "Seraphine stopped beside the glowing tree.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-137-74d80bde50774e7b": {
    "text": "瑟拉芬停在銀樹旁。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-138-09050d8da282ca1b": {
    "text": "Then she turned toward Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-138-1ab885e5760faf7e": {
    "text": "轉頭看向伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-139-0163b561200bdf05": {
    "text": "“Because your father once stood exactly where you stand now.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-139-31b5856d32ff6af7": {
    "text": "「因為你的父親曾經站在和你一樣的位置。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-140-641a78e1b01c7f32": {
    "text": "Ethan froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-140-8d885feee9177340": {
    "text": "伊森瞬間僵住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-141-728f482601d17876": {
    "text": "The library suddenly felt much colder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-141-7702650fb763b631": {
    "text": "圖書館突然變得更冷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-142-dccf9dff39437895": {
    "text": "“You knew my father?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-142-ec9b65b246783c34": {
    "text": "「妳認識我父親？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-143-90bd5a758b77484c": {
    "text": "Seraphine nodded slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-143-b94dc6268193f3c9": {
    "text": "瑟拉芬慢慢點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-144-605c32e719b72803": {
    "text": "“Yes.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-144-24d8447e95122842": {
    "text": "「認識。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-145-60cca0263186f8cd": {
    "text": "“And if the tower has awakened for you…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-145-5234aa8d28d193a8": {
    "text": "「而如果高塔為你甦醒……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-146-5317f35819e66631": {
    "text": "Her mechanical eye glowed faintly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-146-8aa8002989dd896f": {
    "text": "她的機械眼微微發光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-147-36eaae6b48b14e03": {
    "text": "“…Then the darkness sealed beneath the school may also be awakening.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-147-723579a89a355cfe": {
    "text": "「……那被封印在學校底下的黑暗，可能也正在甦醒。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-148-13073d7acb062ba3": {
    "text": "Ethan’s stomach tightened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-148-c38e22fdcc899797": {
    "text": "伊森胃部發緊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-149-7b2ff691ad36d0f9": {
    "text": "“…What darkness?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-149-ec14e3b0c25be480": {
    "text": "「……什麼黑暗？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-150-7886cc3211cc6837": {
    "text": "The giant silver tree suddenly shook violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-150-5a859ca35021cb78": {
    "text": "巨大銀樹突然劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-151-036140789aed19b3": {
    "text": "Books began flying through the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-151-a73f3271b2a79929": {
    "text": "書本開始四處飛舞。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-152-adf0f7e0550c6f85": {
    "text": "The clocks around the library started spinning backward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-152-82d5413b886efee3": {
    "text": "所有時鐘開始倒轉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-153-af17e4ba64ce4fd2": {
    "text": "FAST.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-153-5f4f9bf455776c23": {
    "text": "超快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-154-f7215333185486cd": {
    "text": "TickTickTickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-154-59611e0f2c93d5d7": {
    "text": "滴答滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-155-7d352ae3fdd1d3c7": {
    "text": "Seraphine’s expression changed immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-155-ebd702645a8409f8": {
    "text": "瑟拉芬表情瞬間改變。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-156-7c387c5f8e40517f": {
    "text": "“No…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-156-92141de36152d128": {
    "text": "「不……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-157-ddc474c7b616472a": {
    "text": "The silver watch in Ethan’s hand flashed bright light.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-157-ffc60da50e3770fd": {
    "text": "伊森手中的懷錶爆發強光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-158-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-158-cf172d82c06f42a5": {
    "text": "下一秒——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-159-5f506b726f290ab8": {
    "text": "A giant crack appeared across the library floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-159-a4920523d2ec331d": {
    "text": "圖書館地板出現巨大裂縫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-160-da38b85709af5649": {
    "text": "Dark smoke rose from below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-160-ae7c8cc27d5d31aa": {
    "text": "黑煙從下方湧出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-161-6aa4e0549270ce9c": {
    "text": "Purple light glowed deep inside the darkness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-161-a849ddf59f7e6197": {
    "text": "紫色光芒在深處閃耀。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-162-2665ad4e707d9ceb": {
    "text": "And from somewhere far beneath the tower—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-162-10982fa9673ba0b1": {
    "text": "而在高塔最深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c9-en-block-163-fae55a03fa8bc4ca": {
    "text": "Something laughed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c9-zh-block-163-ee1b6ef9cf631c9f": {
    "text": "某種東西笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-title-6c1f1b278fe6ee0b": {
    "text": "The Shadow Beneath the School",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-title-1000e2150e30ecff": {
    "text": "學院底下的黑影",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-0-735a29cf97c007fb": {
    "text": "The giant crack across the library floor continued spreading.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-0-c36aff461eed8f0d": {
    "text": "圖書館地板上的巨大裂縫持續擴大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-1-70a49705c0343802": {
    "text": "CRACK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-1-c7df42e6c845feb3": {
    "text": "喀啦。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-2-70a49705c0343802": {
    "text": "CRACK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-2-c7df42e6c845feb3": {
    "text": "喀啦。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-3-70a49705c0343802": {
    "text": "CRACK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-3-c7df42e6c845feb3": {
    "text": "喀啦。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-4-13251cd25c111010": {
    "text": "Dark smoke poured upward like black fire.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-4-d2bc680b5fccb15e": {
    "text": "黑煙像黑色火焰般往上衝。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-5-9f6851085ca59632": {
    "text": "Books flew wildly through the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-5-c8faa49cc4191ef4": {
    "text": "書本瘋狂飛舞。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-6-4b83b2c752606dc7": {
    "text": "The ancient clocks spun backward faster and faster.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-6-4d405887a08dc172": {
    "text": "古老時鐘倒轉得越來越快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-7-f7215333185486cd": {
    "text": "TickTickTickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-7-59611e0f2c93d5d7": {
    "text": "滴答滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-8-71c3490c2e694144": {
    "text": "Ethan stumbled backward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-8-1b25cfbbcb0a469d": {
    "text": "伊森往後跌退。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-9-ca4d039c246400a9": {
    "text": "“What is happening?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-9-f1a0084ff6f40881": {
    "text": "「到底發生什麼事？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-10-038f31ca18b0e94a": {
    "text": "Seraphine raised her hand immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-10-55a6f5ea490f3cca": {
    "text": "瑟拉芬立刻抬手。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-11-78caeb9380823a24": {
    "text": "Silver chains shot across the library walls.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-11-d79af9700e88e796": {
    "text": "銀色鎖鏈從圖書館牆壁射出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-12-f9f3f2d0891bfd70": {
    "text": "CLANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-12-690a1a50186dfe69": {
    "text": "鏘！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-13-f9f3f2d0891bfd70": {
    "text": "CLANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-13-690a1a50186dfe69": {
    "text": "鏘！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-14-f9f3f2d0891bfd70": {
    "text": "CLANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-14-690a1a50186dfe69": {
    "text": "鏘！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-15-b91c8891b11f1fe1": {
    "text": "Ancient symbols lit up everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-15-597542ca17fa9160": {
    "text": "古老符號全部亮起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-16-38dbdaa2a492ba98": {
    "text": "“The seal is weakening,” Seraphine said urgently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-16-5db77cc555630bee": {
    "text": "「封印正在變弱，」瑟拉芬急促說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-17-30064a3b49f380e5": {
    "text": "Ethan stared at the growing darkness below the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-17-bc32f79ee256a24a": {
    "text": "伊森看著下方不斷擴大的黑暗。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-18-624cb3830d4c541d": {
    "text": "“The seal on WHAT?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-18-e8c32012e2aa1e5f": {
    "text": "「到底封印了什麼？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-19-ae5be6d371f08d23": {
    "text": "The mechanical eye inside Seraphine’s face glowed bright blue.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-19-20fede097f9d130a": {
    "text": "瑟拉芬的機械眼發出藍光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-20-dd625938de1a2c36": {
    "text": "Then she answered quietly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-20-b943dcc268e2d330": {
    "text": "然後低聲回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-21-ec87b17da111bedd": {
    "text": "“…The Shadow King.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-21-2babb7e487af3337": {
    "text": "「……暗影之王。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-22-a0929b8605cf5cfc": {
    "text": "The library became silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-22-4fb3eed21cf1cc07": {
    "text": "圖書館瞬間安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-23-6d3accc086b95283": {
    "text": "Even the clocks seemed slower for one second.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-23-022e5e0a1dd57491": {
    "text": "連時鐘聲都像停了一秒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-24-d67f68b9bf254d13": {
    "text": "Ethan blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-24-3b39acb18939e7cb": {
    "text": "伊森眨眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-25-86c437f833da6c6a": {
    "text": "“…That sounds bad.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-25-7cc71d4b5750e461": {
    "text": "「……這聽起來很糟。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-26-72e85bfd0635e268": {
    "text": "“It is VERY bad.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-26-c60162730c47c7f1": {
    "text": "「是非常糟。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-27-40e23612b157f307": {
    "text": "The crack exploded wider.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-27-4f27309ee5173489": {
    "text": "裂縫突然爆開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-28-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-28-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-29-2b088e6fdf1e4d48": {
    "text": "A wave of freezing darkness burst upward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-29-7cd1685299318573": {
    "text": "冰冷黑暗猛然衝出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-30-03492af77bc70f70": {
    "text": "Ethan nearly fell.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-30-fd11cccf00708236": {
    "text": "伊森差點摔倒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-31-cc9c6c320f658781": {
    "text": "The silver watch glowed so brightly it hurt his eyes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-31-c1cdca1618fd324d": {
    "text": "銀色懷錶亮得刺眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-32-2a2b11b854c57313": {
    "text": "Deep below the crack—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-32-7a38f87b179b3ce8": {
    "text": "裂縫深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-33-b9d26bd003807d80": {
    "text": "Purple light pulsed slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-33-f130d9ecafde6f04": {
    "text": "紫色光慢慢跳動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-34-de3df42663b31bb9": {
    "text": "Like a heartbeat.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-34-ba4a9c05dd0388b3": {
    "text": "像心跳。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-35-1c4e39e57ac0332e": {
    "text": "Thump.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-35-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-36-1c4e39e57ac0332e": {
    "text": "Thump.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-36-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-37-1c4e39e57ac0332e": {
    "text": "Thump.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-37-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-38-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-38-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-39-e85de87e04dc8f0a": {
    "text": "A voice rose from the darkness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-39-e2d53d801338ac4a": {
    "text": "一個聲音從黑暗中升起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-40-b47c80c12cde794d": {
    "text": "Ancient.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-40-2ef91fda3b675f30": {
    "text": "古老。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-41-619765983384617d": {
    "text": "Cold.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-41-1251cb85b19ff195": {
    "text": "冰冷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-42-5c0c2bc92329d890": {
    "text": "Hungry.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-42-a7db08bff178a66c": {
    "text": "飢餓。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-43-cdd6b4b3ae8a9734": {
    "text": "“THE HEIR RETURNS…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-43-8a66a0360a7c51c7": {
    "text": "「繼承者回來了……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-44-3ab913d3f7c5f6dc": {
    "text": "Ethan froze instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-44-8d885feee9177340": {
    "text": "伊森瞬間僵住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-45-1fcd22ab137eb967": {
    "text": "The voice echoed inside his head.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-45-d69208690122427e": {
    "text": "那聲音直接在他腦中回響。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-46-33c05fa71bffae38": {
    "text": "Seraphine looked alarmed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-46-48b78a035dd749f9": {
    "text": "瑟拉芬神情緊張。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-47-ab514386dc3b81ae": {
    "text": "“It can sense your bloodline already.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-47-7e0970fcd63f4637": {
    "text": "「它已經感應到你的血脈。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-48-3956afbdac9c5d7b": {
    "text": "Ethan pointed at himself.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-48-76869ab41bef4b4f": {
    "text": "伊森指著自己。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-49-d095709fea2a142e": {
    "text": "“Why does every terrifying thing in this school know who I am?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-49-fd8a262b71f35473": {
    "text": "「為什麼這學校所有恐怖東西都認識我？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-50-a4fdeedeeb3f8b36": {
    "text": "The darkness below laughed softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-50-c8e7f4c7730878f0": {
    "text": "黑暗低聲笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-51-afdb06a7916b537d": {
    "text": "“DANIEL’S SON…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-51-b81777f5b5590c9c": {
    "text": "「丹尼爾的兒子……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-52-cc85fab9273b55b9": {
    "text": "Ethan’s chest tightened painfully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-52-e157eef5f983f3cc": {
    "text": "伊森胸口猛然一緊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-53-dccf9dff39437895": {
    "text": "“You knew my father?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-53-0f0f50d857f3d784": {
    "text": "「你認識我父親？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-54-13ffc1861a657123": {
    "text": "The voice answered immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-54-9d34e9c507c6bfdc": {
    "text": "那聲音立刻回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-55-ce903eff864fe5e2": {
    "text": "“HE SEALED ME AWAY…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-55-13ab0b78c3c93fd1": {
    "text": "「是他把我封印起來……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-56-e2961464cc4ce5ef": {
    "text": "Purple light exploded upward from the crack.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-56-c4204099790aa12d": {
    "text": "紫色光芒從裂縫爆發。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-57-f9443ce33890fcb7": {
    "text": "The silver tree shook violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-57-f4fc9cd38dae369b": {
    "text": "巨大銀樹劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-58-1cb58b3659a2b7e6": {
    "text": "Books crashed across the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-58-e1d0a385a864749e": {
    "text": "書本撞滿地面。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-59-0fe08509116b29cc": {
    "text": "Seraphine shouted,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-59-0ba435bdc72dc2bc": {
    "text": "瑟拉芬大喊：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-60-c31f5388496c2e40": {
    "text": "“Ethan! Stay back!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-60-76d7acd5aaabdaf8": {
    "text": "「伊森！後退！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-61-b880641c8a773461": {
    "text": "A giant shadow hand burst from the darkness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-61-0152ebf861729a14": {
    "text": "一隻巨大黑影手掌從裂縫衝出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-62-1df34721166e2eac": {
    "text": "Its claws scraped against the library floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-62-6bf11366a093232b": {
    "text": "利爪刮過圖書館地板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-63-9267db9508d3b969": {
    "text": "The entire room shook.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-63-89046feadba04021": {
    "text": "整個房間震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-64-4a724ebd93fafb83": {
    "text": "Ethan stared in horror.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-64-bee71ad967b8d4e5": {
    "text": "伊森驚恐看著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-65-bfc35a0d758823df": {
    "text": "“That thing is HUGE!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-65-e2082f2938316b26": {
    "text": "「那東西也太大了！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-66-8b1f6e641410cb3b": {
    "text": "The Shadow King laughed again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-66-6b5e71f245776027": {
    "text": "暗影之王再次大笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-67-1899cb75fa208f80": {
    "text": "“YOU CARRY THE KEY…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-67-613f0c00a008b141": {
    "text": "「你帶著鑰匙……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-68-c6616a50af4c9e20": {
    "text": "The silver watch became burning hot.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-68-cf8484008f56be9a": {
    "text": "銀色懷錶變得滾燙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-69-5c1bc1bc6b9c07b5": {
    "text": "Ethan nearly dropped it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-69-8c756ac801248182": {
    "text": "伊森差點丟掉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-70-5a6523aca2a6451f": {
    "text": "“What key?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-70-09601deb88955f5f": {
    "text": "「什麼鑰匙？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-71-8ececb3ed891c471": {
    "text": "Seraphine looked horrified.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-71-7c46c4c5986830b4": {
    "text": "瑟拉芬露出驚恐表情。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-72-ead0aec0fc7662ab": {
    "text": "“The watch…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-72-8d12c30c959ebd10": {
    "text": "「那只懷錶……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-73-acf70b7338a2e166": {
    "text": "Ethan turned toward her.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-73-04f9ebda9f650aeb": {
    "text": "伊森立刻轉頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-74-520301ddf6389fc7": {
    "text": "“What about it?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-74-d09681dc0aa759bc": {
    "text": "「懷錶怎麼了？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-75-36644fc80db4ff6e": {
    "text": "But before she could answer—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-75-66be07b0e61145fb": {
    "text": "但還來不及回答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-76-9ea9665f5db42984": {
    "text": "The shadow hand lunged toward Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-76-31de3cedc95f9d9a": {
    "text": "黑影巨手猛衝向伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-77-af17e4ba64ce4fd2": {
    "text": "FAST.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-77-76e2eaae764d4e9b": {
    "text": "太快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-78-a66a490fe87be3ac": {
    "text": "Too fast.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-78-b775a7920b9c62cd": {
    "text": "太快了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-79-9b4d4394ad3a1461": {
    "text": "Ethan raised the silver watch instinctively.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-79-46f469ab1b62a2a9": {
    "text": "伊森本能舉起懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-80-59f782dcf5d5f0d0": {
    "text": "The watch opened automatically.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-80-a5cd5b578fb0f6ee": {
    "text": "懷錶自動打開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-81-0dd175ab100e45c3": {
    "text": "CLICK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-81-019792da7b48e033": {
    "text": "喀嚓。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-82-0586c6247315355d": {
    "text": "Silver light exploded across the library.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-82-d3d9e7008ea64ebf": {
    "text": "銀光瞬間覆蓋圖書館。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-83-2f538a8dfca19929": {
    "text": "The shadow hand screamed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-83-11ee67d8206edc76": {
    "text": "黑影巨手慘叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-84-dff07e9d28542d9c": {
    "text": "Dark smoke burned away instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-84-cadb5ddaacb992ac": {
    "text": "黑煙瞬間被燒毀。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-85-8daa0809b2c9925d": {
    "text": "The entire library shook violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-85-d3f1ac00725e11e9": {
    "text": "整個圖書館劇烈搖晃。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-86-dfe6ab4dfddf66f9": {
    "text": "The giant silver tree glowed brighter than ever before.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-86-60d63c8553529dde": {
    "text": "巨大銀樹亮到極限。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-87-7d13de9b3b708d56": {
    "text": "And suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-87-932da14da57c5006": {
    "text": "接著——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-88-b3ae2739377d6ad2": {
    "text": "Images appeared inside the light.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-88-1b75cb9c0954efc4": {
    "text": "光裡出現畫面。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-89-c6224024f90be8e6": {
    "text": "A memory.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-89-c7ff3f13a0325738": {
    "text": "一段記憶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-90-7c7619a366067c0b": {
    "text": "Ethan saw a younger version of the Headmaster.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-90-518d7ec4a9239b8c": {
    "text": "伊森看到年輕版校長。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-91-2cc0b4a86ee60a03": {
    "text": "A younger Seraphine.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-91-c766f6ff0a36ae01": {
    "text": "年輕版瑟拉芬。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-92-a9babc1349693e77": {
    "text": "And beside them—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-92-77d0b247e00fde2d": {
    "text": "還有——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-93-426805b6cdcf90d1": {
    "text": "A man with dark hair holding the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-93-14715d36a275f77a": {
    "text": "一個黑髮男人拿著銀色懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-94-be48b213d52246e7": {
    "text": "Daniel Parker.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-94-6eabf13e2158d54f": {
    "text": "丹尼爾・帕克。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-95-06311246378837ef": {
    "text": "Ethan’s father.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-95-bdbef52ecb36f189": {
    "text": "伊森的父親。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-96-e17abc11c0c42274": {
    "text": "The memory Daniel looked exhausted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-96-dcacc63651d71a8e": {
    "text": "記憶中的丹尼爾看起來非常疲憊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-97-a5c0311a9959cbb7": {
    "text": "Blood covered part of his robe.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-97-3986a410275ca4fb": {
    "text": "長袍上有血。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-98-6d831092c3befd6d": {
    "text": "Behind him—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-98-5d3bb46e20e9e90c": {
    "text": "而在他身後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-99-1dc4e9c24f68b05b": {
    "text": "An enormous wall of darkness roared beneath the school.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-99-306583c02fdc0ec4": {
    "text": "學校底下翻騰著巨大黑暗。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-100-189a211089bf4d29": {
    "text": "“You must seal the tower gates NOW!” Daniel shouted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-100-cf22cd2388b7b7ec": {
    "text": "「你們必須立刻封閉高塔之門！」丹尼爾大喊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-101-65843a38466d81e3": {
    "text": "The younger Headmaster looked furious.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-101-1f5ba1d7ba9e753b": {
    "text": "年輕校長憤怒說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-102-5c5ea8aec24edc5f": {
    "text": "“If we close the gates, you’ll be trapped below!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-102-e8eb4b06bf50a5f7": {
    "text": "「如果關閉，你會被困在下面！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-103-fc6654f01bdd5dd0": {
    "text": "Daniel gripped the silver watch tightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-103-d464258b595c0682": {
    "text": "丹尼爾緊握懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-104-b14590e3e9891e13": {
    "text": "“If the Shadow King escapes…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-104-93c3ea4a26b906cc": {
    "text": "「如果暗影之王逃出去……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-105-05dcff02f544f298": {
    "text": "“The entire Keeper world falls.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-105-cc8bf316120a5dfd": {
    "text": "「整個守護者世界都會毀滅。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-106-8a50afc596fb890d": {
    "text": "Young Seraphine stepped forward desperately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-106-f01cc9cf7bca4b96": {
    "text": "年輕瑟拉芬焦急向前。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-107-afe42a2b2759af4a": {
    "text": "“There has to be another way!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-107-5175aeaf91dc4033": {
    "text": "「一定還有別的方法！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-108-3a3ac6ecc44b6e03": {
    "text": "Daniel shook his head slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-108-94ff50165466e14b": {
    "text": "丹尼爾慢慢搖頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-109-5c72a8203249bf8a": {
    "text": "“There isn’t.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-109-77d049477ad80a31": {
    "text": "「沒有了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-110-48a40464d04b2ea2": {
    "text": "He looked toward the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-110-97114caa9d3dfdae": {
    "text": "他看向懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-111-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-111-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-112-92747e76eb685eb2": {
    "text": "Directly toward Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-112-85a5d804d420fbaf": {
    "text": "直接看向伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-113-800711f9b458e983": {
    "text": "Even though this was only a memory—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-113-55657688be328979": {
    "text": "明明只是記憶——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-114-048e62940f035150": {
    "text": "It felt like Daniel could actually see him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-114-2fced7af69da9102": {
    "text": "卻像真的看得到他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-115-35e5843ae763763f": {
    "text": "Ethan stopped breathing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-115-c89d582785954bc6": {
    "text": "伊森停止呼吸。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-116-19e2fb1094091bed": {
    "text": "Daniel spoke softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-116-b1edbbf1e2c671cd": {
    "text": "丹尼爾輕聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-117-a50f2170d9321ab2": {
    "text": "“If you’re seeing this…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-117-8a3c70fb411a107e": {
    "text": "「如果你看見這段記憶……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-118-3b055059e299a27b": {
    "text": "“…then I failed.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-118-8c2fa87def258662": {
    "text": "「……代表我失敗了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-119-468321642940492d": {
    "text": "The memory flickered violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-119-d9ca373e13b971e4": {
    "text": "記憶開始劇烈閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-120-bafdfcbe2f0f244d": {
    "text": "Darkness crashed against the magical barrier behind Daniel.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-120-d7eb06c718136ea2": {
    "text": "後方黑暗瘋狂撞擊魔法屏障。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-121-ba0b5b14d652e8a8": {
    "text": "The entire underground chamber shook.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-121-f8533f856e8d25f8": {
    "text": "整個地下空間震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-122-d0c868cca0a9d1f2": {
    "text": "Daniel raised the silver watch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-122-a943671e92ede527": {
    "text": "丹尼爾舉起懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-123-b128e17479d40134": {
    "text": "“The tower will choose my heir.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-123-0cdb90c1b2683945": {
    "text": "「高塔會選擇我的繼承者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-124-6fb2436725ff7021": {
    "text": "“The watch will awaken when the seal weakens.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-124-9a567feec96992cc": {
    "text": "「當封印變弱時，懷錶就會甦醒。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-125-0f34bd67e995a71b": {
    "text": "“And when that happens…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-125-2025bc0376d966f4": {
    "text": "「而當那天來臨……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-126-77e024f17b5dd97f": {
    "text": "His expression became serious.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-126-5256de7db3d27602": {
    "text": "他的表情變得嚴肅。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-127-5dc6b4ced40aabdd": {
    "text": "“…do not trust the tower completely.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-127-8dc40eb3d0b56d26": {
    "text": "「……不要完全相信高塔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-128-6daad01fa18b0553": {
    "text": "Ethan’s eyes widened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-128-e0efa0f749209bce": {
    "text": "伊森睜大眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-129-5442659457095c55": {
    "text": "“What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-129-5ab60aad745f2829": {
    "text": "「什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-130-f96f77f3c902c651": {
    "text": "The memory suddenly broke apart.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-130-477a22f6d0ca2486": {
    "text": "記憶瞬間碎裂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-131-f8c733966e4ebaf2": {
    "text": "FLASH!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-131-c552f5d7ed5f79bb": {
    "text": "閃光！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-132-7adce6f3ea9c09cf": {
    "text": "The library returned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-132-2e6d52f95fd6d4e6": {
    "text": "圖書館恢復正常。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-133-f6f4f5614d5a552d": {
    "text": "The silver light faded.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-133-a7a2d9815fe6dc6b": {
    "text": "銀光消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-134-96270433624a8ef3": {
    "text": "The shadow hand disappeared back into the crack.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-134-9631b644a5c2fa99": {
    "text": "黑影巨手退回裂縫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-135-260374c19f437054": {
    "text": "Everything became quiet again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-135-13018899237716d1": {
    "text": "一切再次安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-136-ce92f53ee90ba1c6": {
    "text": "Except for the ticking.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-136-bdbae90bedb0de2d": {
    "text": "只剩滴答聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-137-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-137-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-138-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-138-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-139-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-139-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-140-f7e617b2c63b982b": {
    "text": "Ethan stood frozen.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-140-40397dce56c65e3c": {
    "text": "伊森僵在原地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-141-4450bdcad32948b1": {
    "text": "His father’s final words echoed inside his mind.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-141-c93fbf67eb4b8699": {
    "text": "父親最後那句話不斷在腦中回響。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-142-1bc83f9267baa5b2": {
    "text": "Do not trust the tower completely.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-142-9fe0e15a39a66961": {
    "text": "「不要完全相信高塔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-143-829f8e9b07e30f9a": {
    "text": "Seraphine looked pale.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-143-5b5ff2fcf00d3e04": {
    "text": "瑟拉芬臉色蒼白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-144-c1995cf00aa9ab9a": {
    "text": "“You were never supposed to see that memory yet…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-144-6f3ffd9454f87b16": {
    "text": "「你原本不該這麼早看到那段記憶……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-145-0d4f18c8bf4da330": {
    "text": "Ethan slowly looked at her.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-145-573da8d82eb6937f": {
    "text": "伊森慢慢看向她。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-146-d6fe66267b255879": {
    "text": "“What did my father mean?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-146-f1d52f428f3f612a": {
    "text": "「我父親那句話是什麼意思？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-147-4d818a68632cabca": {
    "text": "Seraphine hesitated.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-147-aa7a6c4f0bf38e66": {
    "text": "瑟拉芬沉默。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-148-8de8a656e2c29220": {
    "text": "For the first time—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-148-f34020f63d9ecb89": {
    "text": "第一次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-149-0e228becbb7656a1": {
    "text": "She looked afraid.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-149-a8e3824010b18453": {
    "text": "她露出害怕表情。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-150-8c44065f33913fba": {
    "text": "Very afraid.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-150-764441c6efe4e5af": {
    "text": "真正的害怕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-151-b20e808d1c41773a": {
    "text": "Then suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-151-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-152-febcea33fcfad402": {
    "text": "The giant silver tree began glowing blood red.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-152-f79bf7b9e98e47a1": {
    "text": "巨大銀樹開始變成血紅色。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-153-98d2eae492b997b2": {
    "text": "The entire library shook violently again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-153-a587ec4cb88d7d59": {
    "text": "整個圖書館再次劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-154-779d7685f279d2d4": {
    "text": "And from deep below—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-154-94f8e4c294ffa12c": {
    "text": "而在深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-155-d4ea5fe32b87e0ae": {
    "text": "The Shadow King laughed louder than before.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-155-3f003afeddfef0ed": {
    "text": "暗影之王笑得比剛剛更大聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c10-en-block-156-b353140486983b90": {
    "text": "“THE SEAL IS BREAKING…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c10-zh-block-156-d6ba9666cbfae2d9": {
    "text": "「封印正在崩壞……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-title-b7a2b07bf8bf4e21": {
    "text": "The Secret of the First Keepers",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-title-d6bb064232d566ab": {
    "text": "初代守護者的秘密",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-0-4917a1cac3fb3ab0": {
    "text": "The giant silver tree continued turning red.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-0-334d9e90cbfc2cec": {
    "text": "巨大銀樹持續變紅。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-1-08068e395432631d": {
    "text": "Its glowing branches twisted slowly like veins of light.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-1-03470cbfdaf84986": {
    "text": "發光樹枝像光之血管般慢慢扭動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-2-6b6d4f0c5f6bdcf7": {
    "text": "Books flew wildly through the library.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-2-d6499569e138efb2": {
    "text": "書本在圖書館內瘋狂飛舞。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-3-a3bd7afce9cf5246": {
    "text": "The ancient clocks rang out of sync.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-3-f31a4f5867193366": {
    "text": "古老時鐘發出混亂鐘聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-4-170ee7d507b174a3": {
    "text": "DONG.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-4-c3d49368221bbc81": {
    "text": "噹。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-5-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-5-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-6-170ee7d507b174a3": {
    "text": "DONG.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-6-c3d49368221bbc81": {
    "text": "噹。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-7-24ac229c0a69a711": {
    "text": "TickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-7-9c4f4560ec4ef226": {
    "text": "滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-8-99f739d8448b136b": {
    "text": "Ethan backed away from the crack in the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-8-c984c1143d73ee76": {
    "text": "伊森慢慢後退，遠離裂縫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-9-0a2fcbaca7c1a634": {
    "text": "The purple light below was growing stronger.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-9-e3d6d58275e14341": {
    "text": "下方紫色光越來越強。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-10-d0997e63079b4ff5": {
    "text": "The Shadow King’s laughter echoed upward endlessly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-10-296e1aab93b734c8": {
    "text": "暗影之王的笑聲不斷從深處傳來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-11-e9b402264a926b09": {
    "text": "Seraphine raised both hands quickly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-11-eeabb2123e392e83": {
    "text": "瑟拉芬迅速舉起雙手。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-12-38b38da9cf9217c3": {
    "text": "Silver chains shot across the room again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-12-2a7c47b0ac92f7f4": {
    "text": "銀色鎖鏈再次射出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-13-0c17afd26917a35f": {
    "text": "Ancient symbols covered the library ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-13-ec3b04435a2eb8bd": {
    "text": "古老符號覆蓋整個圖書館天花板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-14-f947bd5182fe7ac7": {
    "text": "“Seal the lower chamber!” she shouted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-14-290e8e6ca4419774": {
    "text": "「封住下層！」她大喊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-15-3157b53dc932ae38": {
    "text": "The chains wrapped around the crack tightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-15-6656f8ef4f8f6378": {
    "text": "鎖鏈死死纏住裂縫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-16-5c97ba6bc6f5119d": {
    "text": "For one moment—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-16-c8ba5d760a83ced0": {
    "text": "短短一瞬間——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-17-0ac962318e6de291": {
    "text": "The darkness stopped moving.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-17-6d063725047c9c22": {
    "text": "黑暗停止移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-18-42caaf875bd101d6": {
    "text": "Silence.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-18-833204688b72a129": {
    "text": "安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-19-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-19-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-20-70a49705c0343802": {
    "text": "CRACK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-20-c7df42e6c845feb3": {
    "text": "喀啦。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-21-77f316be0fe68967": {
    "text": "One silver chain snapped instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-21-db603b159aebc1cb": {
    "text": "一條銀色鎖鏈瞬間斷裂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-22-8d5af15a9bac4dba": {
    "text": "Seraphine’s face turned pale.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-22-892c60bb45e87805": {
    "text": "瑟拉芬臉色發白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-23-bc06b5b4bd0d903d": {
    "text": "“…It’s stronger than before.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-23-b0c6d1cb0c76d777": {
    "text": "「……它比以前更強了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-24-eb0961a0923c7af0": {
    "text": "Ethan looked at her urgently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-24-9be44f85d38921d0": {
    "text": "伊森急忙看向她。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-25-d6fe66267b255879": {
    "text": "“What did my father mean?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-25-886658e853f2cb74": {
    "text": "「我父親到底是什麼意思？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-26-08e4bdaeac43c30b": {
    "text": "“Why shouldn’t I trust the tower?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-26-5372102c55eb5811": {
    "text": "「為什麼不能相信高塔？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-27-3ac88ab83933eb7d": {
    "text": "Seraphine remained silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-27-aa7a6c4f0bf38e66": {
    "text": "瑟拉芬沉默。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-28-b28ceae37edfdcd7": {
    "text": "Too silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-28-cc3dfa7ad7ec91b9": {
    "text": "太沉默了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-29-398d890a7fd257f7": {
    "text": "Ethan stepped closer.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-29-142847b64700b39c": {
    "text": "伊森往前一步。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-30-213cf2c9d7701a7a": {
    "text": "“You know something.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-30-e876a1d21353d2c7": {
    "text": "「妳知道什麼。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-31-1910139852a7c76d": {
    "text": "Her mechanical eye flickered softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-31-08dcd21c099a22c2": {
    "text": "她的機械眼微微閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-32-9831c7b0a6dcfea0": {
    "text": "Then finally—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-32-11cf8b1db92eee37": {
    "text": "最後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-33-e3c3e3b81f0f384b": {
    "text": "She sighed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-33-f160239321126825": {
    "text": "她嘆氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-34-1cc9a46bc580e6c5": {
    "text": "“The Clock Tower was not built to protect the school.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-34-61723886bba8f7ad": {
    "text": "「時鐘塔建立的目的，並不是保護學校。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-35-c8270c3e70686e1e": {
    "text": "Ethan frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-35-f09e32b4e8865c97": {
    "text": "伊森皺眉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-36-389fc6b7ff4276ec": {
    "text": "“…What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-36-0e6d1d8c21b20b5e": {
    "text": "「……什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-37-d5d8643959a6d15d": {
    "text": "“It was built as a prison.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-37-8649d01d61e2487d": {
    "text": "「它是監獄。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-38-734e9894cb5ef407": {
    "text": "The library became cold again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-38-5130442462516047": {
    "text": "圖書館再次變冷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-39-4f3de17b4a0b0067": {
    "text": "Even hearing the words felt wrong.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-39-75777867accd31d6": {
    "text": "連這句話都令人不舒服。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-40-ca5628bce0a93e1d": {
    "text": "Seraphine slowly walked toward the giant red tree.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-40-cb6b2641b7bde723": {
    "text": "瑟拉芬慢慢走向紅色巨樹。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-41-13782712cd25d5d3": {
    "text": "“Hundreds of years ago, the First Keepers discovered something beneath these mountains.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-41-a33c6f5fde02f4ac": {
    "text": "「數百年前，初代守護者在山脈底下發現某種東西。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-42-f8822c82a6ea9601": {
    "text": "Her voice echoed softly through the library.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-42-f141ececb0f8c9ec": {
    "text": "她的聲音回盪在圖書館。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-43-45d4fed5f35a0f9e": {
    "text": "“Something ancient.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-43-071e3394821dda5d": {
    "text": "「某種古老存在。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-44-5acfadc15f0f9897": {
    "text": "“Something alive.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-44-8c53f8ced4ad7a75": {
    "text": "「某種活著的東西。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-45-078ff581c1491739": {
    "text": "Purple smoke curled upward from the crack below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-45-548be7b4cf69afdb": {
    "text": "紫色煙霧從裂縫緩緩升起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-46-78235e9a81fdb980": {
    "text": "Ethan whispered,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-46-53cd7e9af115d060": {
    "text": "伊森低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-47-c0cd70ddf8da108f": {
    "text": "“The Shadow King…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-47-73ac2834786f54d5": {
    "text": "「暗影之王……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-48-90bd5a758b77484c": {
    "text": "Seraphine nodded slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-48-b94dc6268193f3c9": {
    "text": "瑟拉芬慢慢點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-49-e8fe244d0d6ffa75": {
    "text": "“The First Keepers could not destroy it.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-49-8c111f389ff9e1ca": {
    "text": "「初代守護者無法消滅它。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-50-0f9b6200fca76d0d": {
    "text": "“So they built the tower above it instead.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-50-a8031e41d7e30b54": {
    "text": "「所以他們在它上方建立高塔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-51-28e6b42acb95c11f": {
    "text": "“The tower became both lock and cage.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-51-7d0f16c27f5901cd": {
    "text": "「高塔既是鎖，也是牢籠。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-52-aea8f941fbf9a0bc": {
    "text": "Ethan looked upward instinctively.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-52-fb3dc286126c7b55": {
    "text": "伊森下意識抬頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-53-e0a00c0eef791f17": {
    "text": "All this time—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-53-72ec0378b5ebd121": {
    "text": "原來——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-54-b6b3c152873735e6": {
    "text": "The school itself had been a prison.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-54-32a50a247135f61d": {
    "text": "整間學校本身就是監獄。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-55-81a442dcbac464f7": {
    "text": "“The clocks…” Ethan whispered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-55-e4f1eaded4a112a9": {
    "text": "「那些時鐘……」伊森低聲說。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-56-4bb1dafd84784ad4": {
    "text": "“The clocks are part of the seal,” Seraphine explained.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-56-8ec2cd033753c123": {
    "text": "「時鐘是封印的一部分，」瑟拉芬解釋。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-57-9ea0c4d32d6a5bb9": {
    "text": "“Every ticking second strengthens the prison.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-57-1508b2c877fa483e": {
    "text": "「每一次滴答聲都在強化牢籠。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-58-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-58-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-59-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-59-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-60-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-60-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-61-b5812098f081df31": {
    "text": "The silver watch in Ethan’s hand suddenly pulsed brightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-61-2c12a82a6fec7e9b": {
    "text": "伊森手中的銀色懷錶突然強烈發光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-62-a7f2e7d4ba332c44": {
    "text": "Seraphine looked at it carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-62-fc1fd9b114682cd0": {
    "text": "瑟拉芬仔細看著它。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-63-0a6b933dd35ab670": {
    "text": "“Your father discovered something before the war ended.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-63-6e49f6ee5e20f873": {
    "text": "「你父親在戰爭結束前發現了一件事。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-64-b872fa957dcf1c9a": {
    "text": "Ethan looked up immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-64-0229b8d4bcb65a73": {
    "text": "伊森立刻抬頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-65-5442659457095c55": {
    "text": "“What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-65-5ab60aad745f2829": {
    "text": "「什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-66-fb55d2cc31b67c4a": {
    "text": "Seraphine hesitated again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-66-bf939829dd18fd4a": {
    "text": "瑟拉芬再次猶豫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-67-9ec976d718fd2727": {
    "text": "Then she spoke quietly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-67-2765ec3304c2c39c": {
    "text": "然後低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-68-dd184762ea687e13": {
    "text": "“The Shadow King was not trying to destroy the tower.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-68-02a4d81b9ef91f89": {
    "text": "「暗影之王其實不是想摧毀高塔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-69-641a78e1b01c7f32": {
    "text": "Ethan froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-69-2fe0bd33fa452ca5": {
    "text": "伊森僵住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-70-389fc6b7ff4276ec": {
    "text": "“…What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-70-0e6d1d8c21b20b5e": {
    "text": "「……什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-71-f1ae8f21b5794a57": {
    "text": "“It was trying to escape something worse.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-71-d7d895991d1a17e5": {
    "text": "「它是在逃離更可怕的東西。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-72-2c364ec86045307e": {
    "text": "The library suddenly felt freezing cold.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-72-980854d958efa00c": {
    "text": "整座圖書館瞬間冰冷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-73-53a3125b272c6be1": {
    "text": "Ethan stared at her.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-73-60e6194bf00b1996": {
    "text": "伊森瞪著她。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-74-6e7489c11ea1e6bc": {
    "text": "“There’s something WORSE than the Shadow King?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-74-4e72148290c9d609": {
    "text": "「還有比暗影之王更可怕的東西？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-75-fd5d0232f05a2b5f": {
    "text": "Before Seraphine could answer—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-75-76759288839b033c": {
    "text": "瑟拉芬還沒回答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-76-8daa0809b2c9925d": {
    "text": "The entire library shook violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-76-94912941e88b22f5": {
    "text": "整座圖書館劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-77-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-77-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-78-e6e9df73017882c5": {
    "text": "The giant crack exploded wider again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-78-a00fdec9b0043fcb": {
    "text": "巨大裂縫再次爆開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-79-d35f4718e73b1e7d": {
    "text": "Dark smoke burst upward like a storm.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-79-d3f7031782e17045": {
    "text": "黑煙像暴風般衝出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-80-ed56821c09561585": {
    "text": "The chains snapped one after another.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-80-71b23b7b7c612711": {
    "text": "鎖鏈一條條斷裂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-81-f9f3f2d0891bfd70": {
    "text": "CLANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-81-690a1a50186dfe69": {
    "text": "鏘！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-82-f9f3f2d0891bfd70": {
    "text": "CLANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-82-690a1a50186dfe69": {
    "text": "鏘！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-83-f9f3f2d0891bfd70": {
    "text": "CLANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-83-690a1a50186dfe69": {
    "text": "鏘！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-84-6eefebf46c204c90": {
    "text": "The Shadow King laughed louder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-84-d1e35990aa0c9c60": {
    "text": "暗影之王笑得更大聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-85-c84bf68d85e420fc": {
    "text": "“THE TOWER WEAKENS…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-85-4c4a59078ca5a684": {
    "text": "「高塔正在變弱……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-86-01cabcf4e4f5607c": {
    "text": "The red tree flickered violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-86-0b1a5c783295af4b": {
    "text": "紅色巨樹劇烈閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-87-eaf86487e666958a": {
    "text": "Books crashed everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-87-e23c1371bbc3b8d8": {
    "text": "書本四處撞擊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-88-4d514aea2c7589ba": {
    "text": "Seraphine shouted:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-88-0ba435bdc72dc2bc": {
    "text": "瑟拉芬大喊：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-89-3f8aa980fee40004": {
    "text": "“Ethan! The watch!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-89-91feba10b0e89cc6": {
    "text": "「伊森！懷錶！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-90-e61b7ea861352676": {
    "text": "Ethan looked down.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-90-59b156831e604b38": {
    "text": "伊森低頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-91-d48da4b806dd6870": {
    "text": "The silver watch was glowing brighter than ever before.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-91-83fbb5e7f7ee11d6": {
    "text": "銀色懷錶亮到極限。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-92-94ba71c8e9736f66": {
    "text": "Symbols moved rapidly across its surface.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-92-a72a7d4e70b48fc9": {
    "text": "表面符號快速移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-93-b20e808d1c41773a": {
    "text": "Then suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-93-4f96ee8acafc5094": {
    "text": "然後突然——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-94-8e02407803fb4a65": {
    "text": "A hidden compartment opened inside it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-94-b993b547ef55c9f5": {
    "text": "裡面隱藏夾層打開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-95-0dd175ab100e45c3": {
    "text": "CLICK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-95-019792da7b48e033": {
    "text": "喀嚓。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-96-3cbb05fad79d20dd": {
    "text": "Something fell into Ethan’s hand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-96-008aec30e60b4b6e": {
    "text": "有東西掉進伊森手裡。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-97-b1a6e4eddb35807e": {
    "text": "A silver key.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-97-83aecf6820a954f7": {
    "text": "一把銀色鑰匙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-98-100e545791ed7ff8": {
    "text": "Small.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-98-0c340e75c47b8eb8": {
    "text": "小小的。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-99-b47c80c12cde794d": {
    "text": "Ancient.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-99-d8b0d5b59170dfaf": {
    "text": "古老的。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-100-83b2bf16e48bac29": {
    "text": "Covered in glowing symbols.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-100-10caf4ab8608a054": {
    "text": "刻滿發光符號。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-101-f3bcd6b4ef249b09": {
    "text": "Ethan stared at it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-101-4955491aaab68f14": {
    "text": "伊森瞪大眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-102-032b83a50d63a8b9": {
    "text": "“…There was a KEY inside the watch?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-102-9661b9b6161be70c": {
    "text": "「……懷錶裡居然藏著鑰匙？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-103-5be20a43e2be1505": {
    "text": "Seraphine’s expression changed instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-103-ebd702645a8409f8": {
    "text": "瑟拉芬表情瞬間改變。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-104-6824a51a4cbcd680": {
    "text": "Shock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-104-deec07e075b3159d": {
    "text": "震驚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-105-131cb50fb8c68760": {
    "text": "Real shock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-105-e3a9e696ebc5c0bb": {
    "text": "真正的震驚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-106-7c387c5f8e40517f": {
    "text": "“No…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-106-92141de36152d128": {
    "text": "「不……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-107-536ad70b17a15360": {
    "text": "Ethan looked at her.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-107-97e175049ff57404": {
    "text": "伊森看向她。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-108-052bc68392c15730": {
    "text": "“What?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-108-61fe5ba38b4202ef": {
    "text": "「什麼？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-109-25e785140fe60f3e": {
    "text": "Seraphine whispered,",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-109-e79d4a961d18e512": {
    "text": "瑟拉芬低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-110-0b8046e75e068a3f": {
    "text": "“The Final Lock…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-110-a06697e5763328da": {
    "text": "「最終之鎖……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-111-d54123407d9de2f9": {
    "text": "The Shadow King suddenly became silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-111-fd18cf16ddedff4d": {
    "text": "暗影之王突然安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-112-ba6e9d797ea5673b": {
    "text": "Completely silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-112-cb16313461aa2b72": {
    "text": "完全安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-113-89df0a67f40aa14b": {
    "text": "Then slowly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-113-932da14da57c5006": {
    "text": "接著——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-114-fced0cd61e2399af": {
    "text": "Purple eyes appeared deep inside the crack.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-114-e3fc90c2258fb847": {
    "text": "紫色眼睛慢慢出現在裂縫深處。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-115-c11e1682c341ce07": {
    "text": "Watching Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-115-b18f9e04604a0714": {
    "text": "盯著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-116-0ef36d6c182a2186": {
    "text": "Watching the key.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-116-70dd4e80bd3dc48a": {
    "text": "盯著那把鑰匙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-117-68defb90f82e1b29": {
    "text": "The voice rose again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-117-ed549e7f91e863d1": {
    "text": "那聲音再次升起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-118-a2f1103c37928e18": {
    "text": "But now—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-118-c8cf185086313483": {
    "text": "但這次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-119-379c9e62d21c4ff1": {
    "text": "It sounded afraid.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-119-50335bec54dbc0a2": {
    "text": "居然帶著恐懼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-120-5c477c165253319b": {
    "text": "“THE LAST KEY…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-120-38608f1ddd725c05": {
    "text": "「最後的鑰匙……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-121-d8efb1becc2299ea": {
    "text": "Ethan’s heart pounded.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-121-e4a40f6e4a397919": {
    "text": "伊森心跳加速。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-122-58d8821b41f6f11e": {
    "text": "“What is this thing?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-122-d68b6af9d742cb48": {
    "text": "「這到底是什麼？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-123-9080a4736d796223": {
    "text": "Seraphine stepped backward slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-123-f1f6ba0714769a30": {
    "text": "瑟拉芬慢慢後退。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-124-d97ca4b26871b58b": {
    "text": "“The First Keepers created three locks beneath the tower.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-124-247154221fb272cc": {
    "text": "「初代守護者在高塔底下建立了三道鎖。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-125-559f8979adc8788f": {
    "text": "“The silver watch…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-125-62683476e5445c22": {
    "text": "「銀色懷錶……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-126-94fb83ab29a6a817": {
    "text": "“…was never meant to be only a watch.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-126-46409c28a5bbf218": {
    "text": "「從來不只是懷錶。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-127-68ffd999065ea30a": {
    "text": "Ethan looked at the glowing key.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-127-0235e9212a38c1ca": {
    "text": "伊森看著手中鑰匙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-128-1a433da1f5c7765b": {
    "text": "Then at the crack below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-128-fc633e40da7fefa5": {
    "text": "又看向裂縫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-129-d40d2ea72ff8a11b": {
    "text": "A terrible thought entered his mind.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-129-fa9c673147406032": {
    "text": "一個可怕想法出現在腦中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-130-f15983470a83189b": {
    "text": "“…This key opens something.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-130-76e7428697c94199": {
    "text": "「……這把鑰匙會打開某個東西。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-131-17c2b7aa9d17cc17": {
    "text": "Seraphine closed her eyes briefly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-131-cef31c92247a2df9": {
    "text": "瑟拉芬閉上眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-132-605c32e719b72803": {
    "text": "“Yes.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-132-9641153de25c3546": {
    "text": "「沒錯。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-133-fc5532f12800e387": {
    "text": "The library shook harder than ever.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-133-711ed515e1d0d3b6": {
    "text": "圖書館震動越來越劇烈。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-134-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-134-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-135-fbc42fc246c16fa2": {
    "text": "Part of the ceiling collapsed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-135-d23ad8dc5675b5f2": {
    "text": "部分天花板崩塌。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-136-73324d084867e28b": {
    "text": "The Shadow King’s laughter returned immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-136-52fbf26154ac3644": {
    "text": "暗影之王再次狂笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-137-42fc3be3936c3fde": {
    "text": "“THE HEIR UNDERSTANDS…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-137-04e68872a81ba886": {
    "text": "「繼承者終於明白了……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-138-dfd6b874aa51608f": {
    "text": "Dark claws slowly reached upward from the crack.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-138-3e057d7a7f426939": {
    "text": "越來越多黑色利爪從裂縫伸出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-139-9b3f4ab3bf7cb003": {
    "text": "More than before.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-139-7bd655401d28d68a": {
    "text": "比剛剛更多。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-140-291531eca78ba261": {
    "text": "Many more.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-140-288186d835125df9": {
    "text": "更多更多。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-141-2ccd8e04a0ba86b6": {
    "text": "The seal was failing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-141-63e465d1c01ba477": {
    "text": "封印正在失效。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-142-4f422d51cbfcc9dd": {
    "text": "Fast.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-142-eb54625e78037f69": {
    "text": "很快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-143-6ece60732394a817": {
    "text": "Ethan gripped the silver key tightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-143-6e482cebb26e8ef7": {
    "text": "伊森緊握銀色鑰匙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-144-a20c4151bbba8ab3": {
    "text": "His father’s words echoed again inside his mind.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-144-8b311f26bf2fcff5": {
    "text": "父親的話再次在腦中響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-145-1bc83f9267baa5b2": {
    "text": "Do not trust the tower completely.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-145-a3e776c8573332ce": {
    "text": "不要完全相信高塔。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-146-374696b7598fa684": {
    "text": "Then another thought appeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-146-4e83b9571625ff80": {
    "text": "接著，另一個念頭浮現。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-147-2bab6a12003f9d88": {
    "text": "If the tower was a prison—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-147-94d985cb75cedc09": {
    "text": "如果高塔是一座監獄——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-148-bd2a5ab784d4865c": {
    "text": "Then what exactly was trying to get out?",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-148-b2b83bd1daa60ce3": {
    "text": "那真正想逃出來的，到底是什麼？",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-149-1d070c8fc4e1309a": {
    "text": "The silver watch suddenly displayed another message.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-149-af150cd7297a37cf": {
    "text": "銀色懷錶突然再次顯示文字。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-150-bb95867a8b305c9a": {
    "text": "DO NOT OPEN THE FINAL GATE.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-150-c4ddf888105ca6de": {
    "text": "「不要打開最終之門。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-151-8109f9ae9849f537": {
    "text": "Ethan stared at the glowing words.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-151-9c9bfa8bbf166a27": {
    "text": "伊森盯著發光文字。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-152-3b44156e1fe952d2": {
    "text": "Then the message changed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-152-8168734082e52510": {
    "text": "接著文字改變。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-153-6c008ef4504bce9f": {
    "text": "HE IS ALREADY AWAKE.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-153-1fefdffaa4f8465f": {
    "text": "「祂已經醒了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-154-0c13b2edd43c62b2": {
    "text": "The entire library went silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-154-8b1454ab44ce4147": {
    "text": "整座圖書館瞬間死寂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-155-56758bc428befbdc": {
    "text": "Even the Shadow King stopped laughing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-155-a4b6a973bc09350f": {
    "text": "連暗影之王都停止笑聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-156-adf3a7d20044c3db": {
    "text": "And deep below the tower—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-156-10982fa9673ba0b1": {
    "text": "而在高塔最深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c11-en-block-157-bbf6390b53e04871": {
    "text": "Something enormous moved.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c11-zh-block-157-09eba524e4d978c5": {
    "text": "某個龐然巨物動了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-title-149794c93a2d3547": {
    "text": "The Thing Beneath the Clock Tower",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-title-82bf78652f2dc5da": {
    "text": "時鐘塔下的存在",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-0-fb0401222ad07d80": {
    "text": "The moment the message disappeared from the silver watch—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-0-19e8a3266f1a1458": {
    "text": "當銀色懷錶上的訊息消失那一刻——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-1-e2bdcfb00d2c58d6": {
    "text": "Every clock in the library stopped.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-1-915fc62ebd5d042d": {
    "text": "圖書館內所有時鐘全部停止。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-2-c5ef61ea2a6f4f03": {
    "text": "Ticking vanished instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-2-cbc10c273fc8e217": {
    "text": "滴答聲瞬間消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-3-4194d0df77101739": {
    "text": "Silence crushed the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-3-8eb392ecced4d652": {
    "text": "沉重安靜壓住整個空間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-4-e01c9e57b50d7741": {
    "text": "Even the Shadow King became still.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-4-b9a3bcd8d40da804": {
    "text": "連暗影之王都安靜了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-5-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-5-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-6-47e2d53f1ffb6bda": {
    "text": "From far below the tower—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-6-3ca8697891e5ebce": {
    "text": "高塔深處下方——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-7-0ad31ebb425bdad7": {
    "text": "A sound echoed upward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-7-e777f57cc194c25b": {
    "text": "傳來一道聲音。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-8-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-8-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-9-3d04815e6ab1e5fd": {
    "text": "The entire library shook.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-9-94912941e88b22f5": {
    "text": "整座圖書館劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-10-6b322180af24da9d": {
    "text": "Books crashed from the shelves.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-10-6a1e426eb7d20297": {
    "text": "書本從書架砸落。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-11-eab7c428f73be728": {
    "text": "Dust fell from the ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-11-7898265bd84b8a5a": {
    "text": "灰塵從天花板掉下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-12-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-12-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-13-78e13b2e18f41910": {
    "text": "The silver chains around the crack trembled violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-13-9ac538da875f186d": {
    "text": "裂縫上的銀色鎖鏈瘋狂震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-14-80e0a229c0dc05ed": {
    "text": "Ethan felt the vibration inside his chest.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-14-8120444c5642dd92": {
    "text": "伊森甚至能感受到胸口跟著震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-15-fb1ab548da13b5b2": {
    "text": "Like something enormous was walking beneath them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-15-1ded5b4ce9c2f998": {
    "text": "像有某種巨大存在正在地下行走。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-16-68cad7121adcce4c": {
    "text": "Slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-16-5a095fb990919bed": {
    "text": "慢慢地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-17-601a0e9a9a25a8e4": {
    "text": "Awakening.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-17-598238b0bfc7fe89": {
    "text": "正在甦醒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-18-bc47efdfd676613d": {
    "text": "Seraphine whispered one terrible sentence:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-18-f334db4808287971": {
    "text": "瑟拉芬低聲說出一句可怕的話：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-19-92345ade6b901631": {
    "text": "“…It found the Final Lock.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-19-e2c3f1a113c616d4": {
    "text": "「……祂找到最終之鎖了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-20-df32f864af7a5165": {
    "text": "Ethan tightened his grip on the silver key.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-20-776c90d643034179": {
    "text": "伊森握緊銀色鑰匙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-21-96d1ed4292f963af": {
    "text": "“What IS down there?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-21-a74413f2d29a832e": {
    "text": "「下面到底是什麼？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-22-b800ee55f7749c2b": {
    "text": "Nobody answered immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-22-5363b359450a6e07": {
    "text": "沒有人立刻回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-23-fd319f679b3de279": {
    "text": "Because somewhere deep below—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-23-8183f92b29be56ae": {
    "text": "因為深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-24-50e1aa72d3cbeac8": {
    "text": "Another THUMP shook the tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-24-28ccf5965ca5002f": {
    "text": "又一聲咚響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-25-53a487c49f2872e7": {
    "text": "This time louder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-25-da04e78b1d2567bc": {
    "text": "更大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-26-6bde392af93a7912": {
    "text": "Closer.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-26-036011a301dbf83c": {
    "text": "更近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-27-9faa5137833039c6": {
    "text": "The purple light inside the crack flickered wildly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-27-5143ef6bd0254110": {
    "text": "裂縫中的紫光瘋狂閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-28-7d13de9b3b708d56": {
    "text": "And suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-28-b7451d8392143d51": {
    "text": "而這時——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-29-4946329db987d7b1": {
    "text": "The Shadow King spoke again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-29-095d7bb56c004691": {
    "text": "暗影之王再次開口。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-30-a2f1103c37928e18": {
    "text": "But now—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-30-c8cf185086313483": {
    "text": "但這次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-31-c0d2535e511c2c9f": {
    "text": "Its voice no longer sounded cruel.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-31-fa7484a9ec316e28": {
    "text": "聲音不再殘忍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-32-ebf7ab96364f1f4d": {
    "text": "It sounded terrified.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-32-03de8b8bb63a6ff2": {
    "text": "而是恐懼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-33-6d2d82f9c0e12079": {
    "text": "“IT MUST NOT WAKE.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-33-27aae14250c3785a": {
    "text": "「絕對不能讓祂醒來。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-34-db5ca7cb2f1a88af": {
    "text": "Ethan stared at the darkness below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-34-41aa736e95266d99": {
    "text": "伊森瞪著下方黑暗。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-35-a0f7638f2f5b9d8d": {
    "text": "“…You’re afraid of it?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-35-b0cb5263c7d380ae": {
    "text": "「……你在害怕祂？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-36-bc03092fd35a28e2": {
    "text": "The Shadow King laughed bitterly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-36-6fc6c7ec7dcf5e4a": {
    "text": "暗影之王苦笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-37-2fa3ea0fdae26a3c": {
    "text": "“YOU THINK I AM THE MONSTER.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-37-08717912c6426851": {
    "text": "「你以為我是怪物。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-38-939aa1ce4c635ba7": {
    "text": "The giant red tree trembled violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-38-aab7ede20b56096f": {
    "text": "巨大紅樹劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-39-4c176fa77f5cecf0": {
    "text": "Purple smoke filled the library ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-39-07ce43bde8e6ff4c": {
    "text": "紫煙充滿圖書館。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-40-06ac0bd158e9c2a6": {
    "text": "“BUT I WAS THE PRISONER TOO.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-40-d7fa155ea9f9349a": {
    "text": "「但我也曾是囚犯。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-41-641a78e1b01c7f32": {
    "text": "Ethan froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-41-8d885feee9177340": {
    "text": "伊森瞬間僵住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-42-5442659457095c55": {
    "text": "“What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-42-5ab60aad745f2829": {
    "text": "「什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-43-17c2b7aa9d17cc17": {
    "text": "Seraphine closed her eyes briefly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-43-cef31c92247a2df9": {
    "text": "瑟拉芬閉上眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-44-03314ffda1bde2c5": {
    "text": "“The Shadow King was never the true enemy…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-44-1e59248f8040d43c": {
    "text": "「暗影之王從來不是真正敵人……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-45-2eef30e97c0ea2da": {
    "text": "Another massive THUMP echoed upward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-45-5bfff1f380c1b8ef": {
    "text": "又一道巨大咚聲從地下傳來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-46-d5289c1af336f864": {
    "text": "CRACK!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-46-860b09e49ab9e859": {
    "text": "喀啦！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-47-e31a801359143d7c": {
    "text": "A huge fracture split across the library wall.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-47-f00ee57079b0570c": {
    "text": "圖書館牆壁出現巨大裂痕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-48-c60905f95edc0893": {
    "text": "Ancient symbols flickered weakly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-48-aea218e975ae8ff8": {
    "text": "古老符號變得暗淡。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-49-496342a49d575d21": {
    "text": "The seal was failing everywhere now.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-49-02917e554646ce8d": {
    "text": "整個封印都開始崩壞。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-50-3fbaaf455d564ea5": {
    "text": "Seraphine looked at Ethan urgently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-50-951ca5cadde48688": {
    "text": "瑟拉芬急忙看向伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-51-8e81471a357da89a": {
    "text": "“You must listen carefully.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-51-d14a95d11332811d": {
    "text": "「你必須仔細聽好。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-52-cc60e22ef4cfbabc": {
    "text": "“The First Keepers discovered an ancient being beneath these mountains.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-52-1d78e8c2696cda06": {
    "text": "「初代守護者在山脈下發現了一個古老存在。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-53-3096a9f354613b8f": {
    "text": "“Something older than magic itself.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-53-8bfd241e50d451f2": {
    "text": "「某種比魔法更古老的東西。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-54-be72e130add792ee": {
    "text": "Ethan swallowed hard.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-54-b47233f753c5037e": {
    "text": "伊森吞了吞口水。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-55-29405cfe5de3e638": {
    "text": "“…What kind of thing?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-55-b12e6a91e544b792": {
    "text": "「……那是什麼東西？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-56-1341de582d367518": {
    "text": "Seraphine’s mechanical eye dimmed slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-56-a02b4518dcaa7313": {
    "text": "瑟拉芬的機械眼慢慢變暗。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-57-034747d7446bca1a": {
    "text": "“We do not know its true name.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-57-abd11782e768866f": {
    "text": "「我們不知道祂真正名字。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-58-dd605538bc3c0019": {
    "text": "“So the First Keepers gave it one.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-58-f8d5bffcd396beb9": {
    "text": "「所以初代守護者替祂取了一個名字。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-59-e5eb8de496c60762": {
    "text": "The library shook again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-59-1867c2f8079acbae": {
    "text": "圖書館再次震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-60-a7dca45eafd4323e": {
    "text": "The giant crack widened farther.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-60-39cee4b3ed1c163f": {
    "text": "巨大裂縫繼續擴張。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-61-4d18ed83148219ec": {
    "text": "Darkness flooded upward like black water.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-61-a2d5b518ba6c1901": {
    "text": "黑暗像黑水般湧出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-62-9acd665b69315ab1": {
    "text": "Seraphine whispered:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-62-e79d4a961d18e512": {
    "text": "瑟拉芬低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-63-8115bcdd0351c6ec": {
    "text": "“…The Hollow King.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-63-e253d775939aff71": {
    "text": "「……虛空之王。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-64-b707192169aa973e": {
    "text": "The moment she said the name—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-64-bd85c4cd5d64532b": {
    "text": "就在名字被說出口那瞬間——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-65-38f080b773ad236e": {
    "text": "Every candle in the library went out.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-65-e6c1d528dd531660": {
    "text": "圖書館所有蠟燭全部熄滅。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-66-cb462e2da16092be": {
    "text": "Complete darkness swallowed the room.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-66-b5a636bf2669b377": {
    "text": "完全黑暗吞沒整個空間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-67-57cde8930f7ac7f6": {
    "text": "Ethan could hear only breathing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-67-49c4dd634d9d0758": {
    "text": "伊森只能聽見呼吸聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-68-d54843d1329bb6aa": {
    "text": "And the slow heartbeat-like sound below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-68-ed465118bbe5f317": {
    "text": "還有地下那緩慢心跳聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-69-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-69-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-70-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-70-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-71-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-71-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-72-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-72-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-73-263ca37374faae4b": {
    "text": "Two enormous golden eyes opened deep beneath the crack.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-73-bce7bb8db33e6c5a": {
    "text": "裂縫深處睜開兩隻巨大金色眼睛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-74-ed6cf947718def6c": {
    "text": "Not purple.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-74-6e0b7dcc515f76c3": {
    "text": "不是紫色。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-75-d7a770c943d97b2e": {
    "text": "Gold.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-75-c86d07638f36f363": {
    "text": "是金色。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-76-b47c80c12cde794d": {
    "text": "Ancient.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-76-2ef91fda3b675f30": {
    "text": "古老。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-77-885c75a98ac77b41": {
    "text": "Watching.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-77-3a930b10874d0454": {
    "text": "正在注視。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-78-35e5843ae763763f": {
    "text": "Ethan stopped breathing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-78-c89d582785954bc6": {
    "text": "伊森停止呼吸。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-79-6a7b28343c21f0e4": {
    "text": "The eyes were impossibly huge.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-79-aa74e1788fa748c0": {
    "text": "那雙眼巨大得不可思議。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-80-8986ee0cac859c9a": {
    "text": "Far larger than the Shadow King.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-80-4869e830bcd7017c": {
    "text": "遠比暗影之王更大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-81-dc071bf795727ee7": {
    "text": "Far larger than the library itself.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-81-64c448808f242898": {
    "text": "甚至比整座圖書館還巨大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-82-56a5614b8ec10737": {
    "text": "The Hollow King was still deep underground—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-82-b30f2ad075abecb5": {
    "text": "虛空之王依然深埋地下——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-83-805e92af2b9be0f9": {
    "text": "And yet Ethan could already see its eyes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-83-ba12b9818d2ad3bc": {
    "text": "但伊森已經能看見祂的眼睛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-84-60871ea421e55fff": {
    "text": "The Shadow King’s voice shook.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-84-3e5d0d60d421ac6c": {
    "text": "暗影之王聲音顫抖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-85-e583262a36365937": {
    "text": "“IT IS WATCHING THE HEIR.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-85-7b8287e806ba38e4": {
    "text": "「祂正在注視繼承者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-86-e63597737949a459": {
    "text": "Seraphine raised both hands instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-86-8994c7dc8132c907": {
    "text": "瑟拉芬瞬間舉起雙手。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-87-97c8e368fe6ea176": {
    "text": "Silver fire exploded across the library.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-87-c2ce1cd428223f96": {
    "text": "銀色火焰猛然爆發。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-88-ca37c99a79fc3c1e": {
    "text": "WHOOSH!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-88-cda2e8f082302827": {
    "text": "呼——！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-89-8ae48d03d8d4eb2d": {
    "text": "The room lit up again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-89-9c2ba5ddaf473f5b": {
    "text": "圖書館重新亮起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-90-f6f5fd7977bbafde": {
    "text": "The golden eyes disappeared immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-90-e2b52a4b39235734": {
    "text": "金色眼睛瞬間消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-91-54de16831ee1f2ec": {
    "text": "But Ethan could still feel them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-91-95f78d513944203b": {
    "text": "但伊森依然感覺得到。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-92-1171924c281c4a64": {
    "text": "Watching him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-92-42a1cb7fd66b0f95": {
    "text": "祂正在看著自己。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-93-2a84a09c8d4b28a7": {
    "text": "Waiting.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-93-ef6a58a01293e1ab": {
    "text": "等待著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-94-6f14b0f208de1b46": {
    "text": "The silver watch burned hot in his hand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-94-f5cf63f6983d8c1d": {
    "text": "銀色懷錶燙得發熱。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-95-dcb0627d02970259": {
    "text": "Then new words appeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-95-75a3b7ba676dc3a7": {
    "text": "接著新文字浮現。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-96-75b6e6389b7e72e8": {
    "text": "THE FINAL GATE IS WEAKENING.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-96-cf1de462856f130c": {
    "text": "「最終之門正在崩壞。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-97-d484649e511dd156": {
    "text": "Ethan stared at the message.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-97-49a7b7980b351060": {
    "text": "伊森盯著訊息。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-98-4ebe9d3bcd1a25b4": {
    "text": "“What happens if the gate opens?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-98-5b116bac1a222869": {
    "text": "「如果門打開會怎樣？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-99-612630ac491c7e62": {
    "text": "Nobody answered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-99-1d7841f862b8a2a0": {
    "text": "沒有人回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-100-59badea41f6424b7": {
    "text": "Because they already knew.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-100-08c3a5801406aaec": {
    "text": "因為所有人都知道答案。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-101-ad5aaf112c9d7a68": {
    "text": "Another THUMP echoed upward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-101-fee77e6e8cfafe08": {
    "text": "又一道咚聲響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-102-a802cb58bda608af": {
    "text": "This time—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-102-b17aa4e2ac6028ba": {
    "text": "這次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-103-f76ab8423c7f3a4f": {
    "text": "The entire tower screamed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-103-778c15c958248d1c": {
    "text": "整座高塔發出慘叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-104-2ef039eb8d3ead34": {
    "text": "A horrible metallic sound echoed through the library.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-104-23641b67064dab8d": {
    "text": "可怕金屬摩擦聲回盪圖書館。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-105-34daa1330cf215f1": {
    "text": "SCREEEEEEEEE—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-105-9282eade3b3b26ff": {
    "text": "嘎啊啊啊——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-106-dfb6a93e982b07ae": {
    "text": "The giant clocks on the walls cracked one by one.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-106-06f1268fb3eee7e6": {
    "text": "牆上巨大時鐘一個接一個裂開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-107-469cc50dd29ec288": {
    "text": "Ticking became uneven.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-107-d14ebae5c5924bf9": {
    "text": "滴答聲開始混亂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-108-58baea5e0f12ad60": {
    "text": "Some clocks stopped completely.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-108-610abe37c7e8fce4": {
    "text": "有些時鐘完全停止。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-109-ce5540b2dc14ab53": {
    "text": "The prison was breaking.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-109-20ca1d0e1643b530": {
    "text": "監獄正在崩壞。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-110-4f422d51cbfcc9dd": {
    "text": "Fast.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-110-700c4dc53057a187": {
    "text": "而且很快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-111-b20e808d1c41773a": {
    "text": "Then suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-111-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-112-ddd0a8feeacebeca": {
    "text": "The hidden staircase door above exploded open.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-112-233d1f48ad513b3b": {
    "text": "上方隱藏樓梯大門爆炸。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-113-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-113-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-114-ebdcb010b83da3b0": {
    "text": "Lucy and Adrian rushed into the library.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-114-e5a5eebfb94e13cb": {
    "text": "露西與亞德里安衝進圖書館。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-115-095cc8355e8659c5": {
    "text": "Both looked terrified.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-115-e27ce4bc81d6b0b0": {
    "text": "兩人看起來都嚇壞了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-116-abb6c3c6c97f02fa": {
    "text": "“ETHAN!” Lucy shouted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-116-fb9cb6f033902a1a": {
    "text": "「伊森！」露西大喊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-117-bef1f597a0790907": {
    "text": "“We’ve been trying to find you everywhere!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-117-68e087306e2635e2": {
    "text": "「我們到處都找不到你！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-118-e99c5ad446d2fe50": {
    "text": "Adrian’s face turned pale the moment he saw the giant crack.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-118-406d2d5ffc5c9a50": {
    "text": "亞德里安一看見巨大裂縫，臉色瞬間發白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-119-3b0aac89e676221f": {
    "text": "“…No…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-119-af37529d99a89faa": {
    "text": "「……不。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-120-2d7c72974462e62c": {
    "text": "The Shadow King laughed weakly from below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-120-fc2e29b74b574f36": {
    "text": "暗影之王虛弱笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-121-f461db33bd18bac9": {
    "text": "“TOO LATE…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-121-0c8daea844952c63": {
    "text": "「太遲了……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-122-1a323a6c079641bd": {
    "text": "Lucy looked around wildly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-122-70f16b80e62c3b38": {
    "text": "露西驚恐看四周。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-123-7ed04594f6d70283": {
    "text": "“What IS THAT THING?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-123-06991dc261a46f97": {
    "text": "「那到底是什麼東西？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-124-8ac427e6db2f34f3": {
    "text": "Before anyone could answer—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-124-c94e2ed7a208dbc8": {
    "text": "沒人來得及回答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-125-71accd8fea456d2c": {
    "text": "The entire library tilted violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-125-d60fe84c967d45d0": {
    "text": "整座圖書館突然傾斜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-126-2aa1d7ae608b257b": {
    "text": "Shelves collapsed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-126-09cce9ca2c920e69": {
    "text": "書架倒塌。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-127-368d602dfb971b87": {
    "text": "Books flew everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-127-6c43b4d7c5986763": {
    "text": "書本滿天亂飛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-128-af7a07603cb67a8d": {
    "text": "The giant red tree split open down the middle.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-128-4506fc0db50303fc": {
    "text": "巨大紅樹從中央裂開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-129-d5289c1af336f864": {
    "text": "CRACK!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-129-860b09e49ab9e859": {
    "text": "喀啦！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-130-c234ae3a2ee299fb": {
    "text": "Inside the tree—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-130-577fc2e6d2ba0d11": {
    "text": "而在樹裡——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-131-78b414bea32b02bd": {
    "text": "Something appeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-131-ae322e04ef55ac9a": {
    "text": "出現了一樣東西。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-132-5a74eb6647ab7e8c": {
    "text": "A floating silver crown.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-132-a4e890df029838e9": {
    "text": "一頂漂浮銀色王冠。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-133-83b2bf16e48bac29": {
    "text": "Covered in glowing symbols.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-133-10caf4ab8608a054": {
    "text": "刻滿發光符號。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-134-d7b737b5776b732a": {
    "text": "The moment Ethan saw it—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-134-e1dcaaba3edb1556": {
    "text": "伊森一看到它——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-135-e3d75bbe801580e5": {
    "text": "The silver key in his hand floated upward automatically.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-135-7229919dcab4beaf": {
    "text": "手中的銀色鑰匙立刻漂浮起來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-136-c85523c8b0b8a5a9": {
    "text": "The crown began glowing brighter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-136-4bb68286d6929335": {
    "text": "王冠開始發出強光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-137-9cf673719a0c7a66": {
    "text": "The Shadow King roared in panic.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-137-97815db3f7cbb41b": {
    "text": "暗影之王驚恐咆哮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-138-8a4efa433c9417cc": {
    "text": "“DO NOT TOUCH THE CROWN!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-138-e2fee70307227efb": {
    "text": "「不要碰王冠！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-139-47eef2122240e06c": {
    "text": "Seraphine shouted at the same time.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-139-80e9ccd39ee0e437": {
    "text": "瑟拉芬也同時大喊：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-140-2c5ef99a68f86641": {
    "text": "“Ethan, RUN!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-140-2820444bda8ce7a6": {
    "text": "「伊森，快跑！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-141-8c4c774b06b605f9": {
    "text": "But the silver key was already moving toward the crown.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-141-17883660f2ebb03a": {
    "text": "但銀色鑰匙已經開始朝王冠移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-142-68cad7121adcce4c": {
    "text": "Slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-142-5a095fb990919bed": {
    "text": "慢慢地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-143-a71f6a718bb7401c": {
    "text": "Pulled by invisible force.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-143-1e79c608fc9e1d3a": {
    "text": "像被無形力量拉過去。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-144-95003b751c364922": {
    "text": "The Hollow King’s heartbeat echoed again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-144-002d4bb679e602d4": {
    "text": "虛空之王的心跳再次響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-145-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-145-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-146-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-146-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-147-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-147-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-148-61e8919789fa9f3a": {
    "text": "And deep beneath the tower—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-148-10982fa9673ba0b1": {
    "text": "而在高塔最深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c12-en-block-149-9547404ab0ee2d74": {
    "text": "Something began rising toward them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c12-zh-block-149-292e5ffd28a8a1c3": {
    "text": "某種東西正在往上爬。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-title-472120271eeaa3e4": {
    "text": "The Crown of the Hollow King",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-title-3005b3d0f8242e90": {
    "text": "虛空之王的王冠",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-0-7a3f5d59510eae26": {
    "text": "The silver key floated through the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-0-4ade8ff41f1e3b1a": {
    "text": "銀色鑰匙漂浮在空中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-1-68cad7121adcce4c": {
    "text": "Slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-1-5a095fb990919bed": {
    "text": "慢慢地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-2-59917e41c757b88b": {
    "text": "Inevitably.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-2-c684d701165dd462": {
    "text": "無法阻止地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-3-a3ebed9fa29f0d5a": {
    "text": "Toward the glowing crown.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-3-db106c4157286add": {
    "text": "朝發光王冠飛去。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-4-35d75a18f3505a17": {
    "text": "Ethan jumped forward instinctively.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-4-efac2aa14f5d2dce": {
    "text": "伊森本能衝上前。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-5-c9d9442352006c9f": {
    "text": "“No!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-5-b0535fec5579e726": {
    "text": "「不要！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-6-b4d82b35936f251c": {
    "text": "He grabbed the key with both hands.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-6-83906f7c60aeff78": {
    "text": "他雙手抓住鑰匙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-7-2482378e9361e49b": {
    "text": "The moment his fingers touched it—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-7-3262250325ffd464": {
    "text": "就在碰到那瞬間——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-8-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-8-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-9-0786f4a5aca8d8b4": {
    "text": "A massive wave of silver energy exploded across the library.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-9-8fce57576e7cf315": {
    "text": "巨大的銀色能量席捲整座圖書館。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-10-0483b4a08787d5c8": {
    "text": "Lucy was thrown backward into a bookshelf.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-10-e0e8a200372a6a23": {
    "text": "露西被震飛撞進書架。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-11-b5085f18723f53a5": {
    "text": "Adrian barely managed to shield himself.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-11-28571bf0f08c37f8": {
    "text": "亞德里安勉強撐起護盾。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-12-c979ee9e327cddd8": {
    "text": "Seraphine raised both arms as silver fire surrounded her.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-12-d34ada5d5b17e64d": {
    "text": "瑟拉芬雙手高舉，銀火包圍全身。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-13-db03117505848e9b": {
    "text": "The giant crack beneath the library screamed with dark energy.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-13-0a2fc51c37486e05": {
    "text": "圖書館下方裂縫爆發黑暗力量。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-14-043ce191e664092b": {
    "text": "And deep below—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-14-94f8e4c294ffa12c": {
    "text": "而在深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-15-f0186488c813dd29": {
    "text": "The Hollow King laughed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-15-1c8acf55ea325719": {
    "text": "虛空之王笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-16-35c9fbec75f526a8": {
    "text": "A terrible sound.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-16-f091b296b0902a80": {
    "text": "那笑聲古老。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-17-b47c80c12cde794d": {
    "text": "Ancient.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-17-a7db08bff178a66c": {
    "text": "飢餓。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-18-5c0c2bc92329d890": {
    "text": "Hungry.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-18-85a66b9ed430c864": {
    "text": "令人發寒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-19-e5f9c6934ad7c74d": {
    "text": "The silver crown pulsed brighter.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-19-4230fd3458160c9f": {
    "text": "銀色王冠變得更亮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-20-b4f1ee78a9647d6e": {
    "text": "Ethan’s hands burned painfully around the key.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-20-684dfb92154d2f2d": {
    "text": "伊森雙手被燙得發痛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-21-924523187d676e81": {
    "text": "It felt alive.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-21-62ccddbb032811c0": {
    "text": "那把鑰匙像活著一樣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-22-03b0c6659b4e314b": {
    "text": "Like it was trying to escape him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-22-89f14315ed6aa309": {
    "text": "彷彿想掙脫他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-23-b0285d130d3da064": {
    "text": "“Ethan!” Lucy shouted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-23-fb9cb6f033902a1a": {
    "text": "「伊森！」露西大喊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-24-e12b6fbbc8e690d2": {
    "text": "“DROP IT!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-24-a95c5a32c0014d94": {
    "text": "「快放手！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-25-3aa0d2d000208ece": {
    "text": "“I CAN’T!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-25-5dad627963adee91": {
    "text": "「我辦不到！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-26-c2defa65ecf584ac": {
    "text": "The silver watch ticked wildly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-26-6224dace0e64377b": {
    "text": "銀色懷錶瘋狂滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-27-f7215333185486cd": {
    "text": "TickTickTickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-27-59611e0f2c93d5d7": {
    "text": "滴答滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-28-b20e808d1c41773a": {
    "text": "Then suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-28-932da14da57c5006": {
    "text": "接著——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-29-e8b2aea05dad7a59": {
    "text": "The glowing symbols on the key began moving.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-29-494859c0f84f0b30": {
    "text": "鑰匙上的發光符號開始移動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-30-ae04e9d44b6104ef": {
    "text": "They formed words across the silver surface.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-30-33bbaf7510592f4e": {
    "text": "形成一句話。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-31-b44228cb116dbe5c": {
    "text": "ONLY THE HEIR MAY CHOOSE.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-31-9e08a08f7e3458e2": {
    "text": "「只有繼承者能做出選擇。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-32-d484649e511dd156": {
    "text": "Ethan stared at the message.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-32-5a81b28f7ecdb0c4": {
    "text": "伊森瞪著訊息。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-33-cff5afe64a5a429c": {
    "text": "“What does that mean?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-33-34618f8723ec1098": {
    "text": "「這到底什麼意思？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-34-1f7c65ac2dc72d62": {
    "text": "The Shadow King roared from below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-34-135cbae1e0696673": {
    "text": "暗影之王從下方怒吼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-35-0816fe05b97d26c2": {
    "text": "“DESTROY THE CROWN!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-35-963a6255dce4b1d0": {
    "text": "「摧毀王冠！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-36-19bcf4eeee4aafa4": {
    "text": "Seraphine shouted immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-36-a6547faa3c3070d8": {
    "text": "瑟拉芬立刻大喊：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-37-c9d9442352006c9f": {
    "text": "“No!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-37-f43a5f97c10ce8c2": {
    "text": "「不行！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-38-6c99c08572336a53": {
    "text": "Everyone froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-38-e342cdbdfe7ce8ef": {
    "text": "所有人瞬間僵住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-39-8b7f50f40a19240d": {
    "text": "Even the Shadow King became silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-39-2990c6e216a7aafa": {
    "text": "連暗影之王都沉默。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-40-27150f7852755235": {
    "text": "Seraphine looked terrified.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-40-d92d9be7016d17df": {
    "text": "瑟拉芬看起來非常害怕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-41-e21751d84790c89f": {
    "text": "“If the crown is destroyed now…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-41-fa5cb13829564db7": {
    "text": "「如果現在毀掉王冠……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-42-990b2e63f1f34cf2": {
    "text": "“The Final Gate will collapse completely.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-42-ac5447292fa5c0fb": {
    "text": "「最終之門會立刻崩塌。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-43-53a3125b272c6be1": {
    "text": "Ethan stared at her.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-43-60e6194bf00b1996": {
    "text": "伊森瞪著她。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-44-03f1cca9849b4426": {
    "text": "“…So what are we supposed to do?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-44-176988d8bf1644cb": {
    "text": "「……那我們到底該怎麼辦？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-45-1758821645a1a39d": {
    "text": "The library shook violently again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-45-8e39185e5fb5ca63": {
    "text": "圖書館再次劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-46-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-46-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-47-eb2abf65d34c9420": {
    "text": "Another part of the ceiling collapsed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-47-d1d75b0733fa2498": {
    "text": "又一部分天花板崩塌。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-48-398d8f4ee4051238": {
    "text": "The Hollow King was getting closer.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-48-fe2bfe9a7a355d7b": {
    "text": "虛空之王越來越近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-49-4f422d51cbfcc9dd": {
    "text": "Fast.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-49-a666be3ae782eea8": {
    "text": "非常快。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-50-557614b113e16f59": {
    "text": "The giant golden eyes appeared again inside the crack.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-50-2df78d533ed48018": {
    "text": "巨大金色眼睛再次出現在裂縫深處。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-51-c11e1682c341ce07": {
    "text": "Watching Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-51-b18f9e04604a0714": {
    "text": "盯著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-52-71f7f58eeb36bb17": {
    "text": "Watching the crown.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-52-fb8db518ecb19f7c": {
    "text": "盯著王冠。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-53-0ef36d6c182a2186": {
    "text": "Watching the key.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-53-cd58384600804763": {
    "text": "盯著鑰匙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-54-82c70190598d8e42": {
    "text": "The silver crown floated slowly upward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-54-6c6a2dbd1ff86ef3": {
    "text": "銀色王冠慢慢飄起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-55-df286663f0f97de9": {
    "text": "Toward Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-55-317168b50a5f6b7a": {
    "text": "朝伊森靠近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-56-40b5c3b098560ee9": {
    "text": "Lucy backed away nervously.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-56-cce708a9cea06118": {
    "text": "露西緊張後退。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-57-413d82dec9a5ab41": {
    "text": "“That thing definitely looks cursed.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-57-3877b0daedf7a0de": {
    "text": "「那東西看起來超被詛咒。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-58-014b5fee85aef304": {
    "text": "Adrian nodded immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-58-9193ff0039052418": {
    "text": "亞德里安立刻點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-59-8d49b48c642c07e6": {
    "text": "“Yes. Extremely cursed.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-59-c013859b9b7ec4b3": {
    "text": "「對，非常被詛咒。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-60-4c0d57cea89b5fde": {
    "text": "“Thank you, very helpful.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-60-2b3274b386f33369": {
    "text": "「謝謝，你們真的很有幫助。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-61-bed5fc6d1fbf0efd": {
    "text": "The crown stopped directly in front of Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-61-250c6249e1e8022d": {
    "text": "王冠停在伊森面前。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-62-172532cfd31a45a9": {
    "text": "Silver light wrapped around him softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-62-44fa88ed3f10594f": {
    "text": "銀光柔和包圍他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-63-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-63-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-64-0964825240397aa7": {
    "text": "A voice whispered inside his head.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-64-b4e699670b9687e4": {
    "text": "有聲音在他腦中低語。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-65-4fdaf265f33f0ba4": {
    "text": "Not the Hollow King.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-65-df9be146218229b8": {
    "text": "不是虛空之王。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-66-b33f39fdc83a3013": {
    "text": "Not the Shadow King.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-66-61f45754083ba4e0": {
    "text": "不是暗影之王。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-67-b7e32f54d8977357": {
    "text": "Another voice.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-67-89f52b239652a1a0": {
    "text": "而是另一個聲音。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-68-0de8429ea9d205f7": {
    "text": "Gentle.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-68-472a736e7d946fb4": {
    "text": "溫柔。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-69-35dc7e4482cb490c": {
    "text": "Familiar.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-69-e5ae37e6bfcfb60e": {
    "text": "熟悉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-70-75333b50fb6a22bc": {
    "text": "“Ethan…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-70-f385b004225909eb": {
    "text": "「伊森……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-71-647aa134f9dd5014": {
    "text": "His heart stopped.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-71-3fba2b8ea89b7001": {
    "text": "伊森心跳瞬間停止。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-72-d778a624a4b944b4": {
    "text": "He knew that voice.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-72-554536e71e85942a": {
    "text": "他認得那聲音。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-73-48794ed6430c7022": {
    "text": "“…Dad?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-73-14304ba37208a688": {
    "text": "「……爸爸？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-74-4a3b31a9ef724864": {
    "text": "The library disappeared instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-74-831ae2edeee84e96": {
    "text": "圖書館瞬間消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-75-099433082e2183e3": {
    "text": "FLASH.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-75-3a50b0ffc783e892": {
    "text": "閃光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-76-edfbe5232444780b": {
    "text": "Ethan suddenly stood inside a different place.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-76-db798764692a916d": {
    "text": "伊森突然站在另一個地方。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-77-3098b03774e96ede": {
    "text": "A giant circular chamber beneath the tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-77-b45f7ec173b36260": {
    "text": "一座高塔底下的巨大圓形空間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-78-f3ce0d2373330359": {
    "text": "Massive silver gears turned along the walls.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-78-2b491adfef8b0b98": {
    "text": "巨大銀色齒輪沿牆轉動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-79-399f844ce8fdbec6": {
    "text": "Ancient magic symbols glowed across the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-79-24cb5bddbe30dd87": {
    "text": "古老魔法符號覆蓋地板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-80-7239d59a8ed55eab": {
    "text": "And standing in front of him—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-80-b06f59a40437bf8c": {
    "text": "而站在他面前的——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-81-7c7391351bec0914": {
    "text": "Was Daniel Parker.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-81-6c6837c6a1e5876a": {
    "text": "是丹尼爾・帕克。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-82-68e5498432c09857": {
    "text": "Alive.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-82-d57908babee2ac98": {
    "text": "活著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-83-4e4f1b93df86eefe": {
    "text": "Or at least—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-83-6713bb834b4436ca": {
    "text": "或者說——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-84-493ea91ffa7e37c9": {
    "text": "A memory of him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-84-2eadf7b228a56532": {
    "text": "某種記憶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-85-c765b5680e02126f": {
    "text": "Ethan could not breathe.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-85-cb009195212e062f": {
    "text": "伊森幾乎無法呼吸。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-86-99014b5f344322e6": {
    "text": "His father smiled sadly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-86-0146c1b5be702614": {
    "text": "父親露出悲傷微笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-87-5ab4b76bfc0c3562": {
    "text": "“You’ve grown taller.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-87-4b62fe6205d754d9": {
    "text": "「你長高了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-88-1d9a72ee078699f2": {
    "text": "Ethan’s eyes filled with tears immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-88-c837b334dc7304a5": {
    "text": "伊森眼眶瞬間泛淚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-89-48794ed6430c7022": {
    "text": "“…Dad?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-89-14304ba37208a688": {
    "text": "「……爸爸？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-90-0dab1719de33e5f0": {
    "text": "Daniel stepped closer slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-90-7fbf6ccc8e2fe847": {
    "text": "丹尼爾慢慢靠近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-91-c9e400c6963b0056": {
    "text": "“I’m sorry.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-91-f44cf03c274b50e7": {
    "text": "「對不起。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-92-6d8de8dcf0a6c5e8": {
    "text": "“For everything.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-92-c0ac0129d22f56ac": {
    "text": "「對不起所有事情。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-93-e855381887ac5ad2": {
    "text": "Ethan’s chest hurt painfully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-93-766a02664576679a": {
    "text": "伊森胸口痛得厲害。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-94-5d1a66d4d7948e96": {
    "text": "“You disappeared.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-94-76f40a8c155e4bc6": {
    "text": "「你消失了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-95-918fc5f8659139c2": {
    "text": "“I know.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-95-ca5635651b6192f7": {
    "text": "「我知道。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-96-47548a82d2bad799": {
    "text": "“You left me.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-96-3d6d6bc7e31108f4": {
    "text": "「你丟下我。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-97-53b1b78a3e65e613": {
    "text": "Daniel closed his eyes briefly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-97-3c9d3ae2307e692b": {
    "text": "丹尼爾閉上眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-98-c44af7825ea44898": {
    "text": "“I never wanted to.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-98-125b0aec92bffe45": {
    "text": "「我從來不想這樣。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-99-9cdca43469395ab8": {
    "text": "The silver watch floated between them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-99-922de5799a9c3aad": {
    "text": "銀色懷錶漂浮在兩人之間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-100-0e136fab5b298534": {
    "text": "Glowing softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-100-2e4d2ab90ef83e20": {
    "text": "發出柔光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-101-763255c8dd756bac": {
    "text": "Daniel touched it gently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-101-05e08bb2b1883f40": {
    "text": "丹尼爾輕輕碰它。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-102-a037129d5bab6968": {
    "text": "“The watch contains part of my memory.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-102-ce1f4fcc84d92590": {
    "text": "「懷錶裡保留了我的部分記憶。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-103-3548a47bca6febf8": {
    "text": "“So that one day…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-103-9deaf01504d9fddb": {
    "text": "「這樣有一天……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-104-9693831c69a03b1b": {
    "text": "“I could speak to you.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-104-d6d3d6b8f894a54d": {
    "text": "「我才能和你說話。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-105-8afcdc44e7e277b3": {
    "text": "Ethan’s voice shook.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-105-29c89739c8adeaaf": {
    "text": "伊森聲音發抖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-106-0683e02bba56114f": {
    "text": "“What is happening?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-106-b04f926bb56ef428": {
    "text": "「到底發生什麼事？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-107-51d225079905acb4": {
    "text": "Daniel looked upward toward the unseen tower above.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-107-613a0bdcaab41a51": {
    "text": "丹尼爾抬頭看向不存在的高塔。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-108-c8dbee988cc93265": {
    "text": "“The prison is failing.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-108-8eef45e683897b77": {
    "text": "「監獄正在崩壞。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-109-39a9c8eddf67094a": {
    "text": "“The Hollow King is waking.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-109-e9f165515971cb70": {
    "text": "「虛空之王正在甦醒。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-110-be72e130add792ee": {
    "text": "Ethan swallowed hard.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-110-d7b281d380dbeed2": {
    "text": "伊森吞口水。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-111-e237a916fdab7197": {
    "text": "“What IS the Hollow King?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-111-d94951c06a607971": {
    "text": "「虛空之王到底是什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-112-e1fbc6a557769bb4": {
    "text": "Daniel became silent for a moment.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-112-83be33336aa29c4a": {
    "text": "丹尼爾沉默片刻。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-113-c38e8ebf98e80537": {
    "text": "Then he answered quietly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-113-2765ec3304c2c39c": {
    "text": "然後低聲說：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-114-b5d1a6839ad7719a": {
    "text": "“Something that should never have existed.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-114-09c45c2bcc385a5c": {
    "text": "「某種本來就不該存在的東西。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-115-618312b635bdb925": {
    "text": "The giant gears around the chamber slowed heavily.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-115-30cd3e0cbe2de63e": {
    "text": "巨大齒輪開始變慢。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-116-df4e3f49766ad080": {
    "text": "CLUNK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-116-1be230c49971759b": {
    "text": "喀噹。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-117-df4e3f49766ad080": {
    "text": "CLUNK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-117-1be230c49971759b": {
    "text": "喀噹。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-118-df4e3f49766ad080": {
    "text": "CLUNK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-118-1be230c49971759b": {
    "text": "喀噹。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-119-69460342df5e8355": {
    "text": "Daniel’s expression darkened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-119-3ec9d4ad8f9b410c": {
    "text": "丹尼爾表情變沉重。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-120-48b8716c81ce0685": {
    "text": "“The First Keepers made a terrible mistake.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-120-b4dabd2e7fd7e073": {
    "text": "「初代守護者犯了一個巨大錯誤。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-121-13988783fb807ca3": {
    "text": "“They believed they could control the Hollow King.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-121-2d27305f579e8b0c": {
    "text": "「他們以為自己能控制虛空之王。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-122-e996dd94f96fefe3": {
    "text": "“They were wrong.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-122-74f7163e9cdf5eea": {
    "text": "「但他們錯了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-123-3e4db107abd1c3a0": {
    "text": "Ethan looked at the silver crown now floating nearby.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-123-ec1095e23ec577dc": {
    "text": "伊森看向漂浮王冠。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-124-d11da159971d13fe": {
    "text": "“And the crown?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-124-3b0bac55c0ef7ff2": {
    "text": "「那王冠呢？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-125-7310784dff0b307d": {
    "text": "Daniel stared at it carefully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-125-67f2ed930bd46737": {
    "text": "丹尼爾仔細盯著它。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-126-86d8fefe63e405e0": {
    "text": "“The crown controls the Final Gate.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-126-10d3b6bf6c2a049f": {
    "text": "「王冠控制最終之門。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-127-5d9d8290372f6d4b": {
    "text": "“If the wrong person wears it…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-127-3755103dacdaee7f": {
    "text": "「如果錯誤的人戴上它……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-128-7a4854321fc419f5": {
    "text": "His voice became serious.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-128-71f2db70ea0438a9": {
    "text": "他的聲音變嚴肅。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-129-554ae844e07a4aaf": {
    "text": "“…the prison opens.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-129-3f6965a6dafcc95f": {
    "text": "「……監獄會被打開。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-130-13073d7acb062ba3": {
    "text": "Ethan’s stomach tightened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-130-c38e22fdcc899797": {
    "text": "伊森胃部發緊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-131-cf1bda3290c1e6f0": {
    "text": "“And if the right person wears it?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-131-368fce230391ce6e": {
    "text": "「那如果正確的人戴上？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-132-66749d7f638c34a0": {
    "text": "Daniel looked directly into Ethan’s eyes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-132-0fc6fd80d1ad5c36": {
    "text": "丹尼爾直視伊森雙眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-133-2220048ef00ce64f": {
    "text": "“…Then the prison can be sealed forever.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-133-8cc81f04f17012ba": {
    "text": "「……監獄就能永遠封閉。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-134-a2dae5e558207c49": {
    "text": "Silence filled the chamber.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-134-be57254745282403": {
    "text": "安靜充滿整個空間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-135-1b5108d65b3f8a44": {
    "text": "Ethan stared at the crown.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-135-a121fa65e9a13878": {
    "text": "伊森看著王冠。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-136-0c88aea05d151722": {
    "text": "Then at his father.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-136-217c4e1b2339f81f": {
    "text": "又看向父親。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-137-b0d48d7bff5ad50c": {
    "text": "“You want ME to wear that thing?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-137-cdb7e301456e38d3": {
    "text": "「你要我戴那個東西？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-138-5f30d71d1eadfdcf": {
    "text": "Daniel almost smiled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-138-02b745ed33fcf95f": {
    "text": "丹尼爾差點笑出來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-139-aea98557dbc9d8fc": {
    "text": "“I know. Terrible plan.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-139-46a76b9929bf1847": {
    "text": "「我知道，很糟糕的計畫。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-140-04a021fc39b2b92e": {
    "text": "“THIS SCHOOL HAS ONLY TERRIBLE PLANS!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-140-37ba5f29600c4214": {
    "text": "「這學校根本只有糟糕計畫！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-141-8de8a656e2c29220": {
    "text": "For the first time—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-141-f34020f63d9ecb89": {
    "text": "第一次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-142-7746a3da1b123a1c": {
    "text": "Daniel actually laughed softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-142-0b91bab219f390ec": {
    "text": "丹尼爾真的笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-143-a55a73f4687dcdcb": {
    "text": "The sound hurt Ethan’s heart even more.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-143-c18c0e83c0966fb1": {
    "text": "那笑聲讓伊森胸口更痛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-144-7e56d3525669ef92": {
    "text": "Because it felt real.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-144-21d8b3f8eea08582": {
    "text": "因為太真實了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-145-b9872dfd5737b9fa": {
    "text": "Too real.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-145-76fdecbbf32a6fb4": {
    "text": "接著丹尼爾表情再次變嚴肅。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-146-9b08c3303e9eca6c": {
    "text": "Then Daniel’s expression became serious again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-146-76fdecbbf32a6fb4": {
    "text": "接著丹尼爾表情再次變嚴肅。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-147-d5abadec25a0ad5c": {
    "text": "“There’s something else you must know.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-147-e63334de937695a2": {
    "text": "「還有一件事你必須知道。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-148-024a71e789d1182a": {
    "text": "“The tower itself is alive.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-148-ee696ed75ca43167": {
    "text": "「高塔本身是活的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-149-641a78e1b01c7f32": {
    "text": "Ethan froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-149-8d885feee9177340": {
    "text": "伊森瞬間僵住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-150-389fc6b7ff4276ec": {
    "text": "“…What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-150-0e6d1d8c21b20b5e": {
    "text": "「……什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-151-a8034af89584fa22": {
    "text": "“It chooses Keepers.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-151-88daad3b37853674": {
    "text": "「它會選擇守護者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-152-02af1e4b0f108253": {
    "text": "“It watches.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-152-b294aab336ae8d31": {
    "text": "「它會注視。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-153-290c73fca2de2cde": {
    "text": "“It remembers.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-153-2380eab959ae8d4b": {
    "text": "「它會記憶。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-154-18f33ed7662f2179": {
    "text": "The silver watch ticked once.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-154-d415b4239e9694b6": {
    "text": "銀色懷錶滴答一聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-155-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-155-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-156-250a2d693d0bcb2e": {
    "text": "Daniel looked toward the darkness behind Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-156-bc1dea728a5a56e4": {
    "text": "丹尼爾看向伊森身後的黑暗。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-157-e23a874efe40cf1e": {
    "text": "“And sometimes…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-157-021e347551455aef": {
    "text": "「而有時候……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-158-486e05d497909092": {
    "text": "“It lies.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-158-a75f32ca7dc36668": {
    "text": "「它會說謊。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-159-c99291e636970a92": {
    "text": "Cold fear spread through Ethan instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-159-c833a1713a984c29": {
    "text": "冰冷恐懼瞬間蔓延伊森全身。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-160-92051462668e1037": {
    "text": "Before he could ask another question—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-160-f1aaf165c3593448": {
    "text": "但他還來不及繼續問——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-161-01d14185653dcf63": {
    "text": "The chamber shook violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-161-c75d7e5cf69879e1": {
    "text": "整個空間劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-162-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-162-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-163-8ea14d0ea2200d75": {
    "text": "Dark cracks spread across the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-163-a46e937fcc24e4d2": {
    "text": "黑色裂痕覆蓋地板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-164-2f92b113178b9e9e": {
    "text": "Daniel looked upward sharply.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-164-def35d6258fc2b0b": {
    "text": "丹尼爾猛然抬頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-165-7c387c5f8e40517f": {
    "text": "“No…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-165-92141de36152d128": {
    "text": "「不……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-166-8211e925cdb05a5b": {
    "text": "The Hollow King’s roar echoed through the chamber.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-166-50e0d7d773bc69bd": {
    "text": "虛空之王的咆哮傳遍整個空間。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-167-f67cd8d54d9ff84c": {
    "text": "The prison was breaking faster now.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-167-6857683b6450abef": {
    "text": "監獄正在更快速崩壞。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-168-63578e27c64f862e": {
    "text": "Daniel stepped backward slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-168-0d1358396e142a1d": {
    "text": "丹尼爾慢慢後退。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-169-1175cf6225e87cd7": {
    "text": "His body already beginning to fade.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-169-0f413d47dd3a4ffe": {
    "text": "身體已經開始像煙霧般消散。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-170-00d9a2700e119cc4": {
    "text": "“Dad?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-170-4583af9523be77a5": {
    "text": "「爸爸？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-171-efda8a2cbc624530": {
    "text": "Daniel looked at Ethan one last time.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-171-dc123d7d9919ec60": {
    "text": "丹尼爾最後看著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-172-38a24d824d8031a9": {
    "text": "“You must choose carefully.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-172-1da542d41ac646e3": {
    "text": "「你必須謹慎選擇。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-173-8254ddc8253794a4": {
    "text": "“The tower will ask for a sacrifice.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-173-14b716626852d7e3": {
    "text": "「高塔會要求犧牲。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-174-c373b9746a4adfc7": {
    "text": "His form flickered like smoke.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-174-2dbcbcc45e5127e0": {
    "text": "他的身影像煙霧般閃爍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-175-061efab306939034": {
    "text": "“And Ethan…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-175-d4eb1c8a4304a4da": {
    "text": "「還有，伊森……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-176-1ec0f2b20626a81c": {
    "text": "Ethan’s voice trembled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-176-e7e29c61c91b8f88": {
    "text": "伊森聲音顫抖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-177-5442659457095c55": {
    "text": "“What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-177-5ab60aad745f2829": {
    "text": "「什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-178-94d74848afef601e": {
    "text": "Daniel smiled sadly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-178-5172d30d34512c88": {
    "text": "丹尼爾露出悲傷微笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-179-933fd51f9bdc7efd": {
    "text": "“I never stopped trying to come home.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-179-da2009d695351741": {
    "text": "「我從來沒有停止想回家。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-180-099433082e2183e3": {
    "text": "FLASH.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-180-3a50b0ffc783e892": {
    "text": "閃光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-181-ac6cc52fdd42c4d4": {
    "text": "The chamber vanished.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-181-243da962e38c419d": {
    "text": "整個空間消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-182-492100d05e8f346f": {
    "text": "Ethan crashed back into the library.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-182-4ec9f462a13b9d45": {
    "text": "伊森重重回到圖書館。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-183-f8e7e8c38577ea48": {
    "text": "The silver crown floated inches from his face.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-183-e33bb63c580588cb": {
    "text": "銀色王冠漂浮在他面前。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-184-4409a7e0730a03f4": {
    "text": "The Hollow King roared beneath the tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-184-e6bebdc67b2a6e9c": {
    "text": "虛空之王在高塔下咆哮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c13-en-block-185-c3e9fb4a5f3f2f91": {
    "text": "And the silver key in Ethan’s hand began unlocking the crown.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c13-zh-block-185-cddabb0cb95464cf": {
    "text": "而伊森手中的銀色鑰匙，開始解開王冠封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-title-18f05dfcfde4807f": {
    "text": "The Choice of the Heir",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-title-edbca9b391ccca1c": {
    "text": "繼承者的選擇",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-0-0dd175ab100e45c3": {
    "text": "CLICK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-0-019792da7b48e033": {
    "text": "喀嚓。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-1-f0703a33de4a48ac": {
    "text": "The silver key turned by itself inside the crown.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-1-77f7dc1aee4cdfd6": {
    "text": "銀色鑰匙自己在王冠裡轉動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-2-6e6b27569f00479e": {
    "text": "Ancient symbols burst into glowing light.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-2-487aac1e52544015": {
    "text": "古老符號爆發耀眼光芒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-3-cfc8a1109ed50ce5": {
    "text": "The entire library trembled violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-3-94912941e88b22f5": {
    "text": "整座圖書館劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-4-4409a7e0730a03f4": {
    "text": "The Hollow King roared beneath the tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-4-e6bebdc67b2a6e9c": {
    "text": "虛空之王在高塔下咆哮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-5-3617012b560319bd": {
    "text": "Books exploded from shelves.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-5-7e6aecd8796d6c27": {
    "text": "書本從書架炸飛。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-6-06c050703612fc40": {
    "text": "Silver chains snapped apart one after another.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-6-5a5d6ab9a37e89c1": {
    "text": "銀色鎖鏈一條條崩裂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-7-f9f3f2d0891bfd70": {
    "text": "CLANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-7-690a1a50186dfe69": {
    "text": "鏘！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-8-f9f3f2d0891bfd70": {
    "text": "CLANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-8-690a1a50186dfe69": {
    "text": "鏘！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-9-f9f3f2d0891bfd70": {
    "text": "CLANG!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-9-690a1a50186dfe69": {
    "text": "鏘！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-10-beb4df602e0818c2": {
    "text": "Lucy struggled to stand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-10-d93ed3dfa2d4c284": {
    "text": "露西勉強站穩。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-11-c149f3ccbabc0c46": {
    "text": "“ETHAN!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-11-f2f61c144365392f": {
    "text": "「伊森！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-12-d17ef362eeb8d477": {
    "text": "Adrian grabbed onto a collapsing bookshelf.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-12-5673032b9632b8eb": {
    "text": "亞德里安抓住倒塌書架。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-13-13589e20d273764c": {
    "text": "“Stop the crown!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-13-db94db0b5b4892ce": {
    "text": "「阻止王冠！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-14-a3f00cee6ec420fd": {
    "text": "“I’M TRYING!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-14-94126ff2fc9812ff": {
    "text": "「我正在試！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-15-20d81d7b20125555": {
    "text": "But the key continued turning.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-15-9445f9acee943299": {
    "text": "但鑰匙依然持續轉動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-16-68cad7121adcce4c": {
    "text": "Slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-16-5a095fb990919bed": {
    "text": "慢慢地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-17-59917e41c757b88b": {
    "text": "Inevitably.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-17-c684d701165dd462": {
    "text": "無法阻止地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-18-3d9c20710480721a": {
    "text": "The silver crown floated upward above Ethan’s head.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-18-e1b92f4bcde6e61a": {
    "text": "銀色王冠漂浮到伊森頭頂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-19-ff8ca5cfaa836c3a": {
    "text": "The glowing symbols around it formed a giant circle in the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-19-80dadbb28be5d809": {
    "text": "周圍符號形成巨大光圈。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-20-78b940ca33089571": {
    "text": "Seraphine’s mechanical eye flashed red.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-20-9739305f0cdabbbc": {
    "text": "瑟拉芬的機械眼閃爍紅光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-21-e1a237ba5bcbc6bb": {
    "text": "“The Final Gate is opening!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-21-8a40482860564832": {
    "text": "「最終之門正在開啟！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-22-2a2b11b854c57313": {
    "text": "Deep below the crack—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-22-7a38f87b179b3ce8": {
    "text": "裂縫深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-23-99c7ea238403afe2": {
    "text": "Massive golden light pulsed upward.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-23-f8bd3c4c6ad3a348": {
    "text": "巨大金光往上脈動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-24-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-24-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-25-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-25-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-26-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-26-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-27-0f4ca8ff94ec79dd": {
    "text": "Each heartbeat shook the entire school.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-27-efadd8666b3b9390": {
    "text": "每一下心跳都讓整間學校震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-28-c260672b035b96be": {
    "text": "Far above the library, giant tower bells began ringing wildly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-28-e797a9615a9b00eb": {
    "text": "圖書館上方，高塔鐘聲瘋狂響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-29-f56db54e9137cbed": {
    "text": "DONGGGGG—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-29-e3a6a0b2696365cb": {
    "text": "噹————",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-30-f56db54e9137cbed": {
    "text": "DONGGGGG—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-30-e3a6a0b2696365cb": {
    "text": "噹————",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-31-6e5476895e13fdcd": {
    "text": "Students screamed somewhere far above.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-31-6cc4bb62bdecd058": {
    "text": "遠處傳來學生尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-32-66a7034cbeda4730": {
    "text": "The entire Clock Tower Magic School was shaking apart.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-32-fc800740e5607284": {
    "text": "整座時鐘塔魔法學院正在崩塌。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-33-1f7c65ac2dc72d62": {
    "text": "The Shadow King roared from below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-33-135cbae1e0696673": {
    "text": "暗影之王從下方怒吼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-34-a0f1b95111391b3d": {
    "text": "“CHOOSE NOW, HEIR!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-34-15991de783561139": {
    "text": "「做出選擇吧，繼承者！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-35-1b5108d65b3f8a44": {
    "text": "Ethan stared at the crown.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-35-eb9834ec09530372": {
    "text": "伊森盯著王冠。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-36-7dacf6ac91c1f5c9": {
    "text": "His father’s words echoed inside his mind.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-36-b4b1cc0f72bd7f59": {
    "text": "父親的話在腦中迴響。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-37-a561ea341080ef69": {
    "text": "The tower will ask for a sacrifice.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-37-40427a94b535d769": {
    "text": "高塔會要求犧牲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-38-0f84bdc875b17518": {
    "text": "The silver watch suddenly displayed two glowing messages.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-38-2dbcab7b50a8608b": {
    "text": "銀色懷錶突然顯示兩行文字。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-39-a92f0492fb732b44": {
    "text": "SEAL THE GATE\nOR\nOPEN THE PRISON",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-39-2349b1883389eb16": {
    "text": "「封閉大門」\n或者\n「打開監獄」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-40-19e6b540af5cb9b6": {
    "text": "Ethan’s breathing stopped.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-40-6d3e58a08f21d12d": {
    "text": "伊森呼吸停止。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-41-1d7f4c7ed2e22f7d": {
    "text": "“…That’s not a choice.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-41-df6c1e8e86c1a582": {
    "text": "「……這根本不是選擇。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-42-64c013a03fffa0a5": {
    "text": "Lucy looked horrified.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-42-466251e016ef947b": {
    "text": "露西驚恐看著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-43-cff5afe64a5a429c": {
    "text": "“What does that mean?!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-43-34dbf0360e4b8c58": {
    "text": "「那到底是什麼意思？！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-44-81ef332fbb382751": {
    "text": "Seraphine’s voice trembled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-44-8f4dd297eae77d17": {
    "text": "瑟拉芬聲音顫抖。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-45-24a3c7f9fb6a26d6": {
    "text": "“If Ethan seals the gate…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-45-f02e2b4587a6349c": {
    "text": "「如果伊森封閉大門……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-46-f3a96fc32bfd756d": {
    "text": "“The Hollow King remains imprisoned.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-46-51b035843840125c": {
    "text": "「虛空之王會繼續被封印。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-47-014d18b7a649c7b5": {
    "text": "Adrian looked at her sharply.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-47-f0ca73964cbd049a": {
    "text": "亞德里安立刻追問。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-48-6deee12bf1828056": {
    "text": "“And if he opens it?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-48-8ab8f58a581e8ad7": {
    "text": "「那如果打開？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-49-42caaf875bd101d6": {
    "text": "Silence.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-49-833204688b72a129": {
    "text": "安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-50-6fa5e22f6ab49ee5": {
    "text": "Terrible silence.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-50-759b049daff57144": {
    "text": "可怕的安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-51-7fad3564893ff8e7": {
    "text": "Then Seraphine answered quietly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-51-25fcb468e5237ea5": {
    "text": "然後瑟拉芬低聲回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-52-34840ed6a0c1b5f5": {
    "text": "“The prison breaks.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-52-6315ebaf8eea191d": {
    "text": "「監獄會崩壞。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-53-5d797b06939f2edf": {
    "text": "“And the Hollow King enters our world.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-53-367f1b229b6e6fac": {
    "text": "「虛空之王會進入我們世界。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-54-ee43fcf9b6562a78": {
    "text": "The library floor cracked wider.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-54-1847c930c39d1a0e": {
    "text": "圖書館地板裂得更大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-55-92de3424d4a2e1fa": {
    "text": "A gigantic golden claw slowly rose from the darkness below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-55-0dace9b7f29f9824": {
    "text": "一隻巨大金色利爪從黑暗中慢慢升起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-56-031288d02dc847d2": {
    "text": "Far larger than any human.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-56-92c8d2778dee30b0": {
    "text": "比人類巨大太多。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-57-c6c4cae4ee5e65eb": {
    "text": "Covered in ancient glowing scars.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-57-f1fdb88091779942": {
    "text": "布滿古老傷痕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-58-55ce093354d7852b": {
    "text": "Lucy backed away in terror.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-58-50b7caa0a03bb6bb": {
    "text": "露西恐懼後退。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-59-2253c6b2d4d8fb41": {
    "text": "“Oh no.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-59-ae2afbc5f6966442": {
    "text": "「不妙……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-60-6bbb4f98f0ce96bc": {
    "text": "The Hollow King was reaching upward now.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-60-1859036317122ccb": {
    "text": "虛空之王已經開始往上爬。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-61-f36082274e07bddf": {
    "text": "Almost free.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-61-55eaaad973c8ba84": {
    "text": "幾乎快自由了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-62-5fb53435bc84a7f4": {
    "text": "The silver crown floated lower toward Ethan’s head.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-62-01d7b52bb6120577": {
    "text": "銀色王冠慢慢往伊森頭上降下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-63-c2e0fe853ed0c075": {
    "text": "The moment it touched him—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-63-607d98e731d85826": {
    "text": "當它碰到伊森那瞬間——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-64-8b38847899edc6db": {
    "text": "Silver light exploded across his vision.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-64-5f4fc99864680107": {
    "text": "銀光覆蓋視線。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-65-099433082e2183e3": {
    "text": "FLASH.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-65-3a50b0ffc783e892": {
    "text": "閃光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-66-e56f7b4bfede7d0c": {
    "text": "Suddenly Ethan could see everything.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-66-b770186656267226": {
    "text": "突然間，伊森看見了一切。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-67-57fe95f40d4399dc": {
    "text": "The entire tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-67-f1dfa1579b7fc787": {
    "text": "整座高塔。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-68-795b6a9334b3e2ef": {
    "text": "Every clock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-68-e92baeffd26f0f7a": {
    "text": "所有時鐘。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-69-6c5bb4895fb0dce2": {
    "text": "Every magical seal beneath the school.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-69-9db07abee21ea5cb": {
    "text": "學校地下所有封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-70-75251958975a72e9": {
    "text": "The prison.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-70-e3e0f7bb266acfd4": {
    "text": "監獄。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-71-5d55ced4335688a2": {
    "text": "The Hollow King sleeping in darkness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-71-c453d094b672eed1": {
    "text": "沉睡在黑暗中的虛空之王。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-72-dfa53a54a6a8027c": {
    "text": "And above all—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-72-d08591ee91966914": {
    "text": "以及——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-73-640629d7c3a581f4": {
    "text": "The tower itself.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-73-6da86bb538e52c3b": {
    "text": "高塔本身。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-74-68e5498432c09857": {
    "text": "Alive.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-74-d57908babee2ac98": {
    "text": "活著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-75-1171924c281c4a64": {
    "text": "Watching him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-75-0253c9ad3ac4a66b": {
    "text": "正在看著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-76-97f3679fe7cca177": {
    "text": "A giant voice filled Ethan’s mind.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-76-0c64c8ea616df77c": {
    "text": "巨大聲音在伊森腦中響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-77-92adf07e51330688": {
    "text": "AN HEIR MUST CHOOSE.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-77-5b91663b9892029c": {
    "text": "「繼承者必須做出選擇。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-78-3a28f8002f512bb0": {
    "text": "Ethan realized the horrifying truth.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-78-27eff61ac9765a90": {
    "text": "伊森終於明白真相。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-79-36d1c56f5139be41": {
    "text": "The tower was not protecting the world.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-79-147f091aa3e15506": {
    "text": "高塔並不是在保護世界。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-80-eaff4e34b64e2afd": {
    "text": "It was protecting itself.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-80-fabae5f2f1d4d767": {
    "text": "它是在保護自己。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-81-40f6deed07d648c3": {
    "text": "The Hollow King was its prisoner.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-81-d81303a5885c8bd9": {
    "text": "虛空之王是它的囚犯。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-82-1e1dd270cd2938ba": {
    "text": "And Ethan—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-82-f91f29c080e724cd": {
    "text": "而伊森——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-83-dfdfb7d3bcdb1697": {
    "text": "Was meant to become the next lock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-83-c7f3cbf8e54269aa": {
    "text": "本來要成為下一個封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-84-6f31bb1ec2b22c4a": {
    "text": "Forever.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-84-3de39381757cd1ca": {
    "text": "永遠。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-85-0140a63ffb3e179a": {
    "text": "The giant voice continued.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-85-5a5c8bd87b9ef6c5": {
    "text": "巨大聲音再次響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-86-a11b470483956f7f": {
    "text": "WEAR THE CROWN.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-86-57231e3f91fd698d": {
    "text": "「戴上王冠。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-87-9426c3a188c307fe": {
    "text": "BECOME THE SEAL.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-87-886a216ed2d0549a": {
    "text": "「成為封印。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-88-41fa714a11c8313c": {
    "text": "SAVE THE WORLD.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-88-4c7426008873f959": {
    "text": "「拯救世界。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-89-817d395beac6e924": {
    "text": "Ethan’s heart pounded painfully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-89-e58d88474de4770d": {
    "text": "伊森胸口劇烈跳動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-90-7e28159d47daa0c3": {
    "text": "“…Forever?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-90-11b2968180384031": {
    "text": "「……永遠？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-91-8c34c0f37634943b": {
    "text": "The voice answered calmly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-91-4733beede5c303a3": {
    "text": "聲音平靜回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-92-b2fe87e4c63e1cde": {
    "text": "UNTIL THE END OF TIME.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-92-76641b22a85daf2e": {
    "text": "「直到時間終結。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-93-c74cadf94f33696d": {
    "text": "Fear spread through Ethan completely.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-93-d0cf2618d7b73de9": {
    "text": "恐懼瞬間吞沒伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-94-e956c402edab49f2": {
    "text": "He was only a student.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-94-dd913c6019c771c9": {
    "text": "他只是學生。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-95-e4fcd7d13290e8f4": {
    "text": "Only a boy.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-95-ec294d3d3fdad1ee": {
    "text": "只是個男孩。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-96-b74f3040e8f4cf50": {
    "text": "He didn’t want to disappear inside a prison forever.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-96-46dfc5a8fa4a59f4": {
    "text": "他不想永遠消失在監獄裡。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-97-bbe8556a458590ba": {
    "text": "But below him—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-97-98cfbe4123f11118": {
    "text": "但在他下方——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-98-2ce4edcc4ca1c186": {
    "text": "The Hollow King was awakening.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-98-74da456036ab84bd": {
    "text": "虛空之王正在甦醒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-99-02ff4bc1fd6b64eb": {
    "text": "The school was collapsing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-99-8d2e2d354a6fa8fc": {
    "text": "學校正在崩塌。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-100-5a95b0c0c6ebefc5": {
    "text": "People would die.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-100-67a1fb6dc77821a6": {
    "text": "會有人死掉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-101-b2d244f1de7a4a1d": {
    "text": "Lucy suddenly shouted through the chaos:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-101-544cbb73470a2da5": {
    "text": "就在這時，露西在混亂中大喊：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-102-c149f3ccbabc0c46": {
    "text": "“ETHAN!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-102-f2f61c144365392f": {
    "text": "「伊森！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-103-341aae272430da33": {
    "text": "“You’re not alone!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-103-f269c83d45070b65": {
    "text": "「你不是一個人！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-104-508ad228ec610063": {
    "text": "Adrian stepped forward despite the shaking floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-104-3c352158e6e778bf": {
    "text": "亞德里安即使站在正在崩塌的地板上，也往前一步。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-105-80c795603237ba9c": {
    "text": "“We’ll find another way!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-105-010df34e9ca6e6fc": {
    "text": "「我們一定能找到別的方法！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-106-271c762952f9586c": {
    "text": "The tower voice thundered again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-106-2d4d173c06f1b656": {
    "text": "高塔聲音再次轟鳴。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-107-2fd241a3c91c1bb4": {
    "text": "THERE IS NO OTHER WAY.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-107-433be084cbca10e5": {
    "text": "「沒有其他方法。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-108-6f2e1b407dbeabd2": {
    "text": "The silver crown descended slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-108-9efe3199af0c18ad": {
    "text": "銀色王冠慢慢降下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-109-6bde392af93a7912": {
    "text": "Closer.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-109-d662ba97c62dba65": {
    "text": "越來越近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-110-6bde392af93a7912": {
    "text": "Closer.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-110-fd11ff1fcb71c5ab": {
    "text": "伊森閉緊雙眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-111-fb03fbb018e44fb7": {
    "text": "Ethan closed his eyes tightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-111-a7e5d1480ab447e1": {
    "text": "他想起奶奶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-112-c010d55e1cb19341": {
    "text": "He remembered his grandmother.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-112-a699412daabdeae4": {
    "text": "想起父親。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-113-40ab726392d5d099": {
    "text": "His father.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-113-88c1917d4110048f": {
    "text": "想起列車。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-114-24397df677adfa0f": {
    "text": "The train.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-114-d6431ce3ff9b907b": {
    "text": "想起第一天來學校。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-115-b911b7ee35c6abbc": {
    "text": "His first day at the school.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-115-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-116-dda37c734c361181": {
    "text": "Then he remembered something else.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-116-d5cb9f90f8b7e3f7": {
    "text": "他又想起另一件事。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-117-b84f7b6cd7d203b2": {
    "text": "His father’s final warning.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-117-30ac33837d7146b2": {
    "text": "父親最後警告。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-118-1bc83f9267baa5b2": {
    "text": "Do not trust the tower completely.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-118-9fe0e15a39a66961": {
    "text": "「不要完全相信高塔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-119-e8d08aa36a63778d": {
    "text": "Ethan’s eyes opened instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-119-77cd0c7bd069e554": {
    "text": "伊森瞬間睜眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-120-d5c65d060512eee3": {
    "text": "The tower had lied before.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-120-34dd0836917bdbe0": {
    "text": "高塔曾經說過謊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-121-dfe17f37a73cd55e": {
    "text": "So maybe—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-121-66791539fbcaf8e4": {
    "text": "那麼——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-122-9534c6faad8e1f5a": {
    "text": "This was not the only choice.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-122-f11076a932d9c5f6": {
    "text": "現在也可能不是唯一選擇。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-123-0e8a6a4bf642e08b": {
    "text": "The silver watch suddenly glowed wildly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-123-ff3352f0f1e7f67a": {
    "text": "銀色懷錶突然瘋狂發光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-124-f7215333185486cd": {
    "text": "TickTickTickTickTick—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-124-59611e0f2c93d5d7": {
    "text": "滴答滴答滴答——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-125-954672ca6f30908f": {
    "text": "A hidden symbol appeared inside the crown.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-125-4283d8bf01029d6f": {
    "text": "王冠內部浮現隱藏符號。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-126-f5da255e414b3c45": {
    "text": "A second lock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-126-6a8a4d93f14c7e9a": {
    "text": "第二道封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-127-03bfef934b5dda21": {
    "text": "Hidden deep within it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-127-72928d446296ee53": {
    "text": "藏得很深。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-128-d4872d13511d68c1": {
    "text": "Ethan stared in shock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-128-c4363ac3633480ce": {
    "text": "伊森震驚看著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-129-ed470e79165fbe4b": {
    "text": "“…Wait.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-129-4ee7e7f5cb8d1e7f": {
    "text": "「……等等。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-130-a82ff7a351422c3d": {
    "text": "Seraphine saw it too.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-130-0bf8a54efa266731": {
    "text": "瑟拉芬也看見了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-131-a2dd280a3ee4f044": {
    "text": "Her mechanical eye widened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-131-e07e8359be9a67e9": {
    "text": "她的機械眼睜大。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-132-5b98bc6e243860a3": {
    "text": "“That symbol…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-132-811418ffa86fc11e": {
    "text": "「那個符號……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-133-bc237b57dc41e677": {
    "text": "The Shadow King suddenly roared:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-133-f9ef1bf04da412b2": {
    "text": "暗影之王突然怒吼：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-134-3013ec92c9905649": {
    "text": "“THE SECOND SEAL!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-134-f61277b23b13556c": {
    "text": "「第二封印！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-135-a09c3ccce44c6aff": {
    "text": "The Hollow King’s giant claw froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-135-411c59acf89b2b5e": {
    "text": "虛空之王的巨大爪子瞬間停住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-136-3b631fadb18d9893": {
    "text": "The tower voice became furious.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-136-7bdac63a6720c450": {
    "text": "高塔聲音變得憤怒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-137-d0050d8a3b86cdc7": {
    "text": "NO.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-137-f1dca4b0e2227775": {
    "text": "「不。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-138-5b8742b6f5487615": {
    "text": "DO NOT TOUCH IT.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-138-07aa36b42e1eefe8": {
    "text": "「不要碰它。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-139-59cab60aaee18f52": {
    "text": "Ethan’s heart raced.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-139-e4a40f6e4a397919": {
    "text": "伊森心跳加速。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-140-a156fd72d968f063": {
    "text": "The tower was afraid.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-140-69629c10bbd0c5bf": {
    "text": "高塔在害怕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-141-ab6455d7159d8f9a": {
    "text": "That meant this mattered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-141-a93cacf64e19c7f8": {
    "text": "這代表——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-142-044f7c650f933c42": {
    "text": "A lot.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-142-288561cd599f1c79": {
    "text": "那真的很重要。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-143-3e972cf3ddfd21c1": {
    "text": "“What happens if I break the second seal?!” Ethan shouted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-143-0a190dd020bc4b6c": {
    "text": "「如果我破壞第二封印會怎樣？！」伊森大喊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-144-53516a30bcb7cc75": {
    "text": "Seraphine looked stunned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-144-7a4d739930ddce1b": {
    "text": "瑟拉芬震驚看著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-145-89df0a67f40aa14b": {
    "text": "Then slowly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-145-932da14da57c5006": {
    "text": "接著——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-146-b9986603eb1aed81": {
    "text": "Hope appeared in her eyes for the first time.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-146-dc92ac4542b6f5e2": {
    "text": "她眼中第一次出現希望。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-147-11b444939273628b": {
    "text": "“…The prison changes owners.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-147-34f9a2189dd18b0b": {
    "text": "「……監獄會改變主人。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-148-ccffad4099de44de": {
    "text": "The library went silent.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-148-4f54584ebaf00460": {
    "text": "整座圖書館安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-149-66890facb69e97f3": {
    "text": "Even the Hollow King stopped moving.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-149-55e4bf7eec49025e": {
    "text": "連虛空之王都停止動作。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-150-53a3125b272c6be1": {
    "text": "Ethan stared at her.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-150-3aaf6262c5e602a5": {
    "text": "伊森看著她。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-151-e5a57dcaece4276c": {
    "text": "“What does THAT mean?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-151-f77d3deea84b9179": {
    "text": "「那是什麼意思？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-152-0f80684abda35119": {
    "text": "Seraphine looked directly at him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-152-9ebff6ba995d3198": {
    "text": "瑟拉芬直視他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-153-821d1c28ae833076": {
    "text": "“It means the tower would no longer control the prison.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-153-63fc39cbcb72472a": {
    "text": "「代表高塔將不再控制監獄。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-154-ce07b61438c239cc": {
    "text": "“The Hollow King would be sealed…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-154-bc5d8573329374c3": {
    "text": "「虛空之王依然會被封印……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-155-7d222ff171ec24c6": {
    "text": "“…by human choice instead.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-155-85b829c007f0ebd4": {
    "text": "「……但將由人類自己的意志封印。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-156-efd6f894e836e2cf": {
    "text": "The tower voice thundered angrily.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-156-62aa6d59ccc5ba79": {
    "text": "高塔聲音憤怒轟鳴。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-157-7f5f133d898cde8f": {
    "text": "THAT PATH IS FORBIDDEN.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-157-791ede2f436cb283": {
    "text": "「那條道路是禁忌。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-158-91172c798b949a91": {
    "text": "Ethan looked at the glowing second seal.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-158-35da2f051777f442": {
    "text": "伊森看著王冠裡發光的第二封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-159-fe6b24cba366b723": {
    "text": "Then at the collapsing library around him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-159-bf9949ee47e8e3e0": {
    "text": "又看向正在崩塌的圖書館。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-160-ea1273656c1a6450": {
    "text": "Then at his friends.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-160-a34c8618a301d58f": {
    "text": "再看向朋友們。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-161-07138a8a32936037": {
    "text": "Lucy nodded immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-161-99a1b5930fd492f6": {
    "text": "露西立刻點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-162-ee57c1d3caffb214": {
    "text": "“Do it.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-162-24d55e40ef0e7ed0": {
    "text": "「做吧。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-163-faeb01b3bac25f60": {
    "text": "Adrian gave one sharp nod.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-163-e5c23a2939c889d7": {
    "text": "亞德里安也用力點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-164-1674b2b0fbe5a530": {
    "text": "“We trust you.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-164-59a6715ee0702a8e": {
    "text": "「我們相信你。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-165-be72e130add792ee": {
    "text": "Ethan swallowed hard.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-165-f8b469877ed56672": {
    "text": "伊森深吸一口氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-166-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-166-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-167-1afbe27bc2825f91": {
    "text": "He grabbed the second seal inside the crown.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-167-929f1109a250a574": {
    "text": "他伸手抓住王冠裡的第二封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c14-en-block-168-51428c8e6f30c0a7": {
    "text": "The tower screamed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c14-zh-block-168-c50ab53f0db98e26": {
    "text": "高塔發出了尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-title-3053f99f3d95de86": {
    "text": "The Fall of the Tower",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-title-89d793f7f8a95efd": {
    "text": "高塔的崩塌",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-0-96db2a365f9d656e": {
    "text": "The scream of the tower shook the entire world.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-0-ab81280b7e6a0b09": {
    "text": "高塔的尖叫震動整個世界。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-1-34daa1330cf215f1": {
    "text": "SCREEEEEEEEE—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-1-e07623797a2df78b": {
    "text": "嘎啊啊啊啊——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-2-2bb1f047694f7f69": {
    "text": "Every clock inside the school shattered at once.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-2-cd2e5a57b4f56bb7": {
    "text": "學校裡所有時鐘同時炸裂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-3-44a8a4241e299a2f": {
    "text": "Glass exploded through the halls.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-3-abb7a514127a1529": {
    "text": "玻璃碎片飛滿走廊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-4-7a6d62419fe823eb": {
    "text": "The giant bells above the tower cracked apart.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-4-b4c4db03b2308e55": {
    "text": "高塔上的巨大鐘聲接連崩裂。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-5-fc6a32eb7e7618c9": {
    "text": "Students screamed as the castle trembled violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-5-bfb541730d54658c": {
    "text": "學生尖叫，整座城堡劇烈搖晃。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-6-8ac1f3639a2fa047": {
    "text": "Outside the windows—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-6-eba9c6e25eaee0f3": {
    "text": "窗外——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-7-97cb0f365c70ca72": {
    "text": "Lightning covered the sky.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-7-4e2999e0d5e52ce6": {
    "text": "閃電覆蓋天空。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-8-00343535d40aecf9": {
    "text": "The Hollow King roared beneath the mountain.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-8-e60ad27dd6ff2162": {
    "text": "虛空之王在山脈下怒吼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-9-541010c3c90726f6": {
    "text": "And Ethan held the glowing second seal in his hands.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-9-b7334d57e6af9771": {
    "text": "而伊森手中握著發光的第二封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-10-71e419733f87d88d": {
    "text": "The silver crown burned with furious light.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-10-918ec7d0dd50a01f": {
    "text": "銀色王冠燃燒著憤怒光芒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-11-7d1f1f2279100a5d": {
    "text": "The tower voice thundered inside his mind.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-11-104de8486916728a": {
    "text": "高塔聲音在他腦中轟鳴。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-12-d4222a396a0b7234": {
    "text": "YOU DO NOT UNDERSTAND WHAT YOU ARE DOING.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-12-8367c3304bf07e28": {
    "text": "「你根本不知道自己在做什麼。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-13-bbc995c35c46d7f7": {
    "text": "Ethan gritted his teeth.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-13-8c3fd60a79a814ca": {
    "text": "伊森咬牙。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-14-2dfcab727aacd817": {
    "text": "“You tried to turn me into a prison.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-14-4fd0e6511a6a6047": {
    "text": "「你想把我變成監獄。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-15-08f7a013f940e5ef": {
    "text": "SILENCE IS NECESSARY.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-15-7fb57af058257714": {
    "text": "「沉默與封印是必要的。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-16-19648630abe8083f": {
    "text": "“Not forever!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-16-8bf44b9a9dd04700": {
    "text": "「但不是永遠！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-17-562c697e7d04aa71": {
    "text": "The second seal cracked slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-17-7d7179cba5ea3716": {
    "text": "第二封印微微裂開。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-18-8a0f2ca3a734fc13": {
    "text": "A pulse of silver energy burst through the library.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-18-42a092121a541654": {
    "text": "銀色能量脈衝席捲整座圖書館。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-19-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-19-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-20-a0bc6669cb012fa8": {
    "text": "The giant golden claw below recoiled instantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-20-77ed1677f8bcf12a": {
    "text": "下方巨大金色利爪瞬間縮回。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-21-4724c0b6445196a6": {
    "text": "The Hollow King roared in pain.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-21-a21f8587b22bce56": {
    "text": "虛空之王發出痛苦怒吼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-22-8de8a656e2c29220": {
    "text": "For the first time—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-22-f34020f63d9ecb89": {
    "text": "第一次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-23-9949ca9f7ce5ee9c": {
    "text": "The tower sounded afraid.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-23-0515cc40b593d0eb": {
    "text": "高塔聽起來像在害怕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-24-7c27cf9293dc1d67": {
    "text": "IF THE SECOND SEAL BREAKS, I WILL LOSE CONTROL.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-24-b14b99b0b480299a": {
    "text": "「如果第二封印破碎，我將失去控制。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-25-71c55e00c6321871": {
    "text": "“That’s the point,” Ethan shouted.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-25-b3851f9288d76df0": {
    "text": "「這正是目的，」伊森大喊。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-26-a8c1c8b695b9a22f": {
    "text": "Lucy stared at him in shock.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-26-19ac992387d90b97": {
    "text": "露西震驚看著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-27-7762b462e9fab8ff": {
    "text": "“I cannot believe you’re arguing with an entire tower.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-27-0f22bab67d207f19": {
    "text": "「我不敢相信你正在跟整座高塔吵架。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-28-f6e67275af4266c4": {
    "text": "“Honestly, neither can I!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-28-5230ccc847e12a09": {
    "text": "「老實說，我自己也不敢相信！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-29-0e4edefc0a798ede": {
    "text": "The library shook harder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-29-c1652c7836f6927d": {
    "text": "圖書館搖晃更劇烈。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-30-68251ad8ea08702a": {
    "text": "Massive cracks spread across the ceiling.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-30-eb3ecaee0e1da0c2": {
    "text": "巨大裂痕覆蓋天花板。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-31-bade0836c451c476": {
    "text": "Stone collapsed everywhere.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-31-dd3e2a001bc8ba0d": {
    "text": "石塊四處崩落。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-32-6a41728e12cfc8e0": {
    "text": "Seraphine shouted over the chaos:",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-32-b4f5b7e42066512a": {
    "text": "瑟拉芬在混亂中大喊：",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-33-48e009338631d4f3": {
    "text": "“Ethan!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-33-f2f61c144365392f": {
    "text": "「伊森！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-34-7cfa59b3b4941f44": {
    "text": "“If you break the second seal completely…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-34-c15a437e02764026": {
    "text": "「如果你完全破壞第二封印……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-35-00f2d122ca2a7db0": {
    "text": "“The prison will bind to YOU instead of the tower!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-35-32bb902d35ad0f90": {
    "text": "「監獄將改由你來承受！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-36-641a78e1b01c7f32": {
    "text": "Ethan froze.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-36-8d885feee9177340": {
    "text": "伊森瞬間僵住。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-37-389fc6b7ff4276ec": {
    "text": "“…What?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-37-0e6d1d8c21b20b5e": {
    "text": "「……什麼？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-38-e25ffc2946c3653c": {
    "text": "Adrian’s face turned pale.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-38-08f4ea32ae6d1e08": {
    "text": "亞德里安臉色發白。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-39-c0e6758f722d0e47": {
    "text": "“You’ll become the new Keeper.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-39-2edaf229b96af591": {
    "text": "「你會成為新的守護者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-40-90bd5a758b77484c": {
    "text": "Seraphine nodded slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-40-b94dc6268193f3c9": {
    "text": "瑟拉芬慢慢點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-41-c59a777b2a925348": {
    "text": "“But unlike the tower…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-41-672233e67bef34d3": {
    "text": "「但和高塔不同……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-42-fbddbb48e7d187d0": {
    "text": "“You will still remain human.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-42-36a1f7a06ab212f9": {
    "text": "「你依然會保有人類意志。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-43-e64fd5b486acd6ce": {
    "text": "The Hollow King laughed from below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-43-8d1c6df5dd2525e0": {
    "text": "虛空之王從深處大笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-44-eb92f5649b8568fb": {
    "text": "“CHOOSE CAREFULLY, HEIR…”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-44-21886fe43985ea9c": {
    "text": "「謹慎選擇吧，繼承者……」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-45-10eec1d4f3c4b916": {
    "text": "Ethan stared at the second seal.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-45-54b68a2dd6684160": {
    "text": "伊森盯著第二封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-46-cbbfa2874f026104": {
    "text": "He finally understood.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-46-33e3abb20de51f85": {
    "text": "他終於明白了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-47-bada2641493c8fcd": {
    "text": "No matter what happened—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-47-9aa7a1a5e5e56f83": {
    "text": "不管怎麼樣——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-48-f736baa3dab48985": {
    "text": "Someone had to carry the prison.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-48-d230a6ae87aef04e": {
    "text": "總得有人承受這座監獄。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-49-715c3cfd67c36441": {
    "text": "Either the tower…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-49-ffc779aaf6fc40f4": {
    "text": "不是高塔。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-50-9cc280276160468b": {
    "text": "Or him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-50-7631a13395552293": {
    "text": "就是他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-51-0eb07e6c2c407512": {
    "text": "The silver watch ticked softly in his hand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-51-925ab0b7c3849d58": {
    "text": "銀色懷錶在他手中輕輕滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-52-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-52-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-53-18c5e56295443e85": {
    "text": "Then a final message appeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-53-c476561729846f70": {
    "text": "接著最後一句話浮現。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-54-3e7a8c0de774df3b": {
    "text": "TRUE KEEPERS CHOOSE FREELY.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-54-8d3266dce607b483": {
    "text": "「真正的守護者，擁有自由選擇。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-55-33c030ee334eec3e": {
    "text": "Ethan closed his eyes briefly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-55-1cd67edb6eaf48c7": {
    "text": "伊森短暫閉上雙眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-56-1afc4276c9360c69": {
    "text": "He thought about his father.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-56-971c1508ce731509": {
    "text": "他想起父親。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-57-1294b200f8d21bc5": {
    "text": "About all the years he lost.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-57-4f455da64071deb9": {
    "text": "想起失去的歲月。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-58-d22eaacf380187c7": {
    "text": "About how the tower lied.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-58-e34b018ad3698c5f": {
    "text": "想起高塔的謊言。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-59-b6eed4b57c543737": {
    "text": "About how fear had controlled everything.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-59-08c0864c0ee4d820": {
    "text": "想起恐懼如何控制一切。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-60-1846f4a452e580ea": {
    "text": "Then he opened his eyes again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-60-a99f10f7bf61e568": {
    "text": "然後他再次睜開眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-61-db82faabb85265fc": {
    "text": "And smiled slightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-61-70602fa4721b505c": {
    "text": "微微苦笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-62-6da56ebe02aac3a5": {
    "text": "“…I’m really going to regret this.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-62-4128b316868e28c4": {
    "text": "「……我一定會後悔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-63-4318a6108d5f7d9e": {
    "text": "Lucy pointed immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-63-51f89c986913a16b": {
    "text": "露西立刻指著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-64-12fabd69fe5f5c1d": {
    "text": "“Yes. Definitely.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-64-70b82edbaf1496b9": {
    "text": "「對，絕對會。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-65-8e085297533b0363": {
    "text": "Adrian nodded once.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-65-ddb8205ab414ed33": {
    "text": "亞德里安也點頭。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-66-7ba911b78f42b851": {
    "text": "“Almost certainly.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-66-50b6ad4abcb7dcd5": {
    "text": "「幾乎可以肯定。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-67-ab04679c672cdd1f": {
    "text": "“Thank you both for your support.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-67-92a1f356d9316ebd": {
    "text": "「謝謝你們的支持。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-68-3f53dbbd6d75c70f": {
    "text": "Ethan took a deep breath.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-68-f8b469877ed56672": {
    "text": "伊森深吸一口氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-69-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-69-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-70-a459111a99052073": {
    "text": "He shattered the second seal.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-70-0e8f7c97ea28f4db": {
    "text": "他捏碎了第二封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-71-70a49705c0343802": {
    "text": "CRACK.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-71-c7df42e6c845feb3": {
    "text": "喀啦。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-72-0586c6247315355d": {
    "text": "Silver light exploded across the library.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-72-f7ec3b4d7aecf49f": {
    "text": "銀光瞬間覆蓋整座圖書館。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-73-073078eac6725496": {
    "text": "The tower screamed again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-73-9847a10cdc95eac5": {
    "text": "高塔再次發出尖叫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-74-7eea759636e22a90": {
    "text": "But this time—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-74-c8cf185086313483": {
    "text": "但這次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-75-70c53080544b3265": {
    "text": "The scream sounded weaker.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-75-7545d2b91b2dd5a7": {
    "text": "聲音變弱了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-76-c11044068c3d2d76": {
    "text": "The silver crown split apart into thousands of glowing pieces.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-76-44ba1dca0b9782f4": {
    "text": "銀色王冠碎裂成數千發光碎片。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-77-456f3868822a85c9": {
    "text": "The giant clocks across the library stopped completely.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-77-a4106c698bb01fd7": {
    "text": "圖書館所有巨大時鐘完全停止。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-78-92ffc3cca1eae008": {
    "text": "The Hollow King roared in fury.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-78-2ff7fb6ec3374f1e": {
    "text": "虛空之王憤怒咆哮。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-79-b9fa59485bc1dc23": {
    "text": "The entire mountain shook.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-79-7a1c696e6a5cab28": {
    "text": "整座山脈劇烈震動。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-80-b20e808d1c41773a": {
    "text": "Then suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-80-cf172d82c06f42a5": {
    "text": "下一秒——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-81-e58fce133b544c6b": {
    "text": "Silver chains burst upward from the floor.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-81-7283aa19976fc0f3": {
    "text": "銀色鎖鏈從地板爆發而出。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-82-83ed97345e326335": {
    "text": "Not controlled by the tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-82-24e6ab6b70b9d434": {
    "text": "這次不再由高塔控制。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-83-a36a69b3127cb178": {
    "text": "Controlled by Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-83-a8341aff2ad2a23c": {
    "text": "而是由伊森控制。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-84-7f5c8d7fc2cdbef0": {
    "text": "His silver watch floated into the air.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-84-128317898a3c4bee": {
    "text": "銀色懷錶漂浮空中。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-85-e00471c7e08cb36d": {
    "text": "The glowing tower symbol changed shape.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-85-e38b962bdf5d32e5": {
    "text": "高塔圖案開始改變。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-86-2fc24b3976a88413": {
    "text": "No longer a prison mark.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-86-387bc57951541e3d": {
    "text": "不再是監獄印記。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-87-9568e16e2be6fe20": {
    "text": "Now—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-87-aead8f9b7a908494": {
    "text": "而是——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-88-1d129a59ba07fccf": {
    "text": "A Keeper symbol.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-88-18aa420a7cec875f": {
    "text": "守護者印記。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-89-266c6758d9379767": {
    "text": "The chains wrapped around the giant crack below.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-89-a34c1d2835cbbe2a": {
    "text": "鎖鏈纏住下方巨大裂縫。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-90-b387b1545692d37a": {
    "text": "The Hollow King fought violently.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-90-e0aa746c50d7687d": {
    "text": "虛空之王瘋狂掙扎。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-91-f7d23d4837cb61e1": {
    "text": "Golden claws smashed against the chains.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-91-760976c1465bd39e": {
    "text": "巨大金爪猛砸鎖鏈。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-92-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-92-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-93-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-93-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-94-8edc5f5a6a81b3e2": {
    "text": "BOOM!",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-94-f8cb84900fc8e90d": {
    "text": "轟！",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-95-7eea759636e22a90": {
    "text": "But this time—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-95-c8cf185086313483": {
    "text": "但這次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-96-84448a99fe599ba9": {
    "text": "The chains held.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-96-a94e5a9a49cb2e71": {
    "text": "鎖鏈沒有斷。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-97-b99010e7fd743a48": {
    "text": "Ethan felt the prison connecting to him directly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-97-bfd15e7a951139f8": {
    "text": "伊森感覺到監獄直接與自己連結。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-98-c68e91df26ba9c48": {
    "text": "He could feel the Hollow King’s rage.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-98-e19925e090be3a53": {
    "text": "他能感受到虛空之王的憤怒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-99-8ab03c8a930e7018": {
    "text": "Its hunger.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-99-8ed33b87f2a5c00b": {
    "text": "祂的飢餓。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-100-27711ab8d999c7fc": {
    "text": "Its endless loneliness.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-100-c4eca43e2faf8df9": {
    "text": "祂無盡孤獨。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-101-cbf75dc92b91c941": {
    "text": "The feeling nearly crushed him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-101-7f5ef33138f2e5d7": {
    "text": "那感覺幾乎壓垮他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-102-10600a7bc4ac7daa": {
    "text": "Lucy grabbed his arm immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-102-ed96cb0cf975c94e": {
    "text": "露西立刻抓住他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-103-48e009338631d4f3": {
    "text": "“Ethan!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-103-f2f61c144365392f": {
    "text": "「伊森！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-104-1500c0650174e91c": {
    "text": "He almost collapsed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-104-80ce86215c857950": {
    "text": "他差點倒下。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-105-0cbe50463c25697b": {
    "text": "Adrian supported him from the other side.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-105-c18f46b695825867": {
    "text": "亞德里安從另一邊扶住他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-106-b9a6dbf777bb4626": {
    "text": "“Stay conscious!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-106-46b5d66e0536a1dd": {
    "text": "「保持清醒！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-107-385a47ed6b371dd9": {
    "text": "Silver light spread across Ethan’s skin like glowing veins.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-107-9f46758498300ece": {
    "text": "銀光像血管般蔓延伊森全身。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-108-217bb04c1c5c5cd6": {
    "text": "The Keeper symbol burned across his hand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-108-508a9c1a2610132d": {
    "text": "守護者印記灼燒著他的手。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-109-a3bd1506a9ffa277": {
    "text": "The Hollow King roared one final time.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-109-968ce2add7a12aca": {
    "text": "虛空之王最後怒吼一次。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-110-e62153f5361f7f03": {
    "text": "Then—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-110-57a83e53314baae9": {
    "text": "然後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-111-4078e577ca267890": {
    "text": "The crack below began closing.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-111-a37811b309ad3c49": {
    "text": "下方裂縫開始關閉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-112-68cad7121adcce4c": {
    "text": "Slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-112-5a095fb990919bed": {
    "text": "慢慢地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-113-e8b61f7640d7c878": {
    "text": "Painfully.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-113-12f4beff3eb7bbc9": {
    "text": "痛苦地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-114-073a90929be9818e": {
    "text": "Darkness disappeared inch by inch.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-114-d0c230dad85ab51e": {
    "text": "黑暗一寸寸消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-115-cb26350a91c6012c": {
    "text": "The giant golden eyes stared at Ethan one last time.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-115-e2773297ec731c8e": {
    "text": "巨大金色眼睛最後看著伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-116-d79c3a494955270b": {
    "text": "Not with rage.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-116-b11d61750e966029": {
    "text": "不是憤怒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-117-025b84cf60b971b4": {
    "text": "With hatred.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-117-3b166e4ed3fc59ce": {
    "text": "而是仇恨。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-118-63b2ec3f05ad14aa": {
    "text": "And respect.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-118-23a9286e83d086d2": {
    "text": "以及尊敬。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-119-a5073e73a96e44f6": {
    "text": "Then the crack sealed shut completely.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-119-4522c39ce8a91b82": {
    "text": "接著裂縫完全封閉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-120-42caaf875bd101d6": {
    "text": "Silence.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-120-833204688b72a129": {
    "text": "安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-121-3fda833a47318451": {
    "text": "Complete silence.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-121-cb16313461aa2b72": {
    "text": "完全安靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-122-d859cd3aea3e5834": {
    "text": "The shaking stopped.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-122-56d7c80b6ac689c1": {
    "text": "震動停止。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-123-8c198aa9c9763c0b": {
    "text": "The clocks stopped.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-123-aaf67bc1ecb5d64c": {
    "text": "時鐘停止。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-124-99d3dffdd6076981": {
    "text": "The storm outside disappeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-124-121c7d7fc3725e33": {
    "text": "外面暴風雨消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-125-3da9a52a5619c326": {
    "text": "The Hollow King was sealed again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-125-e2cc43e6d208fec1": {
    "text": "虛空之王再次被封印。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-126-e536b2b2d4e55e0b": {
    "text": "Ethan fell to his knees immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-126-4056f95db2b693f6": {
    "text": "伊森立刻跪倒在地。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-127-0fc9c39d26393058": {
    "text": "Breathing hard.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-127-b1fc9fc15c4a5c0a": {
    "text": "劇烈喘氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-128-7c51945c88182d6c": {
    "text": "The silver crown was gone.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-128-9800101e1544688d": {
    "text": "銀色王冠消失了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-129-b8fd299ffe8fa02c": {
    "text": "The tower voice was gone too.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-129-7c6385525917ffe7": {
    "text": "高塔聲音也消失了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-130-94751062df43a0f8": {
    "text": "Only the silver watch remained.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-130-57f4ebb029148616": {
    "text": "只剩銀色懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-131-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-131-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-132-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-132-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-133-34b1475fbf1493c3": {
    "text": "Tick…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-133-6d52d596d4a722eb": {
    "text": "滴答……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-134-04975aca4b9ceaf0": {
    "text": "Lucy rushed toward him.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-134-08426d914d263664": {
    "text": "露西衝向他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-135-738819667b023ba1": {
    "text": "“You idiot!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-135-a66167cf4ebd5eaa": {
    "text": "「你這個笨蛋！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-136-fee2f757c095035e": {
    "text": "She hugged him tightly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-136-e9686f7157b6db5c": {
    "text": "她緊緊抱住他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-137-9ac638127a6312b2": {
    "text": "“You could’ve died!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-137-1f2c733bddc841b4": {
    "text": "「你差點死掉！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-138-5431b18c60ab82b3": {
    "text": "“…Yeah,” Ethan admitted weakly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-138-6168b1df9ced6448": {
    "text": "「……對啊，」伊森虛弱回答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-139-ad8ff386fc84f01a": {
    "text": "“Probably.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-139-5f19e4916e41d4f8": {
    "text": "「大概吧。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-140-c15ed85d66852815": {
    "text": "Adrian helped him stand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-140-d734f1882cdb1974": {
    "text": "亞德里安扶他站起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-141-1c16cd86c1b59489": {
    "text": "For once—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-141-f34020f63d9ecb89": {
    "text": "第一次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-142-ad8336e7587d3fd2": {
    "text": "He looked genuinely impressed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-142-fe740846d329206c": {
    "text": "他看起來真心佩服。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-143-be154fafe125af8d": {
    "text": "“You just overthrew a magical prison tower.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-143-34058a48adbe160a": {
    "text": "「你剛剛推翻了一座魔法監獄高塔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-144-d67f68b9bf254d13": {
    "text": "Ethan blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-144-3b39acb18939e7cb": {
    "text": "伊森眨眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-145-9a6435f57475fc73": {
    "text": "“…When you say it like that, it sounds insane.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-145-973031050d03084c": {
    "text": "「……你這樣講聽起來超瘋狂。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-146-25585d53e39e3e40": {
    "text": "“Because it IS insane.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-146-f8710c8fac56f995": {
    "text": "「因為本來就很瘋狂。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-147-33bb6b3311f73526": {
    "text": "Seraphine slowly approached them.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-147-24015aa4a502c926": {
    "text": "瑟拉芬慢慢走向他們。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-148-68673c737b038bad": {
    "text": "Her mechanical eye glowed softly now.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-148-da07fc40a362ba75": {
    "text": "她的機械眼現在只剩柔和光芒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-149-76647d8eac11748b": {
    "text": "“The tower is no longer the prison keeper.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-149-0010684d033dc710": {
    "text": "「高塔不再是監獄守護者。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-150-07fe7c5fcda9094f": {
    "text": "She looked directly at Ethan.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-150-b3ae715f726d7fda": {
    "text": "她直視伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-151-6a37edde8f9a30f5": {
    "text": "“You are.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-151-92da513a3fb28626": {
    "text": "「現在是你。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-152-613ec9d6f5d04ba7": {
    "text": "The library became quiet.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-152-7f612351ca36962a": {
    "text": "圖書館安靜下來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-153-88e51dadf28f52d7": {
    "text": "Ethan looked at the silver symbol glowing on his hand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-153-0f1718d42c17eae7": {
    "text": "伊森看著自己手上的發光印記。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-154-0c370370d9fccbce": {
    "text": "“…So what happens now?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-154-e44d63df18bf3797": {
    "text": "「……那現在怎麼辦？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-155-a560c0567b96af82": {
    "text": "Seraphine smiled gently for the first time.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-155-818d39cb3518a6b1": {
    "text": "瑟拉芬第一次溫柔微笑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-156-62e0416231894768": {
    "text": "“Now?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-156-226e223c2dd4ec09": {
    "text": "「現在？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-157-0403745030a68bce": {
    "text": "“You change everything.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-157-a7e5a0848ca54168": {
    "text": "「你將改變一切。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-158-9446a124d9b12fb8": {
    "text": "Far above them—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-158-60d35039d63f0033": {
    "text": "而在他們上方——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-159-fe7ea3a88a7b570e": {
    "text": "The giant Clock Tower bells rang softly once more.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-159-1de70a1583dcc134": {
    "text": "時鐘塔的巨大鐘聲再次響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-160-2573684e306c07c2": {
    "text": "Not angry.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-160-9161c173a9cdff6f": {
    "text": "這次不再憤怒。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-161-40a68c948ce85d30": {
    "text": "Not broken.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-161-cebc41acf7c3f028": {
    "text": "不再破碎。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-162-33e91dca9be0d48a": {
    "text": "Peaceful.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-162-1442c32b180c7bc8": {
    "text": "而是平靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-163-68e53d6742988ecc": {
    "text": "DONG…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-163-5c6c114a12fde506": {
    "text": "噹……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-164-289e66f00fab994e": {
    "text": "And somewhere deep within the silent tower—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-164-a9512eba3b158fd0": {
    "text": "而在沉默高塔深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c15-en-block-165-90f7d64ba13eb185": {
    "text": "A new Keeper had awakened.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c15-zh-block-165-fd3cb7ba1e48f91e": {
    "text": "新的守護者，已經誕生。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-title-c116eca41977d768": {
    "text": "The New Keeper",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-title-2c5f1fa55b4a6101": {
    "text": "新的守護者",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-0-97f78bb12cbda2e4": {
    "text": "Three months later…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-0-7d67dd053df1c14a": {
    "text": "三個月後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-1-643bda8561b36b60": {
    "text": "Snow covered the mountains around Clock Tower School.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-1-ec5aa495b5731723": {
    "text": "白雪覆蓋時鐘塔學院周圍山脈。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-2-79945f2db4a1490f": {
    "text": "Winter winds howled softly outside the castle windows.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-2-dc02f9489e05e8eb": {
    "text": "冬季寒風輕輕吹過城堡窗外。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-3-9854027133cb21f8": {
    "text": "Inside the school—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-3-ee3ff73f9c42310f": {
    "text": "而在學校裡——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-4-1b1bc8dc24e0c2d9": {
    "text": "Everything had changed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-4-13629d9f5f743bc7": {
    "text": "一切都改變了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-5-44175e55266bd16d": {
    "text": "The broken clocks were repaired.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-5-f518da049a59551c": {
    "text": "破碎時鐘被修復。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-6-b0effb6330d351ca": {
    "text": "The floating staircases moved normally again.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-6-2bbad3f0e1b04990": {
    "text": "漂浮樓梯恢復正常。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-7-b9734c2544302fd8": {
    "text": "The dark cracks beneath the tower had disappeared.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-7-a2e023c486cf80d5": {
    "text": "高塔底下黑暗裂縫消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-8-eaa217418cb30de4": {
    "text": "And for the first time in many years—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-8-f2f5120fcf1922f0": {
    "text": "而且很多年來第一次——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-9-226fb82f70779a4a": {
    "text": "The school felt peaceful.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-9-e24c2850be182597": {
    "text": "整間學校變得平靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-10-d1a87ca6e389d53c": {
    "text": "Mostly peaceful.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-10-6f57e3ad2adf9c30": {
    "text": "大部分時候算平靜。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-11-94968953cc78c2ee": {
    "text": "Lucy still ran through hallways while carrying far too many books.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-11-aabb5db36e0efe46": {
    "text": "露西依然抱著一大堆書在走廊奔跑。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-12-c149f3ccbabc0c46": {
    "text": "“ETHAN!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-12-f2f61c144365392f": {
    "text": "「伊森！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-13-9fae3f53aadd803c": {
    "text": "She nearly crashed into him beside the west tower stairs.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-13-9db71e005e862fd0": {
    "text": "她差點在西塔樓梯撞上伊森。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-14-7c66bb5047ce07fb": {
    "text": "“You missed breakfast again!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-14-ad5b2716e09e42a0": {
    "text": "「你又錯過早餐了！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-15-6b84a94ca6793de1": {
    "text": "Ethan smiled tiredly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-15-ac8481d36fe87d75": {
    "text": "伊森疲憊笑著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-16-419fda5aa865c353": {
    "text": "“I was studying.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-16-09553b9579872079": {
    "text": "「我在讀書。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-17-bac71f0154549d15": {
    "text": "Lucy narrowed her eyes.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-17-7fcdccc5c110d4d4": {
    "text": "露西瞇起眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-18-bb7e7dbc24833fdb": {
    "text": "“You were sleeping in the library.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-18-9978aa7d38861791": {
    "text": "「你是在圖書館睡覺。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-19-e118c45f673f94b0": {
    "text": "“…Maybe.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-19-da0d0ae7642cfaaa": {
    "text": "「……可能吧。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-20-d7c008179d5b7a62": {
    "text": "“I KNEW IT.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-20-15900817cecd8910": {
    "text": "「我就知道！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-21-45722e8a6e53160a": {
    "text": "Behind them, Adrian approached calmly with his usual serious expression.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-21-c64db5946e3d22ff": {
    "text": "後方，亞德里安依舊帶著嚴肅表情走來。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-22-78dd9862c9a658ed": {
    "text": "“You’re both too loud.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-22-674c36e5bc041a65": {
    "text": "「你們太吵了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-23-ec6647291410e631": {
    "text": "Lucy pointed at him dramatically.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-23-820c95549d950621": {
    "text": "露西誇張指著他。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-24-8be958ea61182f24": {
    "text": "“You secretly enjoy our chaos.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-24-80e0e94ced02de4c": {
    "text": "「你其實很喜歡我們的混亂。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-25-26751d8262b2796e": {
    "text": "“I absolutely do not.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-25-03fb227270fe8651": {
    "text": "「我完全沒有。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-26-ac39d4b9c499550a": {
    "text": "Ethan laughed quietly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-26-82abb560ca040bbf": {
    "text": "伊森輕聲笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-27-74d8840f5da6c470": {
    "text": "Some things never changed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-27-1c3df5d4278ba9b9": {
    "text": "有些事情永遠不會改變。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-28-ede64fa5ecf4e9d8": {
    "text": "But other things had changed forever.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-28-e39ddefa12fa7dbe": {
    "text": "但有些事情，已經永遠不同。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-29-e3f2d92aa1c7b68c": {
    "text": "The silver Keeper symbol still glowed faintly on Ethan’s hand.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-29-09e9866da77c4524": {
    "text": "銀色守護者印記依然微微發光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-30-e900f94cf0a627e7": {
    "text": "Most students could not see it.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-30-8bb0769666181c26": {
    "text": "大部分學生看不見。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-31-defb94b2a5345fa3": {
    "text": "But Ethan could feel it constantly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-31-6a042a811ac340fd": {
    "text": "但伊森一直感覺得到。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-32-ad675b1402194f88": {
    "text": "A soft connection beneath the tower.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-32-5be996986dcd6255": {
    "text": "那是一種與高塔底部相連的感覺。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-33-1dc4e2e120fa0857": {
    "text": "Far below the school—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-33-e7e624b30ffd90e7": {
    "text": "在學校深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-34-117f652f4301cf00": {
    "text": "The prison still existed.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-34-aed086699003817f": {
    "text": "監獄依然存在。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-35-878fd9d6b2aadc06": {
    "text": "And so did the Hollow King.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-35-973b3da4945c0722": {
    "text": "虛空之王也還存在。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-36-2a84a09c8d4b28a7": {
    "text": "Waiting.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-36-ef6a58a01293e1ab": {
    "text": "等待著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-37-baa772984be5d266": {
    "text": "Sleeping.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-37-1927e012fa9e3cc8": {
    "text": "沉睡著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-38-885c75a98ac77b41": {
    "text": "Watching.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-38-5706de263b5e0517": {
    "text": "注視著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-39-f20e6445bf8f09d1": {
    "text": "Sometimes Ethan could hear distant heartbeats at night.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-39-c73e4d7f770e9f6c": {
    "text": "有時夜晚時，伊森仍會聽見遙遠心跳聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-40-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-40-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-41-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-41-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-42-e16ddf86f1512be2": {
    "text": "THUMP.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-42-662390ab20010569": {
    "text": "咚。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-43-d94b3f749abe3f62": {
    "text": "Not dangerous anymore.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-43-f2f4c46782e56295": {
    "text": "現在已經不再危險。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-44-6004b459698896fd": {
    "text": "Just… there.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-44-0b924408d748c77e": {
    "text": "只是……存在著。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-45-cdf37e1145aad76f": {
    "text": "A reminder.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-45-c15c8428310db629": {
    "text": "像提醒一樣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-46-1978e8b2a2b88a38": {
    "text": "The silver watch ticked softly in his pocket.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-46-f24d18b35b914ef3": {
    "text": "銀色懷錶在口袋裡輕輕滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-47-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-47-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-48-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-48-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-49-6325d3bfaf4e9b5a": {
    "text": "Tick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-49-61d2b6e6a41c6df3": {
    "text": "滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-50-2761a49526289626": {
    "text": "Ethan pulled it out slowly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-50-328344e01e915dd1": {
    "text": "伊森慢慢拿出懷錶。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-51-47df015f866db7ce": {
    "text": "The watch looked different now.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-51-88d3008e3328ffd3": {
    "text": "它現在不一樣了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-52-f4a95dfd294430af": {
    "text": "The old prison symbol had vanished.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-52-4769012c3bb0d093": {
    "text": "原本的監獄符號已消失。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-53-cb6beb07c4232ca3": {
    "text": "In its place was a new symbol.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-53-e23d16c0f1079aa2": {
    "text": "取而代之，是一個新圖案。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-54-347485d3f1bc166c": {
    "text": "A silver flame surrounded by a clock circle.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-54-551d3e6b7c9d349d": {
    "text": "銀色火焰包圍時鐘圓環。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-55-515f97102b0f5241": {
    "text": "The symbol of the Free Keeper.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-55-84d37fc1db14ba24": {
    "text": "自由守護者的象徵。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-56-2a0b526bda25d0c4": {
    "text": "Seraphine had explained it weeks ago.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-56-d1db986600068919": {
    "text": "幾週前瑟拉芬曾解釋過。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-57-f8e9ae162d253630": {
    "text": "“The prison now obeys human will.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-57-1c93d13c8abe08e9": {
    "text": "「現在監獄服從人類意志。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-58-64491b19fadf93a1": {
    "text": "“No tower.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-58-a70240faa8e05431": {
    "text": "「不再是高塔。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-59-a36f9a6655fed82c": {
    "text": "“No ancient magic.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-59-c7381dfc3286b318": {
    "text": "「不再是古老魔法。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-60-9a5c0b6bc12f353f": {
    "text": "“Only the Keeper’s choice.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-60-70d353a1d17713e3": {
    "text": "「而是守護者自己的選擇。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-61-31ac869ad121a443": {
    "text": "Ethan still was not sure how he felt about that.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-61-7ba55608d83df665": {
    "text": "伊森直到現在仍不確定自己的感受。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-62-0e31d94ef21bfbbb": {
    "text": "Some nights he felt brave.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-62-7fa742684d50d698": {
    "text": "有些夜晚，他覺得自己很勇敢。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-63-56aaa3d968b76710": {
    "text": "Other nights—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-63-5c06bf65f8710b7b": {
    "text": "但有些夜晚——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-64-73a4447fefc191a3": {
    "text": "Terrified.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-64-2d7843b6bb4b2ea1": {
    "text": "非常害怕。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-65-8279207a6e763357": {
    "text": "Because now he understood something important.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-65-09709bcc19cd4ebd": {
    "text": "因為現在他終於明白一件事。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-66-4f06525df39fd5b4": {
    "text": "Power was dangerous.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-66-47ed22a723b3f941": {
    "text": "力量是危險的。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-67-62dd55942cc370b4": {
    "text": "Even magical towers could become monsters.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-67-acdcfb34c3e5751e": {
    "text": "甚至連魔法高塔都可能變成怪物。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-68-96b351ccb5894138": {
    "text": "That was why choices mattered.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-68-ee52f83334f27e06": {
    "text": "所以選擇才重要。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-69-788fb53ce1879e3f": {
    "text": "And why freedom mattered even more.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-69-31deaf306ea4d2c4": {
    "text": "而自由，更加重要。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-70-baa43fbe06be9919": {
    "text": "Snow drifted softly outside the windows.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-70-4d846d8fb25acf75": {
    "text": "雪靜靜飄落窗外。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-71-e919066f397c9096": {
    "text": "Students laughed somewhere down the hallway.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-71-a20aa7532f73bc9a": {
    "text": "遠處傳來學生笑聲。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-72-ee2798c841c36b9d": {
    "text": "Life continued.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-72-d21143c2dd67c95d": {
    "text": "生活仍在繼續。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-73-00b8b5036f66ccd5": {
    "text": "For the first time since arriving at the school—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-73-f5a00df439b3b5e7": {
    "text": "自從來到學校後——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-74-2389d1d34cfcb708": {
    "text": "Ethan finally felt like he belonged there.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-74-ff8753dd710ad870": {
    "text": "伊森第一次真正感覺自己屬於這裡。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-75-b20e808d1c41773a": {
    "text": "Then suddenly—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-75-979886c7fc87e5b1": {
    "text": "突然——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-76-519fb33ba4cf1c11": {
    "text": "TickTickTick.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-76-08691ae6c2e70a69": {
    "text": "滴答滴答。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-77-704aa6b0b6e71e5c": {
    "text": "The silver watch glowed softly.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-77-66af83781e83ce3d": {
    "text": "銀色懷錶微微發光。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-78-c8270c3e70686e1e": {
    "text": "Ethan frowned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-78-f09e32b4e8865c97": {
    "text": "伊森皺眉。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-79-b2e8bad49bfb4b1a": {
    "text": "“…That’s new.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-79-2864c70c33cad5ce": {
    "text": "「……這倒是新狀況。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-80-d67d3b0a1eb3ce41": {
    "text": "Lucy leaned closer immediately.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-80-f8810e0d76aa0480": {
    "text": "露西立刻湊近。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-81-32da867547cac16d": {
    "text": "“What is it?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-81-f414f5476008b2f4": {
    "text": "「怎麼了？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-82-a950387177ec462f": {
    "text": "A tiny silver message appeared on the watch surface.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-82-ed954d3aea62d64f": {
    "text": "懷錶表面浮現小小銀色文字。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-83-0532ff7713afb5f6": {
    "text": "THE EAST TOWER HAS OPENED.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-83-f2a1369677663bed": {
    "text": "「東塔已開啟。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-84-e84432e140ba4962": {
    "text": "Adrian stopped walking.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-84-202cc15cda70b629": {
    "text": "亞德里安瞬間停下腳步。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-85-f34fcb51d616b449": {
    "text": "“…That tower has been sealed for over a hundred years.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-85-f5da733c5afc20bd": {
    "text": "「……那座塔封印超過一百年了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-86-3ca97c81d6dd7f11": {
    "text": "Lucy blinked.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-86-121f9b3b4705bf72": {
    "text": "露西眨眼。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-87-2253c6b2d4d8fb41": {
    "text": "“Oh no.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-87-248a6abb9d1b5487": {
    "text": "「喔不。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-88-8109f9ae9849f537": {
    "text": "Ethan stared at the glowing words.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-88-9c9bfa8bbf166a27": {
    "text": "伊森盯著發光文字。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-89-0e45a08048e1429a": {
    "text": "Then slowly smiled.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-89-0042c4ac34ec4485": {
    "text": "接著慢慢笑了。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-90-d0062b9fddc73824": {
    "text": "“…Well.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-90-30953fea9c7eee96": {
    "text": "「……好吧。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-91-45409e3f914d31a5": {
    "text": "He adjusted his school robe.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-91-d24c85fe2e035867": {
    "text": "他整理校袍。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-92-863e0ca3a798be7a": {
    "text": "“Looks like the school is trying to kill us again.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-92-d9f2b27359eb2f20": {
    "text": "「看來學校又想殺掉我們了。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-93-c00aa1cb9179af4f": {
    "text": "Lucy groaned dramatically.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-93-b2d8ac009bba7606": {
    "text": "露西誇張哀號。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-94-9a89a912a42bc867": {
    "text": "“I JUST survived one magical apocalypse!”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-94-d8376ea0e09b86b0": {
    "text": "「我才剛從魔法世界末日活下來耶！」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-95-b6ab68795b4762d3": {
    "text": "Adrian sighed deeply.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-95-37cbc5704877d112": {
    "text": "亞德里安深深嘆氣。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-96-8f22eee3b366617f": {
    "text": "“…We’re going, aren’t we?”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-96-2be2587bcaadd85b": {
    "text": "「……我們還是會去，對吧？」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-97-0812224424cc390e": {
    "text": "Ethan grinned.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-97-20f2cbcd654ca1a5": {
    "text": "伊森露出笑容。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-98-0df4428564a79523": {
    "text": "“Definitely.”",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-98-a8bdb628e68cb25a": {
    "text": "「當然。」",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-99-9446a124d9b12fb8": {
    "text": "Far above them—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-99-29570fc4e683a218": {
    "text": "而在高空之上——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-100-b8c4cbd84ec67a36": {
    "text": "One of the giant Clock Tower bells rang softly through the snow.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-100-5d52a1b247e98832": {
    "text": "時鐘塔巨大鐘聲穿過雪夜輕輕響起。",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-101-68e53d6742988ecc": {
    "text": "DONG…",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-101-5c6c114a12fde506": {
    "text": "噹……",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-102-a7c86142b30ea5a1": {
    "text": "And somewhere deep inside the ancient school—",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-102-b49fac144e5ea0c2": {
    "text": "而在古老學院深處——",
    "lang": "zh-TW"
  },
  "v1-clock-tower-magic-school-c16-en-block-103-bc3fb830c089481d": {
    "text": "Another secret waited to awaken.",
    "lang": "en-US"
  },
  "v1-clock-tower-magic-school-c16-zh-block-103-d3ed12ca0f4a2b2e": {
    "text": "另一個秘密，正在等待甦醒。",
    "lang": "zh-TW"
  }
});
